import { readFileSync, statSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { problemResponse } from "@/lib/server/problem";
import { z } from "zod";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

type CatchAllRouteContext = {
  params: Promise<{ rest?: string[] }>;
};

const routeDir = dirname(fileURLToPath(import.meta.url));
const DEFAULT_CLIENT_DIST = resolve(routeDir, "../../..", "client", "dist");
const CLIENT_DIST = resolve(
  /* turbopackIgnore: true */ process.env.HOMER_CLIENT_DIST ??
    DEFAULT_CLIENT_DIST
);
const CLIENT_ASSET_DIST = join(
  /* turbopackIgnore: true */ CLIENT_DIST,
  "client"
);
const CLIENT_HTML_DIST = join(
  /* turbopackIgnore: true */ CLIENT_DIST,
  "server"
);

const expoHtmlRouteSchema = z
  .object({
    page: z.string(),
    namedRegex: z.string(),
  })
  .passthrough();

const expoRoutesManifestSchema = z
  .object({
    htmlRoutes: z.array(expoHtmlRouteSchema).optional(),
    notFoundRoutes: z.array(expoHtmlRouteSchema).optional(),
  })
  .passthrough();

type ExpoRoutesManifest = z.infer<typeof expoRoutesManifestSchema>;

const MIME = new Map([
  [".html", "text/html; charset=utf-8"],
  [".js", "application/javascript; charset=utf-8"],
  [".mjs", "application/javascript; charset=utf-8"],
  [".css", "text/css; charset=utf-8"],
  [".json", "application/json; charset=utf-8"],
  [".map", "application/json; charset=utf-8"],
  [".svg", "image/svg+xml"],
  [".png", "image/png"],
  [".jpg", "image/jpeg"],
  [".jpeg", "image/jpeg"],
  [".gif", "image/gif"],
  [".webp", "image/webp"],
  [".avif", "image/avif"],
  [".ico", "image/x-icon"],
  [".woff", "font/woff"],
  [".woff2", "font/woff2"],
  [".ttf", "font/ttf"],
  [".otf", "font/otf"],
  [".txt", "text/plain; charset=utf-8"],
]);

function mimeFor(path: string): string {
  const dot = path.lastIndexOf(".");
  if (dot < 0) return "application/octet-stream";
  return MIME.get(path.slice(dot).toLowerCase()) ?? "application/octet-stream";
}

function safeJoin(root: string, segments: string[]): string | null {
  for (const s of segments) {
    if (!s || s === "." || s === ".." || s.includes("/") || s.includes("\\")) {
      return null;
    }
  }
  const rel = segments.length === 0 ? "" : segments.join("/");
  const abs = rel ? join(/* turbopackIgnore: true */ root, rel) : root;
  if (!abs.startsWith(root)) return null;
  return abs;
}

function tryServe(path: string, cacheHint: "static" | "html"): Response | null {
  try {
    const stat = statSync(/* turbopackIgnore: true */ path);
    if (!stat.isFile()) return null;
    const body = readFileSync(/* turbopackIgnore: true */ path);
    const headers = new Headers({
      "Content-Type": mimeFor(path),
    });
    if (cacheHint === "static") {
      headers.set("Cache-Control", "public, max-age=31536000, immutable");
    } else {
      headers.set("Cache-Control", "no-cache");
    }
    return new Response(new Uint8Array(body), { headers });
  } catch {
    return null;
  }
}

function readRoutesManifest(): ExpoRoutesManifest | null {
  try {
    const parsed = expoRoutesManifestSchema.safeParse(
      JSON.parse(
        readFileSync(
          /* turbopackIgnore: true */ join(
            /* turbopackIgnore: true */ CLIENT_HTML_DIST,
            "_expo",
            "routes.json"
          ),
          "utf8"
        )
      )
    );
    return parsed.success ? parsed.data : null;
  } catch {
    return null;
  }
}

function htmlPathForPage(page: string): string {
  return join(
    /* turbopackIgnore: true */ CLIENT_HTML_DIST,
    `${page.replace(/^\//, "")}.html`
  );
}

function tryServeExpoRoute(segments: string[]): Response | null {
  const manifest = readRoutesManifest();
  const pathname = `/${segments.join("/")}`;
  for (const route of manifest?.htmlRoutes ?? []) {
    if (new RegExp(route.namedRegex).test(pathname)) {
      return tryServe(htmlPathForPage(route.page), "html");
    }
  }
  const notFound = manifest?.notFoundRoutes?.[0];
  return notFound ? tryServe(htmlPathForPage(notFound.page), "html") : null;
}

export async function GET(_request: Request, { params }: CatchAllRouteContext) {
  const { rest } = await params;
  const segments = rest ?? [];
  if (segments[0] === "api") {
    return problemResponse(404, {
      code: "api_route_not_found",
      message: `API route /${segments.join("/")} was not found`,
    });
  }

  const asset = safeJoin(CLIENT_ASSET_DIST, segments);
  if (asset) {
    const cacheHint = segments.some(
      (s) => s.includes(".") && !s.endsWith(".html")
    )
      ? "static"
      : "html";
    const direct = tryServe(asset, cacheHint);
    if (direct) return direct;
    const indexInDir = tryServe(
      join(/* turbopackIgnore: true */ asset, "index.html"),
      "html"
    );
    if (indexInDir) return indexInDir;
  }

  const flat = safeJoin(CLIENT_DIST, segments);
  if (flat) {
    const direct = tryServe(flat, "static");
    if (direct) return direct;
  }

  const route = tryServeExpoRoute(segments);
  if (route) return route;

  const fallback = tryServe(
    join(/* turbopackIgnore: true */ CLIENT_DIST, "index.html"),
    "html"
  );
  if (fallback) return fallback;
  return new Response(
    "Client web export not found. Build with `pnpm build`.\n",
    {
      status: 503,
      headers: { "Content-Type": "text/plain; charset=utf-8" },
    }
  );
}

import { beforeEach, describe, expect, it, vi } from "vitest";

const {
  readFileSync,
  writeFileSync,
  renameSync,
  readChatProfileId,
  getChatProfileConf,
  reconnectRuntime,
  statusCodeForReconnect,
} = vi.hoisted(() => ({
  readFileSync: vi.fn(),
  writeFileSync: vi.fn(),
  renameSync: vi.fn(),
  readChatProfileId: vi.fn(),
  getChatProfileConf: vi.fn(),
  reconnectRuntime: vi.fn(),
  statusCodeForReconnect: vi.fn(),
}));

vi.mock("node:fs", () => ({ readFileSync, writeFileSync, renameSync }));
vi.mock("@/lib/server/chat-profile", () => ({ readChatProfileId }));
vi.mock("@/lib/server/conf", () => ({ getChatProfileConf }));
vi.mock("@/lib/server/runtime-control", () => ({
  reconnectRuntime,
  statusCodeForReconnect,
}));

import { GET, PUT } from "./route";

describe("/api/admin/conf", () => {
  beforeEach(() => {
    vi.clearAllMocks();
    getChatProfileConf.mockReturnValue("/configs/qwen36.conf");
    readChatProfileId.mockReturnValue("other-profile");
  });

  it("reads the selected profile through the canonical response", async () => {
    readFileSync.mockReturnValue("MODEL=qwen36\n");

    const response = await GET(
      new Request("http://api.test/api/admin/conf?profile=qwen36")
    );

    expect(response.status).toBe(200);
    await expect(response.json()).resolves.toEqual({
      profile: "qwen36",
      content: "MODEL=qwen36\n",
    });
    expect(readFileSync).toHaveBeenCalledWith("/configs/qwen36.conf", "utf8");
  });

  it("writes a non-active profile atomically without restarting", async () => {
    const response = await PUT(
      new Request("http://api.test/api/admin/conf", {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ profile: "qwen36", content: "MODEL=qwen36\n" }),
      })
    );

    expect(response.status).toBe(200);
    await expect(response.json()).resolves.toEqual({
      status: "saved",
      restarted: false,
    });
    expect(writeFileSync).toHaveBeenCalledWith(
      expect.stringMatching(/^\/configs\/qwen36\.conf\.\d+\.tmp$/),
      "MODEL=qwen36\n",
      "utf8"
    );
    expect(renameSync).toHaveBeenCalledWith(
      expect.stringMatching(/^\/configs\/qwen36\.conf\.\d+\.tmp$/),
      "/configs/qwen36.conf"
    );
    expect(reconnectRuntime).not.toHaveBeenCalled();
  });

  it("returns failed reconnects as typed problems", async () => {
    readChatProfileId.mockReturnValue("qwen36");
    statusCodeForReconnect.mockReturnValue(500);
    reconnectRuntime.mockResolvedValue({
      status: "error",
      target: "chat",
      runtime: "openai-compatible",
      model: "qwen36",
      probe: {
        kind: "chat",
        ready: false,
        attempts: 1,
        error: "restart failed",
      },
      restarted: true,
      error: "restart failed",
      at: "2026-08-11T00:00:00.000Z",
    });

    const response = await PUT(
      new Request("http://api.test/api/admin/conf", {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ profile: "qwen36", content: "MODEL=qwen36\n" }),
      })
    );

    expect(response.status).toBe(500);
    await expect(response.json()).resolves.toEqual({
      code: "runtime_reconnect_failed",
      message: "restart failed",
    });
  });

  it("returns a typed problem when the request body is invalid", async () => {
    const response = await PUT(
      new Request("http://api.test/api/admin/conf", {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ profile: "qwen36" }),
      })
    );

    expect(response.status).toBe(400);
    await expect(response.json()).resolves.toEqual({
      code: "invalid_request",
      message: "invalid request body",
    });
    expect(writeFileSync).not.toHaveBeenCalled();
  });
});

import {
  chmod,
  chown,
  mkdtemp,
  rm,
  symlink,
  writeFile,
} from "node:fs/promises";
import { join } from "node:path";
import { tmpdir } from "node:os";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

import { videoArtifactUrl } from "@/lib/server/video-artifact";
import { GET, HEAD } from "./route";

let artifactRoot: string;
const artifactKey = "a".repeat(64);

function request(range?: string) {
  const headers = new Headers();
  if (range) headers.set("range", range);
  return new Request(
    `https://homer.example.test/api/video/media/${artifactKey}`,
    { headers }
  );
}

function context(key = artifactKey) {
  return { params: Promise.resolve({ artifactKey: key }) };
}

beforeEach(async () => {
  artifactRoot = await mkdtemp(join(tmpdir(), "homer-video-artifacts-"));
  await chmod(artifactRoot, 0o750);
  const uid = process.getuid?.();
  const gid = process.getgid?.();
  if (uid === undefined || gid === undefined) {
    throw new Error("The video media route tests require a Unix user.");
  }
  await chown(artifactRoot, uid, gid);
  process.env.HOMER_VIDEO_ARTIFACT_ROOT = artifactRoot;
  await writeFile(join(artifactRoot, `${artifactKey}.mp4`), "0123456789", {
    mode: 0o440,
  });
});

afterEach(async () => {
  vi.unstubAllEnvs();
  delete process.env.HOMER_VIDEO_ARTIFACT_ROOT;
  await rm(artifactRoot, { recursive: true, force: true });
});

describe("GET /api/video/media/[artifactKey]", () => {
  it("uses the canonical HTTPS origin in production", () => {
    vi.stubEnv("NODE_ENV", "production");
    vi.stubEnv("EXPO_PUBLIC_HOMER_BASE_URL", "https://api.example.test");

    expect(
      videoArtifactUrl(artifactKey, "http://127.0.0.1:3202/api/video/tasks")
    ).toBe(`https://api.example.test/api/video/media/${artifactKey}`);
  });

  it("serves a capability-owned MP4 with safe content headers", async () => {
    const response = await GET(request(), context());

    expect(response.status).toBe(200);
    expect(response.headers.get("content-type")).toBe("video/mp4");
    expect(response.headers.get("content-length")).toBe("10");
    expect(response.headers.get("accept-ranges")).toBe("bytes");
    expect(response.headers.get("content-disposition")).toMatch(
      /^inline; filename="homer-video-[0-9a-f]{12}\.mp4"$/
    );
    expect(response.headers.get("cache-control")).toBe("private, max-age=3600");
    expect(response.headers.get("referrer-policy")).toBe("no-referrer");
    await expect(response.text()).resolves.toBe("0123456789");
  });

  it("serves one valid byte range", async () => {
    const response = await GET(request("bytes=2-5"), context());

    expect(response.status).toBe(206);
    expect(response.headers.get("content-range")).toBe("bytes 2-5/10");
    expect(response.headers.get("content-length")).toBe("4");
    await expect(response.text()).resolves.toBe("2345");
  });

  it("answers HEAD with the same media metadata and no body", async () => {
    const response = await HEAD(request(), context());

    expect(response.status).toBe(200);
    expect(response.headers.get("content-type")).toBe("video/mp4");
    expect(response.headers.get("content-length")).toBe("10");
    await expect(response.text()).resolves.toBe("");
  });

  it("returns 416 for malformed or unsatisfiable ranges", async () => {
    for (const range of ["bytes=20-30", "bytes=1-2,4-5", "items=0-1"]) {
      const response = await GET(request(range), context());
      expect(response.status).toBe(416);
      expect(response.headers.get("content-range")).toBe("bytes */10");
    }
  });

  it("rejects traversal and non-capability route params", async () => {
    for (const key of ["../etc/passwd", "a".repeat(63), "A".repeat(64)]) {
      const response = await GET(request(), context(key));
      expect(response.status).toBe(400);
    }
  });

  it("requires the exact immutable publication directory mode", async () => {
    await chmod(artifactRoot, 0o755);

    expect((await GET(request(), context())).status).toBe(404);
  });

  it("does not serve symlinks, writable artifacts, or group-unreadable artifacts", async () => {
    const realPath = join(artifactRoot, "real.mp4");
    const artifactPath = join(artifactRoot, `${artifactKey}.mp4`);
    await writeFile(realPath, "private", { mode: 0o640 });
    await rm(artifactPath);
    await symlink(realPath, artifactPath);
    expect((await GET(request(), context())).status).toBe(404);

    await rm(artifactPath);
    await writeFile(artifactPath, "writable", { mode: 0o666 });
    await chmod(artifactPath, 0o666);
    expect((await GET(request(), context())).status).toBe(404);

    await chmod(artifactPath, 0o400);
    expect((await GET(request(), context())).status).toBe(404);

    await chmod(artifactPath, 0o444);
    expect((await GET(request(), context())).status).toBe(404);
  });
});

import { randomUUID } from "node:crypto";
import { describe, expect, it } from "vitest";

import { GET } from "./route";

describe("GET /api/video/tasks/[taskId]/status", () => {
  it("returns an API problem when the task does not exist", async () => {
    const taskId = `missing-${randomUUID()}`;
    const response = await GET(
      new Request(`http://localhost/api/video/tasks/${taskId}/status`),
      { params: Promise.resolve({ taskId }) }
    );

    expect(response.status).toBe(404);
    await expect(response.json()).resolves.toEqual({
      code: "video_task_not_found",
      message: "task not found",
    });
  });
});

import type {
  ChatModelEndpoint,
  RuntimeReconnectProbe,
} from "@homer/shared/runtime-types";
import type { RuntimeReadinessCode } from "@homer/shared/runtime-types";

const DEFAULT_READY_TIMEOUT_MS = 2_000;

type UnreadyProbeStatus = {
  ready: false;
  status?: number;
};

type ServingProbe = { ready: true } | (UnreadyProbeStatus & { error: string });

export type ChatServingProbe = RuntimeReconnectProbe &
  ({ ready: true } | { ready: false; error: string });

export type ChatRuntimeReadiness =
  | { ready: true }
  | (Required<UnreadyProbeStatus> & {
      code: RuntimeReadinessCode;
      message: string;
      upstream: string;
      upstreamStatus?: number;
      retryAfterSeconds?: number;
    });

export function modelsProbeUrl(endpoint: ChatModelEndpoint): string {
  return `${endpoint.baseURL.replace(/\/$/, "")}/models`;
}

export function completionsProbeUrl(endpoint: ChatModelEndpoint): string {
  return `${endpoint.baseURL.replace(/\/$/, "")}/chat/completions`;
}

function completionProbeModel(endpoint: ChatModelEndpoint): string {
  return endpoint.servedModelName ?? endpoint.id;
}

async function probeModelsEndpoint(
  url: string,
  signal: AbortSignal
): Promise<ServingProbe> {
  const res = await fetch(url, { cache: "no-store", signal });
  if (!res.ok) {
    return { ready: false, status: res.status, error: `HTTP ${res.status}` };
  }

  const payload = await res.json().catch(() => null);
  const data =
    payload && typeof payload === "object" && "data" in payload
      ? payload.data
      : null;
  if (!Array.isArray(data) || data.length === 0) {
    return {
      ready: false,
      status: res.status,
      error: "models endpoint returned no available models",
    };
  }

  return { ready: true };
}

async function probeChatCompletionsEndpoint(
  endpoint: ChatModelEndpoint,
  signal: AbortSignal
): Promise<ServingProbe> {
  const res = await fetch(completionsProbeUrl(endpoint), {
    method: "POST",
    cache: "no-store",
    headers: { "content-type": "application/json" },
    signal,
    body: JSON.stringify({
      model: completionProbeModel(endpoint),
      stream: true,
      max_tokens: 1,
      temperature: 0,
      messages: [{ role: "user", content: "ping" }],
    }),
  });

  if (res.ok) {
    await res.body?.cancel().catch(() => undefined);
    return { ready: true };
  }

  const payload = await res.json().catch(() => null);
  const upstreamMessage =
    payload &&
    typeof payload === "object" &&
    "error" in payload &&
    payload.error &&
    typeof payload.error === "object" &&
    "message" in payload.error &&
    typeof payload.error.message === "string"
      ? payload.error.message
      : null;

  return {
    ready: false,
    status: res.status,
    error: upstreamMessage ?? `HTTP ${res.status}`,
  };
}

async function probeServingEndpoint(
  endpoint: ChatModelEndpoint,
  timeoutMs: number
): Promise<ServingProbe> {
  const signal = AbortSignal.timeout(timeoutMs);
  const modelProbe = await probeModelsEndpoint(
    modelsProbeUrl(endpoint),
    signal
  );
  if (!modelProbe.ready) return modelProbe;
  return probeChatCompletionsEndpoint(endpoint, signal);
}

export async function probeChatRuntimeServing(
  endpoint: ChatModelEndpoint,
  timeoutMs: number,
  attempts: number
): Promise<ChatServingProbe> {
  const url = completionsProbeUrl(endpoint);
  try {
    const probe = await probeServingEndpoint(endpoint, timeoutMs);
    if (probe.ready) {
      return { ready: true, kind: "chat", attempts, url };
    }
    return {
      ready: false,
      kind: "chat",
      attempts,
      url,
      error: probe.error,
    };
  } catch (err) {
    return {
      ready: false,
      kind: "chat",
      attempts,
      url,
      error: err instanceof Error ? err.message : String(err),
    };
  }
}

export async function checkChatRuntimeReadiness(
  endpoint: ChatModelEndpoint,
  timeoutMs = DEFAULT_READY_TIMEOUT_MS
): Promise<ChatRuntimeReadiness> {
  const upstream = modelsProbeUrl(endpoint);
  const serving = completionsProbeUrl(endpoint);
  try {
    const probe = await probeServingEndpoint(endpoint, timeoutMs);
    if (probe.ready) return { ready: true };
    if (probe.status === 503) {
      return {
        ready: false,
        status: 503,
        code: "model_loading",
        message: `Model backend ${endpoint.id} is still loading; retry shortly.`,
        upstream: serving,
        upstreamStatus: probe.status,
        retryAfterSeconds: 5,
      };
    }
    return {
      ready: false,
      status: 502,
      code: "backend_not_ready",
      message: `Model backend ${endpoint.id} is not ready (${probe.error}).`,
      upstream: probe.status ? serving : upstream,
      upstreamStatus: probe.status,
      retryAfterSeconds: 5,
    };
  } catch (err) {
    const detail = err instanceof Error ? err.message : String(err);
    return {
      ready: false,
      status: 502,
      code: "backend_unreachable",
      message: `Can't reach model backend ${endpoint.id}. It may be restarting or down.${detail ? ` ${detail}` : ""}`,
      upstream: serving,
      retryAfterSeconds: 5,
    };
  }
}

import { exec } from "node:child_process";
import { accessSync, constants, existsSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { promisify } from "node:util";

import {
  modelsProbeUrlForActiveProfile,
  readChatProfileId,
} from "@/lib/server/chat-profile";
import {
  getChatRuntimeProfiles,
  isModelPathReady,
  parseConf,
  type ChatRuntimeProfile,
} from "@/lib/server/conf";
import {
  MODEL_CTL,
  commandForChatRuntimeProfileActivation,
  timeoutForChatRuntimeRestart,
  type ChatRuntimeRestartMode,
} from "@/lib/server/chat-runtime-control";
import {
  checkChatRuntimeReadiness as checkServingReadiness,
  modelsProbeUrl,
  probeChatRuntimeServing,
  type ChatRuntimeReadiness,
  type ChatServingProbe,
} from "@/lib/server/chat-runtime-readiness";
import { stopAllImageRuntimes } from "@/lib/server/image-runtime";
import { shouldEnsureLlamaRocmLinkage } from "@/lib/server/llama-linkage-policy";
import { readRuntimeLoadProgress } from "@/lib/server/runtime-load-progress";
import { runtimeProgressForHttpWarming } from "@/lib/server/load-telemetry-phase";
import {
  evaluateRuntimeStartPolicy,
  formatRuntimePolicyFailure,
} from "@/scripts/model-runtime-preflight";
import {
  switchEventSender,
  type SwitchEvent,
  type SwitchEventEstimate,
} from "@homer/shared/switch-stream";
import type { ApiProblem } from "@homer/shared/contracts/api-problem";
import {
  CHAT_BACKEND,
  type ChatModelEndpoint,
  type RuntimeReconnectProbe,
} from "@homer/shared/runtime-types";

const execAsync = promisify(exec);
const MODEL_READY_TIMEOUT_MS = 15_000;
const DEFAULT_SWITCH_TIMEOUT_MS = 900_000;
const DEFAULT_SWITCH_INTERVAL_MS = 1_200;

type PreflightOk = {
  ok: true;
  profile: string;
  model_path: string;
  port: number;
};
type PreflightFail = { ok: false; reason: string; profile?: string };

type ModelServiceSnapshot = {
  activeState: string;
  subState: string;
  result: string;
  execMainStatus: number;
  mainPid: number;
};

type ChatRuntimeActivationOptions = {
  timeoutMs?: number;
  intervalMs?: number;
  restartMode?: ChatRuntimeRestartMode;
};

export type ChatRuntimeActivationResult = {
  status: "ready" | "timeout" | "error";
  profile?: ChatRuntimeProfile;
  probe: RuntimeReconnectProbe;
  restarted: boolean;
  error?: string;
};

export type { ChatRuntimeReadiness };

export class ChatRuntimeError extends Error {
  readonly status: number;
  readonly code: string;

  constructor(status: number, message: string, code: string) {
    super(message);
    this.name = "ChatRuntimeError";
    this.status = status;
    this.code = code;
  }
}

let switchLock: Promise<void> = Promise.resolve();

function stripTrailingV1(baseURL: string): string {
  return baseURL.replace(/\/v1\/?$/, "").replace(/\/$/, "");
}

export function resolveChatRuntimeProfile(
  modelId?: string | null
): ChatRuntimeProfile | null {
  const id = (modelId ?? readChatProfileId()).trim();
  if (!id) return null;
  return getChatRuntimeProfiles().find((profile) => profile.id === id) ?? null;
}

function inferStatusFromError(error: unknown): number {
  if (error && typeof error === "object" && "name" in error) {
    return 502;
  }
  return 500;
}

async function sleep(ms: number): Promise<void> {
  await new Promise((resolve) => setTimeout(resolve, ms));
}

async function withSwitchLock<T>(fn: () => Promise<T>): Promise<T> {
  const previous = switchLock;
  let release!: () => void;
  switchLock = new Promise<void>((resolve) => {
    release = resolve;
  });

  await previous.catch(() => undefined);
  try {
    return await fn();
  } finally {
    release();
  }
}

async function stopAllImageBackendsSafe() {
  try {
    await stopAllImageRuntimes();
  } catch {
    // Image backend shutdown is best effort; chat switching should continue.
  }
}

async function runChatPreflight(
  profile: ChatRuntimeProfile
): Promise<PreflightOk | PreflightFail> {
  try {
    if (profile.runtimeCompatibility) {
      const compatibility = evaluateRuntimeStartPolicy(
        profile.runtimeCompatibility
      );
      if (!compatibility.ok) {
        return {
          ok: false,
          profile: profile.id,
          reason: formatRuntimePolicyFailure(compatibility),
        };
      }
    }
    if (!existsSync(profile.confPath)) {
      return { ok: false, reason: `conf not readable: ${profile.confPath}` };
    }
    const modelPath = profile.modelPath ?? "";
    if (modelPath && !isModelPathReady(modelPath)) {
      return {
        ok: false,
        reason: `MODEL_PATH is not ready: ${modelPath}`,
        profile: profile.id,
      };
    }
    const conf = parseConf(profile.confPath);
    if (
      profile.backend === CHAT_BACKEND.llama &&
      shouldEnsureLlamaRocmLinkage(conf)
    ) {
      const ensureScript = resolve(
        dirname(profile.confPath),
        "scripts/ensure-llama-rocm-linkage.sh"
      );
      if (existsSync(ensureScript)) {
        try {
          await execAsync(`"${ensureScript}" --patch`, {
            timeout: 10_000,
            env: {
              ...process.env,
              LLAMA_CPP_DIR: conf.LLAMA_CPP_DIR ?? "",
              LLAMA_BUILD: conf.LLAMA_BUILD ?? "",
            },
          });
        } catch (err) {
          const detail = err instanceof Error ? err.message : String(err);
          return { ok: false, reason: `llama ROCm linkage invalid: ${detail}` };
        }
      }
    } else if (profile.backend === CHAT_BACKEND.vllm) {
      const vllmDir = conf.VLLM_DIR?.trim();
      if (!vllmDir) {
        return {
          ok: false,
          reason: "VLLM_DIR not set in profile",
          profile: profile.id,
        };
      }
      const vllmPython =
        conf.VLLM_PYTHON ?? resolve(vllmDir, ".venv/bin/python");
      if (!isExecutable(vllmPython)) {
        return {
          ok: false,
          reason: `vLLM python is not executable: ${vllmPython}`,
          profile: profile.id,
        };
      }
    } else if (profile.backend === CHAT_BACKEND.sglang) {
      const sglangDir = conf.SGLANG_DIR?.trim();
      if (!sglangDir) {
        return {
          ok: false,
          reason: "SGLANG_DIR not set in profile",
          profile: profile.id,
        };
      }
      const sglangPython =
        conf.SGLANG_PYTHON ?? resolve(sglangDir, ".venv/bin/python");
      if (!isExecutable(sglangPython)) {
        return {
          ok: false,
          reason: `SGLang python is not executable: ${sglangPython}`,
          profile: profile.id,
        };
      }
      if (conf.SGLANG_REVISION) {
        try {
          const { stdout } = await execAsync("git rev-parse HEAD", {
            cwd: sglangDir,
            timeout: 10_000,
          });
          const actualRevision = stdout.trim();
          if (actualRevision !== conf.SGLANG_REVISION) {
            return {
              ok: false,
              reason: `SGLang runtime revision ${actualRevision || "unavailable"} does not match ${conf.SGLANG_REVISION}`,
              profile: profile.id,
            };
          }
        } catch {
          return {
            ok: false,
            reason: `SGLang runtime revision is unavailable in ${sglangDir}`,
            profile: profile.id,
          };
        }
      }
    } else if (profile.backend === CHAT_BACKEND["sglang-kt"]) {
      const ktDir = conf.SGLANG_KT_DIR?.trim();
      if (!ktDir) {
        return {
          ok: false,
          reason: "SGLANG_KT_DIR not set in profile",
          profile: profile.id,
        };
      }
      const ktPython =
        conf.SGLANG_KT_PYTHON ?? resolve(ktDir, ".venv/bin/python");
      if (!isExecutable(ktPython)) {
        return {
          ok: false,
          reason: `SGLang KT python is not executable: ${ktPython}`,
          profile: profile.id,
        };
      }
      const ktWeightPath = conf.KT_WEIGHT_PATH ?? modelPath;
      if (ktWeightPath && !isModelPathReady(ktWeightPath)) {
        return {
          ok: false,
          reason: `KT_WEIGHT_PATH is not ready: ${ktWeightPath}`,
          profile: profile.id,
        };
      }
    } else if (profile.backend === CHAT_BACKEND.tinygrad) {
      const tinygradDir = conf.TINYGRAD_DIR?.trim();
      if (!tinygradDir) {
        return {
          ok: false,
          reason: "TINYGRAD_DIR not set in profile",
          profile: profile.id,
        };
      }
      const tinygradPython = resolve(tinygradDir, ".venv/bin/python");
      if (!isExecutable(tinygradPython)) {
        return {
          ok: false,
          reason: `Tinygrad python is not executable: ${tinygradPython}`,
          profile: profile.id,
        };
      }
    } else if (profile.backend === CHAT_BACKEND.ds4) {
      const ds4Dir = conf.DS4_DIR?.trim();
      if (!ds4Dir) {
        return {
          ok: false,
          reason: "DS4_DIR not set in profile",
          profile: profile.id,
        };
      }
      const ds4ServerBin = conf.DS4_SERVER_BIN ?? "ds4-server";
      const ds4Server = ds4ServerBin.startsWith("/")
        ? ds4ServerBin
        : resolve(ds4Dir, ds4ServerBin);
      if (!isExecutable(ds4Server)) {
        return {
          ok: false,
          reason: `DS4 server is not executable: ${ds4Server}`,
          profile: profile.id,
        };
      }
    }
    return {
      ok: true,
      profile: profile.id,
      model_path: modelPath,
      port: profile.port,
    };
  } catch (err) {
    return {
      ok: false,
      reason: err instanceof Error ? err.message : "preflight failed",
    };
  }
}

function isExecutable(path: string): boolean {
  try {
    accessSync(path, constants.X_OK);
    return true;
  } catch {
    return false;
  }
}

function unprobed(profile: ChatRuntimeProfile | null): RuntimeReconnectProbe {
  return {
    ready: false,
    kind: "chat",
    attempts: 0,
    url: profile ? modelsProbeUrl(profile) : chatRuntimeProbeUrl(),
  };
}

function chatRuntimeErrorResult(
  error: string,
  profile: ChatRuntimeProfile | null,
  restarted = false
): ChatRuntimeActivationResult {
  return {
    status: "error",
    profile: profile ?? undefined,
    restarted,
    probe: { ...unprobed(profile), error },
    error,
  };
}

async function readModelServiceSnapshot(): Promise<ModelServiceSnapshot | null> {
  try {
    const { stdout } = await execAsync(`${MODEL_CTL} show`, { timeout: 3_000 });
    const props: Record<string, string> = {};
    for (const line of stdout.split("\n")) {
      const eq = line.indexOf("=");
      if (eq <= 0) continue;
      props[line.slice(0, eq)] = line.slice(eq + 1);
    }
    return {
      activeState: props.ActiveState ?? "unknown",
      subState: props.SubState ?? "unknown",
      result: props.Result ?? "unknown",
      execMainStatus: Number(props.ExecMainStatus ?? 0),
      mainPid: Number(props.MainPID ?? 0),
    };
  } catch {
    return null;
  }
}

function modelServiceFailureMessage(
  snapshot: ModelServiceSnapshot | null
): string | null {
  if (!snapshot) return null;
  if (snapshot.activeState === "failed") {
    return `model service failed (${snapshot.subState}; result=${snapshot.result}; exit=${snapshot.execMainStatus})`;
  }
  if (
    snapshot.mainPid === 0 &&
    snapshot.result !== "success" &&
    snapshot.result !== "unknown"
  ) {
    return `model service exited before readiness (result=${snapshot.result}; exit=${snapshot.execMainStatus})`;
  }
  return null;
}

async function chatLoadingEstimate(
  profile: ChatRuntimeProfile
): Promise<SwitchEventEstimate> {
  const progress = await readRuntimeLoadProgress(profile);
  return (
    (progress && runtimeProgressForHttpWarming(progress)) ?? {
      progressKind: "indeterminate",
      percent: null,
      title: "Waiting for runtime signals",
      detail:
        "Using service state, port binding, and health check until a runtime-specific loader signal appears.",
      bucket: "runtime-startup",
      subkey: "awaiting-loader-signal",
      source: "systemd-port-health",
    }
  );
}

async function activateChatRuntimeUnlocked(
  targetProfile: string,
  enqueue: (event: SwitchEvent) => void,
  options: ChatRuntimeActivationOptions = {}
): Promise<ChatRuntimeActivationResult> {
  const send = switchEventSender(
    { target: targetProfile, startedAt: Date.now() },
    enqueue
  );
  const profile = resolveChatRuntimeProfile(targetProfile);
  const intervalMs = options.intervalMs ?? DEFAULT_SWITCH_INTERVAL_MS;
  const timeoutMs =
    options.timeoutMs ?? profile?.switchTimeoutMs ?? DEFAULT_SWITCH_TIMEOUT_MS;
  const preProbe = {
    route: "chat",
    intervalMs,
    attempt: 0,
    max: Math.max(1, Math.ceil(timeoutMs / intervalMs)),
  } as const;
  const failBeforeProbe = (
    error: string,
    failedProfile: ChatRuntimeProfile | null,
    restarted = false
  ) => {
    send({
      ...preProbe,
      variant: "chat-error-pre-probe",
      step: "error",
      phase: "error",
      error,
    });
    return chatRuntimeErrorResult(error, failedProfile, restarted);
  };
  if (!profile) {
    return failBeforeProbe(`invalid chat profile: ${targetProfile}`, null);
  }
  if (profile.disabled === true) {
    return failBeforeProbe(
      profile.disabledReason ??
        `chat profile ${profile.id} is temporarily disabled by config`,
      null
    );
  }
  const preflight = await runChatPreflight(profile);
  if (!preflight.ok) {
    return failBeforeProbe(`preflight: ${preflight.reason}`, profile);
  }

  send({
    ...preProbe,
    variant: "chat-stopping",
    step: "stopping",
    phase: "stopping",
  });
  await stopAllImageBackendsSafe();
  send({
    ...preProbe,
    variant: "chat-starting",
    step: "starting",
    phase: "starting",
  });

  try {
    await activateChatRuntimeProfile(targetProfile, options.restartMode);
  } catch (err) {
    return failBeforeProbe(
      err instanceof Error ? err.message : "chat runtime restart failed",
      profile,
      true
    );
  }

  const deadline = Date.now() + timeoutMs;
  const probeBudget = { ...preProbe, deadline };
  let lastProbe: Extract<ChatServingProbe, { ready: false }> | null = null;

  for (let i = 0; i < preProbe.max && Date.now() < deadline; i += 1) {
    send({
      ...probeBudget,
      variant: "chat-loading",
      step: "loading",
      phase: "loading",
      attempt: i + 1,
      estimate: await chatLoadingEstimate(profile),
    });
    await sleep(intervalMs);
    const probe = await probeChatRuntimeServing(
      profile,
      MODEL_READY_TIMEOUT_MS,
      i + 1
    );
    if (probe.ready) {
      send({
        ...probeBudget,
        variant: "chat-ready",
        step: "ready",
        phase: "ready",
        attempt: i + 1,
      });
      return { status: "ready", profile, probe, restarted: true };
    }
    lastProbe = probe;
    const serviceFailure = modelServiceFailureMessage(
      await readModelServiceSnapshot()
    );
    if (serviceFailure) {
      send({
        ...probeBudget,
        variant: "chat-error-probe",
        step: "error",
        phase: "error",
        attempt: i + 1,
        error: serviceFailure,
      });
      return chatRuntimeErrorResult(serviceFailure, profile, true);
    }
  }

  send(
    lastProbe
      ? {
          ...probeBudget,
          variant: "chat-timeout-probe",
          step: "timeout",
          phase: "timeout",
          attempt: lastProbe.attempts,
          error: lastProbe.error,
        }
      : {
          ...probeBudget,
          variant: "chat-timeout-pre-probe",
          step: "timeout",
          phase: "timeout",
        }
  );
  return {
    status: "timeout",
    profile,
    probe: lastProbe ?? unprobed(profile),
    restarted: true,
    error: lastProbe?.error,
  };
}

