  const targetProfile = (modelId ?? readChatProfileId()).trim();
  return switchChatRuntime(targetProfile, () => {}, {
    timeoutMs,
    intervalMs,
    restartMode,
  });
}

export async function fetchChatRuntimeJSON(
  modelId: string | null | undefined,
  upstreamPath: string,
  options: { backend?: ChatRuntimeProfile["backend"] } = {}
): Promise<{ status: number; payload: unknown }> {
  const profile = resolveChatRuntimeProfile(modelId);
  if (!profile) {
    return {
      status: 400,
      payload: {
        error: `invalid chat model id: ${modelId ?? readChatProfileId()}`,
      },
    };
  }
  if (options.backend && profile.backend !== options.backend) {
    return {
      status: 200,
      payload: {
        status: "unsupported",
        supported: false,
        backend: profile.backend,
        path: upstreamPath,
      },
    };
  }

  const upstreamBase = stripTrailingV1(profile.baseURL);
  const upstreamUrl = `${upstreamBase}${upstreamPath.startsWith("/") ? upstreamPath : `/${upstreamPath}`}`;

  try {
    const upstream = await fetch(upstreamUrl, {
      method: "GET",
      cache: "no-store",
    });
    const payload = await upstream.json().catch(async () => {
      const text = await upstream.text().catch(() => "");
      return {
        detail: text || upstream.statusText || "upstream request failed",
      };
    });
    return { status: upstream.status, payload };
  } catch (error) {
    const message =
      error instanceof Error ? error.message : "upstream request failed";
    const payload = {
      message,
      code: "upstream_unreachable",
    } satisfies ApiProblem;
    return {
      status: inferStatusFromError(error),
      payload,
    };
  }
}

