import type { MachineWorkflowRepository } from "@homer/machine-workflows";
import { ConvexHttpClient } from "convex/browser";
import type { FunctionArgs } from "convex/server";
import { api as convexApi } from "../../../client/convex/_generated/api";

export const MACHINE_REPOSITORY_UNAVAILABLE = "machine_repository_unavailable";

export class MachineRepositoryUnavailableError extends Error {
  readonly code = MACHINE_REPOSITORY_UNAVAILABLE;

  constructor() {
    super("Machine records are temporarily unavailable.");
    this.name = "MachineRepositoryUnavailableError";
  }
}

export function isMachineRepositoryUnavailableError(
  error: unknown
): error is
  | MachineRepositoryUnavailableError
  | { code: typeof MACHINE_REPOSITORY_UNAVAILABLE } {
  return (
    error instanceof MachineRepositoryUnavailableError ||
    (typeof error === "object" &&
      error !== null &&
      "code" in error &&
      error.code === MACHINE_REPOSITORY_UNAVAILABLE)
  );
}

type RepositoryDependencies = {
  convexUrl: string | undefined;
  createClient(
    url: string
  ): Pick<ConvexHttpClient, "setAuth" | "query" | "mutation">;
};

const defaultDependencies: RepositoryDependencies = {
  convexUrl: process.env.CONVEX_URL ?? process.env.NEXT_PUBLIC_CONVEX_URL,
  createClient: (url) => new ConvexHttpClient(url),
};

export function createConvexMachineRepository(
  clerkJwt: string,
  dependencies: RepositoryDependencies = defaultDependencies
) {
  async function client() {
    if (!dependencies.convexUrl || !clerkJwt) {
      throw new MachineRepositoryUnavailableError();
    }
    const convex = dependencies.createClient(dependencies.convexUrl);
    convex.setAuth(clerkJwt);
    return convex;
  }

  return {
    async get(
      machineId: FunctionArgs<typeof convexApi.machines.get>["machineId"]
    ) {
      const convex = await client();
      return await convex.query(convexApi.machines.get, { machineId });
    },

    async inspectAction(
      actionId: FunctionArgs<
        typeof convexApi.littleBird.inspectAction
      >["actionId"]
    ) {
      const convex = await client();
      return await convex.query(convexApi.littleBird.inspectAction, {
        actionId,
      });
    },

    async applyTransition(
      input: FunctionArgs<typeof convexApi.littleBird.applyTransition>
    ) {
      const convex = await client();
      return await convex.mutation(convexApi.littleBird.applyTransition, input);
    },
  } satisfies MachineWorkflowRepository;
}

export type MachineRepository = ReturnType<
  typeof createConvexMachineRepository
>;

