type JsonResult = { payload: unknown; status: number };

function isDisabled(model: ImageModelId): boolean {
  const def = IMAGE_MODELS[model];
  return (
    def.disabled === true ||
    def.availability === "disabled" ||
    def.availability === "missing"
  );
}

function ensureRunnable(model: ImageModelId) {
  const def = IMAGE_MODELS[model];
  if (!def) throw new Error(`unknown image model: ${model}`);
  if (isDisabled(model))
    throw new Error(def.disabledReason ?? `${model} is disabled`);
}

function runtimeForImageModel(model: ImageModelId) {
  const manifest = getRuntimeServiceManifest();
  const binding = manifest.bindings.image[model];
  const runtime = binding ? manifest.services[binding.service]?.runtime : null;
  const parsed = imageRuntimeKindSchema.safeParse(runtime);
  return parsed.success ? parsed.data : undefined;
}

function lightx2vPath(path: string): string {
  return path.startsWith("/") ? path : `/${path}`;
}

function imageHealthFailure(
  code: RuntimeReadinessCode,
  message: string
): ImageHealthResponse {
  return {
    online: false,
    model: null,
    code,
    message,
    retryAfterSeconds: 5,
  };
}

async function sleep(ms: number): Promise<void> {
  await new Promise((resolve) => setTimeout(resolve, ms));
}

async function proxyLightX2VJson(
  path: string,
  init?: RequestInit
): Promise<JsonResult> {
  const upstreamPath = lightx2vPath(path);
  const upstream = await fetch(getLightX2VUrl(upstreamPath), {
    cache: "no-store",
    ...init,
  });
  return { payload: await readJsonResponse(upstream), status: upstream.status };
}

export async function submitImageTask(incoming: FormData): Promise<JsonResult> {
  const modelId = parseImageModelId(incoming.get("model"));
  if (!modelId) {
    return {
      payload: {
        code: "invalid_image_task_request",
        message: "unknown or missing model",
      },
      status: 400,
    };
  }
  try {
    ensureRunnable(modelId);
  } catch (error) {
    return {
      payload: {
        code: "image_model_unavailable",
        message: error instanceof Error ? error.message : String(error),
      },
      status: 409,
    };
  }

  const cap = IMAGE_CAPABILITIES[modelId];
  const capFieldSet = new Set(cap.controls.map((c) => c.field));
  const rawControls: Record<string, string> = {};
  for (const field of capFieldSet) {
    const value = incoming.get(field);
    if (typeof value === "string") rawControls[field] = value;
  }
  const normalized = normalizeImageFields(modelId, rawControls);
  if (!normalized.valid) {
    return {
      payload: {
        code: "invalid_image_task_request",
        message: `Invalid image controls: ${normalized.errors.join("; ")}`,
      },
      status: 400,
    };
  }
  const fields = normalized.fields;

  const upstreamForm = new FormData();
  const prompt = incoming.get("prompt");
  const imageFile = incoming.get("image_file");
  if (!(imageFile instanceof File) || imageFile.size <= 0) {
    const result = await proxyLightX2VJson("/v1/tasks/image/", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify(imageTaskJsonPayload(modelId, prompt, fields)),
    });
    return canonicalImageTaskResult(result);
  }

  if (typeof prompt === "string") upstreamForm.set("prompt", prompt);
  if (imageFile instanceof File && imageFile.size > 0)
    upstreamForm.set("image_file", imageFile);
  for (const [key, value] of Object.entries(fields))
    upstreamForm.set(key, value);
  const result = await proxyLightX2VJson("/v1/tasks/image/form", {
    method: "POST",
    body: upstreamForm,
  });
  return canonicalImageTaskResult(result);
}

function canonicalImageError(result: JsonResult): JsonResult {
  return {
    payload: imageProblemFromLightX2V(result.payload, result.status),
    status: result.status,
  };
}

function canonicalImageTaskResult(
  result: JsonResult,
  fallbackTaskId = ""
): JsonResult {
  if (result.status < 200 || result.status >= 300) {
    return canonicalImageError(result);
  }
  let task: ReturnType<typeof imageTaskFromLightX2V>;
  try {
    task = imageTaskFromLightX2V(result.payload, fallbackTaskId);
  } catch {
    return {
      payload: {
        code: "invalid_image_runtime_response",
        message: "image runtime returned an invalid task payload",
      },
      status: 502,
    };
  }
  if (!task.taskId) {
    return {
      payload: {
        code: "invalid_image_runtime_response",
        message: "image runtime did not return a task id",
      },
      status: 502,
    };
  }
  return { payload: task, status: result.status };
}

export async function getImageTaskStatus(taskId: string): Promise<JsonResult> {
  const result = await proxyLightX2VJson(`/v1/tasks/${taskId}/status`);
  return canonicalImageTaskResult(result, taskId);
}

export async function getImageTaskResultResponse(
  taskId: string
): Promise<Response> {
  const upstreamPath = `/v1/tasks/${taskId}/result`;
  const upstream = await fetch(getLightX2VUrl(upstreamPath), {
    cache: "no-store",
  });
  if (!upstream.ok || !upstream.body) {
    return Response.json(
      imageProblemFromLightX2V(
        await readJsonResponse(upstream),
        upstream.status
      ),
      { status: upstream.status }
    );
  }
  return new Response(upstream.body, {
    status: upstream.status,
    headers: copyResponseHeaders(upstream),
  });
}

export async function cancelImageTask(taskId: string): Promise<JsonResult> {
  const result = await proxyLightX2VJson(`/v1/tasks/${taskId}`, {
    method: "DELETE",
  });
  if (result.status < 200 || result.status >= 300) {
    return canonicalImageError(result);
  }
  return canonicalImageTaskResult(result, taskId);
}

export async function getImageHistory(limit: string): Promise<JsonResult> {
  try {
    const result = await proxyLightX2VJson(
      `/v1/tasks/history?limit=${encodeURIComponent(limit)}`
    );
    if (result.status < 200 || result.status >= 300) {
      return canonicalImageError(result);
    }
    const items = imageHistoryFromLightX2V(result.payload);
    if (!items) {
      return {
        payload: {
          code: "invalid_image_runtime_response",
          message: "invalid image history payload",
        },
        status: 502,
      };
    }
    return { payload: { items }, status: 200 };
  } catch (error) {
    return {
      payload: {
        code: "image_runtime_unavailable",
        message: formatLightX2VProxyError("/v1/tasks/history", error),
      },
      status: 502,
    };
  }
}

export async function probeImageQueue(
  timeoutMs: number
): Promise<RuntimeProbe<MediaQueueStatus>> {
  try {
    const result = await proxyLightX2VJson("/v1/tasks/queue/status", {
      signal: AbortSignal.timeout(timeoutMs),
    });
    return result.status >= 200 && result.status < 300
      ? { state: "answered", value: imageQueueFromLightX2V(result.payload) }
      : {
          state: "unreachable",
          error: `image queue status returned HTTP ${result.status}`,
        };
  } catch (error) {
    return {
      state: "unreachable",
      error: formatLightX2VProxyError("/v1/tasks/queue/status", error),
    };
  }
}

export async function probeImageService(
  timeoutMs: number
): Promise<RuntimeProbe<MediaServiceStatus>> {
  try {
    return {
      state: "answered",
      value: (await getImageServiceStatus(timeoutMs)).service,
    };
  } catch (error) {
    return {
      state: "unreachable",
      error: formatLightX2VProxyError("/v1/service/status", error),
    };
  }
}

export async function getImageServiceStatus(
  timeoutMs = 2_000
): Promise<JsonResult & { service: MediaServiceStatus }> {
  const result = await proxyLightX2VJson("/v1/service/status", {
    signal: AbortSignal.timeout(timeoutMs),
  });
  if (result.status < 200 || result.status >= 300) {
    const service = unavailableImageServiceStatus(
      `image service error (HTTP ${result.status})`
    );
    return {
      payload: imageProblemFromLightX2V(result.payload, result.status),
      status: result.status,
      service,
    };
  }
  const service = imageServiceStatusFromLightX2V(result.payload);
  return { payload: service, status: result.status, service };
}

export async function getImageHealth(): Promise<ImageHealthResponse> {
  let res: Response;
  try {
    res = await fetch(getLightX2VUrl("/v1/service/metadata"), {
      signal: AbortSignal.timeout(3000),
      cache: "no-store",
    });
  } catch (error) {
    const detail = error instanceof Error ? error.message : String(error);
    return imageHealthFailure(
      "backend_unreachable",
      `Can't reach image backend. It may be restarting or down.${detail ? ` ${detail}` : ""}`
    );
  }
  if (!res.ok) {
    return imageHealthFailure(
      res.status === 503 ? "model_loading" : "backend_not_ready",
      res.status === 503
        ? "Image backend is still loading; retry shortly."
        : `Image backend is not ready (HTTP ${res.status}).`
    );
  }
  let payload: unknown;
  try {
    payload = await res.json();
  } catch (error) {
    const detail = error instanceof Error ? error.message : String(error);
    return imageHealthFailure(
      "backend_not_ready",
      `Image backend returned invalid JSON metadata.${detail ? ` ${detail}` : ""}`
    );
  }
  const metadata = imageMetadataFromLightX2V(payload);
  if (!metadata) {
    return imageHealthFailure(
      "backend_not_ready",
      "Image backend returned malformed metadata."
    );
  }
  if (!metadata.modelLoaded) {
    return imageHealthFailure(
      "model_loading",
      "Image backend has not loaded a model; retry shortly."
    );
  }
  if (!metadata.model) {
    return imageHealthFailure(
      "backend_not_ready",
      "Image backend reported an unrecognized loaded model."
    );
  }
  return {
    online: true,
    model: metadata.model,
    runtime: runtimeForImageModel(metadata.model),
  };
}

export async function waitForImageRuntimeReady(
  deadline: number,
  intervalMs: number
) {
  let attempts = 0;
  let latestResult: JsonResult | undefined;
  let error = "";
  while (Date.now() < deadline) {
    attempts += 1;
    try {
      const result = await getImageServiceStatus();
      latestResult = result;
      if (
        result.status >= 200 &&
        result.status < 300 &&
        result.service?.readiness === "ready"
      ) {
        return {
          ready: true,
          kind: "image" as const,
          attempts,
          payload: result.payload,
        };
      }
      const health = await getImageHealth();
      if (health.online) {
        return {
          ready: true,
          kind: "image" as const,
          attempts,
          payload: { status: result.payload, health },
        };
      }
      error = `HTTP ${result.status}`;
    } catch (err) {
      error = err instanceof Error ? err.message : String(err);
    }
    await sleep(intervalMs);
  }
  return {
    ready: false,
    kind: "image" as const,
    attempts,
    payload: latestResult?.payload ?? null,
    error,
  };
}

