import { exec } from "node:child_process";
import { promisify } from "node:util";
import { getLightX2VUrl } from "@/lib/lightx2v";
import {
  IMAGE_MODEL_IDS,
  type ImageModelId,
} from "@homer/shared/model-registry";
import {
  IMAGE_CAPABILITIES,
  type ExecutionProfile,
} from "@homer/shared/image-capabilities";
import { commandForChatRuntimeStop } from "@/lib/server/chat-runtime-control";
import { readExecProfile } from "@/lib/server/exec-profile";
import { getRuntimeServiceManifest } from "@/lib/server/runtime-service-manifest";
import { imageMetadataFromLightX2V } from "@/lib/server/providers/lightx2v/normalize";

const execAsync = promisify(exec);
const BACKEND_CTL = "/usr/bin/sudo -n /usr/local/sbin/homer-backend-ctl";
const LOAD_MODEL_TIMEOUT_MS = 600_000;
const STOP_CHAT_TIMEOUT_MS = 20_000;
const DEFAULT_WARM_ATTEMPTS = 60;
const XDIT_WARM_ATTEMPTS = 300;
// The xDiT exec profile's systemd profile name. xDiT multi-GPU init is slow, so
// it gets a much longer warm window than the single-GPU default.
const XDIT_SYSTEMD_PROFILE = "xdit";

async function backendCtl(command: string, timeout: number) {
  return execAsync(`${BACKEND_CTL} ${command}`, { env: process.env, timeout });
}

async function stopChatRuntime() {
  await execAsync(commandForChatRuntimeStop(), {
    env: process.env,
    timeout: STOP_CHAT_TIMEOUT_MS,
  });
}

async function sleep(ms: number) {
  await new Promise((resolve) => setTimeout(resolve, ms));
}

async function readMetadata(): Promise<{
  model: ImageModelId | null;
  modelLoaded: boolean;
} | null> {
  try {
    const res = await fetch(getLightX2VUrl("/v1/service/metadata"), {
      signal: AbortSignal.timeout(2000),
      cache: "no-store",
    });
    if (!res.ok) return null;
    return imageMetadataFromLightX2V(await res.json());
  } catch {
    return null;
  }
}

export async function readImageBackendMetadata(): Promise<{
  model: ImageModelId | null;
  modelLoaded: boolean;
} | null> {
  return readMetadata();
}

async function waitForBackendState(
  model: ImageModelId,
  loaded: boolean,
  attempts = 60,
  delayMs = 2000
) {
  for (let i = 0; i < attempts; i += 1) {
    const metadata = await readMetadata();
    if (
      metadata &&
      metadata.model === model &&
      metadata.modelLoaded === loaded
    ) {
      return true;
    }
    await sleep(delayMs);
  }
  return false;
}

async function waitForBackendMetadata(
  model: ImageModelId,
  attempts = 60,
  delayMs = 1000
) {
  for (let i = 0; i < attempts; i += 1) {
    const metadata = await readMetadata();
    if (metadata?.model === model) return metadata;
    await sleep(delayMs);
  }
  return null;
}

function systemdProfileFor(model: ImageModelId): string {
  const state = readExecProfile();
  const profileId =
    state?.model === model
      ? state.profile
      : IMAGE_CAPABILITIES[model].defaultExecutionProfile;
  const executionProfiles = IMAGE_CAPABILITIES[model]
    .executionProfiles as readonly ExecutionProfile[];
  const executionProfile = executionProfiles.find(
    (profile) => profile.id === profileId
  );
  const binding = getRuntimeServiceManifest().bindings.image[model];
  const profile = executionProfile?.systemdProfile ?? binding?.profile;
  if (!profile) throw new Error(`${model} is not a systemd-backed image model`);
  return profile;
}

function warmAttemptsFor(model: ImageModelId): number {
  return systemdProfileFor(model) === XDIT_SYSTEMD_PROFILE
    ? XDIT_WARM_ATTEMPTS
    : DEFAULT_WARM_ATTEMPTS;
}

function modelForSystemdProfile(profile: string): ImageModelId | null {
  const manifest = getRuntimeServiceManifest();
  for (const model of IMAGE_MODEL_IDS) {
    if (manifest.bindings.image[model]?.profile === profile) return model;
    if (
      (
        IMAGE_CAPABILITIES[model]
          .executionProfiles as readonly ExecutionProfile[]
      ).some((executionProfile) => executionProfile.systemdProfile === profile)
    ) {
      return model;
    }
  }
  return null;
}

export async function stopAllImageBackends() {
  await backendCtl("stop-all", 20000).catch(() => {});
}

export async function startImageBackend(model: ImageModelId) {
  await backendCtl(`start ${systemdProfileFor(model)}`, 15000);
}

export async function restartImageBackend(model: ImageModelId) {
  await backendCtl(`restart ${systemdProfileFor(model)}`, 15000);
}

export async function findActiveImageBackend(): Promise<ImageModelId | null> {
  try {
    const { stdout } = await backendCtl("active-profile", 3000);
    const profile = stdout.trim();
    return modelForSystemdProfile(profile);
  } catch {
    return null;
  }
}

export async function loadImageBackendModel() {
  const res = await fetch(getLightX2VUrl("/v1/service/load-model"), {
    method: "POST",
    signal: AbortSignal.timeout(LOAD_MODEL_TIMEOUT_MS),
    cache: "no-store",
  });
  if (!res.ok) {
    const detail = await res.text().catch(() => "load-model failed");
    throw new Error(detail || "load-model failed");
  }
}

export async function warmImageBackend(model: ImageModelId) {
  await stopChatRuntime();
  await startImageBackend(model);
  return waitForBackendState(model, false);
}

export async function activateImageBackend(model: ImageModelId) {
  await stopChatRuntime();
  await startImageBackend(model);
  const metadata = await waitForBackendMetadata(
    model,
    warmAttemptsFor(model),
    1000
  );
  if (!metadata) throw new Error(`backend ${model} did not reach warm state`);
  if (!metadata.modelLoaded) {
    await loadImageBackendModel();
    const loaded = await waitForBackendState(
      model,
      true,
      warmAttemptsFor(model),
      3000
    );
    if (!loaded) throw new Error(`backend ${model} did not finish loading`);
  }
}

export async function restartLoadedImageBackend(model: ImageModelId) {
  await stopChatRuntime();
  await restartImageBackend(model);
  const metadata = await waitForBackendMetadata(
    model,
    warmAttemptsFor(model),
    1000
  );
  if (!metadata)
    throw new Error(`backend ${model} did not restart into warm state`);
  if (!metadata.modelLoaded) {
    await loadImageBackendModel();
    const loaded = await waitForBackendState(
      model,
      true,
      warmAttemptsFor(model),
      3000
    );
    if (!loaded)
      throw new Error(`backend ${model} did not reload after restart`);
  }
}

