import { exec } from "node:child_process";
import net from "node:net";
import { promisify } from "node:util";

import type {
  RuntimeServiceReport,
  RuntimeServicesStatus,
} from "@homer/shared/runtime-types";
import { readChatProfileId } from "@/lib/server/chat-profile";
import { getModelEndpoints } from "@/lib/server/conf";
import { getRuntimeServiceManifest } from "@/lib/server/runtime-service-manifest";
import { MODEL_CTL } from "./chat-runtime-control";

const execAsync = promisify(exec);

const UID = process.getuid?.() ?? 1000;
const ENV = {
  ...process.env,
  XDG_RUNTIME_DIR: process.env.XDG_RUNTIME_DIR ?? `/run/user/${UID}`,
  DBUS_SESSION_BUS_ADDRESS:
    process.env.DBUS_SESSION_BUS_ADDRESS ?? `unix:path=/run/user/${UID}/bus`,
};
const BACKEND_CTL = "/usr/bin/sudo -n /usr/local/sbin/homer-backend-ctl";

type UnitSpec = {
  unit: string;
  port?: number;
  system?: boolean;
  profile?: string;
  ctl?: "model" | "backend";
};

const FAILURE_CLASSIFICATION_FOR_PORT = {
  listening: "failed",
  notListening: "crash-loop",
} as const;

function getChatServicePort(): number {
  const activeProfile = readChatProfileId();
  const activeConf = getModelEndpoints({ id: activeProfile })[0] ?? null;
  if (activeConf) return activeConf.port;
  const confs = getModelEndpoints();
  return confs[0]?.port ?? 11434;
}

export function renderRuntimeServiceUnitPattern(
  pattern: string,
  profile: string
): string {
  return pattern.replace("{profile}", profile);
}

export function unitForRuntimeServiceBinding(
  service: ReturnType<typeof getRuntimeServiceManifest>["services"][string],
  profile: string | undefined
): string | null {
  if (!service.systemd) return null;
  if (service.systemd.unit) return service.systemd.unit;
  if (!profile) return null;
  const pattern = service.systemd.unitPattern;
  return pattern ? renderRuntimeServiceUnitPattern(pattern, profile) : null;
}

function getUnitSpecs(): UnitSpec[] {
  const manifest = getRuntimeServiceManifest();
  const specs: UnitSpec[] = [
    { unit: "homer-api@development.service", port: 3201 },
    { unit: "homer-api@production.service", port: 3202 },
    { unit: "homer-terminal.service" },
  ];

  const chatService = manifest.services[manifest.bindings.chat.defaultService];
  if (chatService?.systemd?.unit) {
    specs.push({
      unit: chatService.systemd.unit,
      port: getChatServicePort(),
      ctl: "model",
    });
  }

  for (const binding of Object.values(manifest.bindings.image)) {
    const service = manifest.services[binding.service];
    if (!service) continue;
    const unit = unitForRuntimeServiceBinding(service, binding.profile);
    if (!unit) continue;
    specs.push({
      unit,
      port: binding.baseUrl
        ? Number(new URL(binding.baseUrl).port)
        : service.baseUrl
          ? Number(new URL(service.baseUrl).port)
          : undefined,
      system: service.systemd?.scope === "system",
      profile: binding.profile,
      ctl: service.controller ? "backend" : undefined,
    });
  }

  for (const binding of Object.values(manifest.bindings.asset)) {
    const service = manifest.services[binding.service];
    if (!service) continue;
    const unit = unitForRuntimeServiceBinding(service, binding.profile);
    if (!unit) continue;
    specs.push({
      unit,
      system: service.systemd?.scope === "system",
      profile: binding.profile,
      ctl: service.controller ? "backend" : undefined,
    });
  }

  return specs;
}

async function checkPort(
  port: number,
  host = "127.0.0.1",
  timeoutMs = 500
): Promise<boolean> {
  return new Promise((resolve) => {
    const socket = new net.Socket();
    let settled = false;
    const finish = (ok: boolean) => {
      if (settled) return;
      settled = true;
      socket.destroy();
      resolve(ok);
    };
    socket.setTimeout(timeoutMs);
    socket.once("connect", () => finish(true));
    socket.once("timeout", () => finish(false));
    socket.once("error", () => finish(false));
    socket.connect(port, host);
  });
}

async function checkAnyListeningSocket(port: number): Promise<boolean> {
  if (!Number.isInteger(port) || port < 1 || port > 65535) return false;

  try {
    const { stdout } = await execAsync(`ss -H -ltn 'sport = :${port}'`, {
      timeout: 1_000,
    });
    return stdout.trim().length > 0;
  } catch {
    return false;
  }
}

async function checkPortListening(port: number): Promise<boolean> {
  if (await checkPort(port)) return true;
  return checkAnyListeningSocket(port);
}

async function showUnit(
  unit: string,
  system = false,
  profile?: string,
  ctl?: UnitSpec["ctl"]
): Promise<RuntimeServiceReport> {
  try {
    const cmd =
      ctl === "model"
        ? `${MODEL_CTL} show`
        : system && profile
          ? `${BACKEND_CTL} show ${profile}`
          : `systemctl --user show ${unit} --property=LoadState,ActiveState,SubState,MainPID,NRestarts --no-pager`;
    const { stdout } = await execAsync(cmd, {
      env: ctl || system ? process.env : ENV,
      timeout: 3_000,
    });
    const props: Record<string, string> = {};
    for (const line of stdout.split("\n")) {
      const eq = line.indexOf("=");
      if (eq <= 0) continue;
      props[line.slice(0, eq)] = line.slice(eq + 1);
    }
    return {
      unit,
      loaded: props.LoadState === "loaded",
      activeState: props.ActiveState ?? "unknown",
      subState: props.SubState ?? "unknown",
      mainPid: Number(props.MainPID ?? 0),
      nRestarts: Number(props.NRestarts ?? 0),
      failureClassification: null,
    };
  } catch (err) {
    return {
      unit,
      loaded: false,
      activeState: "error",
      subState: err instanceof Error ? err.message.slice(0, 80) : "exec failed",
      mainPid: 0,
      nRestarts: 0,
      failureClassification: null,
    };
  }
}

export async function getServicesStatus(): Promise<RuntimeServicesStatus> {
  const reports = await Promise.all(
    getUnitSpecs().map(async ({ unit, port, system, profile, ctl }) => {
      const report = await showUnit(unit, system, profile, ctl);
      if (port) {
        report.port = port;
        report.portListening =
          system && profile && report.activeState !== "active"
            ? false
            : await checkPortListening(port);
        if (report.activeState === "failed") {
          report.failureClassification = report.portListening
            ? FAILURE_CLASSIFICATION_FOR_PORT.listening
            : FAILURE_CLASSIFICATION_FOR_PORT.notListening;
        }
      }
      return report;
    })
  );

  const byUnit: Record<string, RuntimeServiceReport> = {};
  for (const r of reports) byUnit[r.unit] = r;

  return {
    timestamp: Date.now(),
    services: byUnit,
  };
}

import { constants } from "node:fs";
import { lstat, open } from "node:fs/promises";
import { join, resolve } from "node:path";
import { Readable } from "node:stream";

import { z } from "zod";
import { homerStateDir } from "./state-dir";

export const videoArtifactKeySchema = z.string().regex(/^[0-9a-f]{64}$/);

function artifactRoot(): string {
  return (
    process.env.HOMER_VIDEO_ARTIFACT_ROOT?.trim() ??
    resolve(homerStateDir(), "video-artifacts")
  );
}

export function videoArtifactUrl(
  artifactKey: string,
  requestUrl: string
): string {
  const key = videoArtifactKeySchema.parse(artifactKey);
  const configuredBaseUrl =
    process.env.HOMER_PUBLIC_BASE_URL?.trim() ||
    process.env.EXPO_PUBLIC_HOMER_BASE_URL?.trim() ||
    (process.env.NODE_ENV === "production" ? "" : requestUrl);
  if (!configuredBaseUrl) {
    throw new Error(
      "HOMER_PUBLIC_BASE_URL or EXPO_PUBLIC_HOMER_BASE_URL is not set in production; configure the public API base URL"
    );
  }
  const baseUrl = new URL(configuredBaseUrl);
  if (baseUrl.protocol !== "https:" && process.env.NODE_ENV === "production") {
    throw new Error("production video artifact URLs require HTTPS");
  }
  return new URL(`/api/video/media/${key}`, baseUrl).toString();
}

function trustedOwnerUid(): number | null {
  if (
    process.env.NODE_ENV === "test" &&
    process.env.HOMER_VIDEO_ARTIFACT_ROOT
  ) {
    return typeof process.getuid === "function" ? process.getuid() : null;
  }
  return 0;
}

function trustedGroupGid(): number | null {
  return typeof process.getgid === "function" ? process.getgid() : null;
}

async function artifactRootIsTrusted(root: string): Promise<boolean> {
  try {
    const metadata = await lstat(root);
    const expectedUid = trustedOwnerUid();
    const expectedGid = trustedGroupGid();
    return (
      metadata.isDirectory() &&
      !metadata.isSymbolicLink() &&
      (expectedUid === null || metadata.uid === expectedUid) &&
      (expectedGid === null || metadata.gid === expectedGid) &&
      (metadata.mode & 0o777) === 0o750
    );
  } catch {
    return false;
  }
}

type ByteRange = { start: number; end: number };

function parseByteRange(value: string, size: number): ByteRange | null {
  const match = /^bytes=(\d*)-(\d*)$/.exec(value);
  if (!match) return null;
  const startText = match[1] ?? "";
  const endText = match[2] ?? "";
  if (!startText && !endText) return null;
  if (!startText) {
    const suffixLength = Number(endText);
    if (!Number.isSafeInteger(suffixLength) || suffixLength <= 0) return null;
    return { start: Math.max(size - suffixLength, 0), end: size - 1 };
  }
  const start = Number(startText);
  const requestedEnd = endText ? Number(endText) : size - 1;
  if (
    !Number.isSafeInteger(start) ||
    !Number.isSafeInteger(requestedEnd) ||
    start < 0 ||
    requestedEnd < start ||
    start >= size
  ) {
    return null;
  }
  return { start, end: Math.min(requestedEnd, size - 1) };
}

function artifactHeaders(input: {
  artifactKey: string;
  contentLength: number;
  contentRange?: string;
}): Headers {
  const headers = new Headers({
    "Accept-Ranges": "bytes",
    "Cache-Control": "private, max-age=3600",
    "Content-Disposition": `inline; filename="homer-video-${input.artifactKey.slice(0, 12)}.mp4"`,
    "Content-Length": String(input.contentLength),
    "Content-Type": "video/mp4",
    "Referrer-Policy": "no-referrer",
    "X-Content-Type-Options": "nosniff",
  });
  if (input.contentRange) headers.set("Content-Range", input.contentRange);
  return headers;
}

export async function videoArtifactResponse(
  artifactKey: string,
  rangeHeader: string | null,
  headOnly = false
): Promise<Response> {
  const parsedKey = videoArtifactKeySchema.safeParse(artifactKey);
  if (!parsedKey.success) {
    return Response.json(
      { code: "invalid_request", message: "invalid artifact capability" },
      { status: 400 }
    );
  }
  const root = artifactRoot();
  if (!(await artifactRootIsTrusted(root))) {
    return Response.json(
      { code: "video_artifact_not_found", message: "artifact not found" },
      { status: 404 }
    );
  }

  let handle;
  try {
    handle = await open(
      join(root, `${parsedKey.data}.mp4`),
      constants.O_RDONLY | constants.O_NOFOLLOW
    );
    const metadata = await handle.stat();
    const expectedUid = trustedOwnerUid();
    const expectedGid = trustedGroupGid();
    if (
      !metadata.isFile() ||
      metadata.size <= 0 ||
      metadata.nlink !== 1 ||
      (expectedUid !== null && metadata.uid !== expectedUid) ||
      (expectedGid !== null && metadata.gid !== expectedGid) ||
      (metadata.mode & 0o777) !== 0o440
    ) {
      await handle.close();
      return Response.json(
        { code: "video_artifact_not_found", message: "artifact not found" },
        { status: 404 }
      );
    }

    const range = rangeHeader
      ? parseByteRange(rangeHeader, metadata.size)
      : { start: 0, end: metadata.size - 1 };
    if (!range) {
      await handle.close();
      return new Response(null, {
        status: 416,
        headers: { "Content-Range": `bytes */${metadata.size}` },
      });
    }
    const contentLength = range.end - range.start + 1;
    const partial = rangeHeader !== null;
    const headers = artifactHeaders({
      artifactKey: parsedKey.data,
      contentLength,
      ...(partial
        ? {
            contentRange: `bytes ${range.start}-${range.end}/${metadata.size}`,
          }
        : {}),
    });
    if (headOnly) {
      await handle.close();
      return new Response(null, { status: partial ? 206 : 200, headers });
    }
    const stream = handle.createReadStream({
      start: range.start,
      end: range.end,
      autoClose: true,
    });
    return new Response(Readable.toWeb(stream) as ReadableStream<Uint8Array>, {
      status: partial ? 206 : 200,
      headers,
    });
  } catch {
    await handle?.close().catch(() => undefined);
    return Response.json(
      { code: "video_artifact_not_found", message: "artifact not found" },
      { status: 404 }
    );
  }
}

import {
  OPENAI_REALTIME_CALLS_URL,
  type VoiceSessionResponse,
  type VoiceTransportProvider,
  voiceSessionRequestSchema,
} from "@homer/shared/voice-types";
import { AccessToken } from "livekit-server-sdk";
import type { RealtimeSessionCreateRequest } from "openai/resources/realtime/realtime";
import { z } from "zod";
import { mintVoiceStreamToken } from "./voice-stream-token";

type VoiceSessionEnv = Partial<Record<string, string | undefined>>;

type VoiceSessionErrorResponse = {
  error: "invalid_voice_session_request";
  message: string;
};

export type VoiceSessionResult =
  | { status: 200; body: VoiceSessionResponse }
  | { status: 503; body: VoiceSessionResponse }
  | { status: 400; body: VoiceSessionErrorResponse };

type VoiceSessionOptions = {
  safetyIdentifier?: string;
};

const TOKEN_TTL_SECONDS = 10 * 60;
const OPENAI_REALTIME_CLIENT_SECRETS_URL =
  "https://api.openai.com/v1/realtime/client_secrets";

const openAIRealtimeSession: RealtimeSessionCreateRequest = {
  type: "realtime",
  model: "gpt-realtime-2.1",
};

const openAIRealtimeClientSecretSchema = z
  .object({ value: z.string().startsWith("ek_") })
  .passthrough();

const voiceAgentSessionStartResponseSchema = z
  .object({
    status: z.literal("accepted"),
    sessionId: z.string().trim().min(1),
    roomName: z.string().trim().min(1),
  })
  .passthrough();

function sessionSafeId(value: string): string {
  const safe = value
    .trim()
    .replace(/[^a-zA-Z0-9_-]+/g, "-")
    .replace(/^-+|-+$/g, "");
  return safe || "session";
}

function voiceAgentUrl(env: VoiceSessionEnv): string | undefined {
  return env.HOMER_VOICE_AGENT_URL?.trim().replace(/\/+$/, "") || undefined;
}

function voiceStreamUrl(env: VoiceSessionEnv): string | undefined {
  return env.HOMER_VOICE_STREAM_URL?.trim() || undefined;
}

async function mintOpenAIRealtimeClientSecret({
  apiKey,
  safetyIdentifier,
  fetchImpl,
}: {
  apiKey: string;
  safetyIdentifier: string;
  fetchImpl: typeof fetch;
}): Promise<string | undefined> {
  let response: Response;
  try {
    response = await fetchImpl(OPENAI_REALTIME_CLIENT_SECRETS_URL, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${apiKey}`,
        "Content-Type": "application/json",
        "OpenAI-Safety-Identifier": safetyIdentifier,
      },
      body: JSON.stringify({ session: openAIRealtimeSession }),
    });
  } catch {
    return undefined;
  }
  if (!response.ok) return undefined;
  const payload: unknown = await response.json().catch(() => undefined);
  const parsed = openAIRealtimeClientSecretSchema.safeParse(payload);
  return parsed.success ? parsed.data.value : undefined;
}

async function createLiveKitJwt({
  apiKey,
  apiSecret,
  identity,
  name,
  roomName,
  metadata,
}: {
  apiKey: string;
  apiSecret: string;
  identity: string;
  name: string;
  roomName: string;
  metadata: Record<string, unknown>;
}): Promise<string> {
  const token = new AccessToken(apiKey, apiSecret, {
    identity,
    name,
    ttl: TOKEN_TTL_SECONDS,
    metadata: JSON.stringify(metadata),
  });
  token.addGrant({
    room: roomName,
    roomJoin: true,
    canPublish: true,
    canSubscribe: true,
  });
  return token.toJwt();
}

async function startVoiceAgentSession({
  agentUrl,
  fetchImpl,
  sessionId,
  roomName,
  transportUrl,
  agentToken,
  request,
}: {
  agentUrl: string;
  fetchImpl: typeof fetch;
  sessionId: string;
  roomName: string;
  transportUrl: string;
  agentToken: string;
  request: {
    conversationId: string;
    modelId: string;
    execution: z.output<typeof voiceSessionRequestSchema>["execution"];
  };
}): Promise<boolean> {
  let response: Response;
  try {
    response = await fetchImpl(`${agentUrl}/session/start`, {
      method: "POST",
      headers: {
        accept: "application/json",
        "content-type": "application/json",
      },
      body: JSON.stringify({
        sessionId,
        roomName,
        conversationId: request.conversationId,
        modelId: request.modelId,
        execution: request.execution,
        transport: {
          provider: "livekit",
          url: transportUrl,
        },
        token: agentToken,
      }),
    });
  } catch {
    return false;
  }
  if (!response.ok) return false;
  const detail = await response.json().catch(() => null);
  const parsed = voiceAgentSessionStartResponseSchema.safeParse(detail);
  return (
    parsed.success &&
    parsed.data.sessionId === sessionId &&
    parsed.data.roomName === roomName
  );
}

type ParsedVoiceSessionRequest = z.output<typeof voiceSessionRequestSchema>;

type VoiceSessionProviderContext = {
  request: ParsedVoiceSessionRequest;
  conversationId: string;
  sessionId: string;
  roomName: string;
  env: VoiceSessionEnv;
  now: () => number;
  fetchImpl: typeof fetch;
  options: VoiceSessionOptions;
};

type VoiceSessionProvider = (
  context: VoiceSessionProviderContext
) => Promise<VoiceSessionResult>;

function unavailable(message: string): VoiceSessionResult {
  return {
    status: 503,
    body: {
      status: "unavailable",
      reason: "voice_not_configured",
      message,
    },
  };
}

async function createOpenAIVoiceSession({
  env,
  fetchImpl,
  options,
  sessionId,
  roomName,
}: VoiceSessionProviderContext): Promise<VoiceSessionResult> {
  const apiKey = env.OPENAI_API_KEY?.trim();
  const safetyIdentifier = options.safetyIdentifier?.trim();
  if (!apiKey || !safetyIdentifier) {
    return unavailable(
      "OpenAI Realtime voice is not configured on this Homer."
    );
  }

  const token = await mintOpenAIRealtimeClientSecret({
    apiKey,
    safetyIdentifier,
    fetchImpl,
  });
  if (!token) {
    return unavailable("OpenAI Realtime voice could not create a session.");
  }

  return {
    status: 200,
    body: {
      status: "configured",
      sessionId,
      roomName,
      transport: {
        provider: "openai",
        url: OPENAI_REALTIME_CALLS_URL,
      },
      token,
    },
  };
}

async function createStreamingVoiceSession({
  env,
  now,
  sessionId,
  roomName,
}: VoiceSessionProviderContext): Promise<VoiceSessionResult> {
  const streamUrl = voiceStreamUrl(env);
  const streamSecret = env.HOMER_VOICE_STREAM_SECRET?.trim();
  if (!streamUrl || !streamSecret) {
    return unavailable(
      "Local voice streaming is not configured on this Homer."
    );
  }

  const expiresAt = new Date(now() + TOKEN_TTL_SECONDS * 1000).toISOString();
  return {
    status: 200,
    body: {
      status: "configured",
      sessionId,
      roomName,
      transport: {
        provider: "streaming",
        url: streamUrl,
      },
      token: mintVoiceStreamToken(
        sessionId,
        streamSecret,
        now(),
        TOKEN_TTL_SECONDS * 1000
      ),
      expiresAt,
    },
  };
}

async function createLiveKitVoiceSession({
  request,
  env,
  now,
  fetchImpl,
  conversationId,
  sessionId,
  roomName,
}: VoiceSessionProviderContext): Promise<VoiceSessionResult> {
  const transportUrl = env.HOMER_VOICE_TRANSPORT_URL?.trim();
  const apiKey = env.HOMER_VOICE_LIVEKIT_API_KEY?.trim();
  const apiSecret = env.HOMER_VOICE_LIVEKIT_API_SECRET?.trim();
  const agentUrl = voiceAgentUrl(env);
  if (!transportUrl || !apiKey || !apiSecret || !agentUrl) {
    return unavailable("Local voice is not configured on this Homer.");
  }

  const expiresAt = new Date(now() + TOKEN_TTL_SECONDS * 1000).toISOString();
  const metadata = {
    conversationId: request.conversationId,
    modelId: request.modelId,
    execution: request.execution,
  };
  const clientToken = await createLiveKitJwt({
    apiKey,
    apiSecret,
    identity: `voice-${conversationId}`,
    name: "Homer Voice",
    roomName,
    metadata,
  });
  const agentToken = await createLiveKitJwt({
    apiKey,
    apiSecret,
    identity: `voice-agent-${conversationId}`,
    name: "Homer Voice Agent",
    roomName,
    metadata: { ...metadata, role: "voice-agent" },
  });

  const agentStarted = await startVoiceAgentSession({
    agentUrl,
    fetchImpl,
    sessionId,
    roomName,
    transportUrl,
    agentToken,
    request,
  });
  if (!agentStarted) {
    return unavailable("Local voice agent could not start the conversation.");
  }

  return {
    status: 200,
    body: {
      status: "configured",
      sessionId,
      roomName,
      transport: {
        provider: "livekit",
        url: transportUrl,
      },
      token: clientToken,
      expiresAt,
    },
  };
}

const voiceSessionProviders = {
  livekit: createLiveKitVoiceSession,
  streaming: createStreamingVoiceSession,
  openai: createOpenAIVoiceSession,
} satisfies Record<VoiceTransportProvider, VoiceSessionProvider>;

export async function createVoiceSession(
  body: unknown,
  env: VoiceSessionEnv = process.env,
  now: () => number = Date.now,
  fetchImpl: typeof fetch = fetch,
  options: VoiceSessionOptions = {}
): Promise<VoiceSessionResult> {
  const parsed = voiceSessionRequestSchema.safeParse(body);
  if (!parsed.success) {
    return {
      status: 400,
      body: {
        error: "invalid_voice_session_request",
        message: "Voice session request is invalid.",
      },
    };
  }

  const conversationId = sessionSafeId(parsed.data.conversationId);
  const roomName = `homer-voice-${conversationId}`;
  const sessionId = `voice_${conversationId}_${now()}`;
  return voiceSessionProviders[parsed.data.transportProvider]({
    request: parsed.data,
    conversationId,
    sessionId,
    roomName,
    env,
    now,
    fetchImpl,
    options,
  });
}

import { z } from "zod";
import type { ApiProblem } from "@homer/shared/contracts/api-problem";
import { voiceOptionIdSchema } from "@homer/shared/voice-types";

type VoiceTtsEnv = Partial<Record<string, string | undefined>>;

const MAX_TTS_TEXT_CHARS = 5000;

const voiceTtsRequestSchema = z
  .object({
    text: z.string().trim().min(1).max(MAX_TTS_TEXT_CHARS),
    voice: voiceOptionIdSchema.optional(),
    lang: z.string().trim().min(1).optional(),
    speed: z.number().min(0.5).max(1.5).optional(),
  })
  .strict();

type VoiceTtsErrorResponse = ApiProblem & {
  code:
    | "invalid_voice_tts_request"
    | "voice_tts_unavailable"
    | "voice_tts_failed";
};

export type VoiceTtsResult =
  | { status: 200; body: ArrayBuffer; contentType: "audio/wav" }
  | { status: 400 | 502 | 503; body: VoiceTtsErrorResponse };

function voiceAgentUrl(env: VoiceTtsEnv): string | undefined {
  return env.HOMER_VOICE_AGENT_URL?.trim().replace(/\/+$/, "") || undefined;
}

export async function createVoiceTts(
  body: unknown,
  env: VoiceTtsEnv = process.env,
  fetchImpl: typeof fetch = fetch
): Promise<VoiceTtsResult> {
  const parsed = voiceTtsRequestSchema.safeParse(body);
  if (!parsed.success) {
    return {
      status: 400,
      body: {
        code: "invalid_voice_tts_request",
        message: "Voice TTS request is invalid.",
      },
    };
  }

  const agentUrl = voiceAgentUrl(env);
  if (!agentUrl) {
    return {
      status: 503,
      body: {
        code: "voice_tts_unavailable",
        message: "Local voice synthesis is not reachable on this Homer.",
      },
    };
  }

  const endpoint = `${agentUrl}/tts`;
  let response: Response;
  try {
    response = await fetchImpl(endpoint, {
      method: "POST",
      headers: {
        accept: "audio/wav",
        "content-type": "application/json",
      },
      body: JSON.stringify(parsed.data),
    });
  } catch {
    return {
      status: 503,
      body: {
        code: "voice_tts_unavailable",
        message: "Local voice synthesis is not reachable on this Homer.",
      },
    };
  }

  if (!response.ok) {
    return {
      status: response.status >= 500 ? 502 : 400,
      body: {
        code:
          response.status >= 500
            ? "voice_tts_failed"
            : "invalid_voice_tts_request",
        message:
          response.status >= 500
            ? "Local voice synthesis failed."
            : "Voice TTS request is invalid.",
      },
    };
  }

  return {
    status: 200,
    contentType: "audio/wav",
    body: await response.arrayBuffer(),
  };
}

import { readFileSync, realpathSync } from "node:fs";
import { mkdir, readFile, realpath, rename, writeFile } from "node:fs/promises";
import {
  basename,
  dirname,
  isAbsolute,
  relative,
  resolve,
  sep,
} from "node:path";
import {
  type WorkspaceAddProjectInput,
  type WorkspaceProject,
  type WorkspaceProjectRegistry,
  type WorkspaceSelectProjectInput,
  workspaceProjectRegistrySchema,
} from "@homer/shared/workspace-types";

type ProjectEnv = Record<string, string | undefined>;

type RegistryOptions = {
  env?: ProjectEnv;
};

const REGISTRY_FILE = ".homer-project-registry.json";

function nowIso() {
  return new Date().toISOString();
}

export function defaultWorkspaceRoot(env: ProjectEnv = process.env): string {
  return resolve(
    /* turbopackIgnore: true */ env.HOMER_WORKSPACE_ROOT ??
      env.HOMER_STATE_DIR ??
      env.INIT_CWD ??
      /* turbopackIgnore: true */ process.cwd()
  );
}

function stateDir(env: ProjectEnv = process.env): string {
  return resolve(
    /* turbopackIgnore: true */ env.HOMER_STATE_DIR ?? defaultWorkspaceRoot(env)
  );
}

function registryPath(env: ProjectEnv = process.env): string {
  return resolve(/* turbopackIgnore: true */ stateDir(env), REGISTRY_FILE);
}

function slugForName(name: string): string {
  const slug = name
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
  return slug || "project";
}

function uniqueProjectId(
  preferred: string,
  projects: WorkspaceProject[],
  path: string
): string {
  const existing = projects.find((project) => project.path === path);
  if (existing) return existing.id;

  const used = new Set(projects.map((project) => project.id));
  if (!used.has(preferred)) return preferred;
  for (let suffix = 2; ; suffix += 1) {
    const candidate = `${preferred}-${suffix}`;
    if (!used.has(candidate)) return candidate;
  }
}

export function defaultWorkspaceProject(
  root = defaultWorkspaceRoot()
): WorkspaceProject {
  const resolvedRoot = resolve(/* turbopackIgnore: true */ root);
  const name = basename(resolvedRoot) || "workspace";
  return {
    id: slugForName(name),
    name,
    path: resolvedRoot,
    addedAt: nowIso(),
    lastOpenedAt: nowIso(),
  };
}

function fallbackRegistry(
  env: ProjectEnv = process.env
): WorkspaceProjectRegistry {
  const project = defaultWorkspaceProject(defaultWorkspaceRoot(env));
  return {
    activeProjectId: project.id,
    projects: [project],
  };
}

function normalizeRegistry(
  value: unknown,
  env: ProjectEnv = process.env
): WorkspaceProjectRegistry {
  const parsed = workspaceProjectRegistrySchema.safeParse(value);
  if (!parsed.success) return fallbackRegistry(env);
  const activeExists = parsed.data.projects.some(
    (project) => project.id === parsed.data.activeProjectId
  );
  if (activeExists) return parsed.data;
  return {
    ...parsed.data,
    activeProjectId:
      parsed.data.projects[0]?.id ?? fallbackRegistry(env).activeProjectId,
  };
}

export async function readWorkspaceProjectRegistry({
  env = process.env,
}: RegistryOptions = {}): Promise<WorkspaceProjectRegistry> {
  try {
    const raw = await readFile(
      /* turbopackIgnore: true */ registryPath(env),
      "utf8"
    );
    return normalizeRegistry(JSON.parse(raw), env);
  } catch {
    return fallbackRegistry(env);
  }
}

export function readWorkspaceProjectRegistrySync(
  env: ProjectEnv = process.env
): WorkspaceProjectRegistry {
  try {
    return normalizeRegistry(
      JSON.parse(
        readFileSync(/* turbopackIgnore: true */ registryPath(env), "utf8")
      ),
      env
    );
  } catch {
    return fallbackRegistry(env);
  }
}

async function writeRegistry(
  registry: WorkspaceProjectRegistry,
  env: ProjectEnv = process.env
): Promise<WorkspaceProjectRegistry> {
  await mkdir(/* turbopackIgnore: true */ dirname(registryPath(env)), {
    recursive: true,
  });
  const tmp = `${registryPath(env)}.${process.pid}.tmp`;
  await writeFile(
    /* turbopackIgnore: true */ tmp,
    `${JSON.stringify(registry, null, 2)}\n`,
    "utf8"
  );
  await rename(
    /* turbopackIgnore: true */ tmp,
    /* turbopackIgnore: true */ registryPath(env)
  );
  return registry;
}

function allowedProjectRoots(env: ProjectEnv = process.env): string[] {
  const explicit = env.HOMER_PROJECT_ROOTS?.split(":")
    .map((entry) => entry.trim())
    .filter(Boolean);
  const roots = explicit?.length
    ? explicit
    : [
        env.HOME ? resolve(env.HOME, "code") : null,
        dirname(defaultWorkspaceRoot(env)),
      ].filter((entry): entry is string => Boolean(entry));
  return roots.map((root) => resolve(/* turbopackIgnore: true */ root));
}

function canonicalProjectRoot(root: string): string {
  try {
    return realpathSync(/* turbopackIgnore: true */ root);
  } catch {
    return root;
  }
}

async function canonicalProjectRootAsync(root: string): Promise<string> {
  try {
    return await realpath(/* turbopackIgnore: true */ root);
  } catch {
    return root;
  }
}

function isPathUnderRoot(path: string, root: string): boolean {
  const rel = relative(root, path).replaceAll(sep, "/");
  return rel === "" || (!rel.startsWith("..") && !isAbsolute(rel));
}

function assertAllowedProjectPath(path: string, env: ProjectEnv): string {
  if (!isAbsolute(path)) throw new Error("Project path must be absolute");
  const resolved = realpathSync(/* turbopackIgnore: true */ path);
  const roots = allowedProjectRoots(env);
  const allowed = roots
    .map(canonicalProjectRoot)
    .some((root) => isPathUnderRoot(resolved, root));
  if (!allowed) {
    throw new Error(`Project path must be under one of: ${roots.join(", ")}`);
  }
  return resolved;
}

async function assertAllowedProjectPathAsync(path: string, env: ProjectEnv) {
  if (!isAbsolute(path)) throw new Error("Project path must be absolute");
  const resolved = await realpath(/* turbopackIgnore: true */ path);
  const roots = allowedProjectRoots(env);
  const canonicalRoots = await Promise.all(
    roots.map(canonicalProjectRootAsync)
  );
  const allowed = canonicalRoots.some((root) =>
    isPathUnderRoot(resolved, root)
  );
  if (!allowed) {
    throw new Error(`Project path must be under one of: ${roots.join(", ")}`);
  }
  return resolved;
}

export async function addWorkspaceProject(
  input: WorkspaceAddProjectInput,
  { env = process.env }: RegistryOptions = {}
): Promise<WorkspaceProjectRegistry> {
  const projectPath = await assertAllowedProjectPathAsync(input.path, env);
  const registry = await readWorkspaceProjectRegistry({ env });
  const name = input.name?.trim() || basename(projectPath) || "workspace";
  const id = uniqueProjectId(slugForName(name), registry.projects, projectPath);
  const existing = registry.projects.find(
    (project) => project.path === projectPath
  );
  const project: WorkspaceProject = {
    id,
    name,
    path: projectPath,
    addedAt: existing?.addedAt ?? nowIso(),
    lastOpenedAt: nowIso(),
  };
  const projects = [
    project,
    ...registry.projects.filter(
      (entry) => entry.id !== id && entry.path !== projectPath
    ),
  ];
  return writeRegistry({ activeProjectId: id, projects }, env);
}

export async function selectWorkspaceProject(
  input: WorkspaceSelectProjectInput,
  { env = process.env }: RegistryOptions = {}
): Promise<WorkspaceProjectRegistry> {
  const registry = await readWorkspaceProjectRegistry({ env });
  const project = registry.projects.find(
    (entry) => entry.id === input.projectId
  );
  if (!project)
    throw new Error(`Unknown workspace project: ${input.projectId}`);
  const projects = registry.projects.map((entry) =>
    entry.id === project.id ? { ...entry, lastOpenedAt: nowIso() } : entry
  );
  return writeRegistry({ activeProjectId: project.id, projects }, env);
}

export function activeWorkspaceProject(
  registry = readWorkspaceProjectRegistrySync()
): WorkspaceProject {
  return (
    registry.projects.find(
      (project) => project.id === registry.activeProjectId
    ) ??
    registry.projects[0] ??
    defaultWorkspaceProject()
  );
}

export function workspaceProjectRoot(
  registry = readWorkspaceProjectRegistrySync()
): string {
  return activeWorkspaceProject(registry).path;
}

export function workspaceProjectRootSync(
  env: ProjectEnv = process.env
): string {
  const registry = readWorkspaceProjectRegistrySync(env);
  const project = activeWorkspaceProject(registry);
  return assertAllowedProjectPath(project.path, env);
}

