const execFileAsync = promisify(execFile);
const MEMORY_FILE = resolve(homedir(), "notes", ".memory.json");
const jsonRecordSchema = z.record(z.string(), z.unknown());
const RG_CANDIDATES = [
  process.env.RG_PATH,
  "rg",
  "/usr/bin/rg",
  "/opt/homebrew/bin/rg",
  "/usr/local/bin/rg",
].filter((candidate): candidate is string => !!candidate?.trim());

// ── Access control ────────────────────────────────────────────────────────────

const DEFAULT_READ_ROOTS: string[] = [];
const DEFAULT_WRITE_ROOTS: string[] = [];
const MAX_READ_BYTES = 1_000_000;
const CODE_ROOT = resolve(homedir(), "code");

function resolvePath(p: string): string {
  return resolve(p.replace(/^~/, homedir()));
}

function resolveRoot(root: string): string {
  return resolve(root.replace(/^~/, homedir()));
}

function containsGlobSyntax(value: string): boolean {
  return /[*?[{]/.test(value);
}

function firstPathSegment(value: string): string {
  return value.replace(/^~\//, "").split(/[\\/]/)[0] ?? "";
}

function isBroadCodeRootPattern(pattern: string): boolean {
  const first = firstPathSegment(pattern);
  return first === "**" || containsGlobSyntax(first);
}

function searchSpecificityMessage(toolName: "grep" | "glob"): string {
  return [
    `Search too broad for ${toolName}.`,
    "Narrow the search to one repository or concrete subdirectory under ~/code before using recursive or wildcard patterns.",
    "Preferred next step: call search_code or safe_search with a repo and file_types.",
    "Examples: set cwd/path to ~/code/homer, or use a repo-qualified glob like homer/**/*.ts.",
  ].join(" ");
}

function assertSearchSpecificEnough({
  toolName,
  root,
  inputPath,
  pattern,
  glob,
}: {
  toolName: "grep" | "glob";
  root: string;
  inputPath?: string;
  pattern?: string;
  glob?: string;
}): void {
  if (inputPath && containsGlobSyntax(inputPath)) {
    throw new Error(
      `${searchSpecificityMessage(toolName)} The path/cwd must be concrete; put file filters in the glob or pattern field.`
    );
  }

  if (!isSameOrChild(root, CODE_ROOT) || root !== CODE_ROOT) return;

  const broadPattern = pattern ? isBroadCodeRootPattern(pattern) : false;
  const broadGlob = glob ? isBroadCodeRootPattern(glob) : false;
  const grepWithoutGlob = toolName === "grep" && !glob;
  if (broadPattern || broadGlob || grepWithoutGlob) {
    throw new Error(searchSpecificityMessage(toolName));
  }
}

function isMaxBufferError(err: unknown): boolean {
  if (!(err instanceof Error)) return false;
  return /maxBuffer|stdout maxBuffer|stderr maxBuffer/i.test(err.message);
}

function hasProcessExitCode(err: unknown, code: number): boolean {
  return (
    typeof err === "object" &&
    err !== null &&
    "code" in err &&
    err.code === code
  );
}

async function pathExists(path: string): Promise<boolean> {
  try {
    await stat(path);
    return true;
  } catch {
    return false;
  }
}

async function runGit(args: string[], cwd: string): Promise<string> {
  const { stdout } = await execFileAsync("git", args, {
    cwd,
    timeout: 10_000,
    maxBuffer: 200_000,
  });
  return stdout.trim();
}

async function maybeRunGit(
  args: string[],
  cwd: string
): Promise<string | null> {
  try {
    return await runGit(args, cwd);
  } catch {
    return null;
  }
}

async function resolveRepoCheckout(repo: string) {
  const input = repo.trim();
  const candidates = [
    input.startsWith("~/") || input.startsWith("/") ? resolvePath(input) : null,
    resolve(CODE_ROOT, input),
  ].filter((candidate): candidate is string => Boolean(candidate));

  const localCandidates = [];
  for (const candidate of candidates) {
    if (!(await pathExists(join(candidate, ".git")))) continue;
    localCandidates.push(candidate);
  }

  if (localCandidates.length === 0) {
    const entries = await readdir(CODE_ROOT, { withFileTypes: true }).catch(
      () => []
    );
    for (const entry of entries) {
      if (!entry.isDirectory()) continue;
      const candidate = join(CODE_ROOT, entry.name);
      if (!(await pathExists(join(candidate, ".git")))) continue;
      const branch = await maybeRunGit(
        ["rev-parse", "--abbrev-ref", "HEAD"],
        candidate
      );
      const remoteURL = await maybeRunGit(
        ["remote", "get-url", "origin"],
        candidate
      );
      if (
        entry.name === input ||
        branch === input ||
        remoteURL?.toLowerCase().includes(input.toLowerCase())
      ) {
        localCandidates.push(candidate);
        break;
      }
    }
  }

  const localPath = localCandidates[0];
  if (localPath) {
    assertReadAllowed(localPath, "repo_resolve");
    const [branch, head, remoteURL, status] = await Promise.all([
      maybeRunGit(["rev-parse", "--abbrev-ref", "HEAD"], localPath),
      maybeRunGit(["rev-parse", "HEAD"], localPath),
      maybeRunGit(["remote", "get-url", "origin"], localPath),
      maybeRunGit(["status", "--porcelain"], localPath),
    ]);
    return {
      name: basename(localPath),
      path: localPath,
      location: "local",
      branch: branch ?? "unknown",
      head,
      remoteURL,
      dirty: Boolean(status?.trim()),
      status: status?.split("\n").filter(Boolean).slice(0, 50),
    };
  }

  const tailnetMatch = input.match(
    /^(?:(?<user>[^@:\s]+)@)?(?<host>[^:\s]+):(?<path>\/.+)$/
  );
  const path = tailnetMatch?.groups?.path;
  const host = tailnetMatch?.groups?.host;
  if (path !== undefined && host !== undefined) {
    return {
      name: basename(path),
      path,
      location: "tailscale-remote",
      host,
      user: tailnetMatch?.groups?.user,
      branch: "unknown",
      remoteURL: null,
      dirty: null,
      status: [],
    };
  }

  throw new Error(
    `Unable to resolve repo "${repo}". Use a repo name under ~/code, a local path, a branch name, or user@host:/path.`
  );
}

async function resolveSearchRoot(repo: string) {
  const input = repo.trim();
  if (input.startsWith("~/") || input.startsWith("/")) {
    const localPath = resolvePath(input);
    if (localPath === CODE_ROOT) {
      throw new Error(
        "search_code needs one repo or non-code directory, not ~/code. Use homer.inventory.projects, then rerun search_code with a specific repo name."
      );
    }
    const info = await stat(localPath).catch(() => null);
    if (info?.isDirectory()) {
      assertReadAllowed(localPath, "search_code");
      return {
        name: basename(localPath),
        path: localPath,
        location: "local",
        branch: null,
        head: null,
        remoteURL: null,
        dirty: null,
        status: [],
      };
    }
  }

  try {
    return await resolveRepoCheckout(repo);
  } catch (repoError) {
    if (!(input.startsWith("~/") || input.startsWith("/"))) throw repoError;

    const localPath = resolvePath(input);
    const info = await stat(localPath).catch(() => null);
    if (!info?.isDirectory()) throw repoError;

    assertReadAllowed(localPath, "search_code");
    return {
      name: basename(localPath),
      path: localPath,
      location: "local",
      branch: null,
      head: null,
      remoteURL: null,
      dirty: null,
      status: [],
    };
  }
}

function fileTypeGlobs(fileTypes: string[] | undefined): string[] {
  if (!fileTypes?.length) return [];
  return fileTypes.map((type) => {
    const cleaned = type.replace(/^\./, "").trim();
    return cleaned ? `**/*.${cleaned}` : "**/*";
  });
}

function parseRipgrepMatches(output: string, root: string) {
  return output
    .split("\n")
    .filter(Boolean)
    .map((line) => {
      const match = line.match(/^(.+?):(\d+):(.*)$/);
      if (!match) return null;
      const file = match[1];
      const lineNumber = match[2];
      const text = match[3];
      if (
        file === undefined ||
        lineNumber === undefined ||
        text === undefined
      ) {
        return null;
      }
      return {
        file: relative(root, file),
        line: Number(lineNumber),
        text,
      };
    })
    .filter((match): match is { file: string; line: number; text: string } =>
      Boolean(match)
    );
}

function parseSseEvents(sse: string) {
  const events: Array<Record<string, unknown>> = [];
  for (const line of sse.split(/\r?\n/)) {
    if (!line.startsWith("data: ")) continue;
    const data = line.slice(6);
    if (data === "[DONE]") continue;
    try {
      const parsed = jsonRecordSchema.parse(JSON.parse(data));
      events.push(parsed);
    } catch {
      /* ignore malformed stream fragments */
    }
  }
  return events;
}

function textFromEvents(events: Array<Record<string, unknown>>) {
  return events
    .map((event) =>
      (event.type === "text-delta" || event.type === "text") &&
      typeof event.delta === "string"
        ? event.delta
        : typeof event.text === "string"
          ? event.text
          : ""
    )
    .join("")
    .trim();
}

function toolRule(toolName: string) {
  return readAgentRuntimeConfig().toolPathRules[toolName] ?? {};
}

function pathRootsForTool(
  toolName: string,
  kind: "readRoots" | "writeRoots"
): string[] {
  const fallback =
    kind === "readRoots" ? DEFAULT_READ_ROOTS : DEFAULT_WRITE_ROOTS;
  const configured = toolRule(toolName)[kind];
  return (configured && configured.length > 0 ? configured : fallback).map(
    resolveRoot
  );
}

function configuredRoots(
  toolName: string,
  kind: "blockedRoots" | "protectedRoots"
): string[] {
  return (toolRule(toolName)[kind] ?? []).map(resolveRoot);
}

function isSameOrChild(path: string, root: string): boolean {
  if (root === "/") return path === "/";
  return path === root || path.startsWith(`${root}/`);
}

function isSameOrAncestor(path: string, root: string): boolean {
  if (path === "/") return true;
  return path === root || root.startsWith(`${path}/`);
}

function assertNotBlocked(absPath: string, toolName: string): void {
  const blocked = configuredRoots(toolName, "blockedRoots");
  const match = blocked.find((root) => isSameOrChild(absPath, root));
  if (match) {
    throw new Error(
      `Path is blocked for ${toolName}: ${absPath} under ${match}`
    );
  }
}

function assertPathInRoots(
  absPath: string,
  roots: string[],
  message: string
): void {
  if (!roots.some((r) => isSameOrChild(absPath, r))) {
    throw new Error(
      `${message}: ${absPath}. Allowed roots: ${roots.join(", ")}`
    );
  }
}

function assertReadAllowed(absPath: string, toolName: string): void {
  assertNotBlocked(absPath, toolName);
  assertPathInRoots(
    absPath,
    pathRootsForTool(toolName, "readRoots"),
    `Path not in allowed read roots for ${toolName}`
  );
}

function assertWriteAllowed(absPath: string, toolName: string): void {
  assertNotBlocked(absPath, toolName);
  assertPathInRoots(
    absPath,
    pathRootsForTool(toolName, "writeRoots"),
    `Path not in allowed write roots for ${toolName}`
  );
}

function assertDestructivePathAllowed(
  absPath: string,
  toolName: string,
  options: { recursive?: boolean } = {}
): void {
  const rule = toolRule(toolName);
  if (options.recursive && rule.allowRecursiveDelete !== true) {
    throw new Error(
      `Recursive destructive operations are disabled for ${toolName}`
    );
  }
  const protectedRoots = configuredRoots(toolName, "protectedRoots");
  const match = protectedRoots.find((root) => isSameOrAncestor(absPath, root));
  if (match) {
    throw new Error(
      `Refusing destructive operation on protected path for ${toolName}: ${absPath} protects ${match}`
    );
  }
}

function shellTokenToPath(token: string, cwd: string): string | null {
  const cleaned = token.replace(/^['"]|['"]$/g, "").replace(/[,*?[{].*$/, "");
  if (!cleaned || cleaned.startsWith("-")) return null;
  if (cleaned.includes("=")) return null;
  if (cleaned === ".") return cwd;
  if (cleaned === "..") return resolve(cwd, "..");
  if (cleaned.startsWith("~/") || cleaned === "~") return resolvePath(cleaned);
  if (cleaned.startsWith("/")) return resolve(cleaned);
  if (cleaned.startsWith("./") || cleaned.startsWith("../")) {
    return resolve(cwd, cleaned);
  }
  return null;
}

function assertShellDestructiveAllowed(
  command: string,
  cwd: string
): string | null {
  const destructive =
    /\b(rm|rmdir|shred|truncate)\b|\bfind\b[\s\S]*\s-delete\b|\bgit\s+clean\b/.test(
      command
    );
  if (!destructive) return null;
  const rule = toolRule("bash");
  if (rule.allowShellDestructive !== true) {
    throw new Error("Destructive shell commands are disabled for bash");
  }

  const tokens = command.split(/\s+/);
  for (let i = 0; i < tokens.length; i++) {
    const token = tokens[i];
    if (token === undefined || !/^(rm|rmdir|shred|truncate)$/.test(token)) {
      continue;
    }
    for (const target of tokens.slice(i + 1)) {
      if (/^(;|&&|\|\|)$/.test(target)) break;
      const absPath = shellTokenToPath(target, cwd);
      if (!absPath) continue;
      assertWriteAllowed(absPath, "bash");
      assertDestructivePathAllowed(absPath, "bash", {
        recursive: /(^|\s)rm\s+[^;&|]*-[^\s]*r/.test(command),
      });
    }
  }
  return null;
}

function isBinary(buf: Buffer): boolean {
  return buf.subarray(0, 8000).includes(0);
}

async function executableExists(path: string): Promise<boolean> {
  if (!path.startsWith("/")) return true;
  try {
    await access(path);
    return true;
  } catch {
    return false;
  }
}

async function resolveRipgrep(): Promise<string> {
  for (const candidate of RG_CANDIDATES) {
    if (await executableExists(candidate)) return candidate;
  }
  return "rg";
}

function toolError(err: unknown): string {
  return `tool error: ${err instanceof Error ? err.message : String(err)}`;
}

// Blocked shell patterns — anything that could exfiltrate or destroy
const BLOCKED_PATTERNS = [
  /rm\s+-rf?\s+[/~]/,
  />\s*\/etc/,
  /curl.*\|\s*bash/,
  /wget.*\|\s*bash/,
  /chmod\s+[0-7]*7/,
  /sudo/,
  /dd\s+if=/,
];

type LocalAgentToolInputDefinition<
  Name extends string,
  Schema extends z.ZodTypeAny,
> = {
  name: Name;
  title: string;
  description: string;
  inputSchema: Schema;
  annotations?: ToolAnnotations;
  execute: (input: z.infer<Schema>) => Promise<unknown>;
};

export type LocalAgentToolDefinition<
  Name extends string,
  Schema extends z.ZodTypeAny,
> = PiToolSource & LocalAgentToolInputDefinition<Name, Schema>;

function piParametersFromZod(schema: z.ZodTypeAny): PiToolSource["parameters"] {
  const jsonSchema = z.toJSONSchema(schema) as Record<string, unknown>;
  delete jsonSchema.$schema;
  return jsonSchema;
}

function defineLocalAgentTool<Name extends string, Schema extends z.ZodTypeAny>(
  definition: LocalAgentToolInputDefinition<Name, Schema>
): LocalAgentToolDefinition<Name, Schema> {
  return {
    ...definition,
    parameters: piParametersFromZod(definition.inputSchema),
    parseAndExecute: async (rawInput: unknown) => {
      const parsed = definition.inputSchema.safeParse(rawInput);
      if (!parsed.success) {
        return {
          error: "invalid tool input",
          issues: parsed.error.issues,
        };
      }
      try {
        return await definition.execute(parsed.data);
      } catch (err) {
        return { error: toolError(err) };
      }
    },
  };
}

function createAiToolFromLocalDefinition<Schema extends z.ZodTypeAny>(
  definition: LocalAgentToolDefinition<string, Schema>
) {
  return tool<z.infer<Schema>, string>({
    description: definition.description,
    inputSchema: definition.inputSchema,
    execute: async (input) => {
      let result: unknown;
      try {
        result = await definition.execute(input);
      } catch (err) {
        result = toolError(err);
      }
      return typeof result === "string"
        ? result
        : JSON.stringify(result, null, 2);
    },
  });
}

const frontierConsultDefinition = defineLocalAgentTool({
  name: FRONTIER_CONSULT_TOOL_NAME,
  title: FRONTIER_CONSULT_TOOL_TITLE,
  description: FRONTIER_CONSULT_TOOL_DESCRIPTION,
  inputSchema: frontierConsultInputSchema,
  execute: executeFrontierConsult,
});

function frontierConsultDefinitionsForMode(mode: AgentToolMode) {
  if (mode !== "workspace" && mode !== "all") return [];
  return [frontierConsultDefinition];
}

function createFrontierConsultAiToolsForMode(mode: AgentToolMode): ToolSet {
  return Object.fromEntries(
    frontierConsultDefinitionsForMode(mode).map((definition) => [
      definition.name,
      createAiToolFromLocalDefinition(definition),
    ])
  );
}

// ── Tools ─────────────────────────────────────────────────────────────────────

const fetchUrl = tool({
  description:
    "Fetch the text content of a URL. Use to read web pages, docs, or any public resource.",
  inputSchema: z.object({ url: z.string().url() }),
  execute: async (input) => {
    const res = await fetch(input.url, {
      signal: AbortSignal.timeout(15_000),
      headers: { "User-Agent": "Mozilla/5.0 (compatible; assistant-bot/1.0)" },
    });
    if (!res.ok) return `HTTP ${res.status}: ${res.statusText}`;
    const text = (await res.text())
      .replace(/<script[\s\S]*?<\/script>/gi, "")
      .replace(/<style[\s\S]*?<\/style>/gi, "")
      .replace(/<[^>]+>/g, " ")
      .replace(/&nbsp;/g, " ")
      .replace(/&amp;/g, "&")
      .replace(/&lt;/g, "<")
      .replace(/&gt;/g, ">")
      .replace(/&quot;/g, '"')
      .replace(/\s{2,}/g, " ")
      .trim();
    return text.length > 12_000
      ? text.slice(0, 12_000) + "\n…[truncated]"
      : text;
  },
});

const readFileDefinition = defineLocalAgentTool({
  name: "read_file",
  title: "Read File",
  description: "Read a file. Allowed: ~/code/ and ~/notes/.",
  inputSchema: z.object({
    path: z.string().describe("File path (~/... or absolute)"),
    offset: z
      .number()
      .int()
      .min(0)
      .optional()
      .describe("Start line (0-indexed)"),
    limit: z
      .number()
      .int()
      .min(1)
      .max(2000)
      .optional()
      .describe("Max lines to return"),
  }),
  execute: async (input) => {
    const absPath = resolvePath(input.path);
    assertReadAllowed(absPath, "read_file");
    const buf = await readFile(absPath);
    if (isBinary(buf)) return `[binary, ${buf.length} bytes]`;
    if (buf.length > MAX_READ_BYTES)
      return `[file too large: ${buf.length} bytes — use offset/limit]`;
    const text = buf.toString("utf8");
    if (input.offset !== undefined || input.limit !== undefined) {
      const lines = text.split("\n");
      const start = input.offset ?? 0;
      const end =
        input.limit !== undefined ? start + input.limit : lines.length;
      return lines
        .slice(start, end)
        .map((l, i) => `${start + i + 1}\t${l}`)
        .join("\n");
    }
    return text;
  },
  annotations: { readOnlyHint: true, idempotentHint: true },
});
