const listDirectoryDefinition = defineLocalAgentTool({
  name: "list_directory",
  title: "List Directory",
  description: "List directory contents. Allowed: ~/code/ and ~/notes/.",
  inputSchema: z.object({
    path: z.string(),
    recursive: z.boolean().optional().describe("Recurse up to depth 2"),
  }),
  execute: async (input) => {
    const absPath = resolvePath(input.path);
    assertReadAllowed(absPath, "list_directory");
    async function listLevel(dir: string, depth: number): Promise<string[]> {
      const entries = await readdir(dir, { withFileTypes: true });
      const lines: string[] = [];
      for (const e of entries.slice(0, 200)) {
        const indent = "  ".repeat(depth);
        if (e.isDirectory()) {
          lines.push(`${indent}${e.name}/`);
          if (input.recursive && depth < 2)
            lines.push(...(await listLevel(join(dir, e.name), depth + 1)));
        } else {
          const s = await stat(join(dir, e.name)).catch(() => null);
          lines.push(
            `${indent}${relative(absPath, join(dir, e.name))}${s ? ` (${s.size} B)` : ""}`
          );
        }
      }
      return lines;
    }
    return (await listLevel(absPath, 0)).join("\n") || "(empty)";
  },
  annotations: { readOnlyHint: true, idempotentHint: true },
});
const listDir = createAiToolFromLocalDefinition(listDirectoryDefinition);

const directoryTree = tool({
  description:
    "Get a recursive JSON tree of a directory. Allowed: ~/code/ and ~/notes/.",
  inputSchema: z.object({
    path: z.string(),
    max_depth: z
      .number()
      .int()
      .min(1)
      .max(4)
      .optional()
      .describe("Max depth (default 3)"),
  }),
  execute: async (input) => {
    const absPath = resolvePath(input.path);
    assertReadAllowed(absPath, "directory_tree");
    const maxDepth = input.max_depth ?? 3;
    type TreeNode = {
      name: string;
      type: "file" | "dir";
      size?: number;
      children?: TreeNode[];
    };
    async function buildTree(dir: string, depth: number): Promise<TreeNode[]> {
      if (depth > maxDepth) return [];
      const entries = await readdir(dir, { withFileTypes: true });
      const nodes: TreeNode[] = [];
      for (const e of entries.slice(0, 300)) {
        if (e.isDirectory()) {
          nodes.push({
            name: e.name,
            type: "dir",
            children: await buildTree(join(dir, e.name), depth + 1),
          });
        } else {
          const s = await stat(join(dir, e.name)).catch(() => null);
          nodes.push({ name: e.name, type: "file", size: s?.size });
        }
      }
      return nodes;
    }
    return JSON.stringify(await buildTree(absPath, 1), null, 2);
  },
});

