const safeSearchInputSchema = z.object({
  repo: z.string().min(1).describe("Repo name, branch, or local path"),
  query: z.string().min(1).describe("Regex or literal search query"),
  file_types: z
    .array(z.string().min(1))
    .max(12)
    .optional()
    .describe("Extensions without dot, e.g. ['ts','tsx']"),
  intent: z.string().optional().describe("Why this search is being run"),
  fixed_strings: z.boolean().optional().describe("Treat query as literal"),
  limit: z.number().int().min(1).max(100).optional(),
});

async function executeSafeSearch(input: z.infer<typeof safeSearchInputSchema>) {
  const repo = await resolveSearchRoot(input.repo);
  if (repo.location !== "local") {
    throw new Error("safe_search currently requires a local checkout");
  }

  const globs = fileTypeGlobs(input.file_types);
  const args = [
    "--line-number",
    "--with-filename",
    "--color=never",
    "--max-count=20",
    "--max-filesize=1M",
  ];
  if (input.fixed_strings) args.push("--fixed-strings");
  for (const glob of globs) args.push("--glob", glob);
  args.push(input.query, repo.path);

  try {
    const { stdout } = await execFileAsync(await resolveRipgrep(), args, {
      timeout: 10_000,
      maxBuffer: 300_000,
    });
    const matches = parseRipgrepMatches(stdout.trim(), repo.path).slice(
      0,
      input.limit ?? 50
    );
    return {
      repo,
      intent: input.intent,
      command: ["rg", ...args],
      matchCount: matches.length,
      matches,
      suggestions:
        matches.length === 0
          ? [
              "Try a literal search with fixed_strings: true.",
              "Add or broaden file_types if the target may not be in the current extension set.",
              "After a few targeted searches, summarize the absence of strong evidence instead of continuing broad exploration.",
            ]
          : [
              "Use read_file on specific matches before editing.",
              "Run a narrower safe_search with a more precise query if there are too many matches.",
              "If these matches answer the question, summarize them instead of running more exploratory searches.",
            ],
    };
  } catch (err: unknown) {
    if (hasProcessExitCode(err, 1)) {
      return {
        repo,
        intent: input.intent,
        command: ["rg", ...args],
        matchCount: 0,
        matches: [],
        suggestions: [
          "Try a literal search with fixed_strings: true.",
          "Add or broaden file_types if the target may not be in the current extension set.",
          "After a few targeted searches, summarize the absence of strong evidence instead of continuing broad exploration.",
        ],
      };
    }
    if (isMaxBufferError(err)) {
      throw new Error(
        "safe_search result exceeded its buffer; narrow query, file_types, or repo path.",
        { cause: err }
      );
    }
    throw err;
  }
}

