const toolDogfoodDefinition = defineLocalAgentTool({
  name: "tool_dogfood",
  title: "Tool Dogfood",
  description:
    "Run a bounded multi-turn /api/chat probe and return normalized tool inputs, tool outputs, final text, errors, and duration per turn.",
  inputSchema: z.object({
    turns: z
      .array(z.object({ prompt: z.string().min(1) }))
      .min(1)
      .max(20),
    modelId: z.string().min(1),
    execution: chatExecutionSchema,
    endpoint: z
      .string()
      .url()
      .optional()
      .describe("Default: http://127.0.0.1:3000/api/chat"),
    maxOutputTokens: z.number().int().min(512).max(8192).default(1024),
  }),
  execute: async (input) => {
    const endpoint = input.endpoint ?? "http://127.0.0.1:3000/api/chat";
    const messages: Array<Record<string, unknown>> = [];
    const turns = [];

    for (const [index, turn] of input.turns.entries()) {
      messages.push({
        id: `dogfood-user-${index + 1}`,
        role: "user",
        parts: [{ type: "text", text: turn.prompt }],
      });
      const started = Date.now();
      const response = await fetch(endpoint, {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({
          modelId: input.modelId,
          execution: input.execution,
          systemPromptMode: "none",
          maxOutputTokens: input.maxOutputTokens,
          messages,
        }),
        signal: AbortSignal.timeout(240_000),
      });
      const body = await response.text();
      const events = parseSseEvents(body);
      const assistantText = textFromEvents(events);
      const toolCalls = events
        .filter((event) => event.type === "tool-input-available")
        .map((event) => ({
          toolCallId: event.toolCallId,
          toolName: event.toolName,
          input: event.input,
        }));
      const toolOutputs = events
        .filter(
          (event) =>
            event.type === "tool-output-available" ||
            event.type === "tool-output-error"
        )
        .map((event) => ({
          toolCallId: event.toolCallId,
          output: event.output ?? event.errorText,
        }));
      const errors = events.filter(
        (event) =>
          event.type === "error" ||
          "error" in event ||
          String(event.type ?? "").includes("error")
      );
      const finish = events.find((event) => event.type === "finish");
      turns.push({
        turn: index + 1,
        status: response.status,
        durationMs: Date.now() - started,
        ok: response.ok && errors.length === 0 && assistantText.length > 0,
        finishReason: finish?.finishReason,
        assistantText,
        toolCalls,
        toolOutputs,
        errors,
        eventCount: events.length,
      });
      messages.push({
        id: `dogfood-assistant-${index + 1}`,
        role: "assistant",
        parts: [{ type: "text", text: assistantText }],
      });
      if (!response.ok || errors.length > 0 || !assistantText) break;
    }

    return {
      ok: turns.every((turn) => turn.ok),
      endpoint,
      modelId: input.modelId,
      execution: input.execution,
      turns,
    };
  },
  annotations: { readOnlyHint: true, idempotentHint: false },
});
const toolDogfood = createAiToolFromLocalDefinition(toolDogfoodDefinition);

const logsDefinition = defineLocalAgentTool({
