const runCommand = tool({
  description:
    "Run a shell command in a project directory under ~/code/. Read-heavy operations (build, test, git, npm, ls, cat). Destructive commands are blocked.",
  inputSchema: z.object({
    command: z.string().describe("The shell command to run"),
    cwd: z
      .string()
      .optional()
      .describe("Working directory (must be under ~/code/, default: ~/code)"),
    timeout_ms: z
      .number()
      .int()
      .min(1000)
      .max(60_000)
      .optional()
      .describe("Timeout in ms (default 15000)"),
  }),
  execute: async (input) => {
    const cwd = resolvePath(input.cwd ?? "~/code");
    assertReadAllowed(cwd, "bash");
    assertShellDestructiveAllowed(input.command, cwd);

    for (const pattern of BLOCKED_PATTERNS) {
      if (pattern.test(input.command)) {
        return `Blocked: command matches safety pattern ${pattern}`;
      }
    }

    return new Promise((resolve) => {
      const proc = spawn("bash", ["-c", input.command], {
        cwd,
        env: { ...process.env, HOME: homedir() },
        timeout: input.timeout_ms ?? 15_000,
      });
      let out = "";
      let err = "";
      proc.stdout.on("data", (d: Buffer) => {
        out += d.toString();
      });
      proc.stderr.on("data", (d: Buffer) => {
        err += d.toString();
      });
      proc.on("close", (code) => {
        const combined = [out, err].filter(Boolean).join("\n").trim();
        const truncated =
          combined.length > 16_000
            ? combined.slice(0, 16_000) + "\n…[truncated]"
            : combined;
        resolve(`exit ${code}\n${truncated}`);
      });
      proc.on("error", (e) => resolve(`error: ${e.message}`));
    });
  },
});

