  execute: async (input) => {
    const cwd = resolvePath(input.cwd ?? "~/code");
    assertReadAllowed(cwd, "git");

    for (const pattern of BLOCKED_GIT) {
      if (pattern.test(input.args)) {
        return `Blocked: ${pattern} — use a safer alternative`;
      }
    }

    try {
      const { stdout, stderr } = await execFileAsync(
        "git",
        input.args.split(/\s+/),
        {
          cwd,
          timeout: 15_000,
          maxBuffer: 200_000,
        }
      );
      const out = (stdout + stderr).trim();
      return out.length > 16_000
        ? out.slice(0, 16_000) + "\n…[truncated]"
        : out || "(no output)";
    } catch (err: unknown) {
      return `git error: ${err instanceof Error ? err.message : String(err)}`;
    }
  },
});

const getCurrentTime = tool({
