const memory = tool({
  description:
    "Read or write persistent memory stored across conversations. Use to remember facts, preferences, or notes for later.",
  inputSchema: z.object({
    action: z.enum(["read", "write", "delete"]),
    key: z
      .string()
      .optional()
      .describe("Memory key (required for write/delete, omit to read all)"),
    value: z
      .string()
      .optional()
      .describe("Value to store (required for write)"),
  }),
  execute: async (input) => {
    await mkdir(dirname(MEMORY_FILE), { recursive: true });
    let store: Record<string, string> = {};
    try {
      store = JSON.parse((await readFile(MEMORY_FILE)).toString("utf8"));
    } catch {
      /* first use */
    }

    if (input.action === "read") {
      if (input.key) return store[input.key] ?? "(not found)";
      if (!Object.keys(store).length) return "(memory is empty)";
      return Object.entries(store)
        .map(([k, v]) => `${k}: ${v}`)
        .join("\n");
    }
    if (input.action === "write") {
      if (!input.key || input.value === undefined)
        return "key and value required for write";
      store[input.key] = input.value;
      await writeFile(MEMORY_FILE, JSON.stringify(store, null, 2), "utf8");
      return `Stored: ${input.key}`;
    }
    if (input.action === "delete") {
      if (!input.key) return "key required for delete";
      delete store[input.key];
      await writeFile(MEMORY_FILE, JSON.stringify(store, null, 2), "utf8");
      return `Deleted: ${input.key}`;
    }
    return "unknown action";
  },
});

const globDefinition = defineLocalAgentTool({
  name: "glob",
  title: "Glob",
  description:
    "Raw file glob for an already-scoped directory. Prefer search_code/safe_search for exploratory code lookup. Do not use this for wildcard scans across ~/code.",
  inputSchema: z.object({
    pattern: z
      .string()
      .describe("Glob pattern, e.g. '**/*.ts' or 'src/**/*.test.*'"),
    cwd: z.string().optional().describe("Base directory (default: ~/code)"),
    limit: z
      .number()
