    assertWriteAllowed(absPath, "delete_file");
    assertDestructivePathAllowed(absPath, "delete_file", {
      recursive: input.recursive === true,
    });
    const s = await stat(absPath);
    if (s.isDirectory()) {
      if (!input.recursive) return "Use recursive: true to delete directories";
      await rmdir(absPath, { recursive: true });
      return `Deleted directory ${absPath}`;
