const multiEdit = tool({
  description:
    "Make multiple targeted string replacements in a single file in one call. More efficient than multiple edit_file calls. Restricted to ~/notes/ only.",
  inputSchema: z.object({
    path: z.string().describe("Path within ~/notes/"),
    edits: z
      .array(
        z.object({
          old_string: z
            .string()
            .describe("Exact string to replace (must be unique)"),
          new_string: z.string().describe("Replacement string"),
        })
      )
      .min(1)
      .describe("List of replacements to apply in order"),
  }),
  execute: async (input) => {
    const absPath = resolvePath(input.path);
    assertWriteAllowed(absPath, "multi_edit");
    let text = (await readFile(absPath)).toString("utf8");
    const results: string[] = [];
    for (const edit of input.edits) {
      const count = text.split(edit.old_string).length - 1;
      if (count === 0) {
        results.push(`✗ not found: ${edit.old_string.slice(0, 40)}`);
        continue;
      }
      if (count > 1) {
        results.push(
          `✗ ambiguous (${count} matches): ${edit.old_string.slice(0, 40)}`
        );
        continue;
      }
      text = text.replace(edit.old_string, edit.new_string);
      results.push(`✓ replaced: ${edit.old_string.slice(0, 40)}`);
    }
    await writeFile(absPath, text, "utf8");
    return results.join("\n");
  },
});

const httpRequest = tool({
  description:
    "Make an HTTP request to any URL. Supports custom method, headers, and body. Use for authenticated APIs, REST endpoints, GraphQL, etc.",
  inputSchema: z.object({
    url: z.string().url(),
    method: z
      .enum(["GET", "POST", "PUT", "PATCH", "DELETE"])
      .optional()
      .describe("Default: GET"),
    headers: z
      .record(z.string(), z.string())
      .optional()
      .describe("Request headers, e.g. { Authorization: 'Bearer ...' }"),
    body: z
      .string()
      .optional()
      .describe("Request body (JSON string or plain text)"),
    timeout_ms: z.number().int().min(1000).max(30_000).optional(),
  }),
  execute: async (input) => {
    const res = await fetch(input.url, {
      method: input.method ?? "GET",
      headers: input.headers,
      body: input.body,
      signal: AbortSignal.timeout(input.timeout_ms ?? 15_000),
    });
    const text = await res.text();
    const truncated =
      text.length > 16_000 ? text.slice(0, 16_000) + "\n…[truncated]" : text;
    return `HTTP ${res.status} ${res.statusText}\n${truncated}`;
