function createPiToolSource(
  definition: Pick<
    PiToolSource,
    "name" | "title" | "description" | "parseAndExecute"
  > & { inputSchema: z.ZodTypeAny }
): PiToolSource {
  return {
    name: definition.name,
    title: definition.title,
    description: definition.description,
    parameters: piParametersFromZod(definition.inputSchema),
    parseAndExecute: definition.parseAndExecute,
  };
}

function createHomerAiToolsForMode(mode: AgentToolMode): ToolSet {
  const allTools = createHomerAiTools();
  return Object.fromEntries(
    homerToolDefinitionsForMode(mode).map((definition) => {
      const implementation = allTools[definition.name];
      if (implementation === undefined) {
        throw new Error(
          `Missing AI tool implementation for ${definition.name}.`
        );
      }
      return [definition.name, implementation];
    })
  );
}

