export function createModelAgentToolsForMode(
  mode: AgentToolMode
): ToolSet | undefined {
  if (mode === "off") return undefined;

  const workspacePrimitiveTools = createWorkspacePrimitiveAiTools();
  if (mode === "readonly") {
    return {
      ...workspacePrimitiveTools,
      ...createHomerAiToolsForMode(mode),
      think,
    };
