  };
}

import { z } from "zod";

import {
  ChatProfileManifestError,
  chatProfileIdSchema,
  chatProfileScopeSchema,
  loadChatProfileManifest,
  resolveChatProfile,
} from "../lib/server/chat-profile-manifest";

const structuralFailure = 78;
const cliArgumentsSchema = z.union([
  z.tuple([z.literal("audit"), z.string().min(1)]),
  z.tuple([
    z.literal("resolve"),
    z.string().min(1),
    chatProfileIdSchema,
    z.string().optional(),
  ]),
]);

function fail(message: string): never {
  process.stderr.write(`${message}\n`);
  process.exit(structuralFailure);
}

const parsedArguments = cliArgumentsSchema.safeParse(process.argv.slice(2));
if (!parsedArguments.success) {
  fail(
    "usage: chat-profile-resolve-cli.ts audit <manifest> | resolve <manifest> <profile> [allowed-scopes]"
  );
}

function loadManifest(manifestPath: string) {
  try {
    return loadChatProfileManifest(manifestPath);
  } catch (error) {
    if (error instanceof ChatProfileManifestError) {
      for (const problem of error.problems) {
        process.stderr.write(`${manifestPath}: ${problem}\n`);
      }
      process.exit(structuralFailure);
    }
    throw error;
  }
}

const [, manifestPath] = parsedArguments.data;
const entries = loadManifest(manifestPath);

if (parsedArguments.data[0] === "resolve") {
  const [, , profile, rawScopes = ""] = parsedArguments.data;
  const parsedScopes = z
    .array(chatProfileScopeSchema)
    .safeParse(rawScopes.split(/\s+/).filter(Boolean));
  if (!parsedScopes.success) {
    fail(`${manifestPath}: invalid allowed scopes: ${rawScopes}`);
  }

  const entry = resolveChatProfile(entries, profile, parsedScopes.data);
  if (!entry) process.exit(1);
  process.stdout.write(`${entry.confFile}\t${entry.scope}\n`);
}

import { spawnSync } from "node:child_process";
import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";
import { testBashCommand } from "./test-runtime-prerequisites.mjs";

const bashExecutable = testBashCommand();
const apiRoot = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const helper = join(apiRoot, "scripts", "homer-worker-gpu.sh");

function runHarness(script: string, args: string[] = []) {
  const root = mkdtempSync(join(tmpdir(), "homer-worker-gpu-"));
  const result = spawnSync(
    bashExecutable,
    ["-c", script, "--", helper, root, ...args],
    { encoding: "utf8", timeout: 5_000 }
  );
  rmSync(root, { force: true, recursive: true });
  return {
    status: result.status,
    stdout: result.stdout.replaceAll(root, "<fixture>"),
    stderr: result.stderr.replaceAll(root, "<fixture>"),
  };
}

function runLeaseDeadline(mode: "bounded" | "invalid" | "persistent") {
  return runHarness(
    `set -euo pipefail
source "$1"
lease_dir="$2"
mode="$3"
kill_log="$lease_dir/kill.log"
marker="$lease_dir/marker"
pid_file="$lease_dir/pid"

start_service_command() {
  "$@" &
  lease_child_pid=$!
  printf '%s\n' "$lease_child_pid" >"$pid_file"
}

kill() {
  printf '%s\n' "$*" >>"$kill_log"
  local -a kill_args=("$@")
  local last_index=$((\${#kill_args[@]} - 1))
  local target="\${kill_args[$last_index]}"
  if [[ "$target" =~ ^-[0-9]+$ ]]; then
    kill_args[$last_index]="\${target#-}"
  fi
  builtin kill "\${kill_args[@]}"
}

case "$mode" in
  persistent)
    HOMER_GPU_LEASE_TIMEOUT_SECONDS=0
    run_service_command /bin/sh -c 'sleep 0.2; printf complete > "$1"' sh "$marker"
    [[ "$(<"$marker")" == complete ]]
    [[ -z "$lease_deadline_pid" ]]
    [[ ! -e "$kill_log" ]]
    ! compgen -G "$lease_dir/deadline.*" >/dev/null
    ;;
  bounded)
    HOMER_GPU_LEASE_TIMEOUT_SECONDS=1
    lease_kill_grace_seconds=0
    set +e
    run_service_command /bin/sh -c 'printf ready > "$1"; trap "exit 0" TERM; while :; do sleep 1; done' sh "$marker"
    status=$?
    set -e
    [[ "$status" == 124 ]]
    [[ "$(<"$marker")" == ready ]]
    grep -Fq -- '-TERM -- -' "$kill_log"
    ! builtin kill -0 "$(<"$pid_file")" 2>/dev/null
    ;;
  invalid)
    HOMER_GPU_LEASE_TIMEOUT_SECONDS=21601
    set +e
    run_service_command /bin/true
    status=$?
    set -e
    [[ "$status" == 64 ]]
    [[ ! -e "$pid_file" ]]
    ;;
esac
`,
    [mode]
  );
}

