function runDeviceGate(
  mode: "cleanup" | "lease" | "preflight",
  inspectionMode:
    | "directory-error"
    | "directory-race"
    | "empty"
    | "error"
    | "holder"
    | "invalid-fd"
    | "inherited-successor"
    | "pre-recognition-leapfrog"
    | "none"
    | "race" = "holder"
) {
  return runHarness(
    `set -euo pipefail
source "$1"
fixture="$2"
mode="$3"
inspection_mode="$4"
proc_root="$fixture/proc"
mkdir -p "$proc_root/$$/task"
fixture_process_path="$proc_root/101"
fixture_task_path="$fixture_process_path/task/102"
fixture_fd_path="$fixture_task_path/fd/7"
sysfs_root="$fixture/sys"
dev_root="$fixture/device-root"
mkdir -p "$fixture_task_path/fd" "$sysfs_root/class/drm/null" "$sysfs_root/class/drm/zero"
case "$inspection_mode" in
  none) ln -s /dev/random "$fixture_fd_path" ;;
  empty) : ;;
  *) ln -s /dev/zero "$fixture_fd_path" ;;
esac
ln -s /usr/bin/gpu-client "$fixture_task_path/exe"
printf '%s\n' '0::/test.slice' >"$fixture_task_path/cgroup"
printf '%s' '102 (gpu-client) S' >"$fixture_task_path/stat"
for _ in {1..18}; do printf '%s' ' 0' >>"$fixture_task_path/stat"; done
printf '%s\n' ' 4242' >>"$fixture_task_path/stat"
printf '%s\n' '1:3' >"$sysfs_root/class/drm/null/dev"
printf '%s\n' '1:5' >"$sysfs_root/class/drm/zero/dev"

require_root() { :; }
validate_child_command() { :; }
initialize_topology() { :; }
acquire_lease_lock() { :; }
assert_exact_topology() { :; }
assert_group_access_policy() { :; }
assert_no_other_tenants() { :; }
assert_no_worker_gpu_openers() { :; }
assert_no_worker_gpu_openers_from_scanner() { assert_no_worker_gpu_openers; }
assert_no_worker_device_holders_from_scanner() { assert_no_worker_device_holders; }
fixture_stat() {
  local target="\${!#}"
  if [[ "$*" == *"-c %u"* ]]; then
    case "$target" in
      "$proc_root") printf '%s\n' 0 ;;
      "$fixture_task_path"|"$proc_root/202/task/202") printf '%s\n' 1000 ;;
      *) return 1 ;;
    esac
    return
  fi
  if [[ "$*" == *"-c %f|%t|%T"* ]]; then
    case "$target" in
      /dev/null) printf '%s\n' '21b6|1|3' ;;
      /dev/zero) printf '%s\n' '21b6|1|5' ;;
      "$fixture_fd_path")
        [[ "$inspection_mode" == error ]] && return 1
        [[ -L "$fixture_fd_path" ]] || return 1
        [[ "$inspection_mode" == none ]] && printf '%s\n' '21b6|1|8' || printf '%s\n' '21b6|1|5'
        ;;
      "$proc_root/202/task/202/fd/8") printf '%s\n' '21b6|1|5' ;;
      *) return 1 ;;
    esac
    return
  fi
  return 1
}

fixture_readlink() {
  local target="\${!#}"
  [[ "$target" == "$fixture_task_path/exe" || "$target" == "$proc_root/202/task/202/exe" ]] || return 1
  if [[ "$inspection_mode" == race ]]; then
    rm -f -- "$fixture_fd_path"
  fi
  [[ "$target" == "$proc_root/202/task/202/exe" ]] && printf '%s\n' /usr/bin/gpu-successor || printf '%s\n' /usr/bin/gpu-client
}
listing_calls="$fixture/listing-calls"
printf '%s\n' 0 >"$listing_calls"
fixture_ls() {
  local calls listing next_pid process_path successor_task target="\${!#}"
  if [[ "$inspection_mode" == pre-recognition-leapfrog && "$target" == "$proc_root/"[0-9]*"/task" && "$target" != "$proc_root/$$/task" ]]; then
    listing="$(/bin/ls "$@")"
    calls="$(( $(<"$listing_calls") + 1 ))"
    printf '%s\n' "$calls" >"$listing_calls"
    process_path="\${target%/task}"
    rm -rf -- "$process_path"
    next_pid="$((200 + calls))"
    successor_task="$proc_root/$next_pid/task/$next_pid"
    mkdir -p "$successor_task/fd"
    ln -s /dev/zero "$successor_task/fd/$((7 + calls))"
    ln -s /usr/bin/gpu-successor "$successor_task/exe"
    printf '%s\n' '0::/successor.slice' >"$successor_task/cgroup"
    printf '%s' "$next_pid (gpu-successor) S" >"$successor_task/stat"
    for _ in {1..18}; do printf '%s' ' 0' >>"$successor_task/stat"; done
    printf ' %s\n' "$((5252 + calls))" >>"$successor_task/stat"
    printf '%s\n' "$listing"
    return
  fi
  if [[ "$inspection_mode" == directory-error && "$target" == "$fixture_task_path/fd" ]]; then
    calls="$(( $(<"$listing_calls") + 1 ))"
    printf '%s\n' "$calls" >"$listing_calls"
    return 1
  fi
  if [[ "$inspection_mode" == directory-race && "$target" == "$fixture_task_path/fd" ]]; then
    rm -rf -- "$fixture_task_path"
    return 1
  fi
  if [[ "$inspection_mode" == invalid-fd && "$target" == "$fixture_task_path/fd" ]]; then
    printf '%s\n' invalid
    return 0
  fi
  /bin/ls "$@"
}
holder_snapshot_sorts="$fixture/holder-snapshot-sorts"
printf '%s\n' 0 >"$holder_snapshot_sorts"
sort() {
  /usr/bin/sort "$@"
  local calls
  calls="$(( $(<"$holder_snapshot_sorts") + 1 ))"
  printf '%s\n' "$calls" >"$holder_snapshot_sorts"
  if [[ "$inspection_mode" == inherited-successor && "$calls" == 1 ]]; then
    rm -rf -- "$fixture_process_path"
    successor_task="$proc_root/202/task/202"
    mkdir -p "$successor_task/fd"
    ln -s /dev/zero "$successor_task/fd/8"
    ln -s /usr/bin/gpu-successor "$successor_task/exe"
    printf '%s\n' '0::/successor.slice' >"$successor_task/cgroup"
    printf '%s' '202 (gpu-successor) S' >"$successor_task/stat"
    for _ in {1..18}; do printf '%s' ' 0' >>"$successor_task/stat"; done
    printf '%s\n' ' 5252' >>"$successor_task/stat"
  fi
}
collect_worker_occupancy_nodes() { printf '%s\n' /dev/null /dev/zero; }
run_service_command() { : >"$fixture/child-started"; }
stat_bin=fixture_stat
readlink_bin=fixture_readlink
ls_bin=fixture_ls

set +e
case "$mode" in
  cleanup) cleanup_command ;;
  lease) leased_command lease-run -- /usr/bin/true ;;
  preflight) leased_command preflight-run -- /usr/bin/true ;;
esac
status=$?
set -e
if [[ "$mode" != cleanup && ( "$inspection_mode" == none || "$inspection_mode" == race || "$inspection_mode" == empty || "$inspection_mode" == directory-race ) ]]; then
  [[ -e "$fixture/child-started" ]]
else
  [[ ! -e "$fixture/child-started" ]]
fi
if [[ "$inspection_mode" == directory-error ]]; then
  [[ "$(<"$listing_calls")" == 2 ]]
fi
exit "$status"
`,
    [mode, inspectionMode]
  );
}

