  [[ "$1" == show && "$2" == -p && "$4" == --value && "$5" == --no-pager ]] || return 64
  local property="$3"
  local delegate=no active=active
  if [[ "$opener_mode" == delegated ]]; then delegate=yes; fi
  if [[ "$opener_mode" == inactive ]]; then active=inactive; fi
  case "$property" in
    ControlGroup) printf '%s\n' /system.slice/homer-embeddings.service ;;
    LoadState) printf '%s\n' loaded ;;
    ActiveState) printf '%s\n' "$active" ;;
    User) printf '%s\n' homersvc ;;
    Group) printf '%s\n' homersvc ;;
    SupplementaryGroups) printf '%s\n' homer-gpu ;;
    DevicePolicy) printf '%s\n' closed ;;
    DeviceAllow) [[ -z "\${OPENER_DEVICE_ALLOW:-}" ]] || printf '%s\n' "$OPENER_DEVICE_ALLOW" ;;
    Delegate) printf '%s\n' "$delegate" ;;
    *) return 1 ;;
  esac
  if [[ "$opener_mode" == race ]]; then
    printf '%s\n' $'Uid:\t991\t991\t991\t991' $'Gid:\t991\t991\t991\t991' $'Groups:\t991' >"$task_path/status"
  fi
}
fixture_stat() {
  [[ "$*" == *"-c %u"* && "\${!#}" == "$proc_root" ]] && printf '%s\n' 0
}
fixture_ls() {
  local calls listing next_pid replacement_task target="\${!#}"
  if [[ "$opener_mode" == pre-recognition-leapfrog && "$target" == "$proc_root/"[0-9]*"/task" && "$target" != "$proc_root/$$/task" ]]; then
    listing="$(/bin/ls "$@")"
    calls="$(( $(<"$fixture/leapfrog-calls") + 1 ))"
    printf '%s\n' "$calls" >"$fixture/leapfrog-calls"
    rm -rf -- "\${target%/task}"
    next_pid="$((200 + calls))"
    replacement_task="$proc_root/$next_pid/task/$next_pid"
    mkdir -p "$replacement_task"
    printf '%s' "$next_pid (replacement) S" >"$replacement_task/stat"
    for _ in {1..18}; do printf '%s' ' 0' >>"$replacement_task/stat"; done
    printf ' %s\n' "$((5252 + calls))" >>"$replacement_task/stat"
    printf '%s\n' 'Name: replacement' $'Uid:\t991\t991\t991\t991' $'Gid:\t991\t991\t991\t991' $'Groups:\t991 992' >"$replacement_task/status"
    printf '%s\n' '0::/system.slice/homer-embeddings.service' >"$replacement_task/cgroup"
    printf '%s\n' "$listing"
    return
  fi
  if [[ "$opener_mode" == replacement-race && "$target" == "$proc_root/101/task" && ! -e "$fixture/replaced" ]]; then
    : >"$fixture/replaced"
    rm -rf -- "$proc_root/101"
    replacement_task="$proc_root/202/task/202"
    mkdir -p "$replacement_task"
    printf '%s' '202 (replacement) S' >"$replacement_task/stat"
    for _ in {1..18}; do printf '%s' ' 0' >>"$replacement_task/stat"; done
