    printf '%s\n' 'Name: replacement' $'Uid:\t991\t991\t991\t991' $'Gid:\t1001\t1001\t1001\t1001' $'Groups:\t1001 992' >"$replacement_task/status"
    printf '%s\n' '0::/user.slice/user-991.slice/session-3.scope' >"$replacement_task/cgroup"
    return 1
  fi
  /bin/ls "$@"
}
opener_snapshot_sorts="$fixture/opener-snapshot-sorts"
printf '%s\n' 0 >"$opener_snapshot_sorts"
printf '%s\n' 0 >"$fixture/leapfrog-calls"
sort() {
  /usr/bin/sort "$@"
  local calls next_pid replacement_task
  calls="$(( $(<"$opener_snapshot_sorts") + 1 ))"
  printf '%s\n' "$calls" >"$opener_snapshot_sorts"
  if [[ "$opener_mode" == ephemeral-never-capable && "$calls" == 1 ]]; then
    rm -rf -- "$proc_root/$task_pid"
  elif [[ "$opener_mode" == capable-disappears ]]; then
    for process_path in "$proc_root"/[0-9]*; do
      [[ "$process_path" == "$proc_root/$$" ]] || rm -rf -- "$process_path"
    done
    next_pid="$((200 + calls))"
    task_pid="$next_pid"
    task_tid="$next_pid"
    task_path="$proc_root/$task_pid/task/$task_tid"
    mkdir -p "$task_path"
    printf '%s' "$task_tid (replacement) S" >"$task_path/stat"
    for _ in {1..18}; do printf '%s' ' 0' >>"$task_path/stat"; done
    printf '%s\n' " $((4242 + calls))" >>"$task_path/stat"
    printf '%s\n' 'Name: replacement' $'Uid:\t991\t991\t991\t991' $'Gid:\t991\t991\t991\t991' $'Groups:\t991 992' >"$task_path/status"
    printf '%s\n' '0::/system.slice/homer-embeddings.service' >"$task_path/cgroup"
  fi
