  );
}

function runDeniedDeviceAllowDecision(mode: "omitted" | "present") {
  return runHarness(
    `set -euo pipefail
source "$1"
fixture="$2"
device_allow_mode="$3"
mkdir -p "$fixture/bin"
printf '%s\n' \
  '#!/usr/bin/env bash' \
  'set -euo pipefail' \
  '[[ "$1" == show && "$2" == -p && "$4" == --value && "$5" == --no-pager && "$6" == homer-embeddings.service ]]' \
  'case "$3" in' \
  '  ControlGroup) printf "%s\\n" /system.slice/homer-embeddings.service ;;' \
  '  LoadState) printf "%s\\n" loaded ;;' \
  '  ActiveState) printf "%s\\n" active ;;' \
  '  User) printf "%s\\n" homersvc ;;' \
  '  Group) printf "%s\\n" homersvc ;;' \
  '  SupplementaryGroups) printf "%s\\n" homer-gpu ;;' \
  '  DevicePolicy) printf "%s\\n" closed ;;' \
  '  DeviceAllow) if [[ "$DEVICE_ALLOW_MODE" == present ]]; then printf "%s\\n" "/dev/dri/renderD128 rw"; fi ;;' \
  '  Delegate) printf "%s\\n" no ;;' \
  '  *) exit 64 ;;' \
  'esac' >"$fixture/bin/systemctl"
chmod +x "$fixture/bin/systemctl"
PATH="$fixture/bin:$PATH"
systemctl_bin=systemctl
DEVICE_ALLOW_MODE="$device_allow_mode"
export DEVICE_ALLOW_MODE
set +e
validate_denied_opener_unit /system.slice/homer-embeddings.service
status=$?
set -e
printf 'decision=%s\\n' "$status"
exit "$status"
`,
    [mode]
  );
}

