import { join } from "node:path";
import { describe, expect, it } from "vitest";

const scriptsDir = join(process.cwd(), "apps/api/scripts");

async function loadModule() {
  return import(`file://${join(scriptsDir, "mint-homer-api-token.mjs")}`);
}

describe("mint-homer-api-token", () => {
  it("parses explicit user, template, and expiry flags", async () => {
    const { parseArgs } = await loadModule();

    expect(
      parseArgs([
        "--user-id",
        "user_123",
        "--template",
        "homer-api",
        "--expires-in",
        "120",
      ])
    ).toEqual({
      userId: "user_123",
      email: "",
      template: "homer-api",
      expiresInSeconds: 120,
    });
  });

  it("resolves the user id by email lookup when no id is given", async () => {
    const { parseArgs, resolveUserId } = await loadModule();

    expect(parseArgs([], { E2E_CLERK_EMAIL: "e2e@example.com" }).email).toBe(
      "e2e@example.com"
    );

    const clerk = {
      users: {
        getUserList: async ({ emailAddress }) => ({
          data:
            emailAddress[0] === "e2e@example.com"
              ? [{ id: "user_resolved" }]
              : [],
        }),
      },
    };
    await expect(
      resolveUserId(clerk, { userId: "", email: "e2e@example.com" })
    ).resolves.toBe("user_resolved");
    await expect(
      resolveUserId(clerk, { userId: "", email: "missing@example.com" })
    ).rejects.toThrow("expected exactly one Clerk user");
  });

  it("redeems a sign-in ticket against the derived production FAPI host", async () => {
    const { createProductionSessionId } = await loadModule();
    const publishableKey = `pk_live_${Buffer.from("clerk.example.com$").toString("base64")}`;

    const clerk = {
      signInTokens: {
        createSignInToken: async ({ userId }) => ({
          token: `ticket-for-${userId}`,
        }),
      },
    };
    const requests = [];
    const fetchImpl = async (url, init) => {
      requests.push({ url, body: init.body.toString() });
      return {
        ok: true,
        status: 200,
        json: async () => ({ response: { created_session_id: "sess_42" } }),
      };
    };

    await expect(
      createProductionSessionId(clerk, {
        userId: "user_9",
        publishableKey,
        fetchImpl,
      })
    ).resolves.toBe("sess_42");
    expect(requests).toEqual([
      {
        url: "https://clerk.example.com/v1/client/sign_ins?_is_native=1",
        body: "strategy=ticket&ticket=ticket-for-user_9",
      },
    ]);

    await expect(
      createProductionSessionId(clerk, {
        userId: "user_9",
        publishableKey: "pk_live_broken",
        fetchImpl,
      })
    ).rejects.toThrow("could not derive the Clerk Frontend API host");
    await expect(
      createProductionSessionId(clerk, {
        userId: "user_9",
        publishableKey,
        fetchImpl: async () => ({
          ok: false,
          status: 422,
          json: async () => ({ errors: [{ code: "ticket_invalid" }] }),
        }),
      })
    ).rejects.toThrow("Clerk sign-in ticket redemption failed (422)");
  });

  it("fails loud when required values are missing or malformed", async () => {
    const { parseArgs, readRequiredEnv, extractJwt } = await loadModule();

    expect(() => parseArgs(["--expires-in", "0"], {})).toThrow(
      "--expires-in must be a positive integer"
    );
    expect(() => parseArgs([], {})).toThrow(
      "--user-id, --email, or E2E_CLERK_EMAIL is required"
    );
    expect(() => readRequiredEnv("CLERK_SECRET_KEY", {})).toThrow(
      "CLERK_SECRET_KEY is required"
    );
    expect(() => extractJwt({ token: "not-clerk" })).toThrow(
      "Clerk sessions.getToken response did not include jwt"
    );
  });
});

