type VoiceConversationProvenance = {
  modelSnapshot: ChatModelSnapshot;
  effectiveRequest: EffectiveChatRequest;
};

type VoiceRouteFailure =
  | {
      kind: "start";
      detail: string;
    }
  | {
      kind: "return";
      detail: string;
    };

type VoiceCapabilityAction = {
  label: string;
  testID: string;
  onPress(): void;
};

function errorDetail(cause: unknown): string {
  return cause instanceof Error ? cause.message : String(cause);
}

function voiceRuntimeTurns(
  runtime: VoiceSessionRuntime
): readonly VoiceConversationTurn[] {
  switch (runtime.kind) {
    case "starting":
    case "listening":
    case "processing":
    case "speaking":
      return runtime.turns;
    case "idle":
    case "error":
    case "unavailable":
      return [];
  }
}

function voiceConversationChangeForTurn({
  turn,
  provenance,
  createdAt,
}: {
  turn: VoiceConversationTurn;
  provenance: VoiceConversationProvenance;
  createdAt: number;
}): ConversationChange {
  const messageId = newLocalId(`voice-${turn.role}`);
  switch (turn.role) {
    case "user":
      return {
        type: "message.put",
        message: {
          messageId,
          role: "user",
          parts: [{ type: "text", text: turn.text, state: "done" }],
          createdAt,
        },
      };
    case "assistant":
      return {
        type: "message.put",
        message: {
          messageId,
          role: "assistant",
          parts: [{ type: "text", text: turn.text, state: "done" }],
          modelSnapshot: provenance.modelSnapshot,
          effectiveRequest: provenance.effectiveRequest,
          createdAt,
        },
      };
  }
}

function voiceConversationChanges(
  turns: readonly VoiceConversationTurn[],
  provenance: VoiceConversationProvenance
): readonly ConversationChange[] {
  const createdAt = Date.now();
  return turns.map((turn, index) =>
    voiceConversationChangeForTurn({
      turn,
      provenance,
      createdAt: createdAt + index,
    })
  );
}

