function VoiceCapabilityRoute() {
  const router = useRouter();
  const colors = THEME_COLORS.light;
  const {
    conversation,
    voice: { target: voiceTarget, availability: voiceAvailability },
    dispatchConversationChange,
  } = useConversationRuntime();
  const conversationId = conversation.conversation.conversationId;
  const {
    runtime,
    start,
    stop: handleEndVoiceConversation,
    dismissVoiceNotice,
  } = useVoiceSession();
  const enabled = voiceTarget !== null;
  const voiceSupported = voiceConversationsSupported();
  const handleStartVoiceConversation = useCallback(() => {
    if (!voiceTarget) return Promise.resolve();
    return start({
      conversationId,
      target: voiceTarget,
    });
  }, [conversationId, start, voiceTarget]);
  const provenanceRef = useRef<VoiceConversationProvenance | null>(null);
  const pendingChangesRef = useRef<readonly ConversationChange[] | null>(null);
  const returnInFlightRef = useRef(false);
  const routeFocusedRef = useRef(false);
  const [returning, setReturning] = useState(false);
  const [failure, setFailure] = useState<VoiceRouteFailure | null>(null);

  const createProvenance = useCallback(() => {
    if (!voiceTarget) {
      throw new Error("A parsed chat model is required for voice.");
    }
    const provenance: VoiceConversationProvenance = {
      modelSnapshot: modelSnapshotForTarget(voiceTarget),
      effectiveRequest: {
        kind: "chat",
        execution: voiceTarget.execution,
      },
    };
    return provenance;
  }, [voiceTarget]);

  const startVoice = useCallback(async () => {
    setFailure(null);
    pendingChangesRef.current = null;
    try {
      provenanceRef.current = createProvenance();
      await handleStartVoiceConversation();
    } catch (cause) {
      provenanceRef.current = null;
      if (routeFocusedRef.current) {
        setFailure({ kind: "start", detail: errorDetail(cause) });
      }
    }
  }, [createProvenance, handleStartVoiceConversation]);

  const dismissVoice = useCallback(async () => {
    await handleEndVoiceConversation();
    if (routeFocusedRef.current) {
      router.replace({
        pathname: "/conversations/[conversationId]",
        params: { conversationId },
      });
    }
  }, [handleEndVoiceConversation, router, conversationId]);

  const returnVoiceResult = useCallback(async () => {
    if (returnInFlightRef.current) return;
    returnInFlightRef.current = true;
    setReturning(true);
    setFailure(null);
    try {
      let changes = pendingChangesRef.current;
      if (!changes) {
        const provenance = provenanceRef.current;
        if (!provenance) {
          throw new Error("Voice result provenance is unavailable.");
        }
        changes = voiceConversationChanges(
          voiceRuntimeTurns(runtime),
          provenance
        );
        pendingChangesRef.current = changes;
      }
      await handleEndVoiceConversation();
      for (const change of changes) {
        await dispatchConversationChange(change);
      }
      pendingChangesRef.current = null;
      provenanceRef.current = null;
      if (routeFocusedRef.current) {
        router.replace({
          pathname: "/conversations/[conversationId]",
          params: { conversationId },
        });
      }
    } catch (cause) {
      if (routeFocusedRef.current) {
        setFailure({ kind: "return", detail: errorDetail(cause) });
        setReturning(false);
      }
    } finally {
      returnInFlightRef.current = false;
    }
  }, [
    conversationId,
    dispatchConversationChange,
    handleEndVoiceConversation,
    router,
    runtime,
  ]);

  const retryVoiceStart = useCallback(() => {
    dismissVoiceNotice();
    void startVoice();
  }, [dismissVoiceNotice, startVoice]);

  useFocusEffect(
    useCallback(() => {
      routeFocusedRef.current = true;
      return () => {
        routeFocusedRef.current = false;
      };
    }, [])
  );

  if (returning) {
    return (
      <VoiceCapabilityPanel
        title="Saving voice conversation"
        detail="Your voice turns are being added to this conversation."
      />
    );
  }

  if (failure?.kind === "return") {
    return (
      <VoiceCapabilityPanel
        title="Voice result not saved"
        detail={failure.detail}
        action={{
          label: "Retry save",
          testID: "homer-voice-result-retry",
          onPress: () => {
            void returnVoiceResult();
          },
        }}
      />
    );
  }

  if (failure?.kind === "start") {
    return (
      <VoiceCapabilityPanel
        title="Voice unavailable"
        detail={failure.detail}
        onClose={() => {
          void dismissVoice();
        }}
        action={{
          label: "Try again",
          testID: "homer-voice-session-retry",
          onPress: retryVoiceStart,
        }}
      />
    );
  }

  if (!enabled) {
    const detail = !voiceSupported
      ? "Voice conversations are available in the native iOS and Android apps."
      : "Voice conversations are not available for Machine bindings.";
    return (
      <VoiceCapabilityPanel
        title="Voice unavailable"
        detail={detail}
        showVoiceOptions={voiceSupported}
        onClose={() => {
          void dismissVoice();
        }}
      />
    );
  }

  if (runtime.kind === "error" || runtime.kind === "unavailable") {
    return (
      <VoiceCapabilityPanel
        title={runtime.notice.title}
        detail={runtime.notice.detail}
        onClose={() => {
          void dismissVoice();
        }}
        action={
          runtime.kind === "error"
            ? {
                label: "Try again",
                testID: "homer-voice-session-retry",
                onPress: retryVoiceStart,
              }
            : undefined
        }
      />
    );
  }

  if (runtime.kind === "idle") {
    if (voiceAvailability.state === "blocked") {
      return (
        <VoiceCapabilityPanel
          title="Voice conversation blocked"
          detail={voiceAvailability.reason}
          onClose={() => {
            void dismissVoice();
          }}
        />
      );
    }
    return (
      <VoiceCapabilityPanel
        title="Voice conversation"
        detail="Start when you are ready. The microphone stays off until you tap below."
        onClose={() => {
          void dismissVoice();
        }}
        action={{
          label: "Start voice",
          testID: "homer-voice-session-start",
          onPress: () => {
            void startVoice();
          },
        }}
      />
    );
  }

  return (
    <View className="flex-1" style={{ backgroundColor: colors.voiceBg }}>
      <VoiceConversationOverlay runtime={runtime} onEnd={returnVoiceResult} />
    </View>
  );
}

export default function VoiceRoute() {
  return (
    <VoiceOptionsHost>
      <VoiceCapabilityRoute />
    </VoiceOptionsHost>
  );
}

