function parseConfText(text: string) {
  const values = new Map<string, string>();
  for (const line of text.split("\n")) {
    const l = line.trim();
    if (!l || l.startsWith("#")) continue;
    const idx = l.indexOf("=");
    if (idx < 0) continue;
    values.set(l.slice(0, idx).trim(), l.slice(idx + 1).trim());
  }
  return values;
}

function validateConf(text: string): string[] {
  const warnings: string[] = [];
  const values = parseConfText(text);
  const kvType = values.get("KV_TYPE");
  const contextSize = values.get("CTX_SIZE");
  const chatTemplateKwargs = values.get("CHAT_TEMPLATE_KWARGS");

  if (kvType && !VALID_KV_TYPES.has(kvType)) {
    warnings.push(
      `KV_TYPE="${kvType}" is not a recognised value (expected e.g. f16, q8_0, q4_0)`
    );
  }

  if (contextSize && !/^\d+$/.test(contextSize)) {
    warnings.push(`CTX_SIZE="${contextSize}" must be a positive integer`);
  }

  if (chatTemplateKwargs) {
    const raw = chatTemplateKwargs.replace(/^'|'$/g, "").replace(/^"|"$/g, "");
    try {
      JSON.parse(raw);
    } catch {
      warnings.push(`CHAT_TEMPLATE_KWARGS is not valid JSON: ${raw}`);
    }
  }

  if (values.get("SPLIT_MODE") === "tensor") {
    warnings.push(
      'SPLIT_MODE=tensor is broken on uneven multi-GPU setups (llama.cpp #21947) — use "layer" instead'
    );
  }

  return warnings;
}

function RestartProgress({ active }: { active: boolean }) {
  const opacity = useSharedValue(1);
  useEffect(() => {
    if (active) {
      opacity.set(withRepeat(withTiming(0.3, { duration: 700 }), -1, true));
    } else {
      cancelAnimation(opacity);
      opacity.set(1);
    }
    return () => cancelAnimation(opacity);
  }, [active, opacity]);
  const style = useAnimatedStyle(() => ({ opacity: opacity.value }));
  if (!active) return null;
  return (
    <View className="gap-1.5">
      <Text
        className="text-mb-muted text-[11px] lowercase"
        style={{ fontFamily: "GeistMono_400Regular" }}
      >
        reconnecting runtime…
      </Text>
      <View className="h-[3px] rounded-full bg-mb-border overflow-hidden">
        <Animated.View
          className="h-[3px] bg-mb-accent rounded-full w-full"
          style={style}
        />
      </View>
    </View>
  );
}

function AdminPromptSourcesNativeIsland({
  draft,
  updateAgentDraft,
  colors,
}: {
  draft: AgentRuntimeConfig;
  updateAgentDraft: (patch: Partial<AgentRuntimeConfig>) => void;
  colors: Record<string, string>;
}) {
  const setPromptSource = (key: AgentPromptSourceKey, value: boolean): void => {
    hapticTick("light");
    const nextPatch: Partial<AgentRuntimeConfig> = { [key]: value };
    updateAgentDraft(nextPatch);
  };

  return (
    <ExpoNativeHost
      matchContents
      testID="homer-admin-prompt-sources-native-island"
      style={{ width: "100%" }}
    >
      <Column modifiers={fillUniversalWidth} spacing={6}>
        {ADMIN_PROMPT_SOURCE_ITEMS.map((item) => {
          const active = draft[item.key];
          return (
            <Row
              key={item.key}
              alignment="center"
              spacing={8}
              style={{
                paddingHorizontal: 12,
                paddingVertical: 8,
                borderRadius: 6,
                borderWidth: 1,
                borderColor: active ? colors.accent : colors.borderStrong,
                backgroundColor: active ? colors.accentDim : colors.surface,
              }}
              modifiers={fillUniversalWidth}
              testID={`homer-admin-prompt-source-${item.key}`}
            >
              <Column spacing={2} style={{ width: "75%" }}>
                <ExpoText
                  textStyle={{
                    color: colors.text,
                    fontFamily: "GeistMono_600SemiBold",
                    fontSize: 11,
                    fontWeight: "600",
                    letterSpacing: 0.3,
                  }}
                >
                  {item.label}
                </ExpoText>
                <ExpoText
                  textStyle={{
                    color: colors.muted,
                    fontFamily: "GeistMono_400Regular",
                    fontSize: 12,
                  }}
                  numberOfLines={1}
                >
                  {item.detail}
                </ExpoText>
              </Column>
              <Spacer flexible />
              <ExpoSwitch
                value={active}
                onValueChange={(value) => setPromptSource(item.key, value)}
                testID={`homer-admin-prompt-source-switch-${item.key}`}
              />
            </Row>
          );
        })}
      </Column>
    </ExpoNativeHost>
  );
}

export default function AdminScreen() {
  const agentConfig = useAgentRuntimeConfig();
  if (agentConfig.error) {
    return (
      <View className="flex-1 bg-mb-bg px-4 py-4">
        <Text
          className="text-mb-danger text-[11px]"
          style={{ fontFamily: "GeistMono_400Regular" }}
          selectable
        >
          {String(agentConfig.error)}
        </Text>
      </View>
    );
  }
  if (!agentConfig.data) return null;
  return <AdminScreenContent agentConfig={agentConfig.data} />;
}

function AdminScreenContent({
  agentConfig,
}: {
  agentConfig: AgentRuntimeConfig;
}) {
  const { api, baseURL } = useApi();
  const navigation = useNavigation();
  const { width } = useWindowDimensions();
  const isDesktop = width >= 768;
  const modelCatalog = useModelCatalog();
  const { colors } = useThemeMode();
  const queryClient = useQueryClient();
  const runtimeStatus = useRuntimeStatus();
  const workspaceStatus = useWorkspaceStatus({ enabled: true });
  const workspaceRefreshing =
    runtimeStatus.isFetching || workspaceStatus.isFetching;

  const [agentState, setAgentState] = useState<{
    sourceKey: string;
    draft: AgentRuntimeConfig;
    original: AgentRuntimeConfig;
    toolPathRulesText: string;
  }>(() => ({
    sourceKey: agentConfigKey(agentConfig),
    draft: agentConfig,
    original: agentConfig,
    toolPathRulesText: JSON.stringify(agentConfig.toolPathRules, null, 2),
  }));
  const [showRawPathRules, setShowRawPathRules] = useState(false);

  const agentConfigSourceKey = agentConfigKey(agentConfig);
  if (agentState.sourceKey !== agentConfigSourceKey) {
    setAgentState({
      sourceKey: agentConfigSourceKey,
      draft: agentConfig,
      original: agentConfig,
      toolPathRulesText: JSON.stringify(agentConfig.toolPathRules, null, 2),
    });
  }
  const agentDraft = agentState.draft;
  const agentOriginal = agentState.original;
  const toolPathRulesText = agentState.toolPathRulesText;

  const toolPathRulesError = useMemo(() => {
    try {
      const parsed: unknown = JSON.parse(toolPathRulesText);
      if (
        parsed === null ||
        typeof parsed !== "object" ||
        Array.isArray(parsed)
      ) {
        return "path rules must be a JSON object";
      }
      for (const [toolName, rawRule] of Object.entries(parsed)) {
        const rule = agentToolPathRuleSchema.safeParse(rawRule);
        if (!rule.success) {
          return `${toolName}: ${rule.error.issues[0]?.message ?? "invalid path rule"}`;
        }
      }
      return null;
    } catch (error) {
      return error instanceof Error ? error.message : "invalid JSON";
    }
  }, [toolPathRulesText]);

  const agentDirty =
    agentConfigKey(agentDraft) !== agentConfigKey(agentOriginal);
  const saveAgentConfig = useMutation({
    mutationFn: async (payload: AgentRuntimeConfig) =>
      api.saveAgentConfig(payload),
    onSuccess: (saved) => {
      setAgentState({
        sourceKey: agentConfigKey(saved),
        draft: saved,
        original: saved,
        toolPathRulesText: JSON.stringify(saved.toolPathRules, null, 2),
      });
      void queryClient.invalidateQueries({
        queryKey: ["agent-config", baseURL],
      });
    },
  });

  const updateAgentDraft = (patch: Partial<AgentRuntimeConfig>) => {
    setAgentState((prev) => ({
      ...prev,
      draft: { ...prev.draft, ...patch },
    }));
  };

  const updateAgentModelPrompt = (key: AgentModelPromptKey, value: string) => {
    setAgentState((prev) => ({
      ...prev,
      draft: {
        ...prev.draft,
        modelPrompts: {
          ...prev.draft.modelPrompts,
          [key]: value,
        },
      },
    }));
  };

  const updateToolPathRule = (
    toolName: string,
    patch: Partial<AgentToolPathRule>
  ) => {
    setAgentState((prev) => {
      const nextRule = {
        ...(prev.draft.toolPathRules[toolName] ?? {}),
        ...patch,
      };
      const nextRules = {
        ...prev.draft.toolPathRules,
        [toolName]: nextRule,
      };
      return {
        ...prev,
        draft: { ...prev.draft, toolPathRules: nextRules },
        toolPathRulesText: JSON.stringify(nextRules, null, 2),
      };
    });
  };

  const toolPathRuleNames = useMemo(
    () =>
      [
        ...new Set([
          ...Object.keys(DEFAULT_AGENT_TOOL_PATH_RULES),
          ...Object.keys(agentDraft.toolPathRules),
        ]),
      ].sort(),
    [agentDraft.toolPathRules]
  );

  const chatProfiles = useMemo(
    () =>
      modelCatalog.data?.models
        .filter((model) => model.kind === "chat")
        .map((model) => ({
          id: model.id,
          name: model.name,
          port: model.runtime.port,
          runtime: model.runtime.engine,
        })),
    [modelCatalog.data?.models]
  );

  const [selectedOverride, setSelectedOverride] = useState<string | null>(null);
  const selected = selectedOverride ?? chatProfiles?.[0]?.id ?? null;

  const conf = useQuery({
    queryKey: ["admin-conf", baseURL, selected],
    queryFn: async () => {
      if (selected === null) {
        throw new Error("Cannot load admin config without a selected profile.");
      }
      return api.adminConf(selected);
    },
    enabled: !!selected,
  });

  const [confDraftState, setConfDraftState] = useState<{
    profileId: string | null;
    sourceContent: string | null;
    draft: string;
    originalAtLoad: string;
  }>(() => ({
    profileId: null,
    sourceContent: null,
    draft: "",
    originalAtLoad: "",
  }));
  const confContent = conf.data?.content;
  const [prevConfSyncKey, setPrevConfSyncKey] = useState<string | null>(null);
  const confSyncKey =
    selected === null || confContent === undefined
      ? null
      : `${selected}:${confContent}`;
  if (
    confSyncKey !== null &&
    confContent !== undefined &&
    confSyncKey !== prevConfSyncKey
  ) {
    setPrevConfSyncKey(confSyncKey);
    setConfDraftState({
      profileId: selected,
      sourceContent: confContent,
      draft: confContent,
      originalAtLoad: confContent,
    });
  }
  const confDraftReady =
    selected !== null && confDraftState.profileId === selected;
  const draft = confDraftState.draft;
  const originalAtLoad = confDraftState.originalAtLoad;
  const setDraft = (text: string) => {
    setConfDraftState((prev) => ({ ...prev, draft: text }));
  };

  const save = useMutation({
    mutationFn: (payload: { profile: string; content: string }) =>
      api.adminConfSave(payload),
    onSuccess: () => {
      setConfDraftState((prev) => ({
        ...prev,
        sourceContent: prev.draft,
        originalAtLoad: prev.draft,
      }));
      void queryClient.invalidateQueries({
        queryKey: ["runtime-status", baseURL],
      });
    },
  });

  const dirty = draft !== originalAtLoad;
  const hasUnsavedChanges = agentDirty || dirty;

  useLayoutEffect(() => {
    navigation.setOptions({ gestureEnabled: !hasUnsavedChanges });
  }, [hasUnsavedChanges, navigation]);

  const canSaveUnsaved =
    hasUnsavedChanges &&
    !saveAgentConfig.isPending &&
    !save.isPending &&
    !toolPathRulesError &&
    (!dirty || Boolean(selected));
  const validationWarnings = useMemo(
    () => (draft ? validateConf(draft) : []),
    [draft]
  );

  const saveUnsaved = useCallback(async () => {
    if (agentDirty) {
      await saveAgentConfig.mutateAsync(agentDraft);
    }
    if (dirty && selected) {
      await save.mutateAsync({ profile: selected, content: draft });
    }
  }, [agentDirty, agentDraft, dirty, draft, save, saveAgentConfig, selected]);

  const leaveGuard = useAdminLeaveGuard({
    canSave: canSaveUnsaved,
    hasUnsavedChanges,
    save: saveUnsaved,
  });
  usePreventRemove(
    hasUnsavedChanges && !leaveGuard.bypassNavigation,
    ({ data }) => {
      leaveGuard.handleLeaveAttempt({
        preventDefault: () => undefined,
        proceed: () => navigation.dispatch(data.action),
      });
    }
  );

  const leavePromptSaving = leaveGuard.saving;
  const leavePromptSaveDisabled = !canSaveUnsaved || leavePromptSaving;
  const leavePromptError = saveAgentConfig.error ?? save.error;
  const leavePromptActions = (
    <View className="flex-row flex-wrap gap-2 justify-end">
      <Touchable
        feedback="subtle"
        disabled={leavePromptSaving}
        onPress={leaveGuard.cancel}
        testID="homer-admin-leave-cancel"
        accessibilityRole="button"
        accessibilityLabel="cancel leaving admin"
        accessibilityState={{ disabled: leavePromptSaving }}
        hitSlop={adminActionHitSlop}
        style={{ borderCurve: "continuous" }}
        className={`h-9 px-3 rounded-md border border-mb-border-strong bg-mb-surface items-center justify-center ${
          leavePromptSaving ? "opacity-60" : ""
        }`}
      >
        <Text
          className="text-mb-text text-[11px] lowercase"
          style={{
            fontFamily: "GeistMono_500Medium",
            letterSpacing: 0.3,
          }}
        >
          cancel
        </Text>
      </Touchable>
      <Touchable
        feedback="subtle"
        disabled={leavePromptSaving}
        onPress={leaveGuard.discard}
        testID="homer-admin-leave-discard"
        accessibilityRole="button"
        accessibilityLabel="discard admin changes and leave"
        accessibilityState={{ disabled: leavePromptSaving }}
        hitSlop={adminActionHitSlop}
        style={{ borderCurve: "continuous" }}
        className={`h-9 px-3 rounded-md border border-mb-danger/60 bg-mb-danger-dim items-center justify-center ${
          leavePromptSaving ? "opacity-60" : ""
        }`}
      >
        <Text
          className="text-mb-danger text-[11px] lowercase"
          style={{
            fontFamily: "GeistMono_500Medium",
            letterSpacing: 0.3,
          }}
        >
          discard
        </Text>
      </Touchable>
      <Touchable
        feedback="subtle"
        disabled={leavePromptSaveDisabled}
        onPress={() => {
          void leaveGuard.saveAndLeave();
        }}
        testID={
          leavePromptSaveDisabled
            ? "homer-admin-leave-save-disabled"
            : "homer-admin-leave-save"
        }
        accessibilityRole="button"
        accessibilityLabel="save admin changes and leave"
        accessibilityState={{
          disabled: leavePromptSaveDisabled,
          busy: leavePromptSaving,
        }}
        hitSlop={adminActionHitSlop}
        style={{ borderCurve: "continuous" }}
        className={`h-9 px-3 rounded-md items-center justify-center ${
          !leavePromptSaveDisabled
            ? "bg-mb-accent"
            : "bg-mb-surface-2 opacity-60"
        }`}
      >
        <Text
          className={`text-[11px] lowercase ${
            !leavePromptSaveDisabled ? "text-mb-accent-ink" : "text-mb-muted"
          }`}
          style={{
            fontFamily: "GeistMono_600SemiBold",
            letterSpacing: 0.3,
          }}
        >
          {leavePromptSaving ? "saving…" : "save"}
        </Text>
      </Touchable>
    </View>
  );

  const leavePromptPathRuleError = toolPathRulesError ? (
    <Text
      selectable
      testID="homer-admin-leave-path-rule-error"
      className="text-mb-danger text-[10px]"
      style={{ fontFamily: "GeistMono_400Regular", lineHeight: 15 }}
    >
      fix path rules before saving: {toolPathRulesError}
    </Text>
  ) : null;
  const leavePromptSaveError = leavePromptError ? (
    <Text
      accessibilityLiveRegion="assertive"
      selectable
      testID="homer-admin-leave-save-error"
      className="text-mb-danger text-[10px]"
      style={{ fontFamily: "GeistMono_400Regular", lineHeight: 15 }}
    >
      {String(leavePromptError)}
    </Text>
  ) : null;

  return (
    <View className="flex-1 bg-mb-bg">
      <SheetModal
        open={leaveGuard.open}
        accessibilityLabel="unsaved admin changes"
        enablePanDownToClose={!leavePromptSaving}
        onClose={() => {
          if (!leavePromptSaving) leaveGuard.cancel();
        }}
        onDismiss={leaveGuard.completeDismissal}
      >
        <SheetFrame flex={false}>
          <View
            testID="homer-admin-leave-sheet"
            accessibilityRole="summary"
            accessibilityLabel="unsaved admin changes"
            accessibilityViewIsModal
            importantForAccessibility="yes"
            className="bg-mb-bg"
          >
            <SheetHeader
              title="Unsaved Changes"
              subtitle="save or discard admin edits before leaving this screen"
            />
            <View className="gap-3 px-5 pt-4">
              {leavePromptActions}
              {leavePromptPathRuleError}
              {leavePromptSaveError}
            </View>
          </View>
        </SheetFrame>
      </SheetModal>
      <ScrollView
        className="flex-1"
        contentContainerStyle={{
          paddingTop: isDesktop ? 28 : 20,
          paddingBottom: 32,
          paddingHorizontal: isDesktop ? 24 : 16,
          gap: 20,
          maxWidth: isDesktop ? 820 : undefined,
          width: "100%",
          alignSelf: "center",
        }}
        contentInsetAdjustmentBehavior="automatic"
      >
        <View className="gap-3">
          <SectionHeader>access</SectionHeader>
          <View
            className="rounded-xl border border-mb-border-strong bg-mb-surface px-3 py-3 gap-3"
            style={{ borderCurve: "continuous" }}
          >
            <View className="flex-row items-start justify-between gap-3">
              <View className="min-w-0 flex-1 gap-1">
                <Text
                  className="text-mb-text text-[13px] lowercase"
                  style={{
                    fontFamily: "GeistMono_600SemiBold",
                    letterSpacing: 0.2,
                  }}
                >
                  writable terminal
                </Text>
                <Text
                  className="text-mb-muted text-[10px]"
                  style={{
                    fontFamily: "GeistMono_400Regular",
                    lineHeight: 15,
                  }}
                >
                  choose an authenticated Machine when the terminal opens
                </Text>
              </View>
            </View>
            <View className="flex-row flex-wrap gap-2 items-center">
              <StyledLink href="/terminal" asChild>
                <RouterLinkPressable
                  accessibilityRole="button"
                  accessibilityLabel="open terminal from admin"
                  testID="homer-admin-terminal"
                  hitSlop={adminActionHitSlop}
                  onPress={() => hapticTick("light")}
                  style={{ borderCurve: "continuous" }}
                  className="px-3 h-9 rounded-md bg-mb-accent items-center justify-center"
                >
                  <Text
                    className="text-mb-accent-ink text-[11px] lowercase"
                    style={{
                      fontFamily: "GeistMono_600SemiBold",
                      letterSpacing: 0.4,
                    }}
                  >
                    open terminal
                  </Text>
                </RouterLinkPressable>
              </StyledLink>
              <Touchable
                feedback="subtle"
                accessibilityRole="button"
                accessibilityLabel="refresh terminal and workspace status"
                disabled={workspaceRefreshing}
                hitSlop={adminActionHitSlop}
                onPress={() => {
                  hapticTick("light");
                  void Promise.all([
                    runtimeStatus.refetch(),
                    workspaceStatus.refetch(),
                  ]);
                }}
                style={{ borderCurve: "continuous" }}
                className={`px-3 h-9 rounded-md border border-mb-border-strong bg-mb-surface-2 items-center justify-center ${
                  workspaceRefreshing ? "opacity-60" : ""
                }`}
              >
                <Text
                  className="text-mb-text text-[11px] lowercase"
                  style={{
                    fontFamily: "GeistMono_500Medium",
                    letterSpacing: 0.3,
                  }}
                >
                  {workspaceRefreshing ? "refreshing…" : "refresh"}
                </Text>
              </Touchable>
            </View>
            <View className="rounded-md bg-mb-surface-2 px-2.5 py-2 gap-1">
              <Text
                className="text-mb-muted text-[10px] lowercase"
                style={{
                  fontFamily: "GeistMono_500Medium",
                  letterSpacing: 0.3,
                }}
              >
                workspace
              </Text>
              <Text
                className="text-mb-text text-[11px] lowercase"
                style={{
                  fontFamily: "GeistMono_500Medium",
                  letterSpacing: 0.2,
                }}
                numberOfLines={1}
              >
                {workspaceStatus.data
                  ? `${workspaceStatus.data.projectName} · ${workspaceStatus.data.branch} · ${
                      workspaceStatus.data.writeEnabled ? "writes" : "read"
                    }`
                  : null}
              </Text>
            </View>
            {runtimeStatus.error ? (
              <Text
                className="text-mb-danger text-[11px]"
                style={{ fontFamily: "GeistMono_400Regular" }}
                selectable
              >
                {runtimeStatus.error instanceof Error
                  ? runtimeStatus.error.message
                  : String(runtimeStatus.error)}
              </Text>
            ) : null}
            {workspaceStatus.error ? (
              <Text
                className="text-mb-danger text-[11px]"
                style={{ fontFamily: "GeistMono_400Regular" }}
                selectable
              >
                {workspaceStatus.error instanceof Error
                  ? workspaceStatus.error.message
                  : String(workspaceStatus.error)}
              </Text>
            ) : null}
          </View>
        </View>

        <View className="gap-3">
          <SectionHeader>agent runtime</SectionHeader>
          <View className="gap-1.5">
            <Text
              className="text-mb-muted text-[10px] lowercase px-0.5"
              style={{ fontFamily: "GeistMono_500Medium", letterSpacing: 0.3 }}
            >
              tool mode
            </Text>
            <View className="flex-row flex-wrap gap-1.5">
              {AGENT_TOOL_MODES.map((mode) => {
                const active = agentDraft.toolMode === mode;
                const meta = TOOL_MODE_LABELS[mode];
                return (
                  <Touchable
                    feedback="subtle"
                    key={mode}
                    hitSlop={adminChipHitSlop}
                    onPress={() => {
                      hapticTick("light");
                      updateAgentDraft({ toolMode: mode });
                    }}
                    style={{ borderCurve: "continuous" }}
                    className={`px-3 py-2 min-h-11 rounded-md border ${
                      active
                        ? "bg-mb-accent border-mb-accent"
                        : "bg-mb-surface border-mb-border-strong"
                    }`}
                  >
                    <Text
                      className={`text-[11px] lowercase ${
                        active ? "text-mb-accent-ink" : "text-mb-text"
                      }`}
                      style={{
                        fontFamily: "GeistMono_600SemiBold",
                        letterSpacing: 0.3,
                      }}
                    >
                      {meta.label}
                    </Text>
                    <Text
                      className={`text-[12px] lowercase ${
                        active ? "text-mb-accent-ink" : "text-mb-muted"
                      }`}
                      style={{ fontFamily: "GeistMono_400Regular" }}
                    >
                      {meta.detail}
                    </Text>
                  </Touchable>
                );
              })}
            </View>
          </View>

          <View className="gap-1.5">
            <Text
              className="text-mb-muted text-[10px] lowercase px-0.5"
              style={{ fontFamily: "GeistMono_500Medium", letterSpacing: 0.3 }}
