                  style={{ fontFamily: "GeistMono_500Medium" }}
                >
                  {MODEL_PROMPT_LABELS[key]}
                </Text>
                <MonoTextInput
                  accessibilityLabel={MODEL_PROMPT_LABELS[key]}
                  multiline
                  options={{
                    autoCorrect: false,
                    autoCapitalize: "none",
                    minHeight: 88,
                    variant: "editor",
                  }}
                  value={agentDraft.modelPrompts[key] ?? ""}
                  onChangeText={(value) => updateAgentModelPrompt(key, value)}
                  placeholder={`${key} prompt…`}
                />
              </View>
            ))}
          </View>

          <View className="gap-1.5">
            <View className="flex-row items-center justify-between gap-2 px-0.5">
              <Text
                className="text-mb-muted text-[10px] lowercase"
                style={{
                  fontFamily: "GeistMono_500Medium",
                  letterSpacing: 0.3,
                }}
              >
                per-tool path rules
              </Text>
              <Touchable
                feedback="subtle"
                onPress={() => {
                  hapticTick("light");
                  setShowRawPathRules((prev) => !prev);
                }}
                hitSlop={adminTinyActionHitSlop}
                style={{ borderCurve: "continuous" }}
                className="h-7 px-2 rounded-md border border-mb-border-strong bg-mb-surface items-center justify-center"
              >
                <Text
                  className="text-mb-text text-[10px] lowercase"
                  style={{
                    fontFamily: "GeistMono_500Medium",
                    letterSpacing: 0.3,
                  }}
                >
                  {showRawPathRules ? "hide json" : "raw json"}
                </Text>
              </Touchable>
            </View>
            <View className="gap-2">
              {toolPathRuleNames.map((toolName) => {
                const rule = agentDraft.toolPathRules[toolName] ?? {};
                const inherited = Object.hasOwn(
                  DEFAULT_AGENT_TOOL_PATH_RULES,
                  toolName
                );
                return (
                  <View
                    key={toolName}
                    className="rounded-lg border border-mb-border bg-mb-surface px-3 py-3 gap-2"
                    style={{ borderCurve: "continuous" }}
                  >
                    <View className="flex-row flex-wrap items-start justify-between gap-2">
                      <View className="gap-0.5">
                        <Text
                          className="text-mb-text text-[12px]"
                          style={{ fontFamily: "GeistMono_600SemiBold" }}
                        >
                          {toolName}
                        </Text>
                        <Text
                          className="text-mb-muted text-[10px] lowercase"
                          style={{ fontFamily: "GeistMono_400Regular" }}
                        >
                          {inherited ? "default policy" : "custom policy"} ·{" "}
                          {ruleValueCount(rule)} controls
                        </Text>
                      </View>
                      <View className="flex-row flex-wrap gap-1.5">
                        {(
                          [
                            ["allowRecursiveDelete", "recursive delete"],
                            ["allowShellDestructive", "destructive shell"],
                          ] as const
                        ).map(([key, label]) => {
                          const active = rule[key] === true;
                          return (
                            <Touchable
                              feedback="subtle"
                              key={key}
                              hitSlop={adminTinyActionHitSlop}
                              onPress={() => {
                                hapticTick("light");
                                updateToolPathRule(toolName, {
                                  [key]: !active,
                                });
                              }}
                              style={{ borderCurve: "continuous" }}
                              className={`h-7 px-2 rounded-md border items-center justify-center ${
                                active
                                  ? "bg-mb-danger-dim border-mb-danger"
                                  : "bg-mb-surface-2 border-mb-border-strong"
                              }`}
                            >
                              <Text
                                className={`text-[12px] lowercase ${
                                  active ? "text-mb-danger" : "text-mb-muted"
                                }`}
                                style={{
                                  fontFamily: "GeistMono_500Medium",
                                  letterSpacing: 0.2,
                                }}
                              >
                                {active ? "allows " : "blocks "}
                                {label}
                              </Text>
                            </Touchable>
                          );
                        })}
                      </View>
                    </View>
                    <View className="gap-2">
                      {PATH_RULE_FIELDS.map(({ key, label }) => (
                        <View key={key} className="gap-1">
                          <Text
                            className="text-mb-muted text-[12px] lowercase"
                            style={{
                              fontFamily: "GeistMono_500Medium",
                              letterSpacing: 0.3,
                            }}
                          >
                            {label}
                          </Text>
                          <MonoTextInput
                            accessibilityLabel={label}
                            multiline
                            options={{
                              autoCorrect: false,
                              autoCapitalize: "none",
                              minHeight: 58,
                              variant: "editor",
                            }}
                            value={formatPathList(rule[key])}
                            onChangeText={(text) =>
                              updateToolPathRule(toolName, {
                                [key]: parsePathList(text),
                              })
                            }
                            placeholder="none"
                          />
                        </View>
                      ))}
                    </View>
                  </View>
                );
              })}
            </View>
            {showRawPathRules ? (
              <MonoTextInput
                accessibilityLabel="raw path rules JSON"
                multiline
                options={{
                  autoCorrect: false,
                  autoCapitalize: "none",
                  minHeight: 180,
                  variant: "editor",
                }}
                value={toolPathRulesText}
                onChangeText={(text) => {
                  setAgentState((prev) => {
                    let nextDraft = prev.draft;
                    try {
                      const value: unknown = JSON.parse(text);
                      const parsed = agentToolPathRulesSchema.parse(value);
                      nextDraft = { ...prev.draft, toolPathRules: parsed };
                    } catch {
                      // Keep the text editable while surfacing the parse error below.
                    }
                    return {
                      ...prev,
                      draft: nextDraft,
                      toolPathRulesText: text,
                    };
                  });
                }}
                placeholder="{ }"
              />
            ) : null}
            {toolPathRulesError ? (
              <Text
                className="text-mb-danger text-[11px] px-0.5"
                style={{ fontFamily: "GeistMono_400Regular" }}
                selectable
              >
                {toolPathRulesError}
              </Text>
            ) : (
              <Text
                className="text-mb-muted text-[10px] px-0.5"
                style={{ fontFamily: "GeistMono_400Regular" }}
              >
                each tool may define readRoots, writeRoots, blockedRoots,
                protectedRoots, and destructive allow flags
              </Text>
            )}
          </View>

          <View className="flex-row gap-2 items-center flex-wrap">
            <Touchable
              feedback="subtle"
              disabled={
                !agentDirty || saveAgentConfig.isPending || !!toolPathRulesError
              }
              hitSlop={adminActionHitSlop}
              onPress={() => {
                hapticTick("medium");
                saveAgentConfig.mutate(agentDraft);
              }}
              style={{ borderCurve: "continuous" }}
              className={`px-3 h-9 rounded-md items-center justify-center ${
                agentDirty && !saveAgentConfig.isPending && !toolPathRulesError
                  ? "bg-mb-accent"
                  : "bg-mb-surface-2 opacity-60"
              }`}
            >
              <Text
                className={`text-[11px] lowercase ${
                  agentDirty &&
                  !saveAgentConfig.isPending &&
                  !toolPathRulesError
                    ? "text-mb-accent-ink"
                    : "text-mb-muted"
                }`}
                style={{
                  fontFamily: "GeistMono_600SemiBold",
                  letterSpacing: 0.4,
                }}
              >
                {saveAgentConfig.isPending ? "saving…" : "save agent config"}
              </Text>
            </Touchable>
            <Touchable
              feedback="subtle"
              hitSlop={adminActionHitSlop}
              onPress={() => {
                hapticTick("light");
                setAgentState((prev) => ({
                  ...prev,
                  draft: prev.original,
                  toolPathRulesText: JSON.stringify(
                    prev.original.toolPathRules,
                    null,
                    2
                  ),
                }));
              }}
              style={{ borderCurve: "continuous" }}
              className="px-3 h-9 rounded-md items-center justify-center border border-mb-border-strong bg-mb-surface"
            >
              <Text
                className="text-mb-text text-[11px] lowercase"
                style={{
                  fontFamily: "GeistMono_500Medium",
                  letterSpacing: 0.4,
                }}
              >
                defaults
              </Text>
            </Touchable>
            {saveAgentConfig.isSuccess && !agentDirty ? (
              <Text
                className="text-mb-success text-[11px]"
                style={{ fontFamily: "GeistMono_400Regular" }}
              >
                saved
              </Text>
            ) : null}
            {saveAgentConfig.error ? (
              <Text
                className="text-mb-danger text-[11px]"
                style={{ fontFamily: "GeistMono_400Regular" }}
                selectable
              >
                {String(saveAgentConfig.error)}
              </Text>
            ) : null}
          </View>
        </View>

        <View className="gap-2">
          <SectionHeader>chat profile</SectionHeader>
          <View className="flex-row flex-wrap gap-1.5">
            {chatProfiles?.map((p) => {
              const active = selected === p.id;
              return (
                <Touchable
                  feedback="subtle"
                  accessibilityRole="button"
                  accessibilityLabel={`select chat profile ${p.id}`}
                  key={p.id}
                  hitSlop={adminChipHitSlop}
                  onPress={() => {
                    hapticTick("light");
                    setSelectedOverride(p.id);
                  }}
                  style={{ borderCurve: "continuous" }}
                  className={`px-3 py-2 rounded-md items-start justify-center border ${
                    active
                      ? "bg-mb-accent border-mb-accent"
                      : "bg-mb-surface border-mb-border-strong"
                  }`}
                >
                  <Text
                    className={`text-[11px] lowercase ${
                      active ? "text-mb-accent-ink" : "text-mb-text"
                    }`}
                    style={{
                      fontFamily: "GeistMono_500Medium",
                      letterSpacing: 0.3,
                    }}
                  >
                    {p.name}
                  </Text>
                  <Text
                    className={`text-[12px] lowercase ${
                      active ? "text-mb-accent-ink" : "text-mb-muted"
                    }`}
                    style={{
                      fontFamily: "GeistMono_400Regular",
                      letterSpacing: 0.2,
                    }}
                  >
                    {p.id} · {p.runtime} · :{p.port}
                  </Text>
                </Touchable>
              );
            })}
          </View>
        </View>
        {conf.data?.error ? (
          <Text
            className="text-mb-danger text-[11px] px-0.5"
            style={{ fontFamily: "GeistMono_400Regular" }}
            selectable
          >
            {conf.data.error}
          </Text>
        ) : null}
        {confDraftReady ? (
          <MonoTextInput
            accessibilityLabel="conf content"
            multiline
            options={{
              autoCorrect: false,
              autoCapitalize: "none",
              minHeight: 360,
              variant: "editor",
            }}
            value={draft}
            onChangeText={setDraft}
            placeholder="conf content…"
          />
        ) : null}
        {validationWarnings.length > 0 ? (
          <View className="gap-1.5">
            {validationWarnings.map((w, i) => (
              <View
                key={i}
                className="rounded-lg border border-mb-warm-dim bg-mb-warm-dim/40 px-3 py-2"
                style={{ borderCurve: "continuous" }}
              >
                <Text
                  className="text-mb-warm text-[11px]"
                  style={{ fontFamily: "GeistMono_400Regular", lineHeight: 17 }}
                  selectable
                >
                  {w}
                </Text>
              </View>
            ))}
          </View>
        ) : null}
        <View className="gap-3">
          <View className="flex-row gap-2 items-center flex-wrap">
            <Touchable
              feedback="subtle"
              disabled={!dirty || save.isPending || !selected}
              hitSlop={adminActionHitSlop}
              onPress={() => {
                if (!selected) return;
                hapticTick("medium");
                save.mutate({ profile: selected, content: draft });
              }}
              style={{ borderCurve: "continuous" }}
              className={`px-3 h-9 rounded-md items-center justify-center ${
                dirty && !save.isPending
                  ? "bg-mb-accent"
                  : "bg-mb-surface-2 opacity-60"
              }`}
            >
              <Text
                className={`text-[11px] lowercase ${
                  dirty && !save.isPending
                    ? "text-mb-accent-ink"
                    : "text-mb-muted"
                }`}
                style={{
                  fontFamily: "GeistMono_600SemiBold",
                  letterSpacing: 0.4,
                }}
              >
                {save.isPending ? "saving…" : "save & restart if active"}
              </Text>
            </Touchable>
            {save.data?.restarted ? (
              <Text
                className="text-mb-success text-[11px]"
                style={{ fontFamily: "GeistMono_400Regular" }}
              >
                {save.data.status}
              </Text>
            ) : save.data?.status === "saved" ? (
              <Text
                className="text-mb-muted text-[11px]"
                style={{ fontFamily: "GeistMono_400Regular" }}
              >
                saved · no restart needed
              </Text>
            ) : null}
            {save.error ? (
              <Text
                className="text-mb-danger text-[11px]"
                style={{ fontFamily: "GeistMono_400Regular" }}
                selectable
              >
                {String(save.error)}
              </Text>
            ) : null}
          </View>
          <RestartProgress active={save.isPending} />
        </View>
      </ScrollView>
    </View>
  );
}

import { useCallback, useMemo, useRef, useState } from "react";
import { Platform, useWindowDimensions } from "react-native";
import { Link } from "expo-router";
import {
  RouterLinkPressable,
  Touchable,
  ScrollView,
  Text,
  TextInput,
  View,
} from "@/tw";
import { MascotImage } from "@/components/MascotImage";
import { useRuntimeSignOut } from "@/components/auth/use-runtime-sign-out";
import { SectionHeader } from "@/components/chat/section-header";
import { NativeSwitch } from "@/components/ui/expo-native-controls";
import { DEFAULT_BASE_URL, normalizeBaseURL, useBaseURL } from "@/lib/config";
import {
  useModelCatalog,
  useRuntimeStatus,
  useSaveWorkspacePreferences,
  useWorkspacePreferences,
} from "@/lib/data";
import { useFeaturePrefs } from "@/lib/feature-prefs";
import { useThemeMode } from "@/lib/theme";
import { hapticTick } from "@/lib/haptics";
import { getHitSlopForVisualSize } from "@/lib/native-ui";
import { endpointHealthState } from "@/screens/settings/settings-endpoint-state";
import { useNotificationSetting } from "@/components/notifications/use-notification-setting";

const settingsActionHitSlop = getHitSlopForVisualSize(36);

function SettingsServerNativeIsland({
  baseURL,
  effectiveBaseURL,
  setBaseURL,
}: {
  baseURL: string;
  effectiveBaseURL: string;
  setBaseURL: (nextBaseURL: string) => void;
}) {
  const { colors } = useThemeMode();
  const [draft, setDraft] = useState(baseURL);
  const dirty = normalizeBaseURL(draft) !== baseURL;

  const saveServerURL = useCallback(() => {
    const normalized = normalizeBaseURL(draft);
    hapticTick("medium");
    setDraft(normalized);
    setBaseURL(normalized);
  }, [draft, setBaseURL]);

  const resetServerURL = useCallback(() => {
    hapticTick("light");
    setDraft(DEFAULT_BASE_URL);
    setBaseURL(DEFAULT_BASE_URL);
  }, [setBaseURL]);

  return (
    <View testID="homer-settings-server-native-island" className="gap-2">
      <TextInput
        value={draft}
        onChangeText={setDraft}
        onSubmitEditing={saveServerURL}
        autoCapitalize="none"
        autoCorrect={false}
        keyboardType="url"
        placeholder={effectiveBaseURL}
        placeholderTextColor={colors.muted}
        cursorColor={colors.accent}
        selectionColor={colors.accent}
        returnKeyType="done"
        testID="homer-settings-server-url-input"
        className="h-11 rounded-lg border border-mb-border-strong bg-mb-input px-3 text-[13px] text-mb-text"
        style={{ fontFamily: "GeistMono_400Regular" }}
      />
      <View className="flex-row gap-2">
        <Touchable
          feedback="standard"
          disabled={!dirty}
          accessibilityRole="button"
          accessibilityLabel="save server URL"
          accessibilityState={{ disabled: !dirty }}
          onPress={saveServerURL}
          testID="homer-settings-server-save"
          className={`h-11 min-w-24 items-center justify-center rounded-lg bg-mb-text px-4 ${dirty ? "" : "opacity-40"}`}
        >
          <Text
            className="text-[13px] text-mb-bg"
            style={{ fontFamily: "Geist_600SemiBold" }}
          >
            Save
          </Text>
        </Touchable>
        <Touchable
          feedback="standard"
          accessibilityRole="button"
          accessibilityLabel="reset server URL"
          onPress={resetServerURL}
          testID="homer-settings-server-reset"
          className="h-11 min-w-24 items-center justify-center rounded-lg border border-mb-border-strong bg-mb-surface px-4"
        >
          <Text
            className="text-[13px] text-mb-text"
            style={{ fontFamily: "Geist_600SemiBold" }}
          >
            Reset
          </Text>
        </Touchable>
      </View>
      {dirty ? (
        <Text
          className="text-[12px] text-mb-muted"
          style={{
            fontFamily: "GeistMono_400Regular",
            letterSpacing: 0.2,
          }}
        >
          {`Saved: ${effectiveBaseURL}`}
        </Text>
      ) : null}
    </View>
  );
}

function FeatureToggleRow({
  border = false,
  description,
  label,
  onToggle,
  testID,
  value,
}: {
  border?: boolean;
  description: string;
  label: string;
  onToggle: () => void;
  testID: string;
  value: boolean;
}) {
  return (
    <View
      className={`flex-row items-center gap-3 px-3 py-2.5 ${
        border ? "border-b border-mb-border" : ""
      }`}
    >
      <View className="flex-1 gap-0.5">
        <Text
          className="text-mb-text text-[12px]"
          style={{ fontFamily: "Geist_500Medium" }}
        >
          {label}
        </Text>
        <Text
          className="text-mb-muted text-[12px]"
          style={{
            fontFamily: "GeistMono_400Regular",
            letterSpacing: 0.2,
          }}
        >
          {description}
        </Text>
      </View>
      <NativeSwitch
        accessibilityLabel={label}
        onValueChange={() => {
          hapticTick("light");
          onToggle();
        }}
        testID={testID}
        value={value}
      />
    </View>
  );
}

export default function SettingsScreen() {
  const { width } = useWindowDimensions();
  const isDesktop = width >= 768;
  const { baseURL, setBaseURL, storedUrlError } = useBaseURL();
  const signOut = useRuntimeSignOut();
  const runtimeStatus = useRuntimeStatus();
  const modelCatalog = useModelCatalog();
  const workspacePreferences = useWorkspacePreferences({ enabled: true });
  const saveWorkspacePreferences = useSaveWorkspacePreferences();
  const { prefs, toggle } = useFeaturePrefs();
  const notifications = useNotificationSetting();
  const [signOutError, setSignOutError] = useState<string | null>(null);
  const [signingOut, setSigningOut] = useState(false);
  const signOutOperationRef = useRef<ReturnType<typeof signOut> | null>(null);
  const catalogModels = modelCatalog.error
    ? undefined
    : modelCatalog.data?.models;
  const chatEndpoints = useMemo(
    () => catalogModels?.filter((model) => model.kind === "chat"),
    [catalogModels]
  );
  const endpointHealth = runtimeStatus.error
    ? undefined
    : runtimeStatus.data?.active.chatHealth;

  const startSignOut = useCallback(() => {
    if (signOutOperationRef.current) return;
    hapticTick("medium");
    setSignOutError(null);
    const operation = signOut();
    signOutOperationRef.current = operation;
    setSigningOut(true);
    const settle = () => {
      if (signOutOperationRef.current !== operation) return;
      signOutOperationRef.current = null;
      setSigningOut(false);
    };
    void operation.then(settle, () => {
      settle();
      setSignOutError("Couldn't sign out. Try again.");
    });
  }, [signOut]);

  const effectiveBaseURL =
    baseURL ||
    (Platform.OS === "web" && typeof window !== "undefined"
      ? window.location.origin
      : DEFAULT_BASE_URL);

  return (
    <View className="flex-1 bg-mb-bg">
      <ScrollView
        className="flex-1"
        contentContainerStyle={{
          paddingTop: isDesktop ? 28 : 20,
          paddingBottom: 32,
          paddingHorizontal: isDesktop ? 24 : 16,
          gap: 24,
          maxWidth: isDesktop ? 820 : undefined,
          width: "100%",
          alignSelf: "center",
        }}
        contentInsetAdjustmentBehavior="automatic"
      >
        <View className="gap-2">
          <SectionHeader>server</SectionHeader>
          <SettingsServerNativeIsland
            key={baseURL}
            baseURL={baseURL}
            effectiveBaseURL={effectiveBaseURL}
            setBaseURL={setBaseURL}
          />
          {storedUrlError ? (
            <Text
              className="text-mb-danger text-[12px]"
              style={{ fontFamily: "GeistMono_400Regular", letterSpacing: 0.2 }}
              testID="homer-settings-server-stored-url-error"
            >
              {`${storedUrlError} the saved value was replaced with ${DEFAULT_BASE_URL}.`}
            </Text>
          ) : null}
        </View>

        <View className="gap-2">
          <SectionHeader>endpoints</SectionHeader>
          {modelCatalog.error || chatEndpoints ? (
            <View
              className="rounded-xl border border-mb-border bg-mb-surface overflow-hidden"
              style={{ borderCurve: "continuous" }}
            >
              {modelCatalog.error || chatEndpoints?.length === 0 ? (
                <View className="px-3 py-4 flex-row gap-3">
                  <MascotImage size={42} radius={12} />
                  <View className="flex-1 gap-1">
                    <Text
                      className="text-mb-text text-[12px]"
                      style={{ fontFamily: "Geist_500Medium" }}
                    >
                      {modelCatalog.error
                        ? "Endpoints unavailable"
                        : "No endpoints reported"}
                    </Text>
                    <Text
                      className="text-mb-muted text-[12px]"
                      style={{
                        fontFamily: "GeistMono_400Regular",
                        letterSpacing: 0.2,
                      }}
                    >
                      {modelCatalog.error
                        ? "The endpoint catalog could not be loaded from the server above."
                        : "Start the Homer API on the server above to populate this list."}
                    </Text>
                  </View>
                </View>
              ) : null}
              {chatEndpoints?.map((model, index, endpoints) => {
                const healthState = endpointHealth
                  ? endpointHealthState(endpointHealth[model.id])
                  : null;
                const isLast = index === endpoints.length - 1;
                return (
                  <View
                    key={model.id}
                    className={`gap-1.5 px-3 py-2.5 ${
                      isLast ? "" : "border-b border-mb-border"
                    }`}
                  >
                    <View className="flex-row items-center gap-2">
                      {healthState ? (
                        <View
                          className={`h-1.5 w-1.5 rounded-full ${
                            healthState === "online"
                              ? "bg-mb-success"
                              : healthState === "checking" ||
                                  healthState === "loading"
                                ? "bg-mb-muted"
                                : "bg-mb-danger"
                          }`}
                        />
                      ) : null}
                      <Text
                        className="text-mb-text text-[12px] flex-1"
                        style={{ fontFamily: "Geist_500Medium" }}
                        numberOfLines={1}
                      >
                        {model.name}
                      </Text>
                      <Text
                        className="text-mb-muted text-[12px]"
                        style={{
                          fontFamily: "GeistMono_500Medium",
                          fontVariant: ["tabular-nums"],
                        }}
                      >
                        :{model.runtime.port}
                        {healthState ? ` · ${healthState}` : ""}
                      </Text>
                    </View>
                    <Text
                      className="text-mb-muted text-[12px] pl-3.5"
                      style={{ fontFamily: "GeistMono_400Regular" }}
                      numberOfLines={1}
                      selectable
                    >
                      {model.id} · {model.runtime.engine}
                    </Text>
                  </View>
                );
              })}
              {chatEndpoints?.length && runtimeStatus.error ? (
                <View className="border-t border-mb-border px-3 py-2">
                  <Text
                    className="text-mb-danger text-[12px]"
                    style={{ fontFamily: "GeistMono_400Regular" }}
                  >
                    Endpoint health is unavailable.
                  </Text>
                </View>
              ) : null}
            </View>
          ) : null}
        </View>

        <View className="gap-2">
          <SectionHeader>workspace</SectionHeader>
          {workspacePreferences.data ? (
            <View
              className="rounded-xl border border-mb-border bg-mb-surface overflow-hidden"
              style={{ borderCurve: "continuous" }}
            >
              <View className="flex-row items-center gap-3 px-3 py-2.5">
                <View className="flex-1 gap-0.5">
                  <Text
                    className="text-mb-text text-[12px]"
                    style={{ fontFamily: "Geist_500Medium" }}
                  >
                    Allow agent writes
                  </Text>
                  <Text
                    className="text-mb-muted text-[12px]"
                    style={{
                      fontFamily: "GeistMono_400Regular",
                      letterSpacing: 0.2,
                    }}
                  >
                    {workspacePreferences.data.writeEnabled
                      ? "Agents may modify files"
                      : "Agent tools remain read-only"}
                  </Text>
                </View>
                <NativeSwitch
                  accessibilityLabel="allow agent writes"
                  disabled={saveWorkspacePreferences.isPending}
