const QUERY_CACHE_OBSERVED =
  __DEV__ || process.env.EXPO_PUBLIC_PERF_FIXTURES === "1";

function observeQueryCache(client: QueryClient): QueryClient {
  if (!QUERY_CACHE_OBSERVED) return client;
  client.getQueryCache().subscribe((event) => {
    if (event.type !== "updated") return;
    const name = JSON.stringify(event.query.queryKey);
    const { status, fetchStatus, error } = event.query.state;
    if (fetchStatus === "fetching") {
      logObservabilityEvent({ category: "query", name, outcome: "start" });
      return;
    }
    if (status === "error") {
      logObservabilityEvent({
        category: "query",
        name,
        outcome: "error",
        detail: error instanceof Error ? error.message : String(error),
      });
      return;
    }
    if (status === "success" && fetchStatus === "idle") {
      logObservabilityEvent({ category: "query", name, outcome: "ok" });
    }
  });
  return client;
}

function AppShell() {
  const [queryClient] = useState(() =>
    observeQueryCache(
      new QueryClient({
        defaultOptions: {
          queries: {
            staleTime: DEFAULT_QUERY_STALE_TIME_MS,
            retry: 1,
            refetchOnWindowFocus: false,
          },
        },
      })
    )
  );
  return (
    <QueryClientProvider client={queryClient}>
      <StatusBar style="dark" />
      <View
        className="flex-1 bg-mb-bg"
