import { requireCurrentUser, requireOwnedMachine } from "./machineAuth";

type DatabaseCtx = QueryCtx | MutationCtx;
type ConversationResource = Infer<typeof conversationResourceValue>;
type ConversationBinding = ConversationResource["binding"];
type ConversationCreateInput = Infer<typeof conversationCreateValue>;
type MachineCreateBinding = Extract<
  ConversationCreateInput["binding"],
  { kind: "machine" }
>;
type ConversationMessageDraft = Extract<
  ConversationChangeInput,
  { type: "message.put" }
>["message"];
type GenerationDraft = Extract<
  ConversationChangeInput,
  { type: "generation.put" }
>["generation"];
type DispatchState = {
  ctx: MutationCtx;
  conversation: Doc<"conversations">;
  now: string;
};

function conversationById(
  ctx: DatabaseCtx,
  userId: Doc<"users">["_id"],
  conversationId: string
) {
  return ctx.db
    .query("conversations")
    .withIndex("by_user_conversation", (query) =>
      query.eq("userId", userId).eq("conversationId", conversationId)
    )
    .unique();
}

function globallyOwnedConversation(ctx: DatabaseCtx, conversationId: string) {
  return ctx.db
    .query("conversations")
    .withIndex("by_conversation", (query) =>
      query.eq("conversationId", conversationId)
    )
    .unique();
}

async function requireConversation(
  ctx: DatabaseCtx,
  userId: Doc<"users">["_id"],
  conversationId: string
) {
  const conversation = await conversationById(ctx, userId, conversationId);
  if (!conversation) {
    throw new Error(`Conversation ${conversationId} does not exist.`);
  }
  return conversation;
}

async function conversationBindingView(
  ctx: DatabaseCtx,
  conversation: Doc<"conversations">
): Promise<ConversationBinding> {
  if (conversation.binding.kind === "model") {
    return conversation.binding;
  }
  const binding = conversation.binding;
  const machine = await requireOwnedMachine(
    ctx,
    conversation.userId,
    binding.machine
  );
  return {
    kind: "machine",
    machineId: machine.machineId,
    agentId: binding.agentId,
    ...(binding.cwd === undefined ? {} : { cwd: binding.cwd }),
  };
}

async function conversationView(
  ctx: DatabaseCtx,
  conversation: Doc<"conversations">
): Promise<ConversationResource> {
  return {
    conversation: {
      conversationId: conversation.conversationId,
      title: conversation.title,
      continuedFrom: conversation.continuedFrom,
      activity: conversation.activity,
      itemCount: conversation.itemCount,
      updatedAt: conversation.updatedAt,
    },
    binding: await conversationBindingView(ctx, conversation),
  };
}

function creationBindingMatches(
  actual: ConversationBinding,
  expected: ConversationCreateInput["binding"]
): boolean {
  if (expected.kind === "model") {
    if (actual.kind !== "model") return false;
    const actualModel = actual.modelSnapshot;
    const expectedModel = expected.modelSnapshot;
    return (
      actualModel.id === expectedModel.id &&
      actualModel.name === expectedModel.name &&
      actualModel.kind === expectedModel.kind &&
      actualModel.targetJson === expectedModel.targetJson
    );
  }
  if (actual.kind !== "machine") return false;
  return (
    actual.machineId === expected.machineId &&
    actual.agentId === expected.agentId &&
    (expected.cwd === undefined || actual.cwd === expected.cwd)
  );
}

function conversationCreationMatches(
  actual: Doc<"conversations">,
  expected: ConversationCreateInput
) {
  return (
    actual.conversationId === expected.conversationId &&
    actual.title === expected.title &&
    actual.continuedFrom === expected.continuedFrom
  );
}

function conversationListRowBase(conversation: Doc<"conversations">) {
  return {
    key: conversation.conversationId,
    conversationId: conversation.conversationId,
    title: conversation.title,
    updatedAt: conversation.updatedAt,
    kind: "conversation" as const,
    activity: conversation.activity,
    itemCount: conversation.itemCount,
  };
}

function modelConversationListRow(conversation: Doc<"conversations">) {
  if (conversation.binding.kind !== "model") {
    throw new Error("Model conversation list row requires a model binding.");
  }
  const modelSnapshot = conversation.binding.modelSnapshot;
  return {
    ...conversationListRowBase(conversation),
    origin: {
      kind: "model" as const,
      model: {
        id: modelSnapshot.id,
        name: modelSnapshot.name,
        kind: modelSnapshot.kind,
      },
    },
  };
}

function machineConversationListRow(
  conversation: Doc<"conversations">,
  machine: Doc<"machines">
) {
  if (conversation.binding.kind !== "machine") {
    throw new Error(
      "Machine conversation list row requires a Machine binding."
    );
  }
  if (conversation.binding.machine !== machine._id) {
    throw new Error("Machine conversation list row resolved another Machine.");
  }
  return {
    ...conversationListRowBase(conversation),
    origin: {
      kind: "machine" as const,
      machineId: machine.machineId,
      machineName: machine.name,
      agentId: conversation.binding.agentId,
    },
  };
}

async function conversationListRow(
  ctx: DatabaseCtx,
  conversation: Doc<"conversations">
) {
  if (conversation.binding.kind === "model") {
    return modelConversationListRow(conversation);
  }
  const machine = await requireOwnedMachine(
    ctx,
    conversation.userId,
    conversation.binding.machine
  );
  return machineConversationListRow(conversation, machine);
}

function conversationRowLimit(limit: number | undefined) {
  const resolved = limit ?? 80;
  if (!Number.isSafeInteger(resolved) || resolved < 1 || resolved > 80) {
    throw new Error("Conversation row limit must be between 1 and 80.");
  }
  return resolved;
}

async function machineBindingForCreate(
  ctx: MutationCtx,
  userId: Doc<"users">["_id"],
  binding: MachineCreateBinding
) {
  const machine = await ctx.db
    .query("machines")
    .withIndex("by_user_machine", (index) =>
      index.eq("userId", userId).eq("machineId", binding.machineId)
    )
    .unique();
  if (!machine || machine.userId !== userId) {
    throw new Error("Machine conversation requires an owned Machine.");
  }
  if (machine.registration.kind !== "connected") {
    throw new Error("Machine conversation requires a connected Machine.");
  }
  if (!machine.roster) {
    throw new Error("Machine conversation requires a published Agent roster.");
  }
  if (!machine.roster.agents.some((agent) => agent.id === binding.agentId)) {
    throw new Error("Machine conversation Agent is not in the Machine roster.");
  }
  return {
    kind: "machine" as const,
    machine: machine._id,
    agentId: binding.agentId,
    ...(binding.cwd === undefined ? {} : { cwd: binding.cwd }),
  };
}

async function allocateSequence(state: DispatchState): Promise<number> {
  const sequence = state.conversation.nextSequence;
  await state.ctx.db.patch("conversations", state.conversation._id, {
    nextSequence: sequence + 1,
  });
  return sequence;
}

async function updateConversationSummary(
  state: DispatchState,
  itemDelta: number,
  activity?: Doc<"conversations">["activity"]
) {
  const itemCount = state.conversation.itemCount + itemDelta;
  if (itemCount < 0) {
    throw new Error("Conversation item count cannot become negative.");
  }
  await state.ctx.db.patch("conversations", state.conversation._id, {
    itemCount,
    ...(activity === undefined ? {} : { activity }),
    updatedAt: state.now,
  });
}

async function putMessage(
  state: DispatchState,
  message: ConversationMessageDraft
) {
  const existing = await state.ctx.db
    .query("conversationMessages")
    .withIndex("by_conversation_message", (query) =>
      query
        .eq("conversationId", state.conversation.conversationId)
        .eq("messageId", message.messageId)
    )
    .unique();
  const sequence = existing ? existing.sequence : await allocateSequence(state);
  const value = {
    conversationId: state.conversation.conversationId,
    ...message,
    sequence,
  };
  if (existing) {
    await state.ctx.db.patch("conversationMessages", existing._id, value);
  } else {
    await state.ctx.db.insert("conversationMessages", value);
  }
  await updateConversationSummary(state, existing ? 0 : 1);
}

async function removeMessage(state: DispatchState, messageId: string) {
  const existing = await state.ctx.db
    .query("conversationMessages")
    .withIndex("by_conversation_message", (query) =>
      query
        .eq("conversationId", state.conversation.conversationId)
        .eq("messageId", messageId)
    )
    .unique();
  if (!existing) return;
  await state.ctx.db.delete("conversationMessages", existing._id);
  await updateConversationSummary(state, -1);
}

async function putGeneration(
  state: DispatchState,
  generation: GenerationDraft
) {
  const existing = await state.ctx.db
    .query("generations")
    .withIndex("by_conversation_generation", (query) =>
      query
        .eq("conversationId", state.conversation.conversationId)
        .eq("generationId", generation.generationId)
    )
    .unique();
  const sequence = existing ? existing.sequence : await allocateSequence(state);
  const { name, ...generationFields } = generation;
  const normalizedName = normalizeGenerationName(name);
  const value = {
    conversationId: state.conversation.conversationId,
    ...generationFields,
    sequence,
    ...(normalizedName === undefined ? {} : { name: normalizedName }),
  };
  if (existing) {
    await state.ctx.db.patch("generations", existing._id, value);
  } else {
    await state.ctx.db.insert("generations", value);
  }
  const active = ["uploading", "queued", "running"].includes(generation.status);
  const failed = ["failed", "disabled"].includes(generation.status);
  await updateConversationSummary(
    state,
    existing ? 0 : 1,
    active ? "working" : failed ? "failed" : "idle"
  );
}

async function renameGeneration(
  state: DispatchState,
  generationId: string,
  name: string
) {
  const existing = await state.ctx.db
    .query("generations")
    .withIndex("by_conversation_generation", (query) =>
      query
        .eq("conversationId", state.conversation.conversationId)
        .eq("generationId", generationId)
    )
    .unique();
  if (!existing) {
    throw new Error("Generation does not exist.");
  }
  const { _id, _creationTime, name: _previousName, ...document } = existing;
  const normalizedName = normalizeGenerationName(name);
  await state.ctx.db.replace("generations", existing._id, {
    ...document,
    ...(normalizedName === undefined ? {} : { name: normalizedName }),
  });
  await state.ctx.db.patch("conversations", state.conversation._id, {
    updatedAt: state.now,
  });
}

async function removeGeneration(state: DispatchState, generationId: string) {
  const existing = await state.ctx.db
    .query("generations")
    .withIndex("by_conversation_generation", (query) =>
      query
        .eq("conversationId", state.conversation.conversationId)
        .eq("generationId", generationId)
    )
    .unique();
  if (!existing) return;
  await state.ctx.db.delete("generations", existing._id);
  await updateConversationSummary(state, -1, "idle");
}

async function applyConversationChange(
  state: DispatchState,
  change: ConversationChangeInput
) {
  if (
    change.type !== "conversation.rename" &&
    state.conversation.binding.kind !== "model"
  ) {
    throw new Error(
      "Machine conversations are projected only by Machine sync."
    );
  }
  switch (change.type) {
    case "message.put":
      return putMessage(state, change.message);
    case "message.remove":
      return removeMessage(state, change.messageId);
    case "generation.put":
      return putGeneration(state, change.generation);
    case "generation.remove":
      return removeGeneration(state, change.generationId);
    case "generation.rename":
      return renameGeneration(state, change.generationId, change.name);
    case "conversation.rename":
      await state.ctx.db.patch("conversations", state.conversation._id, {
        title: change.title,
        updatedAt: state.now,
      });
  }
}

async function dispatchChanges(
  ctx: MutationCtx,
  userId: Doc<"users">["_id"],
  conversationId: string,
  changes: ConversationChangeInput[]
) {
  const now = new Date().toISOString();
  for (const change of changes) {
    const conversation = await requireConversation(ctx, userId, conversationId);
    await applyConversationChange(
      {
        ctx,
        conversation,
        now,
      },
      change
    );
  }
  return conversationView(
    ctx,
    await requireConversation(ctx, userId, conversationId)
  );
}

export const listAllRows = query({
  args: { limit: v.optional(v.number()) },
  returns: v.array(conversationListRowValue),
  handler: async (ctx, args) => {
    const user = await requireCurrentUser(ctx);
    const conversations = await ctx.db
      .query("conversations")
      .withIndex("by_user_updated", (query) => query.eq("userId", user._id))
      .order("desc")
      .take(conversationRowLimit(args.limit));
    return await Promise.all(
      conversations.map((conversation) =>
        conversationListRow(ctx, conversation)
      )
    );
  },
});

export const listRowsForMachine = query({
  args: {
    machineId: machineIdValue,
    limit: v.optional(v.number()),
  },
  returns: v.array(conversationListRowValue),
  handler: async (ctx, args) => {
    assertMachineId(args.machineId);
    const user = await requireCurrentUser(ctx);
    const machine = await ctx.db
      .query("machines")
      .withIndex("by_user_machine", (index) =>
        index.eq("userId", user._id).eq("machineId", args.machineId)
      )
      .unique();
    if (!machine) {
      throw new Error("Machine conversation scope requires an owned Machine.");
    }
    const conversations = await ctx.db
      .query("conversations")
      .withIndex("by_user_machine_updated", (index) =>
        index
          .eq("userId", user._id)
          .eq("binding.kind", "machine")
          .eq("binding.machine", machine._id)
      )
      .order("desc")
      .take(conversationRowLimit(args.limit));
    return conversations.map((conversation) =>
      machineConversationListRow(conversation, machine)
    );
  },
});

export const listRowsForProject = query({
  args: {
    projectId: v.id("machineProjects"),
    limit: v.optional(v.number()),
