      .query("conversations")
      .withIndex("by_user_machine_cwd_updated", (index) =>
        index
          .eq("userId", user._id)
          .eq("binding.kind", "machine")
          .eq("binding.machine", machine._id)
          .eq("binding.cwd", project.cwd)
