export const create = mutation({
  args: { input: conversationCreateValue },
  returns: conversationResourceValue,
  handler: async (ctx, args) => {
    const input = normalizeConversationCreate(args.input);
    assertConversationCreateSemantics(input);
    const user = await requireCurrentUser(ctx);
    const existing = await globallyOwnedConversation(ctx, input.conversationId);
    if (existing) {
      if (existing.userId !== user._id) {
        throw new Error(
          `Conversation UUID ${input.conversationId} is already owned by another user.`
        );
      }
      const view = await conversationView(ctx, existing);
      if (
        !conversationCreationMatches(existing, input) ||
        !creationBindingMatches(view.binding, input.binding)
      ) {
        throw new Error(
          `Conversation UUID ${input.conversationId} was reused with different creation data.`
        );
      }
      return view;
    }
    if (input.continuedFrom !== undefined) {
      if (input.continuedFrom === input.conversationId) {
        throw new Error("continuedFrom cannot reference the new conversation.");
      }
      if (!(await conversationById(ctx, user._id, input.continuedFrom))) {
        throw new Error(
          `continuedFrom conversation ${input.continuedFrom} was not found.`
        );
      }
    }
    const binding =
      input.binding.kind === "machine"
        ? await machineBindingForCreate(ctx, user._id, input.binding)
        : input.binding;
    const now = new Date().toISOString();
    const id = await ctx.db.insert("conversations", {
      userId: user._id,
      conversationId: input.conversationId,
      title: input.title,
      continuedFrom: input.continuedFrom,
      binding,
      activity: "idle",
      itemCount: 0,
      nextSequence: 0,
      updatedAt: now,
    });
    const conversation = await ctx.db.get("conversations", id);
    if (!conversation) throw new Error("Conversation creation failed.");
    return conversationView(ctx, conversation);
  },
});

export const dispatch = mutation({
  args: {
    conversationId: conversationIdValue,
    change: conversationChangeValue,
  },
  returns: conversationResourceValue,
  handler: async (ctx, args) => {
    assertConversationId(args.conversationId);
    const change = normalizeConversationChange(args.change);
    assertConversationChangeSemantics(change);
    const user = await requireCurrentUser(ctx);
    return dispatchChanges(ctx, user._id, args.conversationId, [change]);
  },
});

export const dispatchBatch = mutation({
  args: {
    conversationId: conversationIdValue,
    changes: v.array(conversationChangeValue),
  },
  returns: conversationResourceValue,
  handler: async (ctx, args) => {
    assertConversationId(args.conversationId);
    const changes = args.changes.map(normalizeConversationChange);
    for (const change of changes) assertConversationChangeSemantics(change);
    const user = await requireCurrentUser(ctx);
    return dispatchChanges(ctx, user._id, args.conversationId, changes);
  },
});

export const remove = mutation({
  args: { conversationId: conversationIdValue },
  returns: v.null(),
  handler: async (ctx, args) => {
    const user = await requireCurrentUser(ctx);
    assertConversationId(args.conversationId);
    const conversation = await requireConversation(
      ctx,
      user._id,
      args.conversationId
    );
    const [messages, generations, turns] = await Promise.all([
      ctx.db
        .query("conversationMessages")
        .withIndex("by_conversation_sequence", (query) =>
          query.eq("conversationId", args.conversationId)
        )
        .take(1_000),
      ctx.db
        .query("generations")
        .withIndex("by_conversation_sequence", (query) =>
          query.eq("conversationId", args.conversationId)
        )
        .take(1_000),
      ctx.db
        .query("agentTurns")
        .withIndex("by_conversation_sequence", (query) =>
          query.eq("conversationId", args.conversationId)
        )
        .take(1_000),
    ]);
    if (
      messages.length === 1_000 ||
      generations.length === 1_000 ||
      turns.length === 1_000
    ) {
      throw new Error(
        "Conversation is too large to remove in one transaction."
      );
    }
    for (const row of messages) {
      await ctx.db.delete("conversationMessages", row._id);
    }
    for (const row of generations) {
      await ctx.db.delete("generations", row._id);
    }
    for (const row of turns) {
      await ctx.db.delete("agentTurns", row._id);
    }
    await ctx.db.delete("conversations", conversation._id);
    return null;
  },
});

