/** @type {import('expo/metro-config').MetroConfig} */
let config = getSentryExpoConfig(__dirname);

const isWeb =
  process.env.EXPO_OS === "web" ||
  process.env.EXPO_PLATFORM === "web" ||
  process.argv.includes("web") ||
  process.argv.includes("--web") ||
  process.argv.includes("--platform=web");

const publicEnvironmentCacheKey = createHash("sha256")
  .update(
    JSON.stringify(
      Object.entries(process.env)
        .filter(
          ([key, value]) =>
            key.startsWith("EXPO_PUBLIC_") && value !== undefined
        )
        .sort(([left], [right]) => left.localeCompare(right))
    )
  )
  .digest("hex");

// The resolver below collapses Clerk to one physical copy of @clerk/react and
// @clerk/shared. A cache built before a dependency change can still hold the
// pre-change module graph, which yields two ClerkInstanceContext objects and the
// misleading "useSignIn can only be used within the <ClerkProvider />" error in
// the development renderer only. Key the cache on the lockfile so any dependency
// change invalidates it.
const dependencyCacheKey = (() => {
  const lockfilePath = path.join(__dirname, "../../pnpm-lock.yaml");
  try {
    return createHash("sha256")
      .update(fs.readFileSync(lockfilePath))
      .digest("hex")
      .slice(0, 16);
  } catch {
    return "no-lockfile";
  }
})();

const forcedSourcePackages = ["@clerk/expo"];
const reactNativeAssetRegistryPath = require.resolve(
  "react-native/asset-registry",
  { paths: [__dirname] }
);

function forceClerkEsm(resolution) {
  if (
    !resolution ||
    resolution.type !== "sourceFile" ||
    !resolution.filePath ||
    !resolution.filePath.includes(`${path.sep}@clerk${path.sep}`)
  ) {
    return resolution;
  }
  if (resolution.filePath.endsWith(".cjs")) {
    const esmPath = resolution.filePath.replace(/\.cjs$/, ".mjs");
    if (fs.existsSync(esmPath)) {
      return { ...resolution, filePath: esmPath };
    }
  }
  return resolution;
}

function resolveForcedSourcePackage(moduleName) {
  if (
    !forcedSourcePackages.some(
      (packageName) =>
        moduleName === packageName || moduleName.startsWith(`${packageName}/`)
    )
  ) {
    return null;
  }

  return {
    type: "sourceFile",
    filePath: require.resolve(moduleName, { paths: [__dirname] }),
  };
}

config.cacheVersion = `${config.cacheVersion}:homer-client:${publicEnvironmentCacheKey}:${dependencyCacheKey}`;

if (!isWeb) {
  config = getBundleModeMetroConfig(config);
  config.transformer = {
    ...config.transformer,
    assetRegistryPath: reactNativeAssetRegistryPath,
  };
  config.watchFolders = [
    ...(config.watchFolders ?? []),
    path.join(
      path.dirname(
        require.resolve("react-native-worklets/package.json", {
          paths: [__dirname],
        })
      ),
      ".worklets"
    ),
  ];
  const bundleModeResolveRequest = config.resolver?.resolveRequest;

  config.resolver = {
    ...config.resolver,
    resolveRequest(context, moduleName, platform) {
      if (moduleName === "@react-native/assets-registry/registry") {
        return {
          type: "sourceFile",
          filePath: reactNativeAssetRegistryPath,
        };
      }
      const forcedPackage = resolveForcedSourcePackage(moduleName);
      if (forcedPackage) return forcedPackage;

      return bundleModeResolveRequest?.(context, moduleName, platform) ?? null;
    },
  };
} else {
  const defaultResolveRequest = config.resolver?.resolveRequest;
  const sourceExts = config.resolver?.sourceExts ?? [];
  const platforms = config.resolver?.platforms ?? [];
  const targetSourceExts = ["web.tsx", "web.ts", "web.jsx", "web.js"];
  config.resolver = {
    ...config.resolver,
    platforms: platforms.includes("web") ? platforms : ["web", ...platforms],
    sourceExts: [
      ...targetSourceExts,
      ...sourceExts.filter(
        (ext) => !ext.startsWith("web.") && !ext.startsWith("desktop.")
      ),
    ],
    resolveRequest(context, moduleName, platform) {
      const forcedPackage = resolveForcedSourcePackage(moduleName);
      if (forcedPackage) return forcedPackage;
      return forceClerkEsm(
        defaultResolveRequest?.(context, moduleName, platform) ?? null
      );
    },
  };
}

