// Uniwind rewrites every "react-native" import to its component proxy and only
// leaves origins under react-native/ or @react-native/ alone. It does not
// recognize the worklets Bundle Mode shim, whose own require("react-native")
// must reach the real package. Left alone, uniwind points the shim at
// uniwind/components while worklets points uniwind/components back at the shim,
// so `get NativeModules` recurses until the JS stack overflows at boot.
const uniwindResolveRequest = config.resolver?.resolveRequest;
config.resolver = {
  ...config.resolver,
  resolveRequest(context, moduleName, platform) {
    if (
      moduleName === "react-native" &&
      context.originModulePath?.includes(
        "react-native-worklets/bundleMode/shims/reactNativeShim"
      )
    ) {
      return {
        type: "sourceFile",
        filePath: require.resolve("react-native", { paths: [__dirname] }),
      };
    }
    return uniwindResolveRequest?.(context, moduleName, platform) ?? null;
  },
};

