const fs = require("fs");
const path = require("path");
const { withDangerousMod } = require("expo/config-plugins");

function resolveAndroidSdkDir(explicitSdkDir) {
  const candidates = [
    explicitSdkDir,
    process.env.ANDROID_HOME,
    process.env.ANDROID_SDK_ROOT,
    process.env.HOME &&
      path.join(process.env.HOME, "Library", "Android", "sdk"),
    "/usr/lib/android-sdk",
  ];

  return candidates.find(
    (candidate) =>
      candidate &&
      fs.existsSync(candidate) &&
      fs.existsSync(path.join(candidate, "platform-tools"))
  );
}

function escapePropertiesValue(value) {
  return value.replace(/\\/g, "\\\\").replace(/:/g, "\\:");
}

function upsertProperty(contents, key, value) {
  const nextLine = `${key}=${escapePropertiesValue(value)}`;
  const lines = contents
    .split(/\r?\n/)
    .filter((line) => line.length > 0 && !line.startsWith(`${key}=`));

  lines.push(nextLine);
  return `${lines.join("\n")}\n`;
}

module.exports = function withAndroidLocalProperties(config, props = {}) {
  return withDangerousMod(config, [
    "android",
    async (config) => {
      const sdkDir = resolveAndroidSdkDir(props.sdkDir);

      if (!sdkDir) {
        throw new Error(
          "Unable to locate the Android SDK. Set ANDROID_HOME or ANDROID_SDK_ROOT to an SDK containing platform-tools."
        );
      }

      const localPropertiesPath = path.join(
        config.modRequest.platformProjectRoot,
        "local.properties"
      );
      const currentContents = fs.existsSync(localPropertiesPath)
        ? fs.readFileSync(localPropertiesPath, "utf8")
        : "";

      fs.writeFileSync(
        localPropertiesPath,
        upsertProperty(currentContents, "sdk.dir", sdkDir)
      );

      return config;
    },
  ]);
};

const fs = require("fs");
const path = require("path");
const {
  IOSConfig,
  createRunOncePlugin,
  withDangerousMod,
  withXcodeProject,
} = require("expo/config-plugins");

const PROVIDER_HEADER = "HomerDependencyProvider.h";
const PROVIDER_SOURCE = "HomerDependencyProvider.mm";

const PROVIDER_HEADER_CONTENT = `#import <Foundation/Foundation.h>

#if __has_include(<React-RCTAppDelegate/RCTDependencyProvider.h>)
#import <React-RCTAppDelegate/RCTDependencyProvider.h>
#elif __has_include(<React_RCTAppDelegate/RCTDependencyProvider.h>)
#import <React_RCTAppDelegate/RCTDependencyProvider.h>
#else
#import "RCTDependencyProvider.h"
#endif

NS_ASSUME_NONNULL_BEGIN

@interface HomerDependencyProvider : NSObject <RCTDependencyProvider>

@end

NS_ASSUME_NONNULL_END
`;

const PROVIDER_SOURCE_CONTENT = `#import "HomerDependencyProvider.h"

#import <React/RCTLog.h>
#import <ReactAppDependencyProvider/RCTAppDependencyProvider.h>

static RCTAppDependencyProvider *HomerBaseDependencyProvider(void)
{
  static RCTAppDependencyProvider *provider = nil;
  static dispatch_once_t onceToken;

  dispatch_once(&onceToken, ^{
    provider = [RCTAppDependencyProvider new];
  });

  return provider;
}

@implementation HomerDependencyProvider

- (NSArray<NSString *> *)imageURLLoaderClassNames
{
  return [HomerBaseDependencyProvider() imageURLLoaderClassNames];
}

- (NSArray<NSString *> *)imageDataDecoderClassNames
{
  return [HomerBaseDependencyProvider() imageDataDecoderClassNames];
}

- (NSArray<NSString *> *)URLRequestHandlerClassNames
{
  return [HomerBaseDependencyProvider() URLRequestHandlerClassNames];
}

- (NSArray<NSString *> *)unstableModulesRequiringMainQueueSetup
{
  return [HomerBaseDependencyProvider() unstableModulesRequiringMainQueueSetup];
}

- (NSDictionary<NSString *, Class<RCTComponentViewProtocol>> *)thirdPartyFabricComponents
{
  return [HomerBaseDependencyProvider() thirdPartyFabricComponents];
}

- (NSDictionary<NSString *, id<RCTModuleProvider>> *)moduleProviders
{
  static NSDictionary<NSString *, id<RCTModuleProvider>> *providers = nil;
  static dispatch_once_t onceToken;

  dispatch_once(&onceToken, ^{
    NSMutableDictionary<NSString *, id<RCTModuleProvider>> *mergedProviders =
      [[HomerBaseDependencyProvider() moduleProviders] mutableCopy] ?: [NSMutableDictionary new];

    if (mergedProviders[@"NitroModules"] == nil) {
      Class nitroModulesClass = NSClassFromString(@"NativeNitroModules");
      id nitroModulesProvider = nitroModulesClass == Nil ? nil : [nitroModulesClass new];

      if ([nitroModulesProvider respondsToSelector:NSSelectorFromString(@"getTurboModule:")]) {
        mergedProviders[@"NitroModules"] = nitroModulesProvider;
      } else {
        RCTLogError(@"NativeNitroModules is not available as a TurboModule provider");
      }
    }

    providers = [mergedProviders copy];
  });

  return providers;
}

@end
`;

function upsertLine(contents, line) {
  return contents.includes(line)
    ? contents
    : `${contents.trimEnd()}\n${line}\n`;
}

function patchAppDelegate(contents) {
  const stockProvider =
    "delegate.dependencyProvider = RCTAppDependencyProvider()";
  const homerProvider =
    "delegate.dependencyProvider = HomerDependencyProvider()";
  const stockImportMatches = contents.match(
    /^import ReactAppDependencyProvider$/gm
  );
  const stockProviderMatches = contents.split(stockProvider).length - 1;
  const homerProviderMatches = contents.split(homerProvider).length - 1;

  if (homerProviderMatches === 0) {
    if (stockImportMatches?.length !== 1) {
      throw new Error(
        "Unable to remove ReactAppDependencyProvider import from AppDelegate"
      );
    }
    if (stockProviderMatches !== 1) {
      throw new Error(
        "Unable to replace RCTAppDependencyProvider in AppDelegate"
      );
    }
  } else if (homerProviderMatches !== 1 || stockProviderMatches !== 0) {
    throw new Error("AppDelegate contains conflicting dependency providers");
  }

  return contents
    .replace(/^import ReactAppDependencyProvider\n/m, "")
    .replace(stockProvider, homerProvider);
}

function providerBuildFile(project) {
  const match = Object.entries(project.pbxBuildFileSection()).find(
    ([, entry]) =>
      entry &&
      typeof entry === "object" &&
      entry.fileRef_comment === PROVIDER_SOURCE
  );
  if (!match) return null;
  return { uuid: match[0], file: match[1] };
}

function removeProviderFromResources(project) {
  const buildFileEntry = providerBuildFile(project);
  if (!buildFileEntry) return;
  const phase = project.pbxResourcesBuildPhaseObj();
  phase.files = phase.files.filter(
    (file) => file.value !== buildFileEntry.uuid
  );
}

function addProviderToSources(project) {
  const buildFileEntry = providerBuildFile(project);
  if (!buildFileEntry) return;
  project.pbxBuildFileSection()[`${buildFileEntry.uuid}_comment`] =
    `${PROVIDER_SOURCE} in Sources`;
  const phase = project.pbxSourcesBuildPhaseObj();
  if (phase.files.some((file) => file.value === buildFileEntry.uuid)) return;
  phase.files.push({
    value: buildFileEntry.uuid,
    comment: `${PROVIDER_SOURCE} in Sources`,
  });
}

const withNitroModulesIosProvider = (config) => {
  config = withDangerousMod(config, [
    "ios",
    async (config) => {
      const projectName = config.modRequest.projectName ?? "homer";
      const appRoot = path.join(
        config.modRequest.platformProjectRoot,
        projectName
      );
      const appDelegatePath = path.join(appRoot, "AppDelegate.swift");
      const bridgingHeaderPath = path.join(
        appRoot,
        `${projectName}-Bridging-Header.h`
      );

      fs.writeFileSync(
        path.join(appRoot, PROVIDER_HEADER),
        PROVIDER_HEADER_CONTENT
      );
      fs.writeFileSync(
        path.join(appRoot, PROVIDER_SOURCE),
        PROVIDER_SOURCE_CONTENT
      );
      fs.writeFileSync(
        appDelegatePath,
        patchAppDelegate(fs.readFileSync(appDelegatePath, "utf8"))
      );
      fs.writeFileSync(
        bridgingHeaderPath,
        upsertLine(
          fs.readFileSync(bridgingHeaderPath, "utf8"),
          '#import "HomerDependencyProvider.h"'
        )
      );

      return config;
    },
  ]);

  config = withXcodeProject(config, (config) => {
    const projectName = config.modRequest.projectName ?? "homer";
    const filepath = `${projectName}/${PROVIDER_SOURCE}`;
    IOSConfig.XcodeUtils.addBuildSourceFileToGroup({
      filepath,
      groupName: projectName,
      project: config.modResults,
    });
    removeProviderFromResources(config.modResults);
    addProviderToSources(config.modResults);
    return config;
  });

  return config;
};

module.exports = createRunOncePlugin(
  withNitroModulesIosProvider,
  "with-nitro-modules-ios-provider",
  "1.0.0"
);
module.exports.patchAppDelegate = patchAppDelegate;

import { readdirSync, readFileSync } from "node:fs";
import path from "node:path";

const EXPECTED_MARKER = "homer-renderer:web";
const FORBIDDEN_MARKER = "homer-renderer:native";
const REQUIRED_RUNTIME_SENTINELS = [
  { label: "Clerk browser authentication", marker: "Clerk client" },
] as const;

function javaScriptFiles(directory: string): string[] {
  return readdirSync(directory, { withFileTypes: true }).flatMap((entry) => {
    const entryPath = path.join(directory, entry.name);
    if (entry.isDirectory()) return javaScriptFiles(entryPath);
    return entry.isFile() && entry.name.endsWith(".js") ? [entryPath] : [];
  });
}

export function verifyRendererArtifactPolicy(outputDirectory: string): void {
  let foundExpectedMarker = false;
  const missingSentinels = new Set(
    REQUIRED_RUNTIME_SENTINELS.map((sentinel) => sentinel.marker)
  );

  for (const filePath of javaScriptFiles(outputDirectory)) {
    const source = readFileSync(filePath, "utf8");
    if (source.includes(EXPECTED_MARKER)) foundExpectedMarker = true;
    for (const marker of missingSentinels) {
      if (source.includes(marker)) missingSentinels.delete(marker);
    }
    if (source.includes(FORBIDDEN_MARKER)) {
      throw new Error(
        `Renderer export ${outputDirectory} contains ${FORBIDDEN_MARKER}`
      );
    }
  }

  if (!foundExpectedMarker) {
    throw new Error(
      `Renderer export ${outputDirectory} does not contain ${EXPECTED_MARKER}`
    );
  }
  for (const sentinel of REQUIRED_RUNTIME_SENTINELS) {
    if (missingSentinels.has(sentinel.marker)) {
      throw new Error(
        `Renderer export ${outputDirectory} is missing ${sentinel.label} (sentinel: ${sentinel.marker})`
      );
    }
  }
}

import { createHash } from "node:crypto";
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import {
  RENDERER_MANIFEST_FILENAME,
  parseRendererManifest,
} from "@homer/shared/renderer-manifest";

export function rendererManifestPath(rendererRoot: string): string {
  return path.join(rendererRoot, RENDERER_MANIFEST_FILENAME);
}

function slashNormalizedSort(left: string, right: string): number {
  if (left < right) return -1;
  if (left > right) return 1;
  return 0;
}

export function rendererBuildId(rendererRoot: string): string {
  const records: string[] = [];

  function walk(relativeDirectory: string): void {
    const absoluteDirectory = path.join(rendererRoot, relativeDirectory);
    const entries = readdirSync(absoluteDirectory, {
      withFileTypes: true,
    }).sort((left, right) => slashNormalizedSort(left.name, right.name));
    for (const entry of entries) {
      const relativePath = relativeDirectory
        ? `${relativeDirectory}/${entry.name}`
        : entry.name;
      if (entry.isDirectory()) {
        walk(relativePath);
      } else if (entry.isFile()) {
        if (relativePath === RENDERER_MANIFEST_FILENAME) continue;
        const content = readFileSync(path.join(rendererRoot, relativePath));
        records.push(
          JSON.stringify([
            relativePath,
            content.byteLength,
            createHash("sha256").update(content).digest("hex"),
          ])
        );
      } else {
        throw new Error(
          `Renderer build contains unsupported entry: ${relativePath}`
        );
      }
    }
  }

  walk("");
  const hash = createHash("sha256");
  for (const record of records.sort(slashNormalizedSort)) {
    hash.update(record, "utf8").update("\n");
  }
  return hash.digest("hex");
}

export function writeRendererManifest(rendererRoot: string) {
  const manifest = {
    kind: "expo-web" as const,
    buildId: rendererBuildId(rendererRoot),
  };
  writeFileSync(
    rendererManifestPath(rendererRoot),
    `${JSON.stringify(manifest)}\n`
  );
  return manifest;
}

export function readRendererManifest(rendererRoot: string) {
  const manifestPath = rendererManifestPath(rendererRoot);
  let raw: unknown;
  try {
    raw = JSON.parse(readFileSync(manifestPath, "utf8"));
  } catch (error) {
    throw new Error(`Failed to read renderer manifest at ${manifestPath}.`, {
      cause: error,
    });
  }
  return parseRendererManifest(raw);
}

export function verifyRendererManifest(rendererRoot: string) {
  const manifest = readRendererManifest(rendererRoot);
  const actualBuildId = rendererBuildId(rendererRoot);
  if (manifest.buildId !== actualBuildId) {
    throw new Error(
      `Renderer manifest mismatch at ${rendererManifestPath(
        rendererRoot
      )}: expected ${manifest.buildId}, recomputed ${actualBuildId}`
    );
  }
  return manifest;
}

import { randomUUID } from "node:crypto";
import { existsSync } from "node:fs";
import { fileURLToPath, pathToFileURL } from "node:url";
import { modelCatalogResponseSchema } from "@homer/shared/model-config";
import { ConvexHttpClient } from "convex/browser";
import type { FunctionArgs, FunctionReturnType } from "convex/server";
import type { api as generatedConvexApi } from "../convex/_generated/api.js";
import type { modelSnapshotForTarget as generatedModelSnapshotForTarget } from "../src/lib/model-directory";

const DEFAULT_E2E_EMAIL = "murderbox+clerk_test@joedeleeuw.com";

type ConvexApi = typeof generatedConvexApi;
type ModelSnapshotForTarget = typeof generatedModelSnapshotForTarget;

type ConversationListRow = FunctionReturnType<
  ConvexApi["conversations"]["listAllRows"]
>[number];

type MintTokenOptions = {
  secretKey: string;
  publishableKey: string;
  userId: string;
  email: string;
  template?: string;
};

type MintToken = (options: MintTokenOptions) => Promise<string>;

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}

function loadClientEnvironment(): void {
  const inheritedEnvironment = { ...process.env };
  for (const name of [".env.development.local", ".env.local"]) {
    const envPath = fileURLToPath(new URL(`../${name}`, import.meta.url));
    if (existsSync(envPath)) process.loadEnvFile(envPath);
  }
  Object.assign(process.env, inheritedEnvironment);
}

function requiredEnvironment(name: string): string {
  const value = process.env[name]?.trim();
  if (!value) throw new Error(`${name} is required`);
  return value;
}

export function resolveE2eEmail(
  configuredEmail: string | undefined = process.env.HOMER_E2E_EMAIL
): string {
  return configuredEmail?.trim() || DEFAULT_E2E_EMAIL;
}

export function selectOwnedEmptyModelConversation(
  rows: readonly ConversationListRow[]
): string | undefined {
  return rows.find((row) => row.itemCount === 0 && row.origin.kind === "model")
    ?.conversationId;
}

function clerkSubjectFromJwt(token: string): string {
  const encodedPayload = token.split(".")[1];
  if (!encodedPayload) throw new Error("Clerk convex JWT is malformed");
  let payload: unknown;
  try {
    payload = JSON.parse(Buffer.from(encodedPayload, "base64url").toString());
  } catch (cause) {
    throw new Error("Clerk convex JWT payload is not valid JSON", { cause });
  }
  if (!isRecord(payload) || typeof payload.sub !== "string") {
    throw new Error("Clerk convex JWT payload does not include a subject");
  }
  const subject = payload.sub.trim();
  if (!subject) {
    throw new Error("Clerk convex JWT payload includes an empty subject");
  }
  return subject;
}

async function importMintToken(): Promise<MintToken> {
  const moduleUrl = new URL(
    "../../api/scripts/mint-homer-api-token.mjs",
    import.meta.url
  );
  const imported: unknown = await import(moduleUrl.href);
  if (!isRecord(imported) || typeof imported.mintToken !== "function") {
    throw new Error("mint-homer-api-token.mjs does not export mintToken");
  }
  const mintToken = imported.mintToken;
  return async (options) => {
    const token: unknown = await Reflect.apply(mintToken, undefined, [options]);
    if (typeof token !== "string" || !token.trim()) {
      throw new Error("mint-homer-api-token.mjs returned an empty token");
    }
    return token;
  };
}

async function importConvexApi(): Promise<ConvexApi> {
  const moduleUrl = new URL("../convex/_generated/api.js", import.meta.url);
  const imported: unknown = await import(moduleUrl.href);
  if (!isRecord(imported)) {
    throw new Error("Convex generated API module is invalid");
  }
  const exports = isRecord(imported.default) ? imported.default : imported;
  if (!isRecord(exports.api)) {
    throw new Error("Convex generated API module does not export api");
  }
  return exports.api as ConvexApi;
}

async function importModelSnapshotForTarget(): Promise<ModelSnapshotForTarget> {
  const moduleUrl = new URL("../src/lib/model-directory.ts", import.meta.url);
  const imported: unknown = await import(moduleUrl.href);
  if (!isRecord(imported)) {
    throw new Error("Client model directory module is invalid");
  }
  const exports = isRecord(imported.default) ? imported.default : imported;
  if (typeof exports.modelSnapshotForTarget !== "function") {
    throw new Error(
      "Client model directory does not export modelSnapshotForTarget"
    );
  }
  return exports.modelSnapshotForTarget as ModelSnapshotForTarget;
}

async function fetchDefaultChatModel(baseUrl: string, apiToken: string) {
  const response = await fetch(new URL("/api/models", baseUrl), {
    headers: {
      accept: "application/json",
      authorization: `Bearer ${apiToken}`,
    },
  });
  if (!response.ok) {
    const detail = await response.text().catch(() => "");
    throw new Error(
      `Model catalog request failed with HTTP ${response.status}: ${detail.slice(0, 300)}`
    );
  }
  const catalog = modelCatalogResponseSchema.parse(await response.json());
  const model = catalog.models.find(
    (candidate) =>
      candidate.kind === "chat" && candidate.id === catalog.defaultChatModelId
  );
  if (!model) {
    throw new Error(
      `Default chat model ${catalog.defaultChatModelId} is not in the model catalog`
    );
  }
  return model;
}

async function main(): Promise<void> {
  loadClientEnvironment();
  const secretKey = requiredEnvironment("CLERK_SECRET_KEY");
  const publishableKey = requiredEnvironment(
    "EXPO_PUBLIC_CLERK_PUBLISHABLE_KEY"
  );
  const convexUrl = requiredEnvironment("EXPO_PUBLIC_CONVEX_URL");
  const baseUrl = requiredEnvironment("EXPO_PUBLIC_HOMER_BASE_URL");
  if (!secretKey.startsWith("sk_test_")) {
    throw new Error("CLERK_SECRET_KEY must select the Clerk test instance");
  }
  if (!publishableKey.startsWith("pk_test_")) {
    throw new Error(
      "EXPO_PUBLIC_CLERK_PUBLISHABLE_KEY must select the Clerk test instance"
    );
  }

  const email = resolveE2eEmail();
  const clerkUserId = process.env.CLERK_E2E_USER_ID?.trim() || "";
  const [mintToken, convexApi, modelSnapshotForTarget] = await Promise.all([
    importMintToken(),
    importConvexApi(),
    importModelSnapshotForTarget(),
  ]);
  const tokenOptions = {
    secretKey,
    publishableKey,
    userId: clerkUserId,
    email,
  };
  const convexJwt = await mintToken({ ...tokenOptions, template: "convex" });
  const clerkSubject = clerkSubjectFromJwt(convexJwt);
  const convex = new ConvexHttpClient(convexUrl);
  convex.setAuth(convexJwt);
  const userId = await convex.mutation(convexApi.users.ensureCurrent, {});
  const rows = await convex.query(convexApi.conversations.listAllRows, {
    limit: 80,
  });
  const existingConversationId = selectOwnedEmptyModelConversation(rows);
  if (existingConversationId) {
    process.stdout.write(
      `${JSON.stringify({ conversationId: existingConversationId, userId, clerkSubject })}\n`
    );
    return;
  }

  const apiToken = await mintToken(tokenOptions);
  const model = await fetchDefaultChatModel(baseUrl, apiToken);
  const input: FunctionArgs<ConvexApi["conversations"]["create"]>["input"] = {
    conversationId: randomUUID(),
    title: "Gate A E2E",
    binding: {
      kind: "model",
      modelSnapshot: modelSnapshotForTarget(model),
    },
  };
  const created = await convex.mutation(convexApi.conversations.create, {
    input,
  });
  process.stdout.write(
    `${JSON.stringify({ conversationId: created.conversation.conversationId, userId, clerkSubject })}\n`
  );
}

const invokedPath = process.argv[1];
if (invokedPath && import.meta.url === pathToFileURL(invokedPath).href) {
  main().catch((error) => {
    console.error(error instanceof Error ? error.message : String(error));
    process.exitCode = 1;
  });
}

import { captureGroups } from "./regex-capture";
import {
  copyFileSync,
  cpSync,
  mkdirSync,
  readFileSync,
  rmSync,
  statSync,
} from "node:fs";
import { createRequire } from "node:module";
import path from "node:path";
import process from "node:process";
import { fileURLToPath, pathToFileURL } from "node:url";
import { z } from "zod";

const clientRoot = fileURLToPath(new URL("..", import.meta.url));
const require = createRequire(import.meta.url);
const katexCssPath = require.resolve("katex/dist/katex.min.css");
const katexPackageRoot = path.resolve(path.dirname(katexCssPath), "..");
const katexFontReferenceSchema = z
  .string()
  .regex(
    /^fonts\/[A-Za-z0-9_-]+\.(?:woff2|woff|ttf)$/,
    "KaTeX CSS contains an unsupported asset reference"
  );

function katexFontReferences(css: string): string[] {
  const references = captureGroups(css.matchAll(/url\(([^)]+)\)/g))
    .map((reference) => reference.trim().replace(/^['"]|['"]$/g, ""))
    .map((reference) => katexFontReferenceSchema.parse(reference));
  const uniqueReferences = [...new Set(references)].sort();
  if (uniqueReferences.length === 0) {
    throw new Error("KaTeX CSS does not reference any packaged fonts");
  }
  return uniqueReferences;
}

export function syncClerkUi(
  destinationRoot = path.join(clientRoot, "public/clerk-ui")
) {
  const clerkUiDist = path.join(
    path.dirname(require.resolve("@clerk/ui/package.json")),
    "dist"
  );

  rmSync(destinationRoot, { force: true, recursive: true });
  cpSync(clerkUiDist, destinationRoot, {
    recursive: true,
    filter: (source) => {
      const base = path.basename(source);
      return !(
        base.endsWith(".map") ||
        base.endsWith(".d.ts") ||
        base.endsWith(".d.ts.map") ||
        base === "package.json"
      );
    },
  });
  if (!statSync(path.join(destinationRoot, "ui.browser.js")).isFile()) {
    throw new Error("Clerk UI browser bundle is missing");
  }

  return { destinationRoot };
}

export function syncWebAssets(
  destinationRoot = path.join(clientRoot, "public/vendor/katex"),
  clerkUiDestinationRoot = path.join(clientRoot, "public/clerk-ui")
) {
  syncClerkUi(clerkUiDestinationRoot);
  const css = readFileSync(katexCssPath, "utf8");
  const fontReferences = katexFontReferences(css);
  const destinationFontsRoot = path.join(destinationRoot, "fonts");

  rmSync(destinationRoot, { force: true, recursive: true });
  mkdirSync(destinationFontsRoot, { recursive: true });
  copyFileSync(katexCssPath, path.join(destinationRoot, "katex.min.css"));
  copyFileSync(
    path.join(katexPackageRoot, "LICENSE"),
    path.join(destinationRoot, "LICENSE")
  );
  for (const reference of fontReferences) {
    const source = path.join(katexPackageRoot, "dist", reference);
    if (!statSync(source).isFile()) {
      throw new Error(`KaTeX font is missing: ${reference}`);
    }
    copyFileSync(source, path.join(destinationRoot, reference));
  }

  return { destinationRoot, fontReferences };
}

const entryPath = process.argv[1];
if (
  entryPath !== undefined &&
  pathToFileURL(path.resolve(entryPath)).href === import.meta.url
) {
  syncWebAssets();
}

import { afterEach, describe, expect, it, vi } from "vitest";
import type { ClerkFapiFetchRequest } from "@homer/shared/clerk-fapi";
import { installClerkFapiFetchOverride } from "./clerk-fapi-fetch.electron";

// "clerk.example.test$" base64url-encoded, matching Clerk's publishable key shape.
const PUBLISHABLE_KEY = `pk_test_${Buffer.from("clerk.example.test$")
  .toString("base64")
  .replace(/\+/g, "-")
  .replace(/\//g, "_")}`;
const FAPI_ORIGIN = "https://clerk.example.test";

const originalFetch = globalThis.fetch;

function installProxy(respond: (payload: ClerkFapiFetchRequest) => unknown) {
  const proxy = vi.fn(async (payload: Parameters<typeof respond>[0]) =>
    respond(payload)
  );
  Reflect.set(globalThis, "window", globalThis);
  Reflect.set(globalThis, "homerClerkFapiFetch", proxy);
  const restore = installClerkFapiFetchOverride(PUBLISHABLE_KEY);
  return { proxy, restore };
}

afterEach(() => {
  globalThis.fetch = originalFetch;
  Reflect.deleteProperty(globalThis, "homerClerkFapiFetch");
  vi.restoreAllMocks();
});

describe("Clerk FAPI fetch override", () => {
  it("round-trips response bytes whose base64 contains + and /", async () => {
    // 0xFB 0xFF 0xBF encodes to "+/+/" family output — the exact bytes that a
    // base64url translation would corrupt before atob sees them.
    const payload = new Uint8Array([
      251, 255, 191, 0, 1, 2, 250, 254, 255, 63, 62, 61,
    ]);
    const base64 = Buffer.from(payload).toString("base64");
    expect(base64).toMatch(/[+/]/);

    const { restore } = installProxy(() => ({
      status: 200,
      statusText: "OK",
      headerEntries: [["content-type", "application/octet-stream"]],
      bodyBase64: base64,
    }));

    const response = await globalThis.fetch(`${FAPI_ORIGIN}/v1/environment`);
    const received = new Uint8Array(await response.arrayBuffer());

    expect(response.status).toBe(200);
    expect(Array.from(received)).toEqual(Array.from(payload));
    restore();
  });

  it("round-trips a realistic JSON environment payload", async () => {
    const body = JSON.stringify({
      auth_config: { single_session_mode: true },
      display_config: { application_name: "homer" },
      // Values that base64-encode with + and / in the output.
      fingerprint: "ÿþý+/=?ü",
    });
    const { restore } = installProxy(() => ({
      status: 200,
      statusText: "OK",
      headerEntries: [["content-type", "application/json"]],
      bodyBase64: Buffer.from(body, "utf8").toString("base64"),
    }));

    const response = await globalThis.fetch(`${FAPI_ORIGIN}/v1/environment`);

    expect(new TextDecoder().decode(await response.arrayBuffer())).toBe(body);
    restore();
  });

  it("rejects malformed responses from the desktop process", async () => {
    const { restore } = installProxy(() => ({
      status: "200",
      statusText: "OK",
      headerEntries: [],
      bodyBase64: "e30=",
    }));

    await expect(
      globalThis.fetch(`${FAPI_ORIGIN}/v1/environment`)
    ).rejects.toThrow();
    restore();
  });

  it("refuses an unsafe FAPI fallback without consuming a POST body", async () => {
    const passthrough = vi.fn(async () => new Response("unsafe fallback"));
    globalThis.fetch = passthrough;
    Reflect.set(globalThis, "window", globalThis);
    const restore = installClerkFapiFetchOverride(PUBLISHABLE_KEY);
    const request = new Request(`${FAPI_ORIGIN}/v1/client/sign_ins`, {
      method: "POST",
      body: "identifier=someone",
    });

    await expect(globalThis.fetch(request)).rejects.toThrow(
      "Desktop Clerk FAPI bridge is unavailable"
    );
    expect(passthrough).not.toHaveBeenCalled();
    expect(request.bodyUsed).toBe(false);
    expect(await request.text()).toBe("identifier=someone");
    restore();
  });

  it("forwards request bodies and leaves non-FAPI origins alone", async () => {
    const passthrough = vi.fn(async () => new Response("untouched"));
    globalThis.fetch = passthrough;

    const { proxy, restore } = installProxy(() => ({
      status: 201,
      statusText: "Created",
      headerEntries: [],
      bodyBase64: Buffer.from("{}", "utf8").toString("base64"),
    }));

    await globalThis.fetch(`${FAPI_ORIGIN}/v1/client/sign_ins`, {
      method: "POST",
      body: "identifier=someone",
    });
    expect(proxy).toHaveBeenCalledTimes(1);
    const [sent] = proxy.mock.calls[0] ?? [];
    expect(sent?.method).toBe("POST");
    expect(Buffer.from(sent?.bodyBase64 ?? "", "base64").toString("utf8")).toBe(
      "identifier=someone"
    );

    await globalThis.fetch("https://convex.example.test/api/query");
    expect(passthrough).toHaveBeenCalledTimes(1);
    expect(proxy).toHaveBeenCalledTimes(1);
    restore();
  });
});

import { ClerkProvider, useAuth } from "@clerk/electron/react";
import type { ComponentProps, JSX } from "react";
import { useEffect, useState } from "react";
import { ConvexProviderWithClerk } from "convex/react-clerk";
import { assertClerkPublishableKeyMatchesDeployment } from "@/components/auth/clerk-provider-config";
import { resolveAuthSessionState } from "@/components/auth/auth-session-state";
import { installClerkFapiFetchOverride } from "@/components/auth/clerk-fapi-fetch.electron";
import { RuntimeSessionGate } from "@/components/auth/runtime-session-gate";
import { ApplicationDestinationRestorer } from "@/components/navigation/application-destination-restorer.electron";
import { clerkEnv } from "@/lib/clerk-env";
import { convexClient } from "@/lib/convex";
import { CLIENT_ENV } from "@/lib/env";

const CLERK_UI_ARTIFACT_PATH = "/clerk-ui/ui.browser.js";

type ClerkElectronProviderProps = ComponentProps<typeof ClerkProvider> & {
  __internal_clerkUIUrl?: string;
};

const ClerkElectronProvider = ClerkProvider as (
  props: ClerkElectronProviderProps
) => JSX.Element;

function useClerkAuthForConvex() {
  return useAuth({ treatPendingAsSignedOut: false });
}

function selfHostedClerkUiUrl(): string {
  return new URL(CLERK_UI_ARTIFACT_PATH, window.location.origin).toString();
}

function ClerkElectronConvexRuntime({
  children,
}: {
  children: Parameters<typeof RuntimeSessionGate>[0]["children"];
}) {
  const { isLoaded, isSignedIn, signOut, userId } = useAuth({
    treatPendingAsSignedOut: false,
  });
  const authState = resolveAuthSessionState(isLoaded, isSignedIn);
  return (
    <ConvexProviderWithClerk
      key={userId ?? authState.kind}
      client={convexClient}
      useAuth={useClerkAuthForConvex}
    >
      <RuntimeSessionGate
        authState={authState}
        onRecover={signOut}
        onSignOut={signOut}
      >
        {(resolvedAuthState) => (
          <>
            {children(resolvedAuthState)}
            {resolvedAuthState.kind === "signedIn" ? (
              <ApplicationDestinationRestorer />
            ) : null}
          </>
        )}
      </RuntimeSessionGate>
    </ConvexProviderWithClerk>
  );
}

export function RuntimeSessionBoundary({
  children,
}: {
  children: Parameters<typeof RuntimeSessionGate>[0]["children"];
}) {
  const publishableKey = clerkEnv().EXPO_PUBLIC_CLERK_PUBLISHABLE_KEY;
  assertClerkPublishableKeyMatchesDeployment(
    publishableKey,
    CLIENT_ENV.EXPO_PUBLIC_HOMER_DEPLOYMENT
  );

  // React flushes child effects before parent effects, so installing this in an
  // effect would let ClerkProvider mount -- and clerk-js begin loading -- before
  // the override existed. The first Clerk request would then leave through the
  // unpatched fetch and hit the Origin/Authorization conflict this exists to
  // avoid, presenting as an intermittent sign-in hang. A state initialiser runs
  // during this component's own render, before any child renders.
  const [uninstallFapiOverride] = useState(() =>
    installClerkFapiFetchOverride(publishableKey)
  );
  useEffect(() => uninstallFapiOverride, [uninstallFapiOverride]);

  return (
    <ClerkElectronProvider
      __internal_clerkUIUrl={selfHostedClerkUiUrl()}
      publishableKey={publishableKey}
    >
      <ClerkElectronConvexRuntime>{children}</ClerkElectronConvexRuntime>
    </ClerkElectronProvider>
  );
}

