export function ChatAttachmentButton({
  attachments = [],
  acceptance,
  onAdd,
  onBeforeOpen,
  onClear = () => undefined,
  onCreateImage,
  onOpenDiagnostics,
  onRemove = () => undefined,
}: Partial<AttachmentSelectionProps> &
  AttachmentAddActionProps & {
    onBeforeOpen?: () => void;
  }) {
  const safeArea = useSafeAreaInsets();
  const { colors } = useThemeMode();
  const [open, setOpen] = useState(false);
  const sheetGenerationRef = useRef(0);
  const pendingSheetActionRef = useRef<{
    action: () => void | Promise<void>;
    generation: number;
  } | null>(null);
  const actionButtonSize = 36;

  useEffect(
    () => () => {
      sheetGenerationRef.current += 1;
      pendingSheetActionRef.current = null;
    },
    []
  );

  const close = useCallback(() => setOpen(false), []);
  const runAction = (action: () => void | Promise<void>) => {
    pendingSheetActionRef.current = {
      action,
      generation: sheetGenerationRef.current,
    };
    close();
  };
  const finishSheetDismiss = (generation: number) => {
    const pendingAction = pendingSheetActionRef.current;
    if (!pendingAction || pendingAction.generation !== generation) return;
    pendingSheetActionRef.current = null;
    void pendingAction.action();
  };
  const show = () => {
    onBeforeOpen?.();
    hapticTick("light");
    sheetGenerationRef.current += 1;
    pendingSheetActionRef.current = null;
    setOpen(true);
  };
  const content = (
    <AddActionsContent
      attachments={attachments}
      acceptance={acceptance}
      onAdd={onAdd}
      onClear={onClear}
      onCreateImage={onCreateImage}
      onOpenDiagnostics={onOpenDiagnostics}
      onRemove={onRemove}
      runAction={runAction}
    />
  );

  return (
    <View
      className="relative items-center justify-center"
      style={{
        height: COMPOSER_ACTION_TARGET_SIZE,
        width: COMPOSER_ACTION_TARGET_SIZE,
      }}
    >
      <Touchable
        feedback="subtle"
        testID="homer-composer-add"
        accessibilityRole="button"
        accessibilityLabel="open insert menu"
        accessibilityState={{ expanded: open }}
        onPress={show}
        hitSlop={getHitSlopForVisualSize(actionButtonSize)}
        className="items-center justify-center border"
        style={{
          borderCurve: "continuous",
          borderColor: open ? colors.borderStrong : colors.border,
          borderWidth: 1,
          height: actionButtonSize,
          borderRadius: 18,
          width: actionButtonSize,
        }}
      >
        <Icon name="plus" size={16} color={colors.text} />
      </Touchable>

      <SheetModal
        open={open}
        onClose={close}
        onDismiss={() => finishSheetDismiss(sheetGenerationRef.current)}
        accessibilityLabel="insert options"
      >
        <SheetFrame
          bottomPadding={Math.max(18, safeArea.bottom + 8)}
          flex={false}
        >
          <SheetHeader title="Insert" onClose={close} />
          <SheetScrollView>{content}</SheetScrollView>
        </SheetFrame>
      </SheetModal>
    </View>
  );
}

