import { useCallback, useEffect, useRef, useState } from "react";
import { useSharedValue, withTiming } from "react-native-reanimated";
import {
  composerTierHeight,
  composerTierNumberOfLines,
  type ComposerTier,
} from "./use-composer-layout-metrics";

export type { ComposerTier } from "./use-composer-layout-metrics";
export {
  composerTierFromHeight,
  composerTierHeight,
  composerTierNumberOfLines,
} from "./use-composer-layout-metrics";

const COMPOSER_TIER_SNAP_MS = 160;

type ComposerLayoutBindingInput = {
  detents: readonly number[];
  initialTier: ComposerTier;
  lineHeight: number;
};

export function useComposerLayoutBinding({
  detents,
  initialTier,
  lineHeight,
}: ComposerLayoutBindingInput) {
  const [tier, setTier] = useState<ComposerTier>(initialTier);
  const inputHeightSV = useSharedValue(
    composerTierHeight(initialTier, detents)
  );
  const tierRef = useRef(initialTier);
  const detentsRef = useRef(detents);

  useEffect(() => {
    if (detentsRef.current === detents) return;
    detentsRef.current = detents;
    inputHeightSV.set(
      withTiming(composerTierHeight(tierRef.current, detents), {
        duration: COMPOSER_TIER_SNAP_MS,
      })
    );
  }, [detents, inputHeightSV]);

  const setTierCommand = useCallback(
    (next: ComposerTier | ((current: ComposerTier) => ComposerTier)) => {
      const nextTier =
        typeof next === "function" ? next(tierRef.current) : next;
      tierRef.current = nextTier;
      setTier(nextTier);
      inputHeightSV.set(
        withTiming(composerTierHeight(nextTier, detents), {
          duration: COMPOSER_TIER_SNAP_MS,
        })
      );
    },
    [detents, inputHeightSV]
  );

  const commitTierCommand = useCallback((nextTier: ComposerTier) => {
    tierRef.current = nextTier;
    setTier(nextTier);
  }, []);

  const numberOfLines = composerTierNumberOfLines(tier, lineHeight, detents);

  return {
    commitTierCommand,
    inputHeightSV,
    isExpanded: tier >= 2,
    isSlim: tier === 0,
    numberOfLines,
    setTierCommand,
    tier,
  };
}

