export type ChatItem =
  | ChatMessageItem
  | ChatErrorItem
  | ChatSwitchBannerItem
  | ChatPendingItem
  | ChatGenerationItem;

function getChatItemType(item: ChatItem): string {
  // streaming must not change the type: a type change at streaming→done moves
  // the row to a different recycle pool, remounting it exactly at completion
  // (convicted in the perf playbook ledger, 2026-06-10).
  if (item.kind === "message") return `${item.role}-message`;
  // pending shares the assistant pool so the first-token handoff recycles the
  // same row instead of remounting into a fresh pool entry.
  if (item.kind === "pending") return "assistant-message";
  if (item.kind === "generation") return `${item.outputKind}-generation`;
  return item.kind;
}

function streamingAnchorFor(items: ChatItem[], enabled: boolean) {
  if (!enabled) return undefined;
  for (let index = items.length - 1; index >= 0; index--) {
    const item = items[index];
    if (item?.kind === "message" && item.role === "user") {
      return { anchorIndex: index };
    }
  }
  return undefined;
}

function clampPercent(value: number | null | undefined): number {
  if (typeof value !== "number" || !Number.isFinite(value)) return 0;
  return Math.max(0, Math.min(100, value));
}

function phaseLabel(item: ChatGenerationItem): string {
  if (item.progress) return item.progress.label.toLowerCase();
  if (item.phase?.trim()) return item.phase.trim().toLowerCase();
  return item.status.toLowerCase();
}

function phaseCount(item: ChatGenerationItem): string | null {
  return item.progress ? `phase ${runtimeProgressCount(item.progress)}` : null;
}

