function IndeterminateMiniBar() {
  const reduceMotion = useReducedMotion();
  const opacity = useSharedValue(0.45);
  useEffect(() => {
    cancelAnimation(opacity);
    if (reduceMotion) {
      opacity.set(1);
      return;
    }
    opacity.set(withRepeat(withTiming(1, { duration: 700 }), -1, true));
    return () => cancelAnimation(opacity);
  }, [opacity, reduceMotion]);
  const style = useAnimatedStyle(() => ({ opacity: opacity.value }));
  return (
    <View className="h-[3px] rounded-full bg-mb-border overflow-hidden">
      <Animated.View
        className="h-[3px] w-[28%] rounded-full bg-mb-accent"
        style={style}
      />
    </View>
  );
}

function blobToDataUrl(blob: Blob): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onerror = () => reject(reader.error ?? new Error("read failed"));
    reader.onloadend = () => resolve(String(reader.result ?? ""));
    reader.readAsDataURL(blob);
  });
}

async function copyImageToClipboard(url: string): Promise<void> {
  const res = await appFetch(url);
  if (!res.ok) throw new Error(`image fetch failed: HTTP ${res.status}`);
  const dataUrl = await blobToDataUrl(await res.blob());
  const separator = dataUrl.indexOf(",");
  const base64 = separator >= 0 ? dataUrl.slice(separator + 1) : dataUrl;
  await Clipboard.setImageAsync(base64);
}

async function shareImage(url: string, prompt: string): Promise<void> {
  if (
    Platform.OS === "web" &&
    typeof globalThis.navigator?.share === "function"
  ) {
    await globalThis.navigator.share({
      title: "homer image",
      text: prompt,
      url,
    });
    return;
  }
  await Share.share({ title: "homer image", message: prompt, url });
}

