function formatVideoParams(item: ChatVideoGenerationItem): string | null {
  const bits: string[] = [];
  if (typeof item.videoFrames === "number") bits.push(`${item.videoFrames}f`);
  if (typeof item.videoFps === "number") bits.push(`${item.videoFps} fps`);
  if (typeof item.videoSteps === "number")
    bits.push(`${item.videoSteps} steps`);
  if (typeof item.videoGuidance === "number")
    bits.push(`cfg ${item.videoGuidance}`);
  return bits.length ? bits.join(" · ") : null;
}

