          ) : null}
        </View>
      )}
    </View>
  );
}

function areChatMessageRowPropsEqual(
  previous: ChatMessageRowProps,
  next: ChatMessageRowProps
): boolean {
  const previousActive = previous.speakingMessageId === previous.item.id;
  const nextActive = next.speakingMessageId === next.item.id;
  return (
    previous.item.id === next.item.id &&
    previous.item.role === next.item.role &&
    previous.item.parts === next.item.parts &&
    previous.item.streaming === next.item.streaming &&
    previous.item.assistantName === next.item.assistantName &&
    previous.item.createdAt === next.item.createdAt &&
    previous.assistantName === next.assistantName &&
    previous.knownSkillIds === next.knownSkillIds &&
    previous.isLatestAssistantMessage === next.isLatestAssistantMessage &&
    previous.isRegenerateTarget === next.isRegenerateTarget &&
    previous.actionRowStyle === next.actionRowStyle &&
    previous.onRegenerate === next.onRegenerate &&
    previous.onDeleteMessage === next.onDeleteMessage &&
    previous.showActionFeedback === next.showActionFeedback &&
    previous.speech === next.speech &&
    previousActive === nextActive
  );
}

