type TranscriptMotionPhase = "stream" | "settle";

const initialTranscriptMotionMetrics = {
  settle: "settle 0: pending",
  stream: "stream 0: pending",
} satisfies Record<TranscriptMotionPhase, string>;

const motionMetricStyle: TextStyle = {
  bottom: 1,
  fontSize: 1,
  height: 1,
  left: 0,
  opacity: 0.01,
  overflow: "hidden",
  position: "absolute",
  width: 1,
};

const motionHeartbeatStyle: ViewStyle = {
  bottom: 0,
  height: 1,
  left: 0,
  position: "absolute",
  width: 1,
};

// Mounted only under EXPO_PUBLIC_PERF_FIXTURES so the shared values and the
// frame callback do not exist in a shipped build. The frame callback runs for
// the whole mount: it drives a 1px heartbeat so simulator recordings (which are
// change-driven, not fixed-rate) carry a frame every display tick, which makes
// an inter-frame gap in the recording mean a real stall instead of a still
// screen. Phase counters accumulate only while `capturing` is set.
function ChatTranscriptMotionMetrics({ streaming }: { streaming: boolean }) {
  const [metrics, setMetrics] = useState(initialTranscriptMotionMetrics);
  const sampleCountsRef = useRef<Record<TranscriptMotionPhase, number>>({
    settle: 0,
    stream: 0,
  });
  const wasStreamingRef = useRef(false);
  const capturing = useSharedValue(false);
  const heartbeat = useSharedValue(0);
  const frames = useSharedValue(0);
  const duration = useSharedValue(0);
  const maxDelta = useSharedValue(0);
  const over20 = useSharedValue(0);
  const over34 = useSharedValue(0);
  useFrameCallback((frameInfo) => {
    heartbeat.value = heartbeat.value === 0 ? 1 : 0;
    const delta = frameInfo.timeSincePreviousFrame;
    if (delta === null || !capturing.value) return;
    frames.value += 1;
    duration.value += delta;
    maxDelta.value = Math.max(maxDelta.value, delta);
    if (delta > 20) over20.value += 1;
    if (delta > 34) over34.value += 1;
  }, true);
  const heartbeatStyle = useAnimatedStyle(() => ({
    backgroundColor: heartbeat.value === 0 ? "#000000" : "#ffffff",
  }));
  const startPhase = useCallback(() => {
    frames.set(0);
    duration.set(0);
    maxDelta.set(0);
    over20.set(0);
    over34.set(0);
    capturing.set(true);
  }, [capturing, duration, frames, maxDelta, over20, over34]);
  const finishPhase = useCallback(
    (phase: TranscriptMotionPhase) => {
      capturing.set(false);
      const count = sampleCountsRef.current[phase] + 1;
      sampleCountsRef.current[phase] = count;
      const label = `${phase} ${count}: frames=${frames.get()} duration=${duration.get().toFixed(1)}ms max=${maxDelta.get().toFixed(1)}ms over20=${over20.get()} over34=${over34.get()}`;
      setMetrics((current) => ({ ...current, [phase]: label }));
    },
    [capturing, duration, frames, maxDelta, over20, over34]
  );

  useEffect(() => {
    if (streaming === wasStreamingRef.current) return;
    wasStreamingRef.current = streaming;
    if (streaming) {
      startPhase();
      return;
    }
    finishPhase("stream");
    startPhase();
    const settleTimer = setTimeout(
      () => finishPhase("settle"),
      MOTION_SETTLE_WINDOW_MS
    );
    return () => clearTimeout(settleTimer);
  }, [finishPhase, startPhase, streaming]);

  return (
    <>
      {(Object.keys(metrics) as TranscriptMotionPhase[]).map((phase) => (
        <Text
          key={phase}
          style={motionMetricStyle}
          testID={`homer-chat-motion-${phase}`}
        >
          {metrics[phase]}
        </Text>
      ))}
      <Animated.View
        pointerEvents="none"
        style={[motionHeartbeatStyle, heartbeatStyle]}
        testID="homer-chat-motion-heartbeat"
      />
    </>
  );
}

const MessageListBase = forwardRef<ChatScrollViewRef, MessageListProps>(
  function MessageList(
    {
      dataKey,
      items,
      assistantName,
      knownSkillIds,
      api,
      bottomInset = 0,
      onRegenerate,
      onDeleteMessage,
      onGenerationAction,
    },
    ref
  ) {
    const { width } = useWindowDimensions();
    const isDesktop = width >= DESKTOP_BREAKPOINT;
    const contentMaxWidth = isDesktop ? 820 : undefined;
    const [speakingMessageId, setSpeakingMessageIdState] = useState<
      string | null
    >(null);
    // Transition-synced mirror: speech callbacks read the ref at event time,
    // and an effect-synced ref would be one commit stale.
    const setSpeakingMessageId = useCallback((id: string | null) => {
      speakingMessageIdRef.current = id;
      setSpeakingMessageIdState(id);
    }, []);
    const [actionFeedback, setActionFeedback] = useState<string | null>(null);
    const [voicePickerVisible, setVoicePickerVisible] = useState(false);
    const voiceSelection = useVoiceSelection();
    const actionFeedbackTimerRef = useRef<ReturnType<typeof setTimeout> | null>(
      null
    );
    const actionFeedbackOpacity = useSharedValue(0);
    const actionFeedbackTranslateY = useSharedValue(8);
    const speakingMessageIdRef = useRef<string | null>(null);
    const showActionFeedback = useCallback(
      (message: string) => {
        if (actionFeedbackTimerRef.current) {
          clearTimeout(actionFeedbackTimerRef.current);
        }
        setActionFeedback(message);
        actionFeedbackTranslateY.set(8);
        actionFeedbackOpacity.set(withTiming(1, { duration: 140 }));
        actionFeedbackTranslateY.set(withTiming(0, { duration: 140 }));
        actionFeedbackTimerRef.current = setTimeout(() => {
          actionFeedbackOpacity.set(withTiming(0, { duration: 160 }));
          actionFeedbackTranslateY.set(withTiming(6, { duration: 160 }));
          actionFeedbackTimerRef.current = setTimeout(() => {
            setActionFeedback(null);
            actionFeedbackTimerRef.current = null;
          }, 180);
        }, 1400);
      },
      [actionFeedbackOpacity, actionFeedbackTranslateY]
    );
    const speechBackend = useMemo(
      () =>
        createNaturalAssistantSpeechBackend({
          voiceId: voiceSelection.selectedVoiceId,
          fetchImpl: (_path, init) => api.voiceTts(init ?? {}),
        }),
      [api, voiceSelection.selectedVoiceId]
    );
    const latestAssistantMessageId = useMemo(() => {
      for (let idx = items.length - 1; idx >= 0; idx--) {
        const item = items[idx];
        if (item === undefined) continue;
        if (item.kind === "message" && item.role === "assistant") {
          return item.id;
        }
      }
      return null;
    }, [items]);
    const regenerateTargetId = useMemo(
      () => resolveRegenerateTargetId(items),
      [items]
    );
    const transcriptStreaming = useMemo(
      () =>
        items.some(
          (item) =>
            item.kind === "pending" ||
            (item.kind === "message" && item.streaming)
        ),
      [items]
    );
    const anchoredEndSpace = streamingAnchorFor(items, transcriptStreaming);
    useEffect(() => {
      return () => {
        if (actionFeedbackTimerRef.current) {
          clearTimeout(actionFeedbackTimerRef.current);
        }
        void speechBackend.stop();
      };
    }, [speechBackend]);
    const actionRowStyle: ViewStyle = useMemo(
      () => ({
        flexDirection: "row",
        flexWrap: "wrap",
        gap: 6,
        marginTop: 6,
        paddingLeft: 2,
      }),
      []
    );
    const getActiveSpeakingMessageId = useCallback(
      () => speakingMessageIdRef.current,
      []
    );
    const openVoicePicker = useCallback(() => {
      hapticTick("light");
      Keyboard.dismiss();
      setVoicePickerVisible(true);
    }, []);
    const speech = useMemo<MessageRowSpeech>(
      () => ({
        backend: speechBackend,
        getActiveId: getActiveSpeakingMessageId,
        setActiveId: setSpeakingMessageId,
        onOpenVoicePicker: openVoicePicker,
      }),
      [
        getActiveSpeakingMessageId,
        openVoicePicker,
        setSpeakingMessageId,
        speechBackend,
      ]
    );
    const contentContainerStyle: ViewStyle = useMemo(
      () => ({
        paddingTop: isDesktop ? 28 : 20,
        paddingBottom:
          Platform.OS === "web" ? bottomInset + (isDesktop ? 32 : 28) : 0,
        paddingHorizontal: isDesktop ? 24 : 16,
        maxWidth: contentMaxWidth,
        width: "100%",
        alignSelf: "center",
      }),
      [bottomInset, contentMaxWidth, isDesktop]
    );
    const onGenerationActionRef = useRef(onGenerationAction);
    useEffect(() => {
      onGenerationActionRef.current = onGenerationAction;
    }, [onGenerationAction]);
    const onGenerationActionStable = useCallback(
      (id: string, kind: GenerationActionKind) => {
        onGenerationActionRef.current?.(id, kind);
      },
      []
    );
    const requestRegenerate = useEffectEvent(() => {
      onRegenerate?.();
    });
    const requestDeleteMessage = useEffectEvent((id: string) => {
      if (transcriptStreaming) {
        showActionFeedback("cannot delete while the reply is streaming");
        return;
      }
      onDeleteMessage?.(id);
    });
    // Row-facing action identities track capability, never turn state, so a
    // stream boundary no longer invalidates renderItem and every visible row.
    const rowRegenerate = onRegenerate ? requestRegenerate : undefined;
    const rowDeleteMessage = onDeleteMessage ? requestDeleteMessage : undefined;
    // Rows live behind LegendList's memo chain; extraData is the supported
    // path to re-invoke renderItem so the row comparators can gate updates.
    const listExtraData = useMemo(
      () => ({
        speakingMessageId,
        speech,
        latestAssistantMessageId,
        regenerateTargetId,
        rowDeleteMessage,
        rowRegenerate,
      }),
      [
        latestAssistantMessageId,
        regenerateTargetId,
        rowDeleteMessage,
        rowRegenerate,
        speakingMessageId,
        speech,
      ]
    );
    const renderItem = useCallback(
      ({ item }: LegendListRenderItemProps<ChatItem>) => {
        if (item.kind === "message") {
          return (
            <ChatMessageRow
              item={item}
              assistantName={assistantName}
              knownSkillIds={knownSkillIds}
              isLatestAssistantMessage={item.id === latestAssistantMessageId}
              isRegenerateTarget={item.id === regenerateTargetId}
              actionRowStyle={actionRowStyle}
              onRegenerate={rowRegenerate}
              onDeleteMessage={rowDeleteMessage}
              showActionFeedback={showActionFeedback}
              speech={speech}
              speakingMessageId={speakingMessageId}
            />
          );
        }
        if (item.kind === "pending") {
          return (
            <PendingAssistantRow
              knownSkillIds={knownSkillIds}
              assistantName={assistantName}
            />
          );
        }
        if (item.kind === "generation") {
          if (item.outputKind === "video") {
            return <VideoGenerationCard item={item} conversationId={dataKey} />;
          }
          if (item.outputKind === "asset") {
            return <AssetGenerationCard item={item} />;
          }
          return (
            <ImageGenerationCard
              item={item}
              conversationId={dataKey}
              onGenerationAction={onGenerationActionStable}
            />
          );
        }
        if (item.kind === "error") {
          return <ErrorRow item={item} />;
        }
        return <SwitchBannerRow item={item} />;
      },
      [
        assistantName,
        actionRowStyle,
        dataKey,
        knownSkillIds,
        latestAssistantMessageId,
        regenerateTargetId,
        rowRegenerate,
        rowDeleteMessage,
        showActionFeedback,
        speech,
        onGenerationActionStable,
        speakingMessageId,
      ]
    );

    const list = (
      <ChatView.ScrollView
        ref={ref}
        data={items}
        dataKey={dataKey}
        keyExtractor={(item) => item.id}
        getItemType={getChatItemType}
        renderItem={renderItem}
        anchoredEndSpace={anchoredEndSpace}
        restingEndSpace={bottomInset + (isDesktop ? 32 : 28)}
        initialScrollAtEnd
        alignItemsAtEnd
        maintainScrollAtEnd
        maintainScrollAtEndThreshold={0.12}
        recycleItems
        extraData={listExtraData}
        style={listStyle}
        contentContainerStyle={contentContainerStyle}
      />
    );

    return (
      <View style={{ flex: 1 }}>
        {Platform.OS === "web" ? (
          list
        ) : (
          <MaskedView style={maskFlexStyle} maskElement={listMaskElement}>
            {list}
          </MaskedView>
        )}
        <ActionSnackbar
          message={actionFeedback}
          bottomInset={bottomInset}
          opacity={actionFeedbackOpacity}
          translateY={actionFeedbackTranslateY}
        />
        <VoicePickerModal
          visible={voicePickerVisible}
          selectedVoiceId={voiceSelection.selectedVoiceId}
          onSelect={(voice) => {
            voiceSelection.setSelectedVoiceId(voice.id);
            setVoicePickerVisible(false);
            showActionFeedback(`${voice.name.toLowerCase()} voice selected`);
          }}
          onClose={() => setVoicePickerVisible(false)}
        />
        {MOTION_METRICS_ENABLED ? (
          <ChatTranscriptMotionMetrics streaming={transcriptStreaming} />
        ) : null}
      </View>
    );
  }
);

