function toolHint(capability?: ChatToolExecutionCapability) {
  if (!capability) return null;
  if (capability.toolCount === 0) return "no local tools";
  return `${capability.toolCount} ${capability.toolCount === 1 ? "tool" : "tools"}`;
}

