    onSelect: (id: string) => void;
  }) {
  return (
    <ChipStripContainer testID={testID} wrap={wrap}>
      {profiles.map((p) => {
        const isSelected = p.id === selectedId;
        const profileDisabled = disabled || p.status === "disabled";
        const profileDisabledReason =
          p.status === "disabled"
