export function ChatExecutionChipStrip({
  modelId,
  selectedExecution,
  onSelect,
  disabled,
  compact,
  capabilities,
  wrap,
  testID,
}: ChipStripLayoutProps &
  ChipStripInteractionProps & {
    modelId: string;
    selectedExecution: ChatExecution;
    onSelect: (execution: ChatExecution) => void;
    capabilities?: Map<string, ChatToolExecutionCapability>;
  }) {
  return (
    <ChipStripContainer testID={testID} wrap={wrap}>
      {CHAT_EXECUTION_OPTIONS.map((option) => {
        const executionLabel = chatExecutionLabel(option.execution);
        const isSelected =
          executionLabel === chatExecutionLabel(selectedExecution);
        const capability = capabilities?.get(
          capabilityKey(modelId, option.execution)
        );
        const isDisabled = disabled === true;
        const secondaryLabel = toolHint(capability);
        const chipClass = isSelected
          ? "bg-mb-accent border-mb-accent"
          : "bg-mb-surface border-mb-border-strong";
        const primaryTextClass = isSelected
          ? "text-mb-accent-ink"
          : "text-mb-text";
        const secondaryTextClass = isSelected
          ? "text-mb-accent-ink/80"
          : "text-mb-text-2";
        return (
          <Touchable
            feedback="highlight"
            key={executionLabel}
            testID={`homer-chat-execution-${modelId}-${executionLabel}`}
            accessibilityRole="button"
            accessibilityLabel={`select ${option.label} chat execution`}
            accessibilityState={{ selected: isSelected, disabled: isDisabled }}
            disabled={isDisabled}
            hitSlop={compact ? modelChipCompactHitSlop : modelChipHitSlop}
            onPress={() => {
              hapticTick("light");
              onSelect(option.execution);
            }}
            style={{ borderCurve: "continuous" }}
            className={`flex-row items-center gap-1.5 rounded-full border ${
              compact ? "px-2 py-1" : "px-2.5 py-1.5"
            } ${chipClass} ${isDisabled ? "opacity-80" : ""}`}
          >
            <Text
              className={`text-[12px] lowercase ${primaryTextClass}`}
              style={{ fontFamily: "GeistMono_500Medium", letterSpacing: 0.2 }}
            >
              {option.label}
            </Text>
            {secondaryLabel ? (
              <Text
                className={`text-[12px] ${secondaryTextClass}`}
                style={{ fontFamily: "GeistMono_500Medium" }}
              >
                {secondaryLabel}
              </Text>
            ) : null}
          </Touchable>
        );
      })}
    </ChipStripContainer>
  );
}

