// Speed stat at/below this (0-100 scale, ~100≈50 tok/s) flags a model "slow".
// ~20 ≈ <10 tok/s — the large-MoE offload band (DeepSeek V4 Flash, GLM-5.1).
const SLOW_SPEED_THRESHOLD = 20;

export function SwitchingModelLabel({ colors }: { colors: ThemePalette }) {
  const opacity = useSharedValue(1);
  const reduceMotion = useReducedMotion();

  useEffect(() => {
    cancelAnimation(opacity);
    if (reduceMotion) {
      opacity.set(1);
      return;
    }
    opacity.set(withRepeat(withTiming(0.78, { duration: 900 }), -1, true));
    return () => cancelAnimation(opacity);
  }, [opacity, reduceMotion]);

  const pulseStyle = useAnimatedStyle(() => ({ opacity: opacity.value }));

  return (
    <Animated.Text
      numberOfLines={1}
      style={[
        {
          color: colors.muted,
          fontFamily: "GeistMono_600SemiBold",
          fontSize: 12,
          lineHeight: 16,
        },
        pulseStyle,
      ]}
    >
      switching…
    </Animated.Text>
  );
}

type ModelScoreStat = {
  label: string;
  value: number;
};

type ModelInfoTarget = {
  active?: boolean;
  modelId: string;
  stats: ModelScoreStat[];
};

function averageScore(stats: ModelScoreStat[]) {
  if (!stats.length) return null;
  const sum = stats.reduce((total, stat) => total + stat.value, 0);
  return Math.round(sum / stats.length);
}

function InfoIcon({
  stats,
  modelId,
  modelName,
  colors,
  onBeforeNavigate,
  compact,
