type MenuRowPresentation = ModelInfoTarget & {
  testID?: string;
  name: string;
  sub?: string;
  dotColor: "online" | "warming" | "offline";
  capabilityTags?: readonly string[];
  disabledReason?: string;
};

type MenuRowState = {
  compact?: boolean;
  dense?: boolean;
  disabled?: boolean;
};

export function MenuRow({
  presentation,
  state,
  actions,
  colors,
  details,
}: {
  presentation: MenuRowPresentation;
  state: MenuRowState;
  actions: {
    onPress: () => void;
    onNavigate?: () => void;
  };
  colors: ThemePalette;
  details?: ReactNode;
}) {
  const {
    modelId,
    testID,
    name,
    sub,
    dotColor,
    active,
    capabilityTags,
    stats,
    disabledReason,
  } = presentation;
  const { compact, dense, disabled } = state;
  const { onPress, onNavigate } = actions;
  const hasStats = stats.length > 0;
  const score = averageScore(stats);
  // Honest "slow" signal: chat profiles whose measured speed stat is low
  // (e.g. large-MoE configs that exceed VRAM and offload, ~<10 tok/s).
  const speedStat = stats.find((stat) => stat.label === "speed");
  const isSlow = speedStat != null && speedStat.value <= SLOW_SPEED_THRESHOLD;
  const roomy = !compact && !dense;
  const rowPadding = compact
    ? "min-h-0 px-2.5 py-2.5"
    : dense
      ? "min-h-14 px-4 py-3"
      : roomy
        ? "min-h-14 px-4 py-3"
        : "px-2.5 py-2";
  const titleReserve = hasStats ? (compact ? "pr-12" : "pr-24") : "pr-2";
  const rowSurface = compact
    ? active
      ? "border-mb-accent bg-mb-accent-dim"
      : "border-transparent bg-transparent"
    : active
      ? "border-mb-accent bg-mb-accent-dim"
      : disabled
        ? "border-mb-border bg-mb-surface"
        : "border-mb-border bg-mb-surface";
  const expandedSurface = active
    ? "border-mb-accent bg-mb-accent-dim"
    : disabled
      ? "border-mb-border bg-mb-surface"
      : "border-mb-border bg-mb-surface";
  return (
    <View
      className={details ? `rounded-xl border ${expandedSurface}` : undefined}
      style={details ? { borderCurve: "continuous" } : undefined}
    >
      <SheetRow
        feedback="highlight"
        accessibilityRole="button"
        accessibilityLabel={`${name}${sub ? `, ${sub}` : ""}, ${dotColor}${score === null ? "" : `, average score ${score}`}`}
        accessibilityHint={
          disabled ? disabledReason : "Opens model runtime options"
        }
        accessibilityState={{
          disabled: Boolean(disabled),
          selected: Boolean(active),
        }}
        testID={testID ?? `homer-model-option-${modelId}`}
        disabled={disabled}
        onPress={() => {
          if (disabled) return;
          hapticTick("light");
          onPress();
        }}
        style={{
          borderCurve: "continuous",
          position: "relative",
          boxShadow:
            details || compact || dense
              ? undefined
              : active
                ? `0 8px 24px ${withAlpha(colors.accent, 0.1)}`
                : `0 1px 0 ${withAlpha(colors.text, 0.04)}`,
        }}
        className={`flex-col items-stretch ${rowPadding} gap-1 ${details ? "rounded-t-xl border-transparent bg-transparent" : `rounded-xl border ${rowSurface}`} ${disabled ? "opacity-80" : ""}`}
      >
        <View className={`flex-row items-center gap-2 ${titleReserve}`}>
          <Dot color={dotColor} colors={colors} />
          <Text
            className={`${compact ? "text-[12px]" : "text-[15px]"} text-mb-text flex-1 min-w-0`}
            style={{
              fontFamily: "Geist_600SemiBold",
              letterSpacing: 0,
              lineHeight: dense ? 18 : undefined,
            }}
            numberOfLines={dense ? 2 : 1}
          >
            {name}
          </Text>
          {capabilityTags?.length ? (
            <View
              className="flex-row flex-wrap justify-end gap-1 shrink-0"
              style={{ maxWidth: compact ? 112 : 176 }}
            >
              {capabilityTags.map((tag) => (
                <View
                  key={tag}
                  className="rounded-full border border-mb-border-strong bg-mb-surface-2 px-1.5 py-0.5"
                  style={{
                    borderCurve: "continuous",
                    maxWidth: compact ? 54 : 72,
                  }}
                >
                  <Text
                    className="text-mb-text-2 text-[12px]"
                    style={{
                      fontFamily: "GeistMono_600SemiBold",
                      letterSpacing: 0,
                    }}
                    numberOfLines={1}
                    ellipsizeMode="tail"
                  >
                    {tag}
                  </Text>
                </View>
              ))}
            </View>
          ) : null}
          {isSlow ? (
            <View
              className="rounded-full bg-mb-warm-dim px-1.5 py-0.5"
              style={{ borderCurve: "continuous" }}
            >
              <Text
                className="text-mb-warm text-[12px] uppercase"
                style={{
                  fontFamily: "GeistMono_600SemiBold",
                  letterSpacing: 0.5,
                }}
              >
                slow speed
              </Text>
            </View>
          ) : null}
        </View>
        {sub ? (
          <SheetRowDetail
            className={compact ? "pl-3.5 text-[12px]" : "pl-4"}
            style={{
              letterSpacing: 0.1,
              lineHeight: dense ? 16 : undefined,
            }}
            numberOfLines={compact ? 1 : 2}
