export function AgentFeatureScene({
  group,
  onBack,
  onChange,
  compact,
}: {
  group: AgentFeatureGroup;
  onBack: () => void;
  onChange: (nextSelectedIds: string[]) => void;
  compact: boolean;
}) {
  const { selectedIds } = group;
  const selectedSet = new Set(selectedIds);
  const sections: (string | undefined)[] = [];
  for (const option of group.options) {
    if (!sections.includes(option.section)) sections.push(option.section);
  }
  const toggleOption = (optionId: string) => {
    hapticTick("light");
    const isSelected = selectedSet.has(optionId);
    const next =
      group.mode === "single"
        ? [optionId]
        : isSelected
          ? selectedIds.filter((id) => id !== optionId)
          : [...selectedIds, optionId];
    onChange(next);
  };
  return (
    <View className="gap-2">
      <SheetNestedBackButton
        onPress={onBack}
        accessibilityLabel="back to model list"
        accessibilityHint="Returns from agent feature details to the model list"
        testID="homer-agent-feature-back"
      />
      <View
        accessibilityRole={group.mode === "single" ? "radiogroup" : undefined}
        className={`${
          compact ? "px-4 py-3.5" : "px-4 py-4"
        } rounded-lg border border-mb-border-strong bg-mb-surface gap-4`}
        style={{ borderCurve: "continuous" }}
      >
        {sections.map((section) => {
          const options = group.options.filter(
            (option) => option.section === section
          );
          return (
            <View key={section ?? "_default"} className="gap-2">
              {section ? <SectionLabel>{section}</SectionLabel> : null}
              <ChipStripContainer
                wrap
                testID={`homer-agent-feature-${group.id}-${section ?? "options"}`}
              >
                {options.map((option) => {
                  const isSelected = selectedSet.has(option.id);
                  const hasDetail = Boolean(option.detail);
                  return (
                    <Touchable
                      feedback="highlight"
                      key={option.id}
                      testID={`homer-agent-feature-option-${group.id}-${option.id}`}
                      accessibilityRole={
                        group.mode === "single" ? "radio" : "checkbox"
                      }
                      accessibilityState={{ checked: isSelected }}
                      accessibilityLabel={option.label}
                      hitSlop={
                        compact ? modelChipCompactHitSlop : modelChipHitSlop
                      }
                      onPress={() => toggleOption(option.id)}
                      style={{ borderCurve: "continuous" }}
                      className={`border ${
                        hasDetail
                          ? "min-h-11 rounded-lg px-3 py-2 gap-0.5"
                          : `rounded-full ${compact ? "px-2 py-1" : "px-2.5 py-1.5"}`
                      } ${
                        isSelected
                          ? "bg-mb-accent border-mb-accent"
                          : "bg-mb-surface border-mb-border-strong"
                      }`}
                    >
                      <Text
                        className={`text-[12px] lowercase ${
                          isSelected ? "text-mb-accent-ink" : "text-mb-text"
                        }`}
                        style={{
                          fontFamily: "GeistMono_500Medium",
                          letterSpacing: 0.2,
                        }}
                        numberOfLines={1}
                      >
                        {option.label}
                      </Text>
                      {option.detail ? (
                        <Text
                          className={`text-[12px] lowercase ${
                            isSelected
                              ? "text-mb-accent-ink/80"
                              : "text-mb-text-2"
                          }`}
                          style={{
                            fontFamily: "GeistMono_500Medium",
                            letterSpacing: 0.15,
                            lineHeight: 16,
                          }}
                          numberOfLines={2}
                        >
                          {option.detail}
                        </Text>
                      ) : null}
                    </Touchable>
                  );
                })}
              </ChipStripContainer>
            </View>
          );
        })}
        <View className="gap-1.5">
          <Text
            className="text-mb-text-2 text-[12px] uppercase"
            style={{ fontFamily: "GeistMono_600SemiBold", letterSpacing: 0.8 }}
          >
            summary
          </Text>
          <View
            className="rounded-md border border-mb-border bg-mb-surface px-3 py-2"
            style={{ borderCurve: "continuous" }}
          >
            <Text
              className="text-mb-text text-[12px]"
              style={{ fontFamily: "GeistMono_400Regular", lineHeight: 17 }}
            >
              {group.summary}
            </Text>
          </View>
        </View>
      </View>
    </View>
  );
}

