// @vitest-environment happy-dom

import { useRef, useState } from "react";
import { act, cleanup, render, screen } from "@testing-library/react";
import { afterEach, describe, expect, it, vi } from "vitest";
import { useChatComposerAttachments } from "./use-chat-composer-attachments";
import type { PickedImage } from "./types";

const imagePicker = vi.hoisted(() => ({
  requestMediaLibraryPermissionsAsync: vi.fn(),
  launchImageLibraryAsync: vi.fn(),
  getPendingResultAsync: vi.fn(),
}));

vi.mock("expo-image-picker", () => imagePicker);
vi.mock("react-native", () => ({
  AppState: { addEventListener: () => ({ remove: vi.fn() }) },
  Platform: { OS: "android" },
}));

function deferred<T>() {
  let resolve!: (value: T) => void;
  const promise = new Promise<T>((next) => {
    resolve = next;
  });
  return { promise, resolve };
}

const stalePickerResult = {
  canceled: false as const,
  assets: [
    {
      uri: "file:///stale.jpg",
      mimeType: "image/jpeg",
      fileName: "stale.jpg",
      base64: "ZmFrZQ==",
    },
  ],
};

type StalePickerResult = typeof stalePickerResult;

function AttachmentHarness({ acceptsAttachments = true }) {
  const [chatAttachments, setChatAttachments] = useState<PickedImage[]>([]);
  const [picked, setPicked] = useState<PickedImage | null>(null);
  const [submitError, setSubmitError] = useState<string | null>(null);
  const recoveredPendingChatImageKeysRef = useRef(new Set<string>());
  const actions = useChatComposerAttachments({
    selectedChatAcceptsAttachments: acceptsAttachments,
    chatAttachments,
    setChatAttachments,
    setPicked,
    setSubmitError,
    recoveredPendingChatImageKeysRef,
  });

  return (
    <div>
      <button onClick={() => void actions.handlePickChatImages()}>
        pick chat
      </button>
      <output data-testid="attachment-count">{chatAttachments.length}</output>
      <output data-testid="picked">{picked?.uri ?? "none"}</output>
      <output data-testid="error">{submitError ?? "none"}</output>
    </div>
  );
}

describe("useChatComposerAttachments", () => {
  afterEach(() => {
    cleanup();
    imagePicker.requestMediaLibraryPermissionsAsync.mockReset();
    imagePicker.launchImageLibraryAsync.mockReset();
    imagePicker.getPendingResultAsync.mockReset();
    imagePicker.getPendingResultAsync.mockResolvedValue(null);
  });

  it("does not apply a picker result after the host unmounts", async () => {
    const picker = deferred<StalePickerResult>();
    imagePicker.requestMediaLibraryPermissionsAsync.mockResolvedValue({
      granted: true,
      canAskAgain: true,
    });
    imagePicker.launchImageLibraryAsync.mockReturnValue(picker.promise);
    const rendered = render(<AttachmentHarness />);

    screen.getByRole("button", { name: "pick chat" }).click();
    await act(async () => undefined);
    rendered.unmount();
    await act(async () => {
      picker.resolve(stalePickerResult);
      await picker.promise;
    });

    expect(rendered.container.textContent).toBe("");
  });

  it("ignores a picker result when attachment support changes", async () => {
    const picker = deferred<StalePickerResult>();
    imagePicker.requestMediaLibraryPermissionsAsync.mockResolvedValue({
      granted: true,
      canAskAgain: true,
    });
    imagePicker.launchImageLibraryAsync.mockReturnValue(picker.promise);
    const rendered = render(<AttachmentHarness />);

    screen.getByRole("button", { name: "pick chat" }).click();
    await act(async () => undefined);
    rendered.rerender(<AttachmentHarness acceptsAttachments={false} />);
    await act(async () => {
      picker.resolve(stalePickerResult);
      await picker.promise;
    });

    expect(screen.getByTestId("attachment-count").textContent).toBe("0");
    expect(screen.getByTestId("error").textContent).toBe("none");
  });
});

