        <View className="flex-row items-center gap-2">
          <View className="h-[6px] w-[6px] rounded-full bg-mb-border-strong" />
          <Text
            className="text-mb-text text-[12px] flex-1"
            style={{ fontFamily: "Geist_500Medium" }}
            numberOfLines={1}
          >
            video runtime
          </Text>
          <Text
            className="text-mb-muted text-[10px] uppercase"
            style={{ fontFamily: "GeistMono_600SemiBold" }}
          >
            {video.healthRuntimeStatus}
          </Text>
        </View>
        <Text
          className="text-mb-muted text-[11px]"
          style={{
            fontFamily: "GeistMono_400Regular",
            letterSpacing: 0.15,
            lineHeight: 16,
          }}
          numberOfLines={3}
        >
          {video.runtimeDisabledReason || "video runtime ready"}
        </Text>
      </View>
    </View>
  );
}

export function useChatComposerControls({
  image,
  video,
  stop,
  mode,
  capabilityRow,
}: UseChatComposerControlsParams) {
  const imageSourceNode = renderImageSource({ mode, image });
  const imageControlsNode = renderImageControls({
    capabilityRow,
    image,
    source: imageSourceNode,
  });
  const videoConfigNode = renderVideoConfig({ video });
  const videoControlsNode = renderVideoControls({
    capabilityRow,
    video,
    config: videoConfigNode,
  });

  return {
    handleStop: stop,
    imageControlsNode,
    videoControlsNode,
  };
}

import { useCallback, useMemo } from "react";
import type {
  ComposerCommand,
  ComposerSubmitContext,
} from "@/components/chat/composer";
import { hapticTick } from "@/lib/haptics";
import type { SwitchRoute } from "@homer/shared/switch-stream";
import type { PickedImage } from "./types";
import type { UseChatScreenGenerationTimelineResult } from "./use-chat-screen-generation-timeline";
import type { ImageModelTarget } from "@/lib/model-directory";
import type { ImageControlValue } from "@homer/shared/image-capabilities";
import {
  composerHasSlot,
  type ComposerCapabilityRow,
} from "../composer-capability-table";

type UseChatComposerSubmitParams = {
  mode: SwitchRoute;
  capabilityRow: ComposerCapabilityRow;
  hasChatAttachmentDraft: boolean;
  clearConversation: () => Promise<void>;
  restartSelectedModel: () => void;
  image: {
    target: ImageModelTarget;
    values: Record<string, ImageControlValue>;
  } | null;
  picked: PickedImage | null;
  sendPrompt: (text: string) => Promise<boolean>;
  revealSubmittedMessage(closeKeyboard: boolean): void;
  startImageGeneration: UseChatScreenGenerationTimelineResult["startImageGeneration"];
};

type AvailableComposerSubmitCapability = {
  kind: "available";
  submit: (text: string) => Promise<boolean>;
};

type ComposerSubmitCapability =
  | AvailableComposerSubmitCapability
  | { kind: "unavailable" };

type ImageSubmitCapabilityInput = {
  text: string;
  operation: Parameters<
    UseChatScreenGenerationTimelineResult["startImageGeneration"]
  >[0]["operation"];
};

export function useChatComposerSubmit({
  mode,
  hasChatAttachmentDraft,
  clearConversation,
  restartSelectedModel,
  image,
  picked,
  sendPrompt,
  revealSubmittedMessage,
  startImageGeneration,
  capabilityRow,
}: UseChatComposerSubmitParams) {
  const hasPickedImage = picked !== null;
  const submitChatCapability = useCallback(
    (text: string): Promise<boolean> => sendPrompt(text),
    [sendPrompt]
  );
  const submitImageCapability = useCallback(
    async ({
      text,
      operation,
    }: ImageSubmitCapabilityInput): Promise<boolean> => {
      if (!image) {
        throw new Error("Image submit requires a selected image target.");
      }
      hapticTick("medium");
      return startImageGeneration({
        prompt: text,
        target: image.target,
        operation,
        source: picked ?? undefined,
        controls: { ...image.values },
      });
    },
    [image, picked, startImageGeneration]
  );
  const activeSubmitCapability = useMemo<ComposerSubmitCapability>(() => {
    const imageOperation = capabilityRow.imageOperation(mode);
    switch (capabilityRow.generation) {
      case "chat-stream":
        return {
          kind: "available",
          submit: submitChatCapability,
        };
      case "image-upload":
        if (imageOperation === "image-to-image" && !hasPickedImage) {
          return { kind: "unavailable" };
        }
        return {
          kind: "available",
          submit: (text: string) =>
            submitImageCapability({
              text,
              operation: imageOperation ?? "text-to-image",
            }),
        };
      case "video-task":
      case null:
        return { kind: "unavailable" };
      default: {
        const exhaustive: never = capabilityRow.generation;
        return exhaustive;
      }
    }
  }, [
    capabilityRow,
    hasPickedImage,
    mode,
    submitChatCapability,
    submitImageCapability,
  ]);

  const handleComposerSubmit = useCallback(
    async ({ text, source }: ComposerSubmitContext) => {
      text = text.trim();
      if (
        !text &&
        !(
          composerHasSlot(capabilityRow, "attachments") &&
          hasChatAttachmentDraft
        )
      )
        return false;
      if (text === "/clear") {
        await clearConversation();
        revealSubmittedMessage(source === "button");
        return true;
      }
      if (text === "/restart") {
        restartSelectedModel();
        revealSubmittedMessage(source === "button");
        return true;
      }
      if (activeSubmitCapability.kind === "unavailable") return false;
      const submitted = await activeSubmitCapability.submit(text);
      if (submitted) revealSubmittedMessage(source === "button");
      return submitted;
    },
    [
      activeSubmitCapability,
      capabilityRow,
      clearConversation,
      hasChatAttachmentDraft,
      revealSubmittedMessage,
      restartSelectedModel,
    ]
  );

  const handleComposerCommand = useCallback(
    async (command: ComposerCommand) => {
      switch (command) {
        case "clear":
          await clearConversation();
          return;
        case "restart":
          restartSelectedModel();
          return;
        default: {
          const unsupportedCommand: never = command;
          throw new Error(
            `Unsupported composer command: ${String(unsupportedCommand)}`
          );
        }
      }
    },
    [clearConversation, restartSelectedModel]
  );

  return { handleComposerSubmit, handleComposerCommand };
}

import { videoProspectiveConfigIdSchema } from "@homer/shared/video-configs";
import type { RuntimeStatus } from "@homer/shared/runtime-types";
