  type SetStateAction,
} from "react";
import { useQueryClient } from "@tanstack/react-query";
import {
  useApi,
  useImageCancelTask,
  useImageUpload,
  useVideoTaskSubmit,
} from "@/lib/data";
import { hapticTick } from "@/lib/haptics";
import type { ImageGenerationOperation } from "@homer/shared/conversation-types";
import {
  modelSnapshotForTarget,
  requireModelTargetById,
  type ImageModelTarget,
  type VideoModelTarget,
} from "@/lib/model-directory";
import { newLocalId } from "@/lib/local-id";
import type { TimelinePosition } from "@/lib/chat-message-meta";
