import {
  imageTargetDisabledReason,
  videoDisabledRuntimeReason,
  videoResolutionLabel,
} from "./model-utils";
import {
  progressLabel,
  progressPercent,
  mediaTaskStatus,
  mediaTaskPercent,
  mediaTaskPhase,
  mediaTaskDetail,
  mediaTaskResultUrl,
  isGenerationTerminalStatus,
} from "./media-task-parsers";
import { sortedTimelineEntries } from "./timeline";
import type { GenerationActionKind } from "@/components/chat/message-list";
import type {
  GenerationView,
  ImageGenerationView,
