} from "../composer-capability-table";
import {
  UNPAIRED_MACHINE_TURN_BLOCKED_REASON,
  useConversationRuntime,
  type ConversationRuntime,
} from "@/screens/conversation-runtime";

function machineGenerationDisabledReason(
  runtime: ConversationRuntime
): string | null {
  if (runtime.conversation.binding.kind === "model") return null;
  switch (runtime.machineAgent.kind) {
    case "problem":
      return runtime.machineAgent.body;
    case "unpaired":
      return UNPAIRED_MACHINE_TURN_BLOCKED_REASON;
    case "active":
      return `This conversation runs on ${runtime.machineAgent.machine.name}. Image and video generation are unavailable in Machine conversations.`;
    case "inactive":
      throw new Error(
        "Machine conversation resolved without a Machine Agent route."
      );
  }
}

export type UseChatScreenGenerationTimelineParams = {
  setPicked: Dispatch<SetStateAction<PickedImage | null>>;
  imageHealthData:
    | { online: boolean; model: string | null | undefined }
    | null
    | undefined;
  videoSubmission: RuntimeStatus["active"]["videoSubmission"] | undefined;
};

type ImageGenerationInput = {
  prompt: string;
  target: ImageModelTarget;
  operation: ImageGenerationOperation;
  source?: PickedImage;
  controls: ImageGenerationView["effectiveRequest"]["controls"];
};

type ImageGenerationProvenance = Pick<
  ImageGenerationView,
  "operation" | "prompt" | "modelSnapshot" | "effectiveRequest"
>;

type VideoGenerationProvenance = Pick<
  VideoGenerationView,
  "operation" | "prompt" | "modelSnapshot" | "effectiveRequest"
>;

export type UseChatScreenGenerationTimelineResult = {
  upload: ReturnType<typeof useImageUpload>;
  videoSubmit: ReturnType<typeof useVideoTaskSubmit>;
  generations: GenerationView[];
  setGenerations: Dispatch<SetStateAction<GenerationView[]>>;
  generationsRef: MutableRefObject<GenerationView[]>;
  generationTimelineEntries: ChatTimelineEntry[];
  handleGenerationAction: (id: string, kind: GenerationActionKind) => void;
  startImageGeneration: (input: ImageGenerationInput) => Promise<boolean>;
  startVideoGeneration: (input: {
    prompt: string;
    target: VideoModelTarget;
  }) => Promise<boolean>;
};

export function useChatScreenGenerationTimeline(
  params: UseChatScreenGenerationTimelineParams
): UseChatScreenGenerationTimelineResult {
  const { setPicked, imageHealthData, videoSubmission } = params;

  const runtime = useConversationRuntime();
  const { models, mode, select: selectModel } = runtime.model;
  const { composerRef, setSubmitError } = runtime.composer;
  const generationBlockedReason = machineGenerationDisabledReason(runtime);

  const { baseURL } = useApi();
  const queryClient = useQueryClient();
  const cancelImageTask = useImageCancelTask();
  const upload = useImageUpload();
  const videoSubmit = useVideoTaskSubmit();
  const cancelImageTaskAsync = cancelImageTask.mutateAsync;
  const uploadAsync = upload.mutateAsync;
  const videoSubmitAsync = videoSubmit.mutateAsync;
  const imageHealthModel = imageHealthData?.model ?? null;
  const imageHealthOnline = imageHealthData?.online === true;

  const [generations, setGenerationsState] = useState<GenerationView[]>([]);
  const generationsRef = useRef<GenerationView[]>([]);
  // The ref is written inside the state transition so tap-time reads are
  // never a commit behind (effect-synced refs swallowed same-commit cancels;
  // render-phase writes are barred by react-hooks lint).
  const setGenerations = useCallback(
    (action: Parameters<typeof setGenerationsState>[0]) => {
      setGenerationsState((prev) => {
        const next = typeof action === "function" ? action(prev) : action;
        generationsRef.current = next;
        return next;
      });
    },
    []
  );

  const submitImageGeneration = useCallback(
    async (provenance: ImageGenerationProvenance) => {
      if (generationBlockedReason) {
        setSubmitError(generationBlockedReason);
        return false;
      }
      if (
        !imageHealthOnline ||
        imageHealthModel !== provenance.modelSnapshot.id
      ) {
        setSubmitError(`switch to ${provenance.modelSnapshot.name} first`);
        return false;
      }

      const generationId = newLocalId("image");
      const generation = {
        ...provenance,
        generationId,
        outputKind: "image",
        status: "uploading",
        phase: "uploading",
        createdAt: Date.now(),
      } satisfies ImageGenerationView;
      setSubmitError(null);
      setGenerations((prev) => [...prev, generation]);

      const form = await COMPOSER_CAPABILITY_TABLE.image.draftToRequestBody({
        kind: "image",
        model: provenance.modelSnapshot.id,
        prompt: provenance.prompt,
        controls: provenance.effectiveRequest.controls,
        source: provenance.effectiveRequest.source
          ? {
              uri: provenance.effectiveRequest.source.uri,
              mimeType: provenance.effectiveRequest.source.mimeType,
              fileName: provenance.effectiveRequest.source.fileName,
              sourceGenerationId:
                provenance.effectiveRequest.source.sourceGenerationId,
            }
          : undefined,
      });

      try {
        const res = await uploadAsync(form);
        const submitProgress = res.progress;
        setGenerations((prev) =>
          prev.map((item) =>
            item.generationId === generationId
              ? {
                  ...item,
                  taskId: res.taskId,
                  status: "queued",
                  phase: submitProgress
                    ? progressLabel(submitProgress)
                    : "queued",
                  percent: progressPercent(submitProgress),
                  progress: submitProgress ?? null,
                }
              : item
          )
        );
      } catch (err) {
        const message = err instanceof Error ? err.message : String(err);
        setSubmitError(message);
        setGenerations((prev) =>
          prev.map((item) =>
            item.generationId === generationId
              ? { ...item, status: "failed", phase: "failed", detail: message }
              : item
          )
        );
      }
      return true;
    },
    [
      generationBlockedReason,
      imageHealthModel,
      imageHealthOnline,
      uploadAsync,
      setSubmitError,
      setGenerations,
    ]
  );

  const startImageGeneration = useCallback(
    async (snapshot: ImageGenerationInput) => {
      const target = snapshot.target;
      const disabledReason = imageTargetDisabledReason(target);
      if (disabledReason) {
        setSubmitError(disabledReason);
        return false;
      }
      if (snapshot.operation === "image-to-image" && !snapshot.source) {
        setSubmitError("load an image first");
        return false;
      }
      return submitImageGeneration({
        operation: snapshot.operation,
        prompt: snapshot.prompt,
        modelSnapshot: modelSnapshotForTarget(target),
        effectiveRequest: {
          kind: "image",
          operation: snapshot.operation,
          executionProfile: target.execution.id,
          controls: snapshot.controls,
          ...(snapshot.source
            ? {
                source: {
                  uri: snapshot.source.uri,
                  mimeType: snapshot.source.mimeType,
                  fileName: snapshot.source.fileName,
                  sourceGenerationId: snapshot.source.sourceGenerationId,
                },
              }
            : {}),
        },
      });
    },
    [setSubmitError, submitImageGeneration]
  );

  const submitVideoGeneration = useCallback(
    async (
      provenance: VideoGenerationProvenance,
      modelDisabledReason?: string | null
    ) => {
      if (generationBlockedReason) {
        setSubmitError(generationBlockedReason);
        return false;
      }
      const configId = videoProspectiveConfigIdSchema.safeParse(
        provenance.effectiveRequest.configId
      );
      const availability = configId.success
        ? videoSubmission?.[configId.data]
        : undefined;
      const reason = videoDisabledRuntimeReason(
        availability?.state === "available" ? null : availability?.reason,
        modelDisabledReason
      );
      const generationId = newLocalId("video");
      const generation = {
        ...provenance,
        generationId,
        outputKind: "video",
        status: "uploading",
        phase: "submitting",
        detail: null,
        disabledReason: null,
        createdAt: Date.now(),
      } satisfies VideoGenerationView;
      setSubmitError(null);
      setGenerations((prev) => [...prev, generation]);
      try {
        const res = await videoSubmitAsync(
          COMPOSER_CAPABILITY_TABLE.video.draftToRequestBody({
            kind: "video",
            model: provenance.modelSnapshot.id,
            configId: provenance.effectiveRequest.configId,
            task: provenance.effectiveRequest.task,
            prompt: provenance.prompt,
          })
        );
        const nextStatus = mediaTaskStatus(res);
        const detail =
          mediaTaskDetail(res) ?? (nextStatus === "disabled" ? reason : null);
        setGenerations((prev) =>
          prev.map((item) =>
            item.generationId === generationId
              ? {
                  ...item,
                  taskId: res.taskId,
                  status: nextStatus,
                  phase: mediaTaskPhase(res),
                  percent: mediaTaskPercent(res),
                  progress: res.progress ?? null,
                  detail,
                  resultUrl: mediaTaskResultUrl(res),
                  disabledReason: nextStatus === "disabled" ? detail : null,
                }
              : item
          )
        );
        if (nextStatus === "disabled") {
          logModelDiagnostic(
            provenance.modelSnapshot.id,
            "video",
            "error",
            "video runtime unavailable; metadata retained",
            detail
          );
        }
        return true;
      } catch (err) {
        const message = err instanceof Error ? err.message : String(err);
        setSubmitError(message);
        setGenerations((prev) =>
          prev.map((item) =>
            item.generationId === generationId
              ? { ...item, status: "failed", phase: "failed", detail: message }
              : item
          )
        );
        return true;
      }
    },
    [
      generationBlockedReason,
      setGenerations,
      setSubmitError,
      videoSubmission,
      videoSubmitAsync,
    ]
  );

  const startVideoGeneration = useCallback(
    async (snapshot: { prompt: string; target: VideoModelTarget }) => {
      const { target } = snapshot;
      const config = target.execution;
      return submitVideoGeneration(
        {
          operation: "text-to-video",
          prompt: snapshot.prompt,
          modelSnapshot: modelSnapshotForTarget(target),
          effectiveRequest: {
            kind: "video",
            operation: "text-to-video",
            configId: config.id,
            configTitle: config.title,
            runtime: config.execution.runtime,
            runtimeStatus: config.runtimeStatus,
            downloadPolicy: config.downloadPolicy,
            task: config.generation.task,
            resolution: videoResolutionLabel(config),
            frames: config.generation.frames,
            fps: config.generation.fps,
            steps: config.generation.steps,
            guidance: config.generation.guidance,
            seed: config.generation.seed,
            parallelism: config.execution.parallelism,
            gpuCount: config.execution.gpuCount,
            defaultEligible: config.defaultEligible,
          },
        },
        target.disabledReason
      );
    },
    [submitVideoGeneration]
  );

  const handleCancelImageTask = useCallback(
    (generation: ImageGenerationView) => {
      const taskId = generation.taskId;
      if (!taskId) return;
      void (async () => {
        try {
          await cancelImageTaskAsync(taskId);
          setSubmitError(null);
          setGenerations((prev) =>
            prev.map((item) =>
              item.generationId === generation.generationId
                ? { ...item, status: "canceled", phase: "canceled" }
                : item
            )
          );
          await queryClient.invalidateQueries({
            queryKey: ["image-task", baseURL, taskId],
          });
        } catch (err) {
          setSubmitError(err instanceof Error ? err.message : String(err));
        }
      })();
    },
    [baseURL, cancelImageTaskAsync, queryClient, setGenerations, setSubmitError]
  );

  const handleRetryGeneration = useCallback(
    (generation: GenerationView) => {
      hapticTick("light");
      const row: ComposerCapabilityRow =
        COMPOSER_CAPABILITY_TABLE[generation.outputKind];
      switch (row.generation) {
        case "image-upload":
          if (generation.outputKind === "image") {
            void submitImageGeneration(generation);
          }
          return;
        case "video-task":
          if (generation.outputKind === "video") {
            void submitVideoGeneration(generation, generation.disabledReason);
          }
          return;
        case "chat-stream":
        case null:
          return;
        default: {
          const exhaustive: never = row.generation;
          return exhaustive;
        }
      }
    },
    [submitImageGeneration, submitVideoGeneration]
  );

  const handleRefineGeneration = useCallback(
    (generation: ImageGenerationView) => {
      const source = refinementSourceFromGeneration(generation);
      if (!source) return;
      hapticTick("medium");
      setPicked(source);
      if (mode !== "edit") {
        const target = requireModelTargetById(models, "image-edit");
        if (target.kind !== "image") {
          throw new Error("Image edit target is not an image model.");
        }
        void selectModel(target);
      }
      composerRef.current?.seedDraft("Refine this image: ", {
        onlyIfEmpty: true,
        focus: true,
      });
      composerRef.current?.expand();
    },
    [composerRef, mode, models, selectModel, setPicked]
  );

  const handleGenerationAction = useCallback(
    (id: string, kind: GenerationActionKind) => {
      const generation = generationsRef.current.find(
        (item) => item.generationId === id
      );
      if (!generation) return;
      if (kind === "cancel") {
        const row: ComposerCapabilityRow =
          COMPOSER_CAPABILITY_TABLE[generation.outputKind];
        switch (row.generation) {
          case "video-task":
            setGenerations((prev) =>
              prev.map((item) =>
                item.generationId === id
                  ? { ...item, status: "canceled", phase: "canceled" }
                  : item
              )
            );
            return;
          case "image-upload":
            if (generation.outputKind === "image") {
              handleCancelImageTask(generation);
            }
            return;
          case "chat-stream":
          case null:
            return;
          default: {
            const exhaustive: never = row.generation;
            return exhaustive;
          }
        }
      }
      if (kind === "retry") {
        handleRetryGeneration(generation);
        return;
      }
      if (kind === "refine" && generation.outputKind === "image") {
        handleRefineGeneration(generation);
      }
    },
    [
      handleCancelImageTask,
      handleRefineGeneration,
      handleRetryGeneration,
      setGenerations,
    ]
  );

  const generationTimelineEntries = useMemo(() => {
    const timeline = generations.map((generation, index) => {
      const terminal = isGenerationTerminalStatus(generation.status);
      const position: TimelinePosition =
        generation.sequence === undefined
          ? { kind: "timestamp", value: generation.createdAt }
          : { kind: "sequence", value: generation.sequence };
      if (generation.outputKind === "video") {
        const request = generation.effectiveRequest;
        return {
          position,
          index,
          item: {
            kind: "generation",
            id: generation.generationId,
            taskId: generation.taskId,
            outputKind: "video",
            name: generation.name,
            prompt: generation.prompt,
            modelTitle: generation.modelSnapshot.name,
            status: generation.status,
            phase: generation.phase,
            percent: generation.percent,
            progress: generation.progress,
            detail: generation.detail,
            resultUrl: generation.resultUrl,
            sourceLabel: null,
            isTerminal: terminal,
            isSucceeded: generation.status === "succeeded",
            isCanceled: generation.status === "canceled",
            canCancel: !terminal && generation.status !== "disabled",
            canRetry: terminal,
            videoConfigId: request.configId,
            videoConfigTitle: request.configTitle,
            videoRuntime: request.runtime,
            videoRuntimeStatus: request.runtimeStatus,
            videoDownloadPolicy: request.downloadPolicy,
            videoTask: request.task,
            videoResolution: request.resolution,
            videoFrames: request.frames,
            videoFps: request.fps,
            videoSteps: request.steps,
            videoGuidance: request.guidance,
            videoSeed: request.seed,
            videoParallelism: request.parallelism,
            videoGpuCount: request.gpuCount,
            videoDefaultEligible: request.defaultEligible,
            disabledReason: generation.disabledReason,
          },
        } satisfies ChatTimelineEntry;
      }
      if (generation.outputKind === "asset") {
        return {
          position,
          index,
          item: {
            kind: "generation",
            id: generation.generationId,
            taskId: generation.taskId,
            outputKind: "asset",
            name: generation.name,
            prompt: generation.prompt,
            modelTitle: generation.modelSnapshot.name,
            status: generation.status,
            phase: generation.phase,
            percent: generation.percent,
            progress: generation.progress,
            detail: generation.detail,
            resultUrl: generation.resultUrl,
            sourceLabel: generation.effectiveRequest.source.fileName,
            isTerminal: terminal,
            isSucceeded: generation.status === "succeeded",
            isCanceled: generation.status === "canceled",
            canCancel: false,
            canRetry: false,
          },
        } satisfies ChatTimelineEntry;
      }
      const request = generation.effectiveRequest;
      return {
        position,
        index,
        item: {
          kind: "generation",
          id: generation.generationId,
          taskId: generation.taskId,
          outputKind: "image",
          name: generation.name,
          prompt: generation.prompt,
          modelTitle: generation.modelSnapshot.name,
          status: generation.status,
          phase: generation.phase,
          percent: generation.percent,
          progress: generation.progress,
          detail: generation.detail,
          resultUrl: generation.resultUrl,
          sourceLabel: request.source?.sourceGenerationId
            ? "generated image"
            : request.source?.fileName,
          isTerminal: terminal,
          isSucceeded: generation.status === "succeeded",
          isCanceled: generation.status === "canceled",
          canCancel: Boolean(generation.taskId) && !terminal,
          canRetry: terminal,
          canRefine:
            generation.status === "succeeded" && Boolean(generation.resultUrl),
        },
      } satisfies ChatTimelineEntry;
    });
    return sortedTimelineEntries(timeline);
  }, [generations]);

  return {
    generations,
    setGenerations,
    generationsRef,
    generationTimelineEntries,
    handleGenerationAction,
    startImageGeneration,
    startVideoGeneration,
    upload,
    videoSubmit,
  };
}

import { useCallback, useEffect, useRef, type RefObject } from "react";
import { AppState } from "react-native";
import type { ConversationId } from "@homer/shared/conversation-id";
import type { TimelineMessage } from "@/lib/chat-message-meta";
import type { SaveConversationTimeline } from "@/screens/conversation-concern-contracts";
import { deferSave } from "./timeline-save-scheduler";
import type { GenerationView } from "./types";

type PendingSave = {
  save: SaveConversationTimeline;
  conversationId: ConversationId;
  messages: TimelineMessage[];
  generations: GenerationView[];
  onError(message: string): void;
};

export type ChatTimelineWriter = {
  saveTimeline: (
    conversationId: ConversationId,
    messages: TimelineMessage[],
    generations: GenerationView[]
  ) => Promise<void>;
  scheduleSave(
    messages: TimelineMessage[],
    generations: GenerationView[]
  ): void;
  flushSave(): void;
};

type UseChatTimelineWriterParams = {
  saveTimeline: SaveConversationTimeline;
  conversationId: ConversationId;
  onError(message: string): void;
};

type UseChatTimelinePersistenceParams = {
  enabled?: boolean;
  messagesRef: RefObject<TimelineMessage[]>;
  generations: GenerationView[];
  generationsRef: RefObject<GenerationView[]>;
  scheduleSave: ChatTimelineWriter["scheduleSave"];
  conversationId: ConversationId;
  historyHydrating: boolean;
  completionRevision: number;
};

/**
 * Every timeline write for a conversation runs through one ordered chain, so a
 * save already awaiting its mutation can never land after a newer snapshot and
 * resurrect what that snapshot removed. Direct writes (delete, undo, clear)
 * additionally drop the deferred snapshot they supersede.
 */
export function useChatTimelineWriter({
  saveTimeline,
  conversationId,
  onError,
}: UseChatTimelineWriterParams): ChatTimelineWriter {
  const pendingSaveRef = useRef<PendingSave | null>(null);
  const cancelDeferredSaveRef = useRef<(() => void) | null>(null);
  const writeChainRef = useRef<Promise<void>>(Promise.resolve());

  const takePendingSave = useCallback(() => {
    cancelDeferredSaveRef.current?.();
    cancelDeferredSaveRef.current = null;
    const pending = pendingSaveRef.current;
    pendingSaveRef.current = null;
    return pending;
  }, []);

  const enqueueSave = useCallback((pending: PendingSave) => {
    const write = writeChainRef.current.then(() =>
      pending.save(
        pending.conversationId,
        pending.messages,
        pending.generations
      )
    );
    writeChainRef.current = write.catch(() => undefined);
    return write;
  }, []);

  const flushSave = useCallback(() => {
    const pending = takePendingSave();
    if (!pending) return;
    void enqueueSave(pending).catch((cause) => {
      pending.onError(cause instanceof Error ? cause.message : String(cause));
    });
  }, [enqueueSave, takePendingSave]);

  const scheduleSave = useCallback(
    (nextMessages: TimelineMessage[], nextGenerations: GenerationView[]) => {
      pendingSaveRef.current = {
        save: saveTimeline,
        conversationId,
        messages: nextMessages,
        generations: nextGenerations,
        onError,
      };
      if (cancelDeferredSaveRef.current) return;
      cancelDeferredSaveRef.current = deferSave(flushSave);
    },
    [conversationId, flushSave, onError, saveTimeline]
  );

  const saveTimelineNow = useCallback(
    async (
      targetConversationId: ConversationId,
      nextMessages: TimelineMessage[],
      nextGenerations: GenerationView[]
    ) => {
      takePendingSave();
      await enqueueSave({
        save: saveTimeline,
        conversationId: targetConversationId,
        messages: nextMessages,
        generations: nextGenerations,
        onError,
      });
    },
    [enqueueSave, onError, saveTimeline, takePendingSave]
  );

  useEffect(() => {
    const subscription = AppState.addEventListener("change", (state) => {
      if (state !== "active") flushSave();
    });
    return () => subscription.remove();
  }, [flushSave]);

  useEffect(() => () => flushSave(), [conversationId, flushSave]);

  return { saveTimeline: saveTimelineNow, scheduleSave, flushSave };
}

export function useChatTimelinePersistence({
  enabled = true,
  messagesRef,
  generations,
  generationsRef,
  scheduleSave,
  conversationId,
  historyHydrating,
  completionRevision,
}: UseChatTimelinePersistenceParams): void {
  const lastCompletionRevisionRef = useRef(completionRevision);
  const lastPersistedGenerationSignatureRef = useRef("");

  useEffect(() => {
    lastPersistedGenerationSignatureRef.current = "";
  }, [conversationId]);

  useEffect(() => {
    if (!enabled) return;
    if (
      historyHydrating ||
      lastCompletionRevisionRef.current === completionRevision
    ) {
      return;
    }
    const currentMessages = messagesRef.current;
    if (currentMessages.length === 0) return;
    lastCompletionRevisionRef.current = completionRevision;
    scheduleSave(currentMessages, generationsRef.current);
  }, [
    completionRevision,
    enabled,
    historyHydrating,
    generationsRef,
    messagesRef,
    scheduleSave,
  ]);

  useEffect(() => {
    const signature = generations
      .map(
        (generation) =>
          `${generation.generationId}:${generation.status}:${generation.resultUrl ?? ""}`
      )
      .join("|");
    if (!enabled || historyHydrating) {
      lastPersistedGenerationSignatureRef.current = signature;
      return;
    }
    if (signature === lastPersistedGenerationSignatureRef.current) return;
    lastPersistedGenerationSignatureRef.current = signature;
    scheduleSave(messagesRef.current, generations);
  }, [enabled, historyHydrating, generations, messagesRef, scheduleSave]);
}

// @vitest-environment happy-dom

import { cleanup, renderHook } from "@testing-library/react";
import type { Dispatch, SetStateAction } from "react";
import { afterEach, describe, expect, it, vi } from "vitest";
import {
  persistedConversationMessages,
  persistedUiMessages,
} from "../../../lib/__fixtures__/persisted-conversation-messages";
import {
  readTimelineEntryMetadata,
  serializeTimelineMessage,
  type TimelineMessage,
  withTimelineMetadata,
} from "../../../lib/chat-message-meta";
import type {
  ConversationMessage,
  ThreadRows,
} from "../../../lib/conversation-convex-types";
import { useConversationTimelineHydration } from "./use-conversation-timeline-hydration";

type UseConversationTimelineHydrationParams = Parameters<
  typeof useConversationTimelineHydration
>[0];

afterEach(cleanup);

function conversationRows(
  messages: readonly ConversationMessage[]
): ThreadRows {
  return messages.map((message) => ({
    kind: "message",
    source: { kind: "conversation" },
    message,
  }));
}

describe("useConversationTimelineHydration", () => {
  it("hydrates a directly loaded conversation when its timeline arrives", () => {
    const conversationId = "5f3f6f1e-9f0c-4b1a-8a53-2f2f3f4c5d6e";
    let currentConversationId: string | null = null;
    const hydration = {
      begin: vi.fn((nextConversationId: string) => {
        const previousConversationId = currentConversationId;
        currentConversationId = nextConversationId;
        return previousConversationId;
      }),
      isCurrent: vi.fn(
        (candidateConversationId: string) =>
          candidateConversationId === currentConversationId
      ),
      complete: vi.fn(),
    };
    const setMessages = vi.fn();
    const setGenerations = vi.fn();
    const initialProps: UseConversationTimelineHydrationParams = {
      conversationId,
      rows: undefined,
      streaming: false,
      optimisticAgentTurnId: null,
      hydrating: true,
      hydration,
      setMessages,
      setGenerations,
    };
    const { rerender } = renderHook(
      (props: UseConversationTimelineHydrationParams) =>
        useConversationTimelineHydration(props),
      { initialProps }
    );

    expect(setMessages).not.toHaveBeenCalled();

    rerender({
      ...initialProps,
      rows: conversationRows(persistedConversationMessages),
    });

    const updateMessages = setMessages.mock.lastCall?.[0];
    const hydratedMessages =
      typeof updateMessages === "function"
        ? updateMessages([])
        : updateMessages;
    expect(hydratedMessages?.map(serializeTimelineMessage)).toEqual(
      persistedUiMessages
    );
    expect(readTimelineEntryMetadata(hydratedMessages?.[2])).toMatchObject({
      sequence: 2,
      cachedPromptTokens: 128,
      assistantName: "Fixture Chat Model",
    });
    expect(hydration.complete).toHaveBeenCalledWith(conversationId);
  });

  it("keeps applying Convex updates while preserving only the pending Machine submission", () => {
    const conversationId = "5f3f6f1e-9f0c-4b1a-8a53-2f2f3f4c5d6e";
    const turnId = "turn-pending";
    let currentConversationId: string | null = null;
    const hydration = {
      begin: vi.fn((nextConversationId: string) => {
        currentConversationId = nextConversationId;
        return null;
      }),
      isCurrent: vi.fn(
        (candidateConversationId: string) =>
          candidateConversationId === currentConversationId
      ),
      complete: vi.fn(),
    };
    let currentMessages: TimelineMessage[] = [
      withTimelineMetadata(
        {
          id: "optimistic-user",
          role: "user" as const,
          parts: [{ type: "text" as const, text: "Run the check" }],
        },
        { createdAt: 1, agentTurnId: turnId }
      ),
    ];
    const setMessages: Dispatch<SetStateAction<TimelineMessage[]>> = vi.fn(
      (update) => {
        currentMessages =
          typeof update === "function" ? update(currentMessages) : update;
      }
    );
    const setGenerations = vi.fn();
    const initialProps: UseConversationTimelineHydrationParams = {
      conversationId,
      rows: [],
      streaming: false,
      optimisticAgentTurnId: turnId,
      hydrating: false,
      hydration,
      setMessages,
      setGenerations,
    };

    const { rerender } = renderHook(
      (props: UseConversationTimelineHydrationParams) =>
        useConversationTimelineHydration(props),
      { initialProps }
    );

    expect(currentMessages.map((message) => message.id)).toEqual([
      "optimistic-user",
    ]);

    rerender({
      ...initialProps,
      rows: conversationRows(persistedConversationMessages),
    });

    expect(currentMessages.map((message) => message.id)).toEqual([
      ...persistedUiMessages.map((message) => message.id),
      "optimistic-user",
    ]);

    rerender({
      ...initialProps,
      rows: [
        ...conversationRows(persistedConversationMessages),
        {
          kind: "message",
          source: {
            kind: "agent-turn",
            turnId,
            agentId: "agent-codex",
            status: "running",
          },
          message: {
            messageId: `${turnId}-user`,
            role: "user",
            parts: [{ type: "text", text: "Run the check" }],
            createdAt: 2,
            sequence: 3,
          },
        },
      ],
    });

    expect(currentMessages.map((message) => message.id)).toEqual([
      ...persistedUiMessages.map((message) => message.id),
      `${turnId}-user`,
    ]);
  });
});

