  VoiceConversationOrb,
  voiceConversationOrbStyles,
} from "@/components/chat/voice-conversation-orb";
import { VoiceOptionsCog } from "@/components/chat/voice-options-cog";
import type {
  VoiceSessionLiveRuntime,
  VoiceSessionRuntime,
} from "./use-voice-session";

type VoiceConversationOverlayProps = {
  runtime: VoiceSessionRuntime;
  onEnd(): void | Promise<void>;
};

const visibleStates = new Set<VoiceSessionState>([
  "starting",
  "listening",
  "processing",
  "speaking",
]);
const recordingRed = "#FF3B30";
const markdownMarkerPattern = /[*_`#>]/g;
const bulletPattern = /^\s*[-*+]\s+/gm;

function isVoiceConversationVisible(runtime: VoiceSessionRuntime): boolean {
  return visibleStates.has(runtime.kind);
}

function isLiveRuntime(
  runtime: VoiceSessionRuntime
): runtime is VoiceSessionLiveRuntime {
  return (
    runtime.kind === "listening" ||
    runtime.kind === "processing" ||
    runtime.kind === "speaking"
  );
}

function visibleRuntimeFieldsEqual(
  previous: VoiceSessionRuntime,
  next: VoiceSessionRuntime
): boolean {
  if (previous.kind !== next.kind) return false;
  if (previous.kind === "starting") {
    return (
      next.kind === "starting" &&
      previous.startedAtMs === next.startedAtMs &&
      previous.turns === next.turns
    );
  }
  if (isLiveRuntime(previous)) {
    return (
      isLiveRuntime(next) &&
      previous.startedAtMs === next.startedAtMs &&
      previous.turns === next.turns &&
      previous.session === next.session
    );
  }
  return true;
}

function voiceDisplayText(text: string, maxLength: number): string {
  const normalized = text
    .replace(bulletPattern, "")
    .replace(markdownMarkerPattern, "")
    .replace(/\s+/g, " ")
    .trim();
  if (normalized.length <= maxLength) return normalized;
  return `${normalized.slice(0, maxLength - 1).trimEnd()}…`;
}

function VoiceConversationOverlayBase({
  runtime,
  onEnd,
}: VoiceConversationOverlayProps) {
  const insets = useSafeAreaInsets();
  const { width } = useWindowDimensions();
  const state = runtime.kind;
  const visible = isVoiceConversationVisible(runtime);
  const recording = state === "listening";
  const connected =
    state === "listening" || state === "processing" || state === "speaking";
  const session = isLiveRuntime(runtime) ? runtime.session : null;
  const amplitude = useVoiceConversationAudio(
    state,
    session?.watchAudioLevel,
    session?.getAudioLevel
  );
  const orbSize = Math.min(width * 0.58, 280);
  const turns = useMemo(() => {
    if (!visible) return [];
    if (
      runtime.kind === "idle" ||
      runtime.kind === "error" ||
      runtime.kind === "unavailable"
    ) {
      return [];
    }
    const limit = width >= 768 ? 4 : 3;
    return runtime.turns.slice(-limit);
  }, [runtime, visible, width]);
  const stateLine =
    state === "starting"
      ? "connecting"
      : state === "listening"
        ? "listening"
        : state === "processing"
          ? "processing"
          : "speaking";
  const micIconColor = recording ? "#05070A" : "rgba(255,255,255,0.42)";
  const micBackgroundColor = recording ? "#FFFFFF" : "rgba(255,255,255,0.06)";
  const micBorderColor = recording
    ? "rgba(255,255,255,0)"
    : "rgba(255,255,255,0.14)";
  const handleEndPress = useCallback(() => {
    hapticTick(connected ? "medium" : "light");
