      <View className="w-full max-w-[720px] flex-1 self-center">
        <View className="flex-row items-center justify-between">
          <Touchable
            feedback="subtle"
            testID="homer-voice-conversation-end"
            accessibilityRole="button"
            accessibilityLabel={
              connected ? "end voice conversation" : "cancel voice conversation"
            }
            onPress={handleEndPress}
            hitSlop={12}
            className="h-11 w-11 items-center justify-center"
          >
            <Icon name="xmark" size={22} color="rgba(255,255,255,0.88)" />
          </Touchable>
          <View className="min-w-0 flex-1 items-center px-3">
            <Text
              className="text-[12px] uppercase"
              style={{
                color: "rgba(255,255,255,0.46)",
                fontFamily: "GeistMono_500Medium",
                letterSpacing: 0,
              }}
              numberOfLines={1}
              ellipsizeMode="tail"
            >
              Voice
            </Text>
          </View>
          <VoiceOptionsCog />
        </View>

        <View className="items-center pt-4 pb-2">
          <View
            accessibilityElementsHidden
            style={[
              voiceConversationOrbStyles.shell,
              {
                width: orbSize,
                height: orbSize,
                borderRadius: orbSize / 2,
              },
            ]}
          >
            <VoiceConversationOrb amplitude={amplitude} size={orbSize} />
          </View>
          <Text
            accessibilityLiveRegion="polite"
            role="status"
            className="mt-4 text-center text-[12px] uppercase"
            style={{
              color: recording ? recordingRed : "rgba(255,255,255,0.52)",
              fontFamily: "GeistMono_500Medium",
              letterSpacing: 0,
            }}
          >
            {stateLine}
          </Text>
        </View>

        <View className="flex-1 justify-end pb-4">
          <ScrollView
