                        style={{
                          borderCurve: "continuous",
                          backgroundColor: "rgba(255,255,255,0.10)",
                        }}
                      >
                        <Text
                          selectable
                          className="text-[16px] text-white"
                          style={{
                            fontFamily: "Geist_500Medium",
                            letterSpacing: 0,
                            lineHeight: 22,
                          }}
                        >
                          {voiceDisplayText(turn.text, latest ? 220 : 140)}
                        </Text>
                      </View>
                    </View>
                  );
                }
                return (
                  <View key={turn.id} className="items-start px-1">
                    <Text
                      selectable
                      className={
                        latest
                          ? "max-w-[94%] text-[17px] text-white"
                          : "max-w-[90%] text-[14px]"
                      }
                      style={{
                        color: latest ? "#FFFFFF" : "rgba(255,255,255,0.64)",
                        fontFamily: "Geist_500Medium",
                        letterSpacing: 0,
                        lineHeight: latest ? 24 : 20,
                      }}
                    >
                      {voiceDisplayText(turn.text, latest ? 320 : 180)}
                    </Text>
                  </View>
                );
              })
            )}
          </ScrollView>
        </View>

        <View className="items-center pt-2">
          <View
            testID="homer-voice-conversation-mic"
            accessible
            accessibilityLabel={
              recording ? "microphone active" : "microphone inactive"
            }
            className="h-14 w-14 items-center justify-center rounded-full border"
            style={{
              borderCurve: "continuous",
              backgroundColor: micBackgroundColor,
              borderColor: micBorderColor,
            }}
          >
            <Icon name="mic.fill" size={22} color={micIconColor} />
          </View>
        </View>
      </View>
    </View>
  );
}

export const VoiceConversationOverlay = memo(
  VoiceConversationOverlayBase,
  (previous, next) => {
    const previousVisible = isVoiceConversationVisible(previous.runtime);
    const nextVisible = isVoiceConversationVisible(next.runtime);
    if (!previousVisible && !nextVisible) return true;
    return (
      visibleRuntimeFieldsEqual(previous.runtime, next.runtime) &&
      previous.onEnd === next.onEnd
    );
  }
);
VoiceConversationOverlay.displayName = "VoiceConversationOverlay";

