function focusView(node: NativeView | null) {
  const focus = node?.focus;
  if (typeof focus === "function") focus.call(node);
  if (Platform.OS !== "web") focusAccessibilityTarget(node);
}

function useCompactNavigationFocusRestoration() {
  const triggerRef = useRef<NativeView>(null);
  const restoreAfterCloseRef = useRef(false);
  const setRestoreAfterClose = useCallback((restore: boolean) => {
    restoreAfterCloseRef.current = restore;
  }, []);
  const completeRestoreAfterClose = useCallback(() => {
    if (!restoreAfterCloseRef.current) return;
    restoreAfterCloseRef.current = false;
    focusView(triggerRef.current);
  }, []);

  return {
    triggerRef,
    setRestoreAfterClose,
    completeRestoreAfterClose,
  };
}

