export function ChatShell({ children }: ChatShellProps) {
  const { width } = useWindowDimensions();
  const pathname = usePathname();
  const { colors } = useThemeMode();
  const insets = useSafeAreaInsets();
  const persistent = !compactChatShellOwnsLeadingNavigation(width);
  const compactPanelWidth = Math.min(
    COMPACT_PANEL_MAX_WIDTH,
    Math.max(0, width - 56)
  );
  const [compactOpen, setCompactOpen] = useState(false);
  const panelOpen = persistent || compactOpen;
  const showWideConversationEmptyState =
    persistent && pathname === "/conversations";
  const progress = useSharedValue(0);
  const previousWidthRef = useRef(width);
  const pendingNavigationRef = useRef<(() => void) | null>(null);
  const { triggerRef, setRestoreAfterClose, completeRestoreAfterClose } =
    useCompactNavigationFocusRestoration();
  const initialFocusRef = useRef<NativeView>(null);
  const panelRef = useRef<NativeView>(null);

  const closeCompactNavigation = useCallback(() => {
    setRestoreAfterClose(true);
    setCompactOpen(false);
  }, [setRestoreAfterClose]);
  const closeFromSwipe = useCallback(() => {
    setRestoreAfterClose(true);
    setCompactOpen(false);
  }, [setRestoreAfterClose]);
  const swipeClosePanel = useMemo(
    () =>
      Gesture.Pan()
        .enabled(!persistent && compactOpen)
        .activeOffsetX(-12)
        .failOffsetX(12)
        .failOffsetY([-16, 16])
        .onUpdate((event) => {
          progress.set(
            Math.min(1, Math.max(0, 1 + event.translationX / compactPanelWidth))
          );
        })
        .onEnd((event) => {
          const shouldClose =
            event.translationX < -SWIPE_CLOSE_DISTANCE ||
            event.velocityX < SWIPE_CLOSE_VELOCITY;
          if (shouldClose) {
            scheduleOnRN(closeFromSwipe);
            return;
          }
          progress.set(
            withTiming(1, {
              duration: PANEL_MOTION_MS,
              easing: Easing.out(Easing.cubic),
              reduceMotion: ReduceMotion.System,
            })
          );
        }),
    [closeFromSwipe, compactOpen, compactPanelWidth, persistent, progress]
  );
  const toggleCompactNavigation = useCallback(() => {
    setRestoreAfterClose(compactOpen);
    setCompactOpen((open) => !open);
  }, [compactOpen, setRestoreAfterClose]);
  const finishPendingNavigation = useCallback(() => {
    const pendingNavigation = pendingNavigationRef.current;
    pendingNavigationRef.current = null;
    pendingNavigation?.();
  }, []);
  const navigate = useCallback(
    (afterClose: () => void) => {
      setRestoreAfterClose(false);
      if (persistent) {
        afterClose();
        return;
      }
      pendingNavigationRef.current = afterClose;
      setCompactOpen(false);
    },
    [persistent, setRestoreAfterClose]
  );
  useEffect(() => {
    if (previousWidthRef.current === width) return;
    previousWidthRef.current = width;
    setRestoreAfterClose(false);
    setCompactOpen(false);
  }, [setRestoreAfterClose, width]);

  useEffect(() => {
    progress.set(
      withTiming(
        compactOpen && !persistent ? 1 : 0,
        {
          duration: PANEL_MOTION_MS,
          easing: Easing.out(Easing.cubic),
          reduceMotion: ReduceMotion.System,
        },
        (finished) => {
          if (!finished) return;
          if (!compactOpen) {
            scheduleOnRN(finishPendingNavigation);
            scheduleOnRN(completeRestoreAfterClose);
          }
        }
      )
    );
  }, [
    compactOpen,
    completeRestoreAfterClose,
    finishPendingNavigation,
    persistent,
    progress,
  ]);

  useEffect(() => {
    if (Platform.OS === "web" || !compactOpen || persistent) return;
    const subscription = BackHandler.addEventListener(
      "hardwareBackPress",
      () => {
        closeCompactNavigation();
        return true;
      }
    );
    return () => subscription.remove();
  }, [closeCompactNavigation, compactOpen, persistent]);

  useEffect(() => {
    if (Platform.OS !== "web") return;
    const panel = panelRef.current;
    if (!(panel instanceof HTMLElement)) return;
    panel.inert = !persistent && !compactOpen;
  }, [compactOpen, persistent]);

  useEffect(() => {
    if (!compactOpen || persistent) return;
    focusView(initialFocusRef.current);
  }, [compactOpen, persistent]);

  useEffect(() => {
    if (Platform.OS !== "web" || !compactOpen || persistent) return;
    const closeOnEscape = (event: KeyboardEvent) => {
      if (event.key === "Escape") closeCompactNavigation();
    };
    document.addEventListener("keydown", closeOnEscape);
    return () => document.removeEventListener("keydown", closeOnEscape);
  }, [closeCompactNavigation, compactOpen, persistent]);

  const compactStackStyle = useAnimatedStyle(() => ({
    transform: [{ translateX: progress.value * compactPanelWidth }],
  }));
  const trigger = !persistent ? (
    <View style={styles.triggerOverlay} testID="chat-shell-trigger-overlay">
      <AdaptiveSurface
        material="chrome"
        interactive
        style={[
          styles.triggerSurface,
          {
            left: insets.left + CHAT_SHELL_TRIGGER_LEFT,
            top: insets.top + 4,
          },
        ]}
      >
        <NativeFloatingCTA
          ref={triggerRef}
          testID="chat-shell-toggle-navigation"
          accessibilityLabel={
            compactOpen ? "Close chat navigation" : "Open chat navigation"
          }
          accessibilityState={{ expanded: compactOpen }}
          contained
          iconName={compactOpen ? "xmark" : "line.3.horizontal"}
          iconColor={colors.text}
          tone="neutral"
          size={CHAT_SHELL_TRIGGER_SIZE}
          onPress={toggleCompactNavigation}
        />
      </AdaptiveSurface>
    </View>
  ) : null;

  return (
    <View
      style={[
        styles.compactShell,
        persistent ? styles.wideShell : null,
        { backgroundColor: colors.bg },
      ]}
    >
      <GestureDetector gesture={swipeClosePanel}>
        <View
          ref={panelRef}
          aria-hidden={!persistent && !compactOpen}
          accessibilityElementsHidden={!persistent && !compactOpen}
          importantForAccessibility={
            !persistent && !compactOpen ? "no-hide-descendants" : "auto"
          }
          style={[
            persistent ? null : styles.compactPanelSlot,
            {
              pointerEvents: persistent || compactOpen ? "auto" : "none",
              width: persistent ? WIDE_PANEL_WIDTH : compactPanelWidth,
              zIndex: persistent || compactOpen ? 1 : 0,
            },
          ]}
          testID="chat-shell-panel-slot"
        >
          <ChatNavigationPanel
            compact={!persistent}
            contentInsets={
              persistent
                ? insets
                : {
                    bottom: insets.bottom,
                    left: insets.left,
                    top: insets.top + 64,
                  }
            }
            enabled={panelOpen}
            initialFocusRef={initialFocusRef}
            onClose={closeCompactNavigation}
            onNavigate={navigate}
          />
        </View>
      </GestureDetector>

      <Animated.View
        style={[styles.stack, compactStackStyle]}
        testID="chat-shell-stack"
      >
        <ChatShellCompactOpenProvider open={!persistent && compactOpen}>
          <View
            aria-hidden={showWideConversationEmptyState}
            accessibilityElementsHidden={showWideConversationEmptyState}
            importantForAccessibility={
              showWideConversationEmptyState ? "no-hide-descendants" : "auto"
            }
            pointerEvents={showWideConversationEmptyState ? "none" : "auto"}
            style={styles.stackContent}
          >
            {children}
          </View>
          {showWideConversationEmptyState ? (
            <View
              style={[
                styles.wideConversationEmptyState,
                { backgroundColor: colors.bg },
              ]}
            >
              <ConversationRouteState
                title="No chat selected"
                body="Select a chat from the sidebar to open it."
              />
            </View>
          ) : null}
        </ChatShellCompactOpenProvider>
      </Animated.View>

      {trigger}

      {MOTION_METRICS_ENABLED ? (
        <ChatShellMotionMetrics
          panelMotionMs={PANEL_MOTION_MS}
          progress={progress}
        />
      ) : null}
    </View>
  );
}

