type ProjectCreationControlProps = {
  machines: MachineList | undefined;
  onNavigate(afterClose: () => void): void;
  variant?: "header" | "text";
};

const styles = StyleSheet.create({
  iconBox: {
    alignItems: "center",
    height: SIDEBAR_PROJECT_ADD_ICON_BOX_PX,
    justifyContent: "center",
    width: SIDEBAR_PROJECT_ADD_ICON_BOX_PX,
  },
  textRow: {
    height: SIDEBAR_PROJECT_ADD_ICON_BOX_PX,
    paddingLeft: SIDEBAR_SECTION_LABEL_INSET_PX,
  },
});

export function ProjectCreationControl({
  machines,
  onNavigate,
  variant = "header",
}: ProjectCreationControlProps) {
  const router = useRouter();
  const { colors } = useThemeMode();
  const createProject = useMutation(api.machineProjects.create);
  const rootRef = useRef<ComponentRef<typeof NativeView>>(null);
  const [open, setOpen] = useState(false);
  const [hovered, setHovered] = useState(false);
  const [focused, setFocused] = useState(false);
  const [cwd, setCwd] = useState("");
  const [selectedMachineId, setSelectedMachineId] = useState<string | null>(
    null
  );
  const [creating, setCreating] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const readyMachines = useMemo(
    () =>
      machines?.machines.filter((machine) => machine.access.status === "ready"),
    [machines]
  );
  const selectedMachine =
    readyMachines?.find((machine) => machine.id === selectedMachineId) ??
    readyMachines?.[0] ??
    null;
  const showTrigger =
    variant === "text" || Platform.OS !== "web" || hovered || focused || open;
  const triggerAccessibilityLabel =
    variant === "header"
      ? "Add project from Projects header"
      : "Add first project";

  const close = useCallback(() => {
    setOpen(false);
    setError(null);
  }, []);

  useDismissableDesktopPopover({
    open,
    enabled: Platform.OS === "web",
    rootRef,
    onDismiss: close,
  });

  const openCreation = () => {
    if (readyMachines === undefined) return;
    if (readyMachines.length === 0) {
      onNavigate(() => router.navigate(connectMachineHref()));
      return;
    }
    setError(null);
    setOpen(true);
  };

  const submit = () => {
    const directory = cwd;
    if (creating || !selectedMachine || !directory.trim()) return;
    setCreating(true);
    setError(null);
    void createProject({ cwd: directory, machineId: selectedMachine.id })
      .then(() => {
        setCreating(false);
        setCwd("");
        close();
      })
      .catch((cause: unknown) => {
        setCreating(false);
        setError(cause instanceof Error ? cause.message : String(cause));
      });
  };

  return (
    <View
      ref={rootRef}
      className="relative shrink-0"
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => setHovered(false)}
    >
      <Touchable
        feedback="subtle"
        testID={`homer-project-add-${variant}`}
        accessibilityRole="button"
        accessibilityLabel={triggerAccessibilityLabel}
        accessibilityHint={
          readyMachines?.length === 0 ? "A Machine is needed first" : undefined
        }
        accessibilityState={{ expanded: open }}
        onFocus={() => setFocused(true)}
        onBlur={() => setFocused(false)}
        onHoverIn={() => setHovered(true)}
        onHoverOut={() => setHovered(false)}
        onPress={openCreation}
        hitSlop={
          variant === "header"
            ? getHitSlopForVisualSize(SIDEBAR_PROJECT_ADD_ICON_BOX_PX)
            : 8
        }
        className={
          variant === "header"
            ? undefined
            : "w-full flex-row items-center justify-between rounded-lg"
        }
        style={[
          variant === "header" ? styles.iconBox : styles.textRow,
          { opacity: showTrigger ? 1 : 0 },
        ]}
      >
        {variant === "header" ? (
          <Icon
            name="plus"
            size={SIDEBAR_PROJECT_ADD_ICON_PX}
            color={hovered ? colors.text2 : colors.muted}
          />
        ) : (
          <>
            <Text className="text-[12px] text-mb-muted">Add project</Text>
            <View style={styles.iconBox}>
              <Icon
                name="plus"
                size={SIDEBAR_PROJECT_ADD_ICON_PX}
                color={colors.muted}
              />
            </View>
          </>
        )}
      </Touchable>

      {open && readyMachines ? (
        <SelectorPopoverFrame
          testID={`homer-project-add-${variant}-popover`}
          accessibilityRole="summary"
          accessibilityLabel="Add project"
          accessibilityViewIsModal
          importantForAccessibility="yes"
          material="chrome"
          className="absolute right-0 top-full z-50 mt-1.5 w-[240px] gap-3 rounded-xl border border-mb-border-strong bg-mb-input p-3"
          style={{
            borderCurve: "continuous",
            boxShadow: `0 18px 40px ${colors.bg}`,
          }}
        >
          {readyMachines.length === 0 ? (
            <View className="gap-2">
              <Text
                className="text-[13px] text-mb-text"
                style={{ fontFamily: "Geist_600SemiBold" }}
              >
                A Machine is needed first.
              </Text>
              <Text className="text-[12px] text-mb-muted">
                Connect a Machine before adding a project directory.
              </Text>
              <Touchable
                feedback="highlight"
                testID="homer-project-connect-machine"
                accessibilityRole="button"
                accessibilityLabel="Connect a Machine"
                onPress={() => {
                  close();
                  onNavigate(() => router.navigate(connectMachineHref()));
                }}
                className="min-h-9 self-start justify-center rounded-lg bg-mb-text px-3"
              >
                <Text className="text-[12px] text-mb-bg">
                  Connect a Machine
                </Text>
              </Touchable>
            </View>
          ) : (
            <View className="gap-2">
              <View className="flex-row items-center gap-2">
                <View className="min-w-0 flex-1">
                  <Text
                    className="text-[13px] text-mb-text"
                    style={{ fontFamily: "Geist_600SemiBold" }}
                  >
                    Add project
                  </Text>
                  <Text className="text-[11px] text-mb-muted">
                    Save a Machine directory to the rail. Its name comes from
                    the canonical directory.
                  </Text>
                </View>
                <Touchable
                  feedback="subtle"
                  accessibilityRole="button"
                  accessibilityLabel="Close add project"
                  onPress={close}
                  className="h-7 w-7 items-center justify-center rounded-lg"
                >
                  <Icon name="xmark" size={14} color={colors.muted} />
                </Touchable>
              </View>

              <TextInput
                accessibilityLabel="Project directory"
                autoCapitalize="none"
                autoCorrect={false}
                onChangeText={setCwd}
                onSubmitEditing={submit}
                placeholder="/path/to/project"
                placeholderTextColor={colors.muted}
                value={cwd}
                className="min-h-10 rounded-lg border border-mb-border-strong bg-mb-surface px-2.5 text-[12px] text-mb-text"
              />

              <Text
                className="pt-1 text-[10px] uppercase text-mb-muted"
                style={{
                  fontFamily: "GeistMono_600SemiBold",
                  letterSpacing: 0.7,
                }}
              >
                Machine
              </Text>
              <View className="gap-1">
                {readyMachines.map((machine) => (
                  <Touchable
                    key={machine.id}
                    feedback="subtle"
                    accessibilityRole="radio"
                    accessibilityLabel={`Use ${machine.name}`}
                    accessibilityState={{
                      selected: selectedMachine?.id === machine.id,
                    }}
                    onPress={() => setSelectedMachineId(machine.id)}
                    className="min-h-8 flex-row items-center gap-2 rounded-lg px-2"
                  >
                    <View
                      className={`h-2 w-2 rounded-full ${selectedMachine?.id === machine.id ? "bg-mb-accent" : "bg-mb-muted"}`}
                    />
                    <Text className="text-[12px] text-mb-text">
                      {machine.name}
                    </Text>
                  </Touchable>
                ))}
              </View>
              {error ? (
                <Text
                  accessibilityLiveRegion="polite"
                  testID="homer-project-create-error"
                  className="text-[11px] text-mb-danger"
                >
                  {error}
                </Text>
              ) : null}
              <Touchable
                feedback="highlight"
                testID="homer-project-create-submit"
                accessibilityRole="button"
                accessibilityLabel="Create project"
                accessibilityState={{
                  disabled: creating || !cwd.trim(),
                }}
                disabled={creating || !cwd.trim()}
                onPress={submit}
                className="min-h-9 items-center justify-center rounded-lg bg-mb-text px-3"
              >
                <Text className="text-[12px] text-mb-bg">
                  {creating ? "Creating…" : "Create project"}
                </Text>
              </Touchable>
            </View>
          )}
        </SelectorPopoverFrame>
      ) : null}
    </View>
  );
}

import { useCallback, useEffect, useState } from "react";
import { getItem, setItem } from "@/lib/storage";

export const PROJECT_CONNECTION_COLORS = [
  "blue",
  "green",
  "orange",
  "purple",
  "red",
] as const;

export type ProjectConnectionColor = (typeof PROJECT_CONNECTION_COLORS)[number];

export const PROJECT_CONNECTION_COLOR_VALUES = {
  blue: "#5d86d8",
  green: "#4fb477",
  orange: "#d99442",
  purple: "#9a78d6",
  red: "#d46c71",
} satisfies Record<ProjectConnectionColor, string>;

const PROJECT_CONNECTION_COLORS_KEY =
  "homer.project-sidebar.connection-colors.v1";

type PersistedProjectConnectionColors = Record<string, ProjectConnectionColor>;

function isProjectConnectionColor(
  value: unknown
): value is ProjectConnectionColor {
  return (
    typeof value === "string" &&
    (PROJECT_CONNECTION_COLORS as readonly string[]).includes(value)
  );
}

function parsePersistedColors(
  value: string | null
): PersistedProjectConnectionColors {
  if (!value) return {};
  try {
    const parsed: unknown = JSON.parse(value);
    if (
      typeof parsed !== "object" ||
      parsed === null ||
      Array.isArray(parsed)
    ) {
      return {};
    }
    return Object.fromEntries(
      Object.entries(parsed).filter(
        (entry): entry is [string, ProjectConnectionColor] =>
          isProjectConnectionColor(entry[1])
      )
    );
  } catch {
    return {};
  }
}

function projectConnectionColorKey(
  machineId: string,
  projectId: string
): string {
  return `${machineId}:${projectId}`;
}

export function useProjectConnectionColors() {
  const [colors, setColors] = useState<PersistedProjectConnectionColors>({});

  useEffect(() => {
    let mounted = true;
    void getItem(PROJECT_CONNECTION_COLORS_KEY).then((stored) => {
      if (mounted) setColors(parsePersistedColors(stored));
    });
    return () => {
      mounted = false;
    };
  }, []);

  const getProjectConnectionColor = useCallback(
    (machineId: string, projectId: string): ProjectConnectionColor =>
      colors[projectConnectionColorKey(machineId, projectId)] ?? "blue",
    [colors]
  );

  const setProjectConnectionColor = useCallback(
    (machineId: string, projectId: string, color: ProjectConnectionColor) => {
      setColors((current) => {
        const next = {
          ...current,
          [projectConnectionColorKey(machineId, projectId)]: color,
        };
        void setItem(PROJECT_CONNECTION_COLORS_KEY, JSON.stringify(next));
        return next;
      });
    },
    []
  );

  return {
    getProjectConnectionColor,
    setProjectConnectionColor,
  };
}

