function optionalGlobalRouteParam(
  value: string | string[] | undefined
): string | undefined {
  return typeof value === "string" && value.length > 0 ? value : undefined;
}

type ProjectConversationContext = {
  activeConversationId: string | undefined;
  displayName: string;
  machineName: string;
  projectId: MachineProject["projectId"];
};

type ProjectRowState = {
  active: boolean;
  expanded: boolean;
};

function isDesktopWeb() {
  return Platform.OS === "web";
}

function conversationRenameTitle(row: ConversationListRow): string | undefined {
  if (Platform.OS !== "web" || typeof window === "undefined") return undefined;
  const nextTitle = window.prompt("Rename conversation", row.title)?.trim();
  return nextTitle && nextTitle !== row.title ? nextTitle : undefined;
}

async function copyToClipboard(value: string) {
  if (typeof navigator === "undefined") return;
  if (typeof navigator.clipboard?.writeText === "function") {
    await navigator.clipboard.writeText(value);
  }
}

function shareConversation(row: ConversationListRow, projectId: string) {
  if (typeof navigator === "undefined") return;
  const url = conversationUrl(projectId, row.conversationId);
  if (typeof navigator.share === "function") {
    void navigator.share({ title: row.title, text: row.title, url });
    return;
  }
  void copyToClipboard(url);
}

function conversationUrl(projectId: string, conversationId: string) {
  const browserOrigin =
    typeof window === "undefined" ? undefined : window.location.origin;
  const hostedOrigin =
    webRuntimeEnvelope === "electron" || browserOrigin === undefined
      ? canonicalHostedOrigin()
      : browserOrigin;
  return buildConversationUrl({
    browserOrigin,
    conversationId,
    hostedOrigin,
    projectId,
    runtimeEnvelope: webRuntimeEnvelope,
  });
}

export function useProjectSidebar(enabled: boolean) {
  const routeParams = useGlobalSearchParams();
  const activeProjectId = optionalGlobalRouteParam(routeParams.projectId);
  const activeConversationId = optionalGlobalRouteParam(
    routeParams.conversationId
  );
  const projects = useQuery(
    api.machineProjects.listSidebar,
    enabled ? {} : "skip"
  );
  const machines = useQuery(api.machines.list, enabled ? {} : "skip");
  const dispatchConversation = useMutation(api.conversations.dispatch);
  const { getProjectConnectionColor, setProjectConnectionColor } =
    useProjectConnectionColors();
  const [expansionOverrides, setExpansionOverrides] = useState<
    ReadonlyMap<string, boolean>
  >(new Map());
  const isExpanded = useCallback(
    (projectId: string) => expansionOverrides.get(projectId) ?? false,
    [expansionOverrides]
  );
  const toggleExpanded = useCallback((projectId: string) => {
    setExpansionOverrides((current) => {
      const next = new Map(current);
      const expanded = current.get(projectId) ?? false;
      next.set(projectId, !expanded);
      return next;
    });
  }, []);
  const renameConversation = useCallback(
    (row: ConversationListRow) => {
      const title = conversationRenameTitle(row);
      if (!title) return;
      void dispatchConversation({
        conversationId: row.conversationId,
        change: { type: "conversation.rename", title },
      }).catch(() => undefined);
    },
    [dispatchConversation]
  );
  return {
    activeConversationId,
    activeProjectId,
    getProjectConnectionColor,
    isExpanded,
    machines,
    projects,
    renameConversation,
    setProjectConnectionColor,
    toggleExpanded,
  };
}
