function ThreadContextMenu({
  onClose,
  onRename,
  projectId,
  row,
}: {
  onClose: () => void;
  onRename(row: ConversationListRow): void;
  projectId: string;
  row: ConversationListRow;
}) {
  const [copyMenuOpen, setCopyMenuOpen] = useState(false);
  const [menuReady, setMenuReady] = useState(false);

  useEffect(() => {
    if (typeof document === "undefined") return;

    const closeOnEscape = (event: KeyboardEvent) => {
      if (event.key !== "Escape") return;
      event.preventDefault();
      if (copyMenuOpen) {
        setCopyMenuOpen(false);
      } else {
        onClose();
      }
    };

    document.addEventListener("keydown", closeOnEscape);
    return () => document.removeEventListener("keydown", closeOnEscape);
  }, [copyMenuOpen, onClose]);

  if (!isDesktopWeb()) return null;
  return (
    <View
      testID={`homer-thread-${row.conversationId}-menu`}
      accessibilityRole="menu"
      accessibilityLabel={`Thread actions for ${row.title}`}
      onLayout={() => setMenuReady(true)}
      pointerEvents={menuReady ? "auto" : "none"}
      className="absolute right-1 top-9 z-30 min-w-[194px] gap-0.5 rounded-xl border border-mb-border bg-mb-surface p-1.5"
      style={{
        opacity: menuReady ? 1 : 0,
        boxShadow: "0 8px 24px rgb(0 0 0 / 0.16), 0 2px 6px rgb(0 0 0 / 0.08)",
      }}
    >
      <ConversationMenuItem
        icon="pencil"
        label="Rename"
        onPress={() => {
          onRename(row);
          onClose();
        }}
      />
      <ConversationMenuItem
        icon="link"
        label="Share"
        onPress={() => {
          shareConversation(row, projectId);
          onClose();
        }}
      />
      <ConversationMenuItem
        icon="doc.on.doc"
        label="Copy"
        trailing="›"
        onPress={() => setCopyMenuOpen((open) => !open)}
      />
      {copyMenuOpen ? (
        <View className="ml-2 border-l border-mb-border pl-1">
          <ConversationMenuItem
            label="Copy title"
            onPress={() => {
              void copyToClipboard(row.title);
              onClose();
            }}
          />
          <ConversationMenuItem
            label="Copy link"
            onPress={() => {
              void copyToClipboard(
                conversationUrl(projectId, row.conversationId)
              );
              onClose();
            }}
          />
        </View>
      ) : null}
      {canOpenConversationInNewWindow(Platform.OS, webRuntimeEnvelope) ? (
        <ConversationMenuItem
          icon="desktopcomputer"
          label="Open in new window"
          onPress={() => {
            if (typeof window !== "undefined") {
              window.open(
                conversationUrl(projectId, row.conversationId),
                "_blank"
              );
            }
            onClose();
          }}
        />
      ) : null}
    </View>
  );
}

function ProjectConversationRow({
