function ProjectRow({
  connection: { getProjectConnectionColor, onChangeConnectionColor },
  activeConversationId,
  navigation: {
    onOpen,
    onOpenConversation,
    onOpenNewConversation,
    onRename,
    onToggle,
  },
  project,
  state: { active, expanded },
  testID,
  wide,
}: ProjectRowProps) {
  const { colors } = useThemeMode();
  const canStartConversation = project.access.status === "ready";
  const connectionColor = getProjectConnectionColor(
    project.machineId,
    project.projectId
  );
  const connectionColorValue = PROJECT_CONNECTION_COLOR_VALUES[connectionColor];
  const [hovered, setHovered] = useState(false);
  const [hoverCardOpen, setHoverCardOpen] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);
  const hoverTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const rows = useQuery(
    api.conversations.listRowsForProject,
    expanded || hoverCardOpen
      ? { limit: 6, projectId: project.projectId }
      : "skip"
  );
  const clearHoverTimeout = useCallback(() => {
    if (hoverTimeoutRef.current === null) return;
    clearTimeout(hoverTimeoutRef.current);
    hoverTimeoutRef.current = null;
  }, []);
  useEffect(() => clearHoverTimeout, [clearHoverTimeout]);
  const handleHoverIn = useCallback(() => {
    setHovered(true);
    if (!wide) return;
    clearHoverTimeout();
    hoverTimeoutRef.current = setTimeout(() => {
      setHoverCardOpen(true);
      hoverTimeoutRef.current = null;
    }, 500);
  }, [clearHoverTimeout, wide]);
  const handleHoverOut = useCallback(() => {
    setHovered(false);
    clearHoverTimeout();
    setHoverCardOpen(false);
  }, [clearHoverTimeout]);
  if (!wide) {
    return (
      <LegacyProjectRow
        activeConversationId={activeConversationId}
        navigation={{
          onOpen,
          onOpenConversation,
          onOpenNewConversation,
          onRename,
          onToggle,
        }}
        project={project}
        rows={rows}
        state={{ active, expanded }}
        testID={testID}
      />
    );
  }
  const showAffordances = wide && (hovered || menuOpen);
  let machineLabel = project.machineName;
  if (project.access.status === "needs-setup") {
    machineLabel = `${project.machineName} · not configured`;
  } else if (project.access.status === "unpaired") {
    machineLabel = `${project.machineName} · unpaired`;
  }
  return (
    <View
      testID={testID}
      onMouseEnter={wide ? handleHoverIn : undefined}
      onMouseLeave={wide ? handleHoverOut : undefined}
      className="relative"
      style={{ zIndex: menuOpen || hoverCardOpen ? 10 : 0 }}
    >
      <View
        className={`min-h-11 flex-row items-center rounded-xl ${active ? "bg-mb-accent-dim" : ""}`}
      >
        <Touchable
          feedback="subtle"
          accessibilityRole="button"
          accessibilityLabel={`${expanded ? "Collapse" : "Expand"} ${project.displayName} on ${project.machineName}`}
          accessibilityState={{ expanded }}
          onPress={onToggle}
          className="h-11 items-center justify-center"
          style={{ width: SIDEBAR_PROJECT_ICON_SLOT_PX }}
        >
          <Icon
            name={expanded ? "folder.open" : "folder"}
            color={expanded ? connectionColorValue : colors.text2}
            size={17}
          />
        </Touchable>
        <Touchable
          feedback="subtle"
          accessibilityRole="button"
          accessibilityLabel={`Open ${project.displayName} on ${project.machineName}`}
          accessibilityState={{ selected: active }}
          onPress={onOpen}
          className="min-w-0 flex-1 flex-row items-center gap-2 py-1.5 pr-1"
          style={{ marginLeft: -SIDEBAR_PROJECT_LABEL_OVERLAP_PX }}
        >
          <Text
            className="min-w-0 flex-1 text-[13px] text-mb-text"
            numberOfLines={1}
          >
            {project.displayName}
          </Text>
          <View
            className="max-w-[46%] shrink-0 flex-row items-center gap-1.5 rounded-md border border-mb-border bg-mb-surface px-1.5 py-0.5"
            accessibilityLabel={`${machineLabel}, ${project.access.status}`}
          >
            <Text
              className="shrink-0 text-[11px] text-mb-muted"
              numberOfLines={1}
            >
              {machineLabel}
            </Text>
            <View
              testID={`homer-project-${project.projectId}-connection-dot`}
              className="h-2 w-2 shrink-0 rounded-full"
              style={{ backgroundColor: connectionColorValue }}
            />
          </View>
        </Touchable>
        {showAffordances ? (
          <Touchable
            feedback="subtle"
            accessibilityRole="button"
            accessibilityLabel={`New conversation in ${project.displayName} on ${project.machineName}`}
            accessibilityState={{ disabled: !canStartConversation }}
            disabled={!canStartConversation}
            onPress={onOpenNewConversation}
            className="h-10 w-10 items-center justify-center rounded-lg"
          >
            <Icon
              name="plus"
              color={canStartConversation ? colors.text2 : colors.muted}
              size={15}
            />
