        ) : null}
        {isDesktopWeb() && showAffordances ? (
          <Touchable
            feedback="subtle"
            testID={`homer-project-${project.projectId}-menu-trigger`}
            accessibilityRole="button"
            accessibilityLabel={`More actions for ${project.displayName}`}
            onPress={() => setMenuOpen((open) => !open)}
