import { ActivityIndicator } from "react-native";
import WebView from "react-native-webview";
import { View } from "@/tw";
import type { TerminalSurfaceProps } from "./terminal-surface.types";

export function TerminalSurface({
  allowedOrigin,
  onError,
  reloadKey,
  url,
}: TerminalSurfaceProps) {
  return (
    <WebView
      key={reloadKey}
      source={{ uri: url }}
      style={{ flex: 1, backgroundColor: "#000" }}
      originWhitelist={[allowedOrigin]}
      onShouldStartLoadWithRequest={(request) => {
        try {
          return new URL(request.url).origin === allowedOrigin;
        } catch {
          return false;
        }
      }}
      thirdPartyCookiesEnabled
      allowsInlineMediaPlayback
      javaScriptEnabled
      domStorageEnabled
      startInLoadingState
      renderLoading={() => (
        <View className="absolute inset-0 items-center justify-center bg-black">
          <ActivityIndicator color="#f6c944" />
        </View>
      )}
      onError={(event) => onError(event.nativeEvent.description)}
      onHttpError={(event) =>
        onError(`Terminal returned HTTP ${event.nativeEvent.statusCode}.`)
      }
      onLoad={() => onError(null)}
    />
  );
}

import { MACHINE_TERMINAL_FRAME_NAME } from "@homer/shared/machine";
import { machineEndpointSchema } from "@homer/shared/machine-contracts";
import { useEffect } from "react";
import type { TerminalSurfaceProps } from "./terminal-surface.types";

function terminalSurfaceError(
  allowedOrigin: string,
  url: string
): string | null {
  const endpoint = machineEndpointSchema.safeParse(allowedOrigin);
  if (!endpoint.success) {
    return "Machine terminal origin is invalid.";
  }

  let terminalUrl: URL;
  try {
    terminalUrl = new URL(url);
  } catch {
    return "Terminal URL is invalid.";
  }
  if (
    terminalUrl.protocol !== "https:" ||
    terminalUrl.username !== "" ||
    terminalUrl.password !== ""
  ) {
    return "Terminal URL must be HTTPS without credentials.";
  }
  if (terminalUrl.origin !== endpoint.data) {
    return "Terminal URL does not match the selected Machine origin.";
  }
  if (terminalUrl.origin === window.location.origin) {
    return "A Machine terminal cannot use the application's own origin.";
  }
  return null;
}

export function TerminalSurface({
  allowedOrigin,
  onError,
  reloadKey,
  url,
}: TerminalSurfaceProps) {
  const error = terminalSurfaceError(allowedOrigin, url);

  useEffect(() => {
    if (error) onError(error);
  }, [error, onError]);

  if (error) return null;

  return (
    <iframe
      key={reloadKey}
      name={MACHINE_TERMINAL_FRAME_NAME}
      title="Homer terminal"
      src={url}
      sandbox="allow-scripts allow-same-origin"
      referrerPolicy="no-referrer"
      data-origin={allowedOrigin}
      onError={() => onError("failed to load terminal")}
      onLoad={() => onError(null)}
      style={{
        backgroundColor: "#000",
        border: 0,
        flex: 1,
        minHeight: 0,
        width: "100%",
      }}
    />
  );
}

