import type {
  AppleLocalModelSource,
  AppleLocalModelsClient,
  LocalModelAvailability,
  LocalModelGenerationResult,
} from "@homer/apple-local-models";
import type { TimelineMessage } from "./chat-message-meta";
import type { AppleLocalChatModelTarget } from "./model-directory";
import { beforeEach, describe, expect, it, vi } from "vitest";
import { createAppleLocalChatRuntime } from "./apple-local-chat-runtime";

const localModels = vi.hoisted(() => {
  let generatedText = "hello";
  let generatedFinishReason: LocalModelGenerationResult["finishReason"] =
    "stop";
  let deferredGeneration = false;
  const availability: AppleLocalModelsClient["availability"] = vi.fn(
    async () => ({ kind: "ready" }) satisfies LocalModelAvailability
  );
  const prepare: AppleLocalModelsClient["prepare"] = vi.fn(
    async (_model, { onProgress }) => {
      onProgress({ phase: "loading" });
    }
  );
  const remove: AppleLocalModelsClient["remove"] = vi.fn(async () => undefined);
  const openSession: AppleLocalModelsClient["openSession"] = vi.fn(
    async () => undefined
  );
  const generate: AppleLocalModelsClient["generate"] = vi.fn(
    async ({ signal, onTextDelta }) => {
      if (deferredGeneration) {
        await new Promise<void>((_resolve, reject) => {
          signal.addEventListener("abort", () => reject(signal.reason), {
            once: true,
          });
        });
      }
      signal.throwIfAborted();
      onTextDelta(generatedText);
      return {
        text: generatedText,
        finishReason: generatedFinishReason,
      } satisfies LocalModelGenerationResult;
    }
  );
  const closeSession: AppleLocalModelsClient["closeSession"] = vi.fn(
    async () => undefined
  );
  const dispose: AppleLocalModelsClient["dispose"] = vi.fn(
    async () => undefined
  );
  const subscribeAvailabilityChanges: AppleLocalModelsClient["subscribeAvailabilityChanges"] =
    vi.fn(() => () => undefined);
  return {
    availability,
    remove,
    prepare,
    openSession,
    generate,
    closeSession,
    dispose,
    subscribeAvailabilityChanges,
    setGeneratedText(value: string) {
      generatedText = value;
    },
    setFinishReason(value: LocalModelGenerationResult["finishReason"]) {
      generatedFinishReason = value;
    },
    deferGeneration(value: boolean) {
      deferredGeneration = value;
    },
  };
});

let appleLocalChatRuntime: ReturnType<typeof createAppleLocalChatRuntime>;
let systemModel: AppleLocalChatModelTarget;
let packagedModel: AppleLocalChatModelTarget;

function userMessage(text: string) {
  return {
    id: `user-${text}`,
    role: "user",
    parts: [{ type: "text", text }],
  } satisfies TimelineMessage;
}

function assistantMessage(text: string) {
  return {
    id: `assistant-${text}`,
    role: "assistant",
    parts: [{ type: "text", text }],
  } satisfies TimelineMessage;
}

async function chunks(stream: ReadableStream) {
  const reader = stream.getReader();
  const values: unknown[] = [];
  for (;;) {
    const result = await reader.read();
    if (result.done) return values;
    values.push(result.value);
  }
}

describe("appleLocalChatRuntime", () => {
  beforeEach(() => {
    vi.clearAllMocks();
    localModels.setGeneratedText("hello");
    localModels.setFinishReason("stop");
    localModels.deferGeneration(false);
    vi.mocked(localModels.availability).mockResolvedValue({ kind: "ready" });
    vi.mocked(localModels.prepare).mockImplementation(
      async (_model, { onProgress }) => {
        onProgress({ phase: "loading" });
      }
    );
    appleLocalChatRuntime = createAppleLocalChatRuntime({
      availability: localModels.availability,
      remove: localModels.remove,
      prepare: localModels.prepare,
      openSession: localModels.openSession,
      generate: localModels.generate,
      closeSession: localModels.closeSession,
      dispose: localModels.dispose,
      subscribeAvailabilityChanges: localModels.subscribeAvailabilityChanges,
    });
    const targets = appleLocalChatRuntime.targets;
    const system = targets[0];
    const packaged = targets[1];
    if (!system || !packaged) {
      throw new Error("Apple-local test models are missing.");
    }
    systemModel = system;
    packagedModel = packaged;
  });

  it("passes the selected system source through availability and preparation", async () => {
    const dispatch = vi.fn();

    await appleLocalChatRuntime.activate({
      target: systemModel,
      signal: new AbortController().signal,
      dispatch,
    });

    expect(localModels.availability).toHaveBeenCalledWith({
      kind: "system",
    });
    expect(localModels.prepare).toHaveBeenCalledWith(
      { kind: "system" },
      expect.objectContaining({ signal: expect.any(AbortSignal) })
    );
    expect(localModels.openSession).not.toHaveBeenCalled();
    expect(dispatch.mock.calls.map(([event]) => event.step)).toEqual([
      "loading",
      "loading",
      "ready",
    ]);
  });

  it("maps package download progress without changing the selected source", async () => {
    vi.mocked(localModels.availability).mockResolvedValue({
      kind: "downloadable",
    });
    vi.mocked(localModels.prepare).mockImplementation(
      async (_model, { onProgress }) => {
        onProgress({ phase: "downloading", fraction: 0.5 });
        onProgress({ phase: "loading" });
      }
    );
    const dispatch = vi.fn();

    await appleLocalChatRuntime.activate({
      target: packagedModel,
      signal: new AbortController().signal,
      dispatch,
    });

    const source = {
      kind: "package",
      modelId: "qwen3-0.6b-local",
    } satisfies AppleLocalModelSource;
    expect(localModels.availability).toHaveBeenCalledWith(source);
    expect(localModels.prepare).toHaveBeenCalledWith(
      source,
      expect.objectContaining({ signal: expect.any(AbortSignal) })
    );
    expect(dispatch.mock.calls[1]?.[0].progress.percent).toBe(50);
  });

  it("streams text and keeps one native session open for a continuing conversation", async () => {
    await appleLocalChatRuntime.activate({
      target: systemModel,
      signal: new AbortController().signal,
      dispatch: vi.fn(),
    });
    const transport = appleLocalChatRuntime.transport(systemModel);
    const first = await transport.sendMessages({
      trigger: "submit-message",
      chatId: "conversation-a",
      messageId: undefined,
      messages: [userMessage("hi")],
      abortSignal: undefined,
    });

    await expect(chunks(first)).resolves.toEqual([
      { type: "start", messageId: expect.any(String) },
      { type: "text-start", id: expect.any(String) },
      { type: "text-delta", id: expect.any(String), delta: "hello" },
      { type: "text-end", id: expect.any(String) },
      { type: "finish", finishReason: "stop" },
    ]);

    localModels.setGeneratedText("again");
    const second = await transport.sendMessages({
      trigger: "submit-message",
      chatId: "conversation-a",
      messageId: undefined,
      messages: [
        userMessage("hi"),
        assistantMessage("hello"),
        userMessage("continue"),
      ],
      abortSignal: undefined,
    });
    await chunks(second);

    expect(localModels.openSession).toHaveBeenCalledTimes(1);
    expect(localModels.generate).toHaveBeenCalledTimes(2);
  });

  it("fails loudly when the native bridge delivers no deltas for returned text", async () => {
    await appleLocalChatRuntime.activate({
      target: systemModel,
      signal: new AbortController().signal,
      dispatch: vi.fn(),
    });
    vi.mocked(localModels.generate).mockResolvedValueOnce({
      text: "dropped answer",
      finishReason: "stop",
    });
    const stream = await appleLocalChatRuntime
      .transport(systemModel)
      .sendMessages({
        trigger: "submit-message",
        chatId: "conversation-drop",
        messageId: undefined,
        messages: [userMessage("hi")],
        abortSignal: undefined,
      });

    await expect(chunks(stream)).rejects.toThrow(
      "the delta bridge dropped assistant text"
    );
  });

  it("forwards the native length finish reason to the AI SDK stream", async () => {
    await appleLocalChatRuntime.activate({
      target: systemModel,
      signal: new AbortController().signal,
      dispatch: vi.fn(),
    });
    localModels.setFinishReason("length");
    const stream = await appleLocalChatRuntime
      .transport(systemModel)
      .sendMessages({
        trigger: "submit-message",
        chatId: "conversation-a",
        messageId: undefined,
        messages: [userMessage("write")],
        abortSignal: undefined,
      });

    await expect(chunks(stream)).resolves.toContainEqual({
      type: "finish",
      finishReason: "length",
    });
  });

  it("opens a cold native session from durable history", async () => {
    await appleLocalChatRuntime.activate({
      target: systemModel,
      signal: new AbortController().signal,
      dispatch: vi.fn(),
    });
    const stream = await appleLocalChatRuntime
      .transport(systemModel)
      .sendMessages({
        trigger: "submit-message",
        chatId: "conversation-b",
        messageId: undefined,
