async function importRegisteredLocalChatRuntime() {
  vi.resetModules();
  const runtime = await import("./platform-local-chat-runtime");
  runtime.registerLocalModelsClient(appleLocalModelsElectronClient);
  const localChatRuntime = runtime.getLocalChatRuntime();
  if (!localChatRuntime) {
    throw new Error("Expected the Electron local chat runtime.");
  }
  return localChatRuntime;
}

function setup(input: { orderedGeneration?: boolean } = {}) {
  let progressListener: Parameters<
    HomerDesktopBridge["subscribeAppleLocalModelPreparationProgress"]
  >[0] = () => undefined;
  let textListener: Parameters<
    HomerDesktopBridge["subscribeAppleLocalModelTextDelta"]
  >[0] = () => undefined;
  let resolveGeneration: (() => void) | undefined;
  const cancelAppleLocalModelOperation = vi.fn(async () => true);
  const generateWithAppleLocalModel = vi.fn(
    (
      operation: Parameters<
        HomerDesktopBridge["generateWithAppleLocalModel"]
      >[0]
    ) =>
      new Promise<{ text: string; finishReason: "stop" }>((resolve) => {
        textListener({ operationId: operation.operationId, delta: "Hel" });
        resolveGeneration = () => {
          if (input.orderedGeneration) {
            resolve({ text: "Hello", finishReason: "stop" });
            queueMicrotask(() => {
              textListener({ operationId: operation.operationId, delta: "lo" });
              textListener({
                operationId: operation.operationId,
                text: "Hello",
                finishReason: "stop",
              });
            });
            return;
          }
          textListener({ operationId: operation.operationId, delta: "lo" });
          textListener({
            operationId: operation.operationId,
            text: "Hello",
            finishReason: "stop",
          });
          resolve({ text: "Hello", finishReason: "stop" });
        };
      })
  );
  const prepareAppleLocalModel = vi.fn(
    async (
      operation: Parameters<HomerDesktopBridge["prepareAppleLocalModel"]>[0]
    ) => {
      progressListener({
        operationId: operation.operationId,
        progress: { phase: "loading" },
      });
      return null;
    }
  );
  const bridge = {
    getRuntimeInfo: vi.fn(
      async () =>
        ({
          appVersion: "0.2.0",
          isPackaged: true,
          platform: "darwin",
          rendererBuildId: "a".repeat(64),
        }) satisfies HomerDesktopRuntimeInfoResult
    ),
    appleLocalModelAvailability: vi.fn(
      async () => ({ kind: "ready" }) satisfies LocalModelAvailability
    ),
    removeAppleLocalModel: vi.fn(async () => null),
    prepareAppleLocalModel,
    openAppleLocalModelSession: vi.fn(async () => null),
    generateWithAppleLocalModel,
    cancelAppleLocalModelOperation,
    closeAppleLocalModelSession: vi.fn(async () => null),
    disposeAppleLocalModels: vi.fn(async () => null),
    readPendingApplicationDestination: vi.fn(async () => null),
    acknowledgeApplicationDestination: vi.fn(async () => false),
    subscribeApplicationDestinationAvailable: vi.fn(() => () => undefined),
    subscribeAppleLocalModelPreparationProgress: vi.fn((listener) => {
      progressListener = listener;
      return () => undefined;
    }),
    subscribeAppleLocalModelTextDelta: vi.fn((listener) => {
      textListener = listener;
      return () => undefined;
    }),
    subscribeAppleLocalModelAvailabilityChanges: vi.fn(() => () => undefined),
  } satisfies HomerDesktopBridge;
  vi.stubGlobal("window", { homerDesktop: bridge });
  return {
    bridge,
    cancelAppleLocalModelOperation,
    generateWithAppleLocalModel,
    prepareAppleLocalModel,
    resolveGeneration: () => resolveGeneration?.(),
  };
}

async function chunks(stream: ReadableStream) {
  const reader = stream.getReader();
  const values: unknown[] = [];
  for (;;) {
    const result = await reader.read();
    if (result.done) return values;
    values.push(result.value);
  }
}

afterEach(() => {
  vi.unstubAllGlobals();
});

