import type { UIMessage } from "ai";
import type {
  ChatModelSnapshot,
  EffectiveChatRequest,
} from "./conversation-convex-types";
import type { ChatPendingItem } from "../components/chat/message-list";
import { extractCachedPromptFromMessage } from "../components/chat/screen/cache-prompt";

const TIMELINE_ENTRY_METADATA_KEY = "__homerTimelineEntry";
const ORIGINAL_MESSAGE_METADATA_KEY = "__homerOriginalMetadata";

// The timeline envelope is client-owned in-memory state written only by this
// module; `modelSnapshot` and `effectiveRequest` are the Convex dispatch
// contract itself, so neither side is re-validated here.
type TimelineMetadataShared = {
  agentTurnId?: string;
  cachedPromptTokens?: number;
  modelSnapshot?: ChatModelSnapshot;
  effectiveRequest?: EffectiveChatRequest;
};

export type TimelineEntryMetadata = TimelineMetadataShared & {
  createdAt: number;
  sequence?: number;
  assistantName?: string;
};

export type TimelineMessageMetadata = Record<string, unknown> & {
  [TIMELINE_ENTRY_METADATA_KEY]?: TimelineEntryMetadata;
};

export type TimelineMessage = UIMessage<TimelineMessageMetadata>;

type TimelineMetadataOptions = TimelineMetadataShared & {
  createdAt: number;
  sequence?: number;
  assistantName?: string;
  previousMessage?: TimelineMessage;
};

type TimelineMetadataListOptions = TimelineMetadataOptions;

export function withTimelineMetadata(
  message: TimelineMessage,
  {
    createdAt,
    sequence,
    agentTurnId,
    assistantName,
    previousMessage,
    cachedPromptTokens: fallbackCachedPromptTokens,
    modelSnapshot,
    effectiveRequest,
  }: TimelineMetadataOptions
): TimelineMessage {
  const previous =
    readTimelineEntryMetadata(message) ??
    previousMessage?.metadata?.[TIMELINE_ENTRY_METADATA_KEY];
  const cachedPromptTokens =
    extractCachedPromptFromMessage(message) ??
    previous?.cachedPromptTokens ??
    fallbackCachedPromptTokens;
  const entry: TimelineEntryMetadata = {
    createdAt: previous?.createdAt ?? createdAt,
    sequence: previous?.sequence ?? sequence,
    agentTurnId: previous?.agentTurnId ?? agentTurnId,
    assistantName: assistantName ?? previous?.assistantName,
    cachedPromptTokens,
    modelSnapshot: modelSnapshot ?? previous?.modelSnapshot,
    effectiveRequest: effectiveRequest ?? previous?.effectiveRequest,
  };
  const wireMessage = serializeTimelineMessage(message);

  return {
    ...wireMessage,
    metadata: {
      ...metadataRecord(wireMessage.metadata),
      [TIMELINE_ENTRY_METADATA_KEY]: entry,
    },
  };
}

export function withTimelineMetadataForMessages(
  messages: readonly TimelineMessage[],
  { createdAt, assistantName }: TimelineMetadataListOptions
): TimelineMessage[] {
  return messages.map((message, index) =>
    withTimelineMetadata(message, {
      createdAt: createdAt + index,
      assistantName: message.role === "assistant" ? assistantName : undefined,
    })
  );
}

export function readTimelineEntryMetadata(
  message: TimelineMessage
): TimelineEntryMetadata | undefined {
  return message.metadata?.[TIMELINE_ENTRY_METADATA_KEY];
}

export function serializeTimelineMessage(message: TimelineMessage): UIMessage {
  if (!isRecord(message.metadata)) return message;
  if (!(TIMELINE_ENTRY_METADATA_KEY in message.metadata)) return message;

  const metadata = { ...message.metadata };
  delete metadata[TIMELINE_ENTRY_METADATA_KEY];
  if (ORIGINAL_MESSAGE_METADATA_KEY in metadata) {
    const original = metadata[ORIGINAL_MESSAGE_METADATA_KEY];
    const { metadata: _metadata, ...rest } = message;
    return original === undefined ? rest : { ...rest, metadata: original };
  }
  if (Object.keys(metadata).length > 0) return { ...message, metadata };
  const { metadata: _metadata, ...rest } = message;
  return rest;
}

export function serializeTimelineMessages(
  messages: readonly TimelineMessage[]
): UIMessage[] {
  return messages.map(serializeTimelineMessage);
}

function metadataRecord(metadata: unknown): TimelineMessageMetadata {
  if (isRecord(metadata)) return { ...metadata };
  if (metadata === undefined) return {};
  return { [ORIGINAL_MESSAGE_METADATA_KEY]: metadata };
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

type RenderableChatRole = Extract<UIMessage["role"], "user" | "assistant">;

export type TimelinePosition =
  | { kind: "sequence"; value: number }
  | { kind: "timestamp"; value: number }
  | { kind: "message-order"; sequence: number };

export type ChatMessageTimelineItem = {
  kind: "message";
  id: string;
  role: RenderableChatRole;
  parts: UIMessage["parts"];
  streaming: boolean;
  assistantName?: string;
  createdAt?: number;
};

export type ChatMessageTimelineEntry = {
  item: ChatMessageTimelineItem;
  position: TimelinePosition;
  index: number;
};

type BuildChatMessageTimelineInput = {
  messages: readonly TimelineMessage[];
  streaming: boolean;
};

type CachedChatMessageTimelineItem = {
  metadata: TimelineEntryMetadata | undefined;
  parts: UIMessage["parts"];
  item: ChatMessageTimelineItem;
};

const chatMessageTimelineItems = new WeakMap<
  TimelineMessage,
  CachedChatMessageTimelineItem
>();

function chatMessageTimelineItem(
  message: TimelineMessage,
  role: RenderableChatRole,
  metadata: TimelineEntryMetadata | undefined,
  streaming: boolean
): ChatMessageTimelineItem {
  const cached = chatMessageTimelineItems.get(message);
  if (
    cached &&
    cached.parts === message.parts &&
    cached.metadata === metadata &&
    cached.item.streaming === streaming
  ) {
    return cached.item;
  }
  const item: ChatMessageTimelineItem = {
    kind: "message",
    id: message.id,
    role,
    parts: message.parts,
    streaming,
    assistantName: role === "assistant" ? metadata?.assistantName : undefined,
    createdAt: metadata?.createdAt,
  };
  chatMessageTimelineItems.set(message, {
    metadata,
    parts: message.parts,
    item,
  });
  return item;
}

export function buildChatMessageTimeline({
  messages,
  streaming,
}: BuildChatMessageTimelineInput): ChatMessageTimelineEntry[] {
  const timeline: ChatMessageTimelineEntry[] = [];

  messages.forEach((message, index) => {
    const role = message.role;
    if (!isRenderableChatRole(role)) return;

    const last = index === messages.length - 1;
    const metadata = message.metadata?.[TIMELINE_ENTRY_METADATA_KEY];
    const position: TimelinePosition = metadata
      ? metadata.sequence === undefined
        ? { kind: "timestamp", value: metadata.createdAt }
        : { kind: "sequence", value: metadata.sequence }
      : { kind: "message-order", sequence: index };

    timeline.push({
      position,
      index,
      item: chatMessageTimelineItem(
        message,
        role,
        metadata,
        streaming && last && role === "assistant"
      ),
    });
  });

  return timeline;
}

function isRenderableChatRole(
  role: UIMessage["role"]
): role is RenderableChatRole {
  return role === "user" || role === "assistant";
}

export type ChatTranscriptTimelineEntry = {
  item: ChatMessageTimelineItem | ChatPendingItem;
  position: TimelinePosition;
  index: number;
};

type BuildChatTranscriptTimelineInput = {
  messages: readonly TimelineMessage[];
  assistantName: string;
  streaming: boolean;
};

export function buildChatTranscriptTimeline({
  messages,
  assistantName,
  streaming,
}: BuildChatTranscriptTimelineInput): ChatTranscriptTimelineEntry[] {
  const timeline: ChatTranscriptTimelineEntry[] = buildChatMessageTimeline({
    messages,
    streaming,
  }).map((entry) => ({
    ...entry,
    item:
      entry.item.role === "assistant" && !entry.item.assistantName
        ? { ...entry.item, assistantName }
        : entry.item,
  }));

  const lastMessage = messages[messages.length - 1];
  const pendingAnchor =
    streaming && lastMessage?.role === "user"
      ? findTimelinePosition(timeline, lastMessage.id)
      : null;
  if (pendingAnchor) {
    timeline.push({
      position: positionAfter(pendingAnchor),
      index: timeline.length,
      item: {
        kind: "pending",
        id: "pending-first-token",
      },
    });
  }

  return timeline;
}

function findTimelinePosition(
  timeline: readonly ChatTranscriptTimelineEntry[],
  messageId: string
): TimelinePosition | undefined {
  for (let index = timeline.length - 1; index >= 0; index -= 1) {
    const entry = timeline[index];
    if (entry === undefined) continue;
    if (entry.item.id === messageId) return entry.position;
  }
  return undefined;
}

function positionAfter(position: TimelinePosition): TimelinePosition {
  if (position.kind === "sequence") {
    return { kind: "sequence", value: position.value + 0.5 };
  }
  return position.kind === "timestamp"
    ? { kind: "timestamp", value: position.value + 0.5 }
    : { kind: "message-order", sequence: position.sequence + 0.5 };
}

