type ClerkTokenGetter = ConstructorParameters<typeof ApiClient>[1];

class LatestClerkTokenGetter {
  private current: ClerkTokenGetter;

  constructor(initial: ClerkTokenGetter) {
    this.current = initial;
  }

  readonly read: ClerkTokenGetter = () => this.current();

  update(next: ClerkTokenGetter) {
    this.current = next;
  }
}

export function useApi() {
  const { baseURL } = useBaseURL();
  const { getToken } = useAuth();
  const [clerkToken] = useState(() => new LatestClerkTokenGetter(getToken));
  useLayoutEffect(() => {
    clerkToken.update(getToken);
  }, [clerkToken, getToken]);
  const api = useMemo(
    () => new ApiClient(baseURL, clerkToken.read),
    [baseURL, clerkToken]
  );
  return { api, baseURL };
}

export function useModelCatalog() {
  const { api, baseURL } = useApi();
  return useQuery({
    queryKey: ["model-catalog", baseURL],
    queryFn: () => api.modelCatalog(),
  });
}

export function useModelDirectory() {
  const catalog = useModelCatalog();
  const localAvailability = useLocalModelAvailability();
  const localChatRuntime = getLocalChatRuntime();
  const models = useMemo(
    () =>
      buildModelDirectory(
        catalog.data?.models ?? [],
        localChatRuntime?.targets ?? []
      ),
    [catalog.data, localChatRuntime]
  );
  const defaultServiceChatTarget = useMemo(() => {
    if (!catalog.data) return null;
    const target = catalog.data.models.find(
      (model) =>
        model.kind === "chat" && model.id === catalog.data.defaultChatModelId
    );
    if (!target) {
      throw new Error(
        `Default chat model ${catalog.data.defaultChatModelId} is not in the service catalog.`
      );
    }
    return target;
  }, [catalog.data]);
  return {
    models,
    catalog,
    localAvailability,
    defaultTargets: {
      localChat: localChatRuntime?.defaultTarget ?? null,
      serviceChat: defaultServiceChatTarget,
    },
  };
}

