  const mutation = useMutation(
    machineEnrollmentMutationOptions({
      baseURL,
      enroll: enrollment.run,
    })
  );
  const executeMutation = mutation.mutateAsync;
  const resetMutation = mutation.reset;
  const mutateAsync = useCallback<typeof mutation.mutateAsync>(
    async (input, options) => {
      try {
        return await executeMutation(input, options);
      } finally {
        resetMutation();
      }
    },
    [executeMutation, resetMutation]
  );
  const mutate = useCallback<typeof mutation.mutate>(
    (input, options) => {
      void mutateAsync(input, options).catch(() => undefined);
    },
    [mutateAsync]
  );
  return { ...mutation, cancel: enrollment.cancel, mutate, mutateAsync };
}

