function mediaTaskStatusValue(data: MediaTask | undefined) {
  return data?.status;
}

const IMAGE_POLL_BASE_MS = 1_500;
const IMAGE_POLL_MAX_MS = 8_000;
const IMAGE_POLL_ABANDON_AFTER = 10;

export function useBatchedImageTaskPolls(taskIds: string[]) {
  const { api, baseURL } = useApi();
  const pollingEnabled = useHighFrequencyQueryEnabled(taskIds.length > 0);
  return useQuery({
    queryKey: ["image-tasks", baseURL, taskIds],
    queryFn: () => api.imageTaskStatuses(taskIds),
    enabled: pollingEnabled,
    retry: false,
    staleTime: DEFAULT_QUERY_STALE_TIME_MS,
    refetchInterval: (q) => {
      if (!pollingEnabled) return false;
      const data = q.state.data;
      const statuses = Object.values(data ?? {});
      if (
        statuses.length > 0 &&
        statuses.every((status) =>
          isTerminalStatus(mediaTaskStatusValue(status))
        )
      ) {
        return false;
      }
      const failures = q.state.fetchFailureCount;
      if (failures >= IMAGE_POLL_ABANDON_AFTER) return false;
      if (failures > 0) {
        const exp = Math.min(failures, 3);
        return Math.min(IMAGE_POLL_MAX_MS, IMAGE_POLL_BASE_MS * 2 ** exp);
      }
      return IMAGE_POLL_BASE_MS;
    },
  });
}

