import { createAudioPlayer, type AudioPlayer } from "expo-audio";
import { File, Paths } from "expo-file-system";
import { Platform } from "react-native";
import type { VoiceOptionId } from "@homer/shared/voice-types";

import type { AssistantSpeechBackend } from "./chat-speech";

const MAX_ASSISTANT_TTS_CHARS = 5000;

type SpeechHandlers = Parameters<AssistantSpeechBackend["speak"]>[1];
type Subscription = { remove(): void };
type WebAudioElement = {
  play(): Promise<void> | void;
  pause(): void;
  currentTime: number;
  onended: ((event: Event) => void) | null;
  onerror: ((event: Event) => void) | null;
};

type ActivePlayback =
  | {
      kind: "native";
      player: AudioPlayer;
      subscription: Subscription;
      onStopped?: () => void;
    }
  | {
      kind: "web";
      audio: WebAudioElement;
      objectUrl: string;
      onStopped?: () => void;
    };

type NaturalAssistantSpeechBackendInput = {
  voiceId?: VoiceOptionId;
  fetchImpl: (path: string, init?: RequestInit) => Promise<Response>;
};

const activeNaturalAssistantSpeechStops = new Set<() => Promise<void> | void>();
export const ASSISTANT_TTS_PATH = "/api/voice/tts";

export function assistantTtsText(text: string): string {
  return text.trim().slice(0, MAX_ASSISTANT_TTS_CHARS);
}

async function responseAudioBytes(response: Response): Promise<Uint8Array> {
  return new Uint8Array(await response.arrayBuffer());
}

function createWebAudio(uri: string): WebAudioElement {
  return new Audio(uri);
}

function writeNativeAudioFile(bytes: Uint8Array, generation: number): string {
  const file = new File(
    Paths.cache,
    `homer-assistant-tts-${Date.now()}-${generation}.wav`
  );
  if (
    !("write" in file) ||
    typeof file.write !== "function" ||
    !("uri" in file) ||
    typeof file.uri !== "string"
  ) {
    throw new Error("native audio files are unavailable on this platform");
  }
  file.write(bytes);
  return file.uri;
}

export function createNaturalAssistantSpeechBackend({
  voiceId,
  fetchImpl,
}: NaturalAssistantSpeechBackendInput): AssistantSpeechBackend {
  let active: ActivePlayback | null = null;
  let generation = 0;

  let stopThisBackend: () => void;
  const cleanup = (notifyStopped: boolean) => {
    const playback = active;
    active = null;
    activeNaturalAssistantSpeechStops.delete(stopThisBackend);
    if (!playback) return;

    if (playback.kind === "native") {
      playback.subscription.remove();
      playback.player.pause();
      playback.player.remove();
    } else {
      playback.audio.onended = null;
      playback.audio.onerror = null;
      playback.audio.pause();
      playback.audio.currentTime = 0;
      URL.revokeObjectURL(playback.objectUrl);
    }
    if (notifyStopped) playback.onStopped?.();
  };

  stopThisBackend = () => {
    generation += 1;
    cleanup(true);
  };

  return {
    stop: stopThisBackend,
    speak(text, options) {
      const spokenText = assistantTtsText(text);
      if (!spokenText) {
        options.onDone?.();
        return;
      }

      const currentGeneration = ++generation;
      activeNaturalAssistantSpeechStops.add(stopThisBackend);
      void (async () => {
        try {
          const response = await fetchImpl(ASSISTANT_TTS_PATH, {
            method: "POST",
            headers: {
              accept: "audio/wav",
              "content-type": "application/json",
            },
            body: JSON.stringify({ text: spokenText, voice: voiceId }),
          });
          if (!response.ok) {
            throw new Error(`voice_tts_${response.status}`);
          }
          const audioBytes = await responseAudioBytes(response);
          if (currentGeneration !== generation) {
            return;
          }

          cleanup(false);
          if (Platform.OS === "web") {
            playWebAudio(
              audioBytes,
              options,
              (playback) => {
                activeNaturalAssistantSpeechStops.add(stopThisBackend);
                active = playback;
              },
              (playback) => {
                if (active === playback) {
                  activeNaturalAssistantSpeechStops.delete(stopThisBackend);
                  active = null;
                }
              }
            );
            return;
          }

          playNativeAudio(
            audioBytes,
            currentGeneration,
            options,
            (playback) => {
              activeNaturalAssistantSpeechStops.add(stopThisBackend);
              active = playback;
            },
            (playback) => {
              if (active === playback) {
                activeNaturalAssistantSpeechStops.delete(stopThisBackend);
                active = null;
              }
            }
          );
        } catch {
          if (currentGeneration !== generation) {
            return;
          }
          cleanup(false);
          options.onError?.();
        } finally {
          if (currentGeneration === generation && !active) {
            activeNaturalAssistantSpeechStops.delete(stopThisBackend);
          }
        }
      })();
    },
  };
}

export async function stopNaturalAssistantSpeechPlayback(): Promise<void> {
  await Promise.all(
    [...activeNaturalAssistantSpeechStops].map((stopPlayback) =>
      Promise.resolve(stopPlayback())
    )
  );
}

function playNativeAudio(
  audioBytes: Uint8Array,
  generation: number,
  options: SpeechHandlers,
  setActive: (playback: ActivePlayback) => void,
  clearActive: (playback: ActivePlayback) => void
): void {
  const uri = writeNativeAudioFile(audioBytes, generation);
  const player = createAudioPlayer(
    { uri, name: "Assistant response" },
    { updateInterval: 250 }
  );
  let playback: ActivePlayback;
  const subscription = player.addListener("playbackStatusUpdate", (status) => {
    if (!status.didJustFinish && !status.error) return;
    subscription.remove();
    player.remove();
    clearActive(playback);
    if (status.error) {
      options.onError?.();
      return;
    }
    options.onDone?.();
  });
  playback = {
    kind: "native",
    player,
    subscription,
    onStopped: options.onStopped,
  };
  setActive(playback);
  player.play();
}

function playWebAudio(
  audioBytes: Uint8Array,
  options: SpeechHandlers,
  setActive: (playback: ActivePlayback) => void,
  clearActive: (playback: ActivePlayback) => void
): void {
  const audioBuffer = new Uint8Array(audioBytes).buffer;
  const objectUrl = URL.createObjectURL(
    new Blob([audioBuffer], { type: "audio/wav" })
  );
  const audio = createWebAudio(objectUrl);
  const playback: ActivePlayback = {
    kind: "web",
    audio,
    objectUrl,
    onStopped: options.onStopped,
  };
  audio.onended = () => {
    URL.revokeObjectURL(objectUrl);
    clearActive(playback);
    options.onDone?.();
  };
  audio.onerror = () => {
    URL.revokeObjectURL(objectUrl);
    clearActive(playback);
    options.onError?.();
  };
  setActive(playback);
  void Promise.resolve(audio.play()).catch(() => {
    clearActive(playback);
    URL.revokeObjectURL(objectUrl);
    options.onError?.();
  });
}

