async function importRuntime() {
  vi.resetModules();
  return import("./platform-local-chat-runtime");
}

async function readChunks(stream: ReadableStream) {
  const reader = stream.getReader();
  const values: unknown[] = [];
  for (;;) {
    const result = await reader.read();
    if (result.done) return values;
    values.push(result.value);
  }
}

function userMessage(text: string) {
  return {
    id: "user-1",
    role: "user",
    parts: [{ type: "text", text }],
  } satisfies TimelineMessage;
}

describe("local chat runtime registration", () => {
  it("has no runtime before a host registers a client", async () => {
    const runtime = await importRuntime();

    expect(runtime.localChatRuntime).toBeNull();
  });

  it("routes generation through a registered client", async () => {
    const runtimeModule = await importRuntime();
    const fake = fakeClient();

    runtimeModule.registerLocalModelsClient(fake.client);

    const runtime = runtimeModule.localChatRuntime;
    if (!runtime) throw new Error("Expected a registered local chat runtime.");
    const target = runtime.targets[0];
    if (!target) throw new Error("Expected a local chat target.");
    const stream = await runtime.transport(target).sendMessages({
      trigger: "submit-message",
      chatId: "conversation-1",
      messageId: undefined,
      messages: [userMessage("hello")],
      abortSignal: undefined,
    });

    await expect(readChunks(stream)).resolves.toEqual([
      { type: "start", messageId: expect.any(String) },
      { type: "text-start", id: expect.any(String) },
      { type: "text-delta", id: expect.any(String), delta: "local response" },
      { type: "text-end", id: expect.any(String) },
      { type: "finish", finishReason: "stop" },
    ]);
    expect(fake.generate).toHaveBeenCalledOnce();
  });

  it("rejects double registration", async () => {
    const runtime = await importRuntime();
    const first = fakeClient();

    runtime.registerLocalModelsClient(first.client);

    expect(() =>
      runtime.registerLocalModelsClient(fakeClient().client)
    ).toThrow("already registered");
  });

  it("rejects registration after the runtime is used", async () => {
    const runtimeModule = await importRuntime();
    const first = fakeClient();
    runtimeModule.registerLocalModelsClient(first.client);
    expect(runtimeModule.getLocalChatRuntime()).not.toBeNull();

    expect(() =>
      runtimeModule.registerLocalModelsClient(fakeClient().client)
    ).toThrow("before use");
  });
});

import { QueryClient, QueryObserver } from "@tanstack/react-query";
import { describe, expect, it, vi } from "vitest";
import {
  DEFAULT_QUERY_STALE_TIME_MS,
  staleTimeForPolling,
} from "./query-polling";

describe("staleTimeForPolling", () => {
  it("keeps data fresh through the active poll interval", () => {
    expect(staleTimeForPolling(true, 15_000)).toBeGreaterThan(
      DEFAULT_QUERY_STALE_TIME_MS
    );
  });

  it("returns to normal mount freshness while polling is disabled", () => {
    expect(staleTimeForPolling(false, 15_000)).toBe(
      DEFAULT_QUERY_STALE_TIME_MS
    );
  });

  it("refetches stale cached data when polling is re-enabled", async () => {
    const queryClient = new QueryClient({
      defaultOptions: { queries: { retry: false } },
    });
    const queryKey = ["polling-re-enable"];
    const queryFn = vi.fn().mockResolvedValue("fresh");
    queryClient.setQueryData(queryKey, "cached", {
      updatedAt: Date.now() - DEFAULT_QUERY_STALE_TIME_MS - 1,
    });
    const observer = new QueryObserver(queryClient, {
      queryKey,
      queryFn,
      enabled: false,
      staleTime: DEFAULT_QUERY_STALE_TIME_MS,
      refetchInterval: false,
    });
    const unsubscribe = observer.subscribe(() => undefined);

    observer.setOptions({
      queryKey,
      queryFn,
      enabled: true,
      staleTime: DEFAULT_QUERY_STALE_TIME_MS,
      refetchInterval: 60_000,
    });

    await vi.waitFor(() => expect(queryFn).toHaveBeenCalledTimes(1));
    unsubscribe();
    queryClient.clear();
  });
});

import { describe, expect, it } from "vitest";
import "web-streams-polyfill/polyfill";

import { installStreamPolyfills } from "./stream-polyfills";

async function readText(stream: ReadableStream<string>) {
  const reader = stream.getReader();
  let text = "";
  while (true) {
    const { done, value } = await reader.read();
    if (done) return text;
    text += value;
  }
}

describe("stream polyfills", () => {
  it("can force native-compatible stream constructors before app modules load", () => {
    const existingReadableStream = globalThis.ReadableStream;
    const existingTransformStream = globalThis.TransformStream;
    const existingWritableStream = globalThis.WritableStream;
    function BrokenTextDecoderStream() {}
    Object.defineProperty(globalThis, "TextDecoderStream", {
      configurable: true,
      writable: true,
      value: BrokenTextDecoderStream,
    });

    installStreamPolyfills({
      forceNativeStreams: true,
      forceTextDecoderStream: true,
    });

    expect(globalThis.ReadableStream).not.toBe(existingReadableStream);
    expect(globalThis.TransformStream).not.toBe(existingTransformStream);
    expect(globalThis.WritableStream).not.toBe(existingWritableStream);
    expect(globalThis.TextDecoderStream).not.toBe(BrokenTextDecoderStream);
  });

  it("keeps TextDecoderStream compatible with web-streams-polyfill streams", async () => {
    installStreamPolyfills();

    const input = new ReadableStream<Uint8Array>({
      start(controller) {
        controller.enqueue(new Uint8Array([0x6f, 0x6b]));
        controller.close();
      },
    });

    await expect(
      readText(
        input.pipeThrough(
          // TypeScript's DOM streams and web-streams-polyfill use incompatible nominal declarations.
          new TextDecoderStream() as ReadableWritablePair<string, Uint8Array>
        )
      )
    ).resolves.toBe("ok");
  });
});

