  constructor(
    message: string,
    public cause?: unknown
  ) {
    super(message);
    this.name = "OpenAIVoiceSessionError";
  }
}

function requireOpenAISession(
  response: VoiceSessionResponse
): OpenAIVoiceTransportSession {
  if (response.status !== "configured") {
    throw new OpenAIVoiceSessionError(response.message);
  }
  const configured = openAIVoiceTransportSessionSchema.safeParse(response);
  if (!configured.success) {
    throw new OpenAIVoiceSessionError(
      "OpenAI voice session requires an OpenAI transport and client secret."
    );
  }
  return configured.data;
}

function dataChannelMessageText(value: unknown): string | undefined {
  if (typeof value === "string") return value;
  if (value instanceof ArrayBuffer) {
    return new TextDecoder().decode(new Uint8Array(value));
  }
  if (ArrayBuffer.isView(value)) {
    return new TextDecoder().decode(
      new Uint8Array(value.buffer, value.byteOffset, value.byteLength)
    );
  }
  return undefined;
}

const transcriptionEventShape = {
  item_id: z.string(),
  content_index: z.number(),
};
const outputTranscriptionEventShape = {
  ...transcriptionEventShape,
  response_id: z.string(),
};

const realtimeServerEventSchema = z.discriminatedUnion("type", [
  z.object({ type: z.literal("input_audio_buffer.speech_started") }),
  z.object({ type: z.literal("input_audio_buffer.speech_stopped") }),
  z.object({ type: z.literal("response.created") }),
  z.object({ type: z.literal("response.output_audio.delta") }),
  z.object({
    type: z.literal("conversation.item.input_audio_transcription.delta"),
    ...transcriptionEventShape,
    delta: z.string(),
  }),
  z.object({
    type: z.literal("conversation.item.input_audio_transcription.completed"),
    ...transcriptionEventShape,
    transcript: z.string(),
  }),
  z.object({
    type: z.literal("response.output_audio_transcript.delta"),
    ...outputTranscriptionEventShape,
    delta: z.string(),
  }),
  z.object({
    type: z.literal("response.output_audio_transcript.done"),
    ...outputTranscriptionEventShape,
    transcript: z.string(),
  }),
  z.object({ type: z.literal("response.done") }),
]);

function parseRealtimeServerEvent(
  message: string
): z.infer<typeof realtimeServerEventSchema> | null {
  let event: unknown;
  try {
    event = JSON.parse(message);
  } catch {
    return null;
  }
  const parsed = realtimeServerEventSchema.safeParse(event);
  return parsed.success ? parsed.data : null;
}

function createRealtimeEventHandler(
  publish: (message: string) => void
): (message: string) => void {
  const assistantTranscripts = new Map<string, string>();
  const userTranscripts = new Map<string, string>();
  const publishState = (state: "listening" | "processing" | "speaking") => {
    publish(
      JSON.stringify({
        channel: VOICE_CONVERSATION_LIVE_EVENT_CHANNEL,
        type: "state",
        state,
      })
    );
  };
  const publishTurn = (role: "user" | "assistant", text: string) => {
    const normalized = text.trim();
    if (!normalized) return;
    publish(
      JSON.stringify({
        channel: VOICE_CONVERSATION_LIVE_EVENT_CHANNEL,
        type: "turn",
        role,
        text: normalized,
      })
    );
  };

  return (message) => {
    const event = parseRealtimeServerEvent(message);
    if (!event) return;

    if (event.type === "input_audio_buffer.speech_started") {
      publishState("listening");
      return;
    }
    if (
      event.type === "input_audio_buffer.speech_stopped" ||
      event.type === "response.created"
    ) {
      publishState("processing");
      return;
    }
    if (
      event.type === "response.output_audio.delta" ||
      event.type === "response.output_audio_transcript.delta"
    ) {
      publishState("speaking");
    }

    if (event.type === "conversation.item.input_audio_transcription.delta") {
      const key = `${event.item_id}:${event.content_index}`;
      userTranscripts.set(
        key,
        `${userTranscripts.get(key) ?? ""}${event.delta}`
      );
      return;
    }
    if (
      event.type === "conversation.item.input_audio_transcription.completed"
    ) {
      const key = `${event.item_id}:${event.content_index}`;
      publishTurn("user", event.transcript);
      userTranscripts.delete(key);
      return;
    }
    if (event.type === "response.output_audio_transcript.delta") {
      const key = `${event.response_id}:${event.item_id}:${event.content_index}`;
      assistantTranscripts.set(
        key,
        `${assistantTranscripts.get(key) ?? ""}${event.delta}`
      );
      return;
    }
    if (event.type === "response.output_audio_transcript.done") {
      const key = `${event.response_id}:${event.item_id}:${event.content_index}`;
      publishTurn("assistant", event.transcript);
      assistantTranscripts.delete(key);
      return;
    }
    if (event.type === "response.done") {
      for (const text of assistantTranscripts.values()) {
        publishTurn("assistant", text);
      }
      assistantTranscripts.clear();
      publishState("listening");
    }
  };
}

function serializeRealtimeClientEvent(event: RealtimeClientEvent): string {
  return JSON.stringify(event);
}

const openAISessionUpdate = serializeRealtimeClientEvent({
  type: "session.update",
  session: {
    type: "realtime",
    audio: {
      input: {
        transcription: { model: "gpt-4o-mini-transcribe" },
      },
    },
  },
});

export function openAIVoiceAvailable(): boolean {
  return (
    typeof RTCPeerConnection === "function" &&
    typeof mediaDevices.getUserMedia === "function"
  );
}

export async function startOpenAIVoiceSession(
  response: VoiceSessionResponse
): Promise<VoiceSession> {
  const configured = requireOpenAISession(response);
  if (!openAIVoiceAvailable()) {
    throw new OpenAIVoiceSessionError(
      "OpenAI voice is not available in this build."
    );
  }

  const { AudioSession } = await import("@livekit/react-native");
  const peerConnection = new RTCPeerConnection();
  const dataChannel = peerConnection.createDataChannel("oai-events");
  let localStream: Awaited<
    ReturnType<typeof mediaDevices.getUserMedia>
  > | null = null;
  let dataListener: VoiceDataListener | null = null;
  let audioSessionStarted = false;
  let stopped = false;
  const handleRealtimeEvent = createRealtimeEventHandler((message) => {
    dataListener?.(message);
  });

  const sendSessionUpdate = () => {
    if (stopped || dataChannel.readyState !== "open") return;
    dataChannel.send(openAISessionUpdate);
  };

  const teardown = async () => {
    dataChannel.onopen = null;
    dataChannel.onmessage = null;
    peerConnection.ontrack = null;
    try {
      dataChannel.close();
    } catch {
      // The channel can already be closed after an interrupted negotiation.
    }
    localStream?.getTracks().forEach((track) => track.stop());
    localStream = null;
    try {
      peerConnection.close();
    } catch {
      // Closing an already-closed peer connection is harmless.
    }
    if (audioSessionStarted) {
      await AudioSession.stopAudioSession().catch(() => undefined);
      audioSessionStarted = false;
    }
  };

  dataChannel.addEventListener("open", sendSessionUpdate);
  dataChannel.addEventListener("message", (event) => {
    const message = dataChannelMessageText(event.data);
    if (message) handleRealtimeEvent(message);
  });
  peerConnection.addEventListener("track", (event) => {
    if (!event.track || event.track.kind !== "audio") return;
    event.track.enabled = true;
    // TODO(verify): confirm @livekit/react-native-webrtc automatically renders
    // this enabled remote audio track once the LiveKit audio session is active.
  });

  try {
    // TODO(verify): confirm the shared LiveKit audio session provides the desired
    // iOS/Android speaker, Bluetooth, and interruption behavior for direct WebRTC.
    await AudioSession.startAudioSession();
    audioSessionStarted = true;
    localStream = await mediaDevices.getUserMedia({ audio: true });
    for (const track of localStream.getAudioTracks()) {
      peerConnection.addTrack(track, localStream);
    }

    const offer = await peerConnection.createOffer();
    await peerConnection.setLocalDescription(offer);
    if (!offer.sdp) {
      throw new OpenAIVoiceSessionError(
        "OpenAI voice could not create a WebRTC offer."
      );
    }

    // TODO(verify): validate whether the native stack needs ICE gathering to
    // complete before this non-trickle SDP exchange is sent on both platforms.
    const answerResponse = await fetch(configured.transport.url, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${configured.token}`,
        "Content-Type": "application/sdp",
      },
      body: offer.sdp,
    });
    const answerSdp = await answerResponse.text();
    if (!answerResponse.ok) {
      throw new OpenAIVoiceSessionError(
        `OpenAI voice call setup failed (${answerResponse.status}).`
      );
    }
    if (!answerSdp.trim()) {
      throw new OpenAIVoiceSessionError(
        "OpenAI voice call setup returned an empty SDP answer."
      );
    }
    await peerConnection.setRemoteDescription({
      type: "answer",
      sdp: answerSdp,
    });
    sendSessionUpdate();
  } catch (error) {
    stopped = true;
    await teardown();
    throw error instanceof OpenAIVoiceSessionError
      ? error
      : new OpenAIVoiceSessionError(
          error instanceof Error
            ? error.message
            : "OpenAI voice conversation failed to start.",
          error
        );
  }

  return {
    sessionId: configured.sessionId,
    transport: "openai",
    roomName: configured.roomName,
    watchAudioLevel: () => () => undefined,
    watchData(listener) {
      dataListener = listener;
      return () => {
        if (dataListener === listener) dataListener = null;
      };
    },
    stop: async () => {
      if (stopped) return;
      stopped = true;
      await teardown();
    },
  };
}

import { existsSync, readFileSync, realpathSync, statSync } from "node:fs";
import { createRequire } from "node:module";
import path from "node:path";
import process from "node:process";
import type { MetroConfig } from "expo/metro-config";
import { afterEach, describe, expect, it } from "vitest";

const require = createRequire(import.meta.url);
const metroConfigPath = require.resolve("../../metro.config.js");
const requireFromExpo = createRequire(require.resolve("expo/metro-config"));
const { resolve: metroResolve } = requireFromExpo("metro-resolver");
const clientRoot = path.resolve(import.meta.dirname, "../..");
const originModulePath = path.join(
  clientRoot,
  "src/platform-contracts/metro-config.test.ts"
);
const originalExpoOs = process.env.EXPO_OS;
const originalExpoPlatform = process.env.EXPO_PLATFORM;
const originalPublicCacheProbe = process.env.EXPO_PUBLIC_RENDERER_CACHE_PROBE;

type ResolverContext = Parameters<
  NonNullable<MetroConfig["resolver"]["resolveRequest"]>
>[0];

function loadMetroConfig(platform = "web"): MetroConfig {
  delete require.cache[metroConfigPath];
  process.env.EXPO_OS = platform;
  delete process.env.EXPO_PLATFORM;
  return require("../../metro.config.js");
}

function readPackageJson(packageJsonPath: string) {
  try {
    return JSON.parse(readFileSync(packageJsonPath, "utf8"));
  } catch {
    return null;
  }
}

function packageForModule(absoluteModulePath: string) {
  let packageRoot = absoluteModulePath;
  while (true) {
    const packageJsonPath = path.join(packageRoot, "package.json");
    const packageJson = readPackageJson(packageJsonPath);
    if (packageJson) {
      return {
        packageJson,
        packageRelativePath: path.relative(packageRoot, absoluteModulePath),
        rootPath: packageRoot,
      };
    }
    if (path.basename(packageRoot) === "node_modules") return null;
    const parent = path.dirname(packageRoot);
    if (parent === packageRoot) return null;
    packageRoot = parent;
  }
}

function createResolverContext(config: MetroConfig): ResolverContext {
  const resolver = config.resolver;
  const resolveRequest = resolver.resolveRequest;
  if (!resolveRequest) throw new Error("Metro resolver chain is missing");
  return {
    allowHaste: false,
    assetExts: new Set(resolver.assetExts),
    customResolverOptions: {},
    disableHierarchicalLookup: false,
    doesFileExist: existsSync,
    dev: false,
    extraNodeModules: resolver.extraNodeModules,
    fileSystemLookup(filePath) {
      try {
        const stats = statSync(filePath);
        return {
          exists: true,
          type: stats.isFile() ? "f" : "d",
          realPath: realpathSync(filePath),
        };
      } catch {
        return { exists: false };
      }
    },
    getPackage: readPackageJson,
    getPackageForModule: packageForModule,
    mainFields: resolver.resolverMainFields,
    nodeModulesPaths: resolver.nodeModulesPaths,
    originModulePath,
    preferNativePlatform: false,
    redirectModulePath: (modulePath) => modulePath,
    resolveAsset: () => null,
    resolveHasteModule: () => null,
    resolveHastePackage: () => null,
    resolveRequest,
    sourceExts: resolver.sourceExts,
    unstable_conditionNames: resolver.unstable_conditionNames,
    unstable_conditionsByPlatform: resolver.unstable_conditionsByPlatform,
    unstable_enablePackageExports: resolver.unstable_enablePackageExports,
    unstable_incrementalResolution: resolver.unstable_incrementalResolution,
    unstable_logWarning: () => undefined,
  };
}

function resolvePrimary(config: MetroConfig): string {
  const resolution = metroResolve(
    createResolverContext(config),
    "./primary",
    "web"
  );
  if (resolution.type !== "sourceFile") {
    throw new Error(`Unexpected Metro resolution: ${resolution.type}`);
  }
  return resolution.filePath;
}

afterEach(() => {
  delete require.cache[metroConfigPath];
  if (originalExpoOs === undefined) delete process.env.EXPO_OS;
  else process.env.EXPO_OS = originalExpoOs;
  if (originalExpoPlatform === undefined) delete process.env.EXPO_PLATFORM;
  else process.env.EXPO_PLATFORM = originalExpoPlatform;
  if (originalPublicCacheProbe === undefined)
    delete process.env.EXPO_PUBLIC_RENDERER_CACHE_PROBE;
  else process.env.EXPO_PUBLIC_RENDERER_CACHE_PROBE = originalPublicCacheProbe;
});

describe("Metro renderer targets", () => {
  it("uses React Native's asset registry for native bundles", () => {
    const config = loadMetroConfig("ios");
    const assetRegistryPath = require.resolve("react-native/asset-registry");

    expect(config.transformer.assetRegistryPath).toBe(assetRegistryPath);
    expect(
      config.resolver.resolveRequest?.(
        createResolverContext(config),
        "@react-native/assets-registry/registry",
        "ios"
      )
    ).toEqual({ type: "sourceFile", filePath: assetRegistryPath });
  });

  it("defaults to browser resolution while keeping Metro on web", () => {
    const config = loadMetroConfig();

    expect(config.resolver.sourceExts.slice(0, 4)).toEqual([
      "web.tsx",
      "web.ts",
      "web.jsx",
      "web.js",
    ]);
    expect(
      config.resolver.platforms.filter((platform) =>
        ["web", "desktop"].includes(platform)
      )
    ).toEqual(["web"]);
    expect(resolvePrimary(config)).toMatch(/primary\.web\.ts$/);
  });

  it("changes the cache namespace when public build inputs change", () => {
    process.env.EXPO_PUBLIC_RENDERER_CACHE_PROBE = "first";
    const first = loadMetroConfig();
    process.env.EXPO_PUBLIC_RENDERER_CACHE_PROBE = "second";
    const second = loadMetroConfig();
    const secondAgain = loadMetroConfig();

    expect(second.cacheVersion).not.toBe(first.cacheVersion);
    expect(secondAgain.cacheVersion).toBe(second.cacheVersion);
  });

  it("resolves universal Expo UI and forced-source packages", () => {
    const config = loadMetroConfig();
    const context = createResolverContext(config);
    expect(metroResolve(context, "@expo/ui", "web")).toEqual({
      type: "sourceFile",
      filePath: expect.stringMatching(
        /@expo\/ui\/build\/universal\/index\.js$/
      ),
    });
    expect(metroResolve(context, "@clerk/expo", "web")).toEqual({
      type: "sourceFile",
      filePath: require.resolve("@clerk/expo"),
    });
  });
});

