type ChatAttachmentAcceptanceInput = Pick<
  Parameters<typeof resolveChatAttachmentAcceptance>[0],
  "mode" | "modalities" | "execution"
> & { chatAttachmentCount: number };

type ChatAttachmentAcceptanceState = {
  acceptance: ChatAttachmentAcceptance;
  accepted: boolean;
  warning: ChatAttachmentRefusalReason | null;
};

function chatComposerMachineRoute(machineAgent: MachineAgentRouteState) {
  switch (machineAgent.kind) {
    case "inactive":
      return { kind: "model" as const };
    case "active":
      return { kind: "machine" as const };
    case "unpaired":
      return {
        kind: "blocked" as const,
        title: "Machine unpaired",
        reason: UNPAIRED_MACHINE_TURN_BLOCKED_REASON,
      };
    case "problem":
      return {
        kind: "blocked" as const,
        title: machineAgent.title,
        reason: machineAgent.body,
      };
  }
}

function useChatAttachmentAcceptance({
  mode,
  modalities,
  execution,
  chatAttachmentCount,
}: ChatAttachmentAcceptanceInput): ChatAttachmentAcceptanceState {
  const acceptance = useMemo(
    () =>
      resolveChatAttachmentAcceptance({
        mode,
        modalities,
        execution,
      }),
    [execution, mode, modalities]
  );
  return {
    acceptance,
    accepted: acceptance.kind === "accepted",
    warning:
      mode === "chat" &&
      chatAttachmentCount > 0 &&
      acceptance.kind === "refused"
        ? acceptance.reason
        : null,
  };
}

