    models,
    localAvailability,
    select: selectModel,
  } = model;
  const { availability: voiceConversationAvailability } = voice;
  const selectedChatExecution =
    nextTurn?.kind === "chat"
      ? nextTurn.execution
      : ({ kind: "model" } as const);
  const {
    composerRef,
    timelineRef,
    submitError,
    setSubmitError,
    dismissSubmitError,
    promptComposition: promptCompositionOverride,
    applyPromptComposition,
    thinkingMode: selectedThinkingMode,
    selectThinkingMode: handleThinkingModeChange,
  } = composer;
  const queryClient = useQueryClient();
  const { baseURL } = useApi();
  const chatToolCapabilities = useChatToolCapabilities();
  const agentRuntimeConfig = useAgentRuntimeConfig();
  const saveAgentRuntimeConfig = useSaveAgentRuntimeConfig();
  const workspaceStatus = useWorkspaceStatus({
    enabled: conversation.binding.kind === "model",
  });
  const machineProjectCwd =
    conversation.binding.kind === "machine"
      ? conversation.binding.cwd
