  const machineProject = useQuery(
    api.machineProjects.getForMachineCwd,
    activeMachineId && machineProjectCwd !== undefined
      ? { machineId: activeMachineId, cwd: machineProjectCwd }
      : "skip"
  );
  const { valuesFor: imageValuesFor, setValue: setImageDefaultValue } =
    useImageDefaults();
  const skills = useSkills();
  const [picked, setPicked] = useState<PickedImage | null>(null);
  const [chatAttachments, setChatAttachments] = useState<PickedImage[]>([]);
  const recoveredPendingChatImageKeysRef = useRef<Set<string>>(new Set());
  const clearChatAttachments = useCallback(() => {
    setChatAttachments([]);
  }, []);
  const dismissComposerKeyboard = useCallback(() => {
    if (Platform.OS === "web") return;
    composerRef.current?.blur();
    void KeyboardController.dismiss({ animated: true });
  }, [composerRef]);
  const selectedChatTarget = nextTurn?.kind === "chat" ? nextTurn : null;
  const capabilityRow = composerCapabilityRowForMode(
    mode,
    selectedChatTarget?.runtime.kind === "local" ? "local" : "service"
  );
  const selectedImageTarget = nextTurn?.kind === "image" ? nextTurn : null;
  const selectedImageDraft = useMemo(() => {
    if (!selectedImageTarget) return null;
