  const promptSkills = useMemo(
    () =>
      (skills.data?.skills ?? []).filter((skill) =>
        skill.tags.includes("prompt")
      ),
    [skills.data]
  );
  const defaultPromptComposition = useMemo(
    () => promptCompositionFromAgentConfig(agentRuntimeConfig.data),
    [agentRuntimeConfig.data]
  );
  const promptComposition =
    promptCompositionOverride ?? defaultPromptComposition;
  const saveAgentRuntimeConfigMutate = saveAgentRuntimeConfig.mutate;
  const handleToolScopeSelect = useCallback(
    (toolMode: AgentToolMode) => {
      const current = agentRuntimeConfig.data;
