export function useConversationVoiceSession() {
  const {
    conversation,
    voice: { target: voiceTarget, availability: voiceConversationAvailability },
  } = useConversationRuntime();
  const conversationId = conversation.conversation.conversationId;
  const router = useRouter();
  const { runtime, stop, dismissVoiceNotice } = useVoiceSession();
  const handleStartVoiceConversation = useCallback(() => {
    if (!voiceTarget) return Promise.resolve();
    router.push({
      pathname: "/conversations/[conversationId]/voice",
      params: { conversationId },
    });
    return Promise.resolve();
  }, [conversationId, router, voiceTarget]);
  const voiceSessionInProgress =
    runtime.kind === "starting" ||
    runtime.kind === "listening" ||
    runtime.kind === "processing" ||
    runtime.kind === "speaking";
  useEffect(() => {
    if (!voiceTarget && voiceSessionInProgress) {
      void stop();
    }
  }, [stop, voiceSessionInProgress, voiceTarget]);
  const notice =
    runtime.kind === "error" || runtime.kind === "unavailable"
      ? runtime.notice
      : null;

  return {
    runtime,
    enabled: voiceTarget !== null,
    handleStartVoiceConversation,
    handleEndVoiceConversation: stop,
    dismissVoiceNotice,
    notice,
    voiceConversationAvailability,
  };
}

