import {
  readTimelineEntryMetadata,
  type TimelineMessage,
} from "@/lib/chat-message-meta";
import { conversationMessagesFromUi } from "@/lib/conversation-message-adapter";
import type {
  ConversationChange,
  ConversationMessageDraft,
  GenerationDraft,
  ThreadRows,
} from "@/lib/conversation-convex-types";

function canonicalDurableJson(value: unknown): string {
  if (Array.isArray(value)) {
    return `[${value.map(canonicalDurableJson).join(",")}]`;
  }
  if (value && typeof value === "object") {
    const entries = Object.entries(value)
      .filter(([, entry]) => entry !== undefined)
      .sort(([left], [right]) => left.localeCompare(right));
    return `{${entries
      .map(
        ([key, entry]) =>
          `${JSON.stringify(key)}:${canonicalDurableJson(entry)}`
      )
      .join(",")}}`;
  }
  return JSON.stringify(value) ?? "null";
}

const storedSignatures = new WeakMap<object, string>();

function storedSignature(stored: object): string {
  const cached = storedSignatures.get(stored);
  if (cached !== undefined) return cached;
  const signature = canonicalDurableJson(stored);
  storedSignatures.set(stored, signature);
  return signature;
}

const draftSignatures = new WeakMap<
  object,
  { sequence: number; signature: string }
>();

function draftSignature(draft: object, sequence: number): string {
  const cached = draftSignatures.get(draft);
  if (cached !== undefined && cached.sequence === sequence) {
    return cached.signature;
  }
  const signature = canonicalDurableJson({ ...draft, sequence });
  draftSignatures.set(draft, { sequence, signature });
  return signature;
}

const confirmedDrafts = new WeakMap<object, object>();

function alreadyStored(stored: object, draft: object, sequence: number) {
  if (confirmedDrafts.get(stored) === draft) return true;
  if (storedSignature(stored) !== draftSignature(draft, sequence)) return false;
  confirmedDrafts.set(stored, draft);
  return true;
}

const namelessGenerations = new WeakMap<object, object>();

function generationWithoutName<T extends { name?: string }>(generation: T) {
  const cached = namelessGenerations.get(generation);
  if (cached !== undefined) return cached;
  const { name: _name, ...rest } = generation;
  namelessGenerations.set(generation, rest);
  return rest;
}

const messageDraftCache = new WeakMap<
  TimelineMessage,
  ConversationMessageDraft | null
>();

export function timelineMessageDrafts(
  messages: readonly TimelineMessage[]
): ConversationMessageDraft[] {
  const drafts: ConversationMessageDraft[] = [];
  for (const message of messages) {
    const cached = messageDraftCache.get(message);
    if (cached !== undefined) {
      if (cached) drafts.push(cached);
      continue;
    }
    const [draft] = conversationMessagesFromUi([message]);
    if (draft) drafts.push(draft);
    if (readTimelineEntryMetadata(message)) {
      messageDraftCache.set(message, draft ?? null);
    }
  }
  return drafts;
}

type TimelineDurabilityInput = {
  storedRows: ThreadRows;
  messageDrafts: readonly ConversationMessageDraft[];
  generationDrafts: readonly GenerationDraft[];
};

export function conversationTimelineChanges({
  storedRows,
  messageDrafts,
  generationDrafts,
}: TimelineDurabilityInput): ConversationChange[] {
  const changes: ConversationChange[] = [];
  const messageIds = new Set(messageDrafts.map((draft) => draft.messageId));
  const storedMessages = new Map(
    storedRows.flatMap((row) =>
      row.kind === "message" && row.source.kind === "conversation"
        ? [[row.message.messageId, row.message] as const]
        : []
    )
  );
  for (const message of storedMessages.values()) {
    if (messageIds.has(message.messageId)) continue;
    changes.push({ type: "message.remove", messageId: message.messageId });
  }
  for (const message of messageDrafts) {
    const existing = storedMessages.get(message.messageId);
    if (existing && alreadyStored(existing, message, existing.sequence)) {
      continue;
    }
    changes.push({ type: "message.put", message });
  }
  const generationIds = new Set(
    generationDrafts.map((draft) => draft.generationId)
  );
  const storedGenerations = new Map(
    storedRows.flatMap((row) =>
      row.kind === "generation"
        ? [[row.generation.generationId, row.generation] as const]
        : []
    )
  );
  for (const generation of storedGenerations.values()) {
    if (generationIds.has(generation.generationId)) continue;
    changes.push({
      type: "generation.remove",
      generationId: generation.generationId,
    });
  }
  for (const generation of generationDrafts) {
    const existing = storedGenerations.get(generation.generationId);
    if (
      existing &&
      alreadyStored(
        generationWithoutName(existing),
        generationWithoutName(generation),
        existing.sequence
      )
    ) {
      continue;
    }
    changes.push({ type: "generation.put", generation });
  }
  return changes;
}

export type MachineScannerPermission = {
  granted: boolean;
  canAskAgain: boolean;
};

export type MachineScannerAdapter = {
  permission: "camera" | "notRequired";
  isSupported(): boolean;
  getPermission?(): Promise<MachineScannerPermission>;
  requestPermission?(): Promise<MachineScannerPermission>;
  isLaunchCancellation?(error: unknown): boolean;
  subscribe(listener: (value: string) => void): { remove(): void };
  launch(): Promise<void>;
  dismiss(): Promise<void>;
};

type MachineScannerStartResult =
  | { kind: "presented" }
  | { kind: "cancelled" }
  | { kind: "unsupported" }
  | { kind: "permissionDenied"; canAskAgain: boolean }
  | { kind: "launchFailed"; message: string };

type MachineScannerSessionOptions = {
  adapter: MachineScannerAdapter;
  isValid: (value: string) => boolean;
  onAccepted: (value: string) => void;
};

export function createMachineScannerSession({
  adapter,
  isValid,
  onAccepted,
}: MachineScannerSessionOptions) {
  let accepted = false;
  let active = false;
  let disposed = false;
  let subscription: { remove(): void } | null = null;
  let currentStartRequest: symbol | null = null;

  const cleanup = async () => {
    if (!active) return;
    active = false;
    const activeSubscription = subscription;
    subscription = null;
    activeSubscription?.remove();
    await adapter.dismiss().catch(() => undefined);
  };

  return {
    async start(): Promise<MachineScannerStartResult> {
      if (disposed || !adapter.isSupported()) {
        return { kind: "unsupported" };
      }
      if (active) {
        return { kind: "presented" };
      }
      const startRequest = Symbol();
      currentStartRequest = startRequest;
      const cancelled = () => disposed || currentStartRequest !== startRequest;
      try {
        if (adapter.permission === "camera") {
          let permission = adapter.getPermission
            ? await adapter.getPermission()
            : { granted: false, canAskAgain: false };
          if (cancelled()) return { kind: "cancelled" };
          if (
            !permission.granted &&
            permission.canAskAgain &&
            adapter.requestPermission
          ) {
            permission = await adapter.requestPermission();
            if (cancelled()) return { kind: "cancelled" };
          }
          if (!permission.granted) {
            currentStartRequest = null;
            return {
              kind: "permissionDenied",
              canAskAgain: permission.canAskAgain,
            };
          }
        }
        if (cancelled()) return { kind: "cancelled" };
        accepted = false;
        subscription = adapter.subscribe((value) => {
          if (accepted || !isValid(value)) return;
          accepted = true;
          void cleanup().then(() => {
            if (!cancelled()) onAccepted(value);
          });
        });
        active = true;
        await adapter.launch();
        if (cancelled()) {
          await cleanup();
          return { kind: "cancelled" };
        }
        return { kind: "presented" };
      } catch (error) {
        if (cancelled() || adapter.isLaunchCancellation?.(error)) {
          currentStartRequest = null;
          await cleanup();
          return { kind: "cancelled" };
        }
        currentStartRequest = null;
        await cleanup();
        return {
          kind: "launchFailed",
          message: "The QR scanner could not be opened.",
        };
      }
    },
    async cancel(): Promise<void> {
      currentStartRequest = null;
      await cleanup();
    },
    async dispose(): Promise<void> {
      disposed = true;
      currentStartRequest = null;
      await cleanup();
    },
  };
}

