export function useConversationThreadActions() {
  const removeConversation = useConvexMutation(convexApi.conversations.remove);
  const [target, setTarget] = useState<ConversationThreadActionTarget | null>(
    null
  );
  const [removeError, setRemoveError] = useState<string | null>(null);
  const close = useCallback(() => setTarget(null), []);
  const open = useCallback((nextTarget: ConversationThreadActionTarget) => {
    hapticTick("medium");
    setTarget(nextTarget);
  }, []);
  const runRemove = useCallback(
    (conversationId: ConversationId) => {
      setRemoveError(null);
      void removeConversation({ conversationId }).catch(() => {
        setRemoveError("Couldn't remove thread. Try again.");
      });
    },
    [removeConversation]
  );
  const confirmRemove = useCallback(
    (conversationId: ConversationId) => {
      confirmDestructive({
        title: "Remove thread?",
        message: "Its history stays on the Machine.",
        confirmLabel: "Remove",
        onConfirm: () => {
          runRemove(conversationId);
          close();
        },
        onCancel: close,
      });
    },
    [close, runRemove]
  );
  const remove = useCallback(() => {
    if (!target) return;
    hapticTick("light");
    confirmRemove(target.conversationId);
  }, [confirmRemove, target]);
  return {
    open,
    removeError,
    overlay: (
      <ConversationThreadActionsMenu
        target={target}
        onClose={close}
        onRemove={remove}
      />
    ),
  };
}

function ConversationThreadActionsMenu({
  target,
  onClose,
  onRemove,
}: {
  target: ConversationThreadActionTarget | null;
  onClose: () => void;
  onRemove: () => void;
}) {
  const { height } = useWindowDimensions();
  if (!target) return null;

  const menuTop = Math.min(Math.max(target.pageY - 20, 120), height - 220);

  return (
    <Modal transparent animationType="fade" onRequestClose={onClose}>
      <Touchable
        feedback="none"
        accessibilityLabel="dismiss thread menu"
        className="flex-1"
        onPress={onClose}
      >
        <SelectorPopoverFrame
          testID="homer-conversations-thread-menu"
          accessibilityLabel="thread actions"
          accessibilityRole="menu"
          material="chrome"
          className="absolute left-[25px] w-56 gap-0.5 rounded-2xl border p-1.5"
          style={{
            top: menuTop,
            borderCurve: "continuous",
            boxShadow:
              "0 2px 6px rgb(0 0 0 / 0.06), 0 12px 32px -4px rgb(0 0 0 / 0.14)",
          }}
        >
          <ThreadActionItem
            icon="trash"
            label="Remove"
            destructive
            onPress={onRemove}
          />
        </SelectorPopoverFrame>
      </Touchable>
    </Modal>
  );
}

function ThreadActionItem({
  icon,
  label,
  destructive = false,
  onPress,
}: {
  icon: IconName;
  label: string;
  destructive?: boolean;
  onPress: () => void;
}) {
  const { colors } = useThemeMode();
  const color = destructive ? colors.danger : colors.text;
  return (
    <Touchable
      feedback="highlight"
      accessibilityRole="button"
      accessibilityLabel={label}
      onPress={onPress}
      className="min-h-11 w-full flex-row items-center gap-2.5 rounded-[10px] px-2.5"
      style={{ borderCurve: "continuous" }}
    >
      <Icon name={icon} size={16} color={color} />
      <Text
        className="min-w-0 flex-1 text-[13px]"
        style={{
          color,
          fontFamily: "Geist_500Medium",
        }}
        numberOfLines={1}
      >
        {label}
      </Text>
    </Touchable>
  );
}

