export type ConversationsScope =
  | { kind: "all" }
  | { kind: "machine"; machineId: MachineId; machine: MachineView | null }
  | { kind: "project"; project: MachineProject };

type ConversationsSurfaceProps = {
  scope: ConversationsScope;
  canonicalMachines: readonly MachineView[];
} & ConversationListControls;

function conversationsScopeTitle(scope: ConversationsScope) {
  switch (scope.kind) {
    case "all":
      return "Conversations";
    case "project":
      return scope.project.displayName;
    case "machine":
      return scope.machine
        ? machineNavigationLabel(scope.machine)
        : scope.machineId;
  }
}

export function ConversationsSurface({
  scope,
  canonicalMachines,
  searchQuery,
  onChangeSearch,
  onNewConversation,
  canStartConversation,
}: ConversationsSurfaceProps) {
  const selectedMachineId = scope.kind === "machine" ? scope.machineId : null;
  const selectedProjectId =
    scope.kind === "project" ? scope.project.projectId : null;
  const title = conversationsScopeTitle(scope);
  const router = useRouter();
  const { bottom } = useSafeAreaInsets();
  const { width } = useWindowDimensions();
  const listMaxWidth = width >= 768 ? 720 : undefined;
  const {
    open: openThreadActions,
    overlay: threadActionsOverlay,
    removeError,
  } = useConversationThreadActions();
  const allMachineConversations = useConvexQuery(
    convexApi.conversations.listAllRows,
    selectedMachineId || selectedProjectId ? "skip" : {}
  );
  const selectedMachineConversations = useConvexQuery(
    convexApi.conversations.listRowsForMachine,
    selectedMachineId ? { machineId: selectedMachineId } : "skip"
  );
  const projectConversations = useConvexQuery(
    convexApi.conversations.listRowsForProject,
    selectedProjectId ? { projectId: selectedProjectId } : "skip"
  );
  let conversationRows = allMachineConversations;
  if (selectedProjectId) {
    conversationRows = projectConversations;
  } else if (selectedMachineId) {
    conversationRows = selectedMachineConversations;
  }
  const visibleItems = useMemo(
    () =>
      conversationRows === undefined
        ? undefined
        : filterConversationListItems(conversationRows, searchQuery),
    [conversationRows, searchQuery]
  );
  const renderListItem = useCallback(
    ({ item }: LegendListRenderItemProps<ConversationListRow>) => {
      return (
        <ConversationFeedRow
          row={item}
          scope={scope}
          onPress={() => {
            hapticTick("light");
            router.push({
              pathname: "/conversations/[conversationId]",
              params: {
                conversationId: item.conversationId,
                ...(selectedProjectId ? { projectId: selectedProjectId } : {}),
              },
            });
          }}
          onLongPress={(pageY) => {
            openThreadActions({
              conversationId: item.conversationId,
              pageY,
            });
          }}
        />
      );
    },
    [openThreadActions, router, scope, selectedProjectId]
  );

  const listHeader = (
    <>
      <MachineNavigationChips
        canonicalMachines={canonicalMachines}
        allSelected={scope.kind === "all"}
        selectedMachineId={selectedMachineId}
      />

      {removeError ? (
        <View className="mb-3">
          <ProblemCard
            testID="homer-conversations-remove-error"
            title="Thread not removed"
            body={removeError}
            danger
          />
        </View>
      ) : null}

      {canonicalMachines.length === 0 ? (
        <View className="mb-3">
          <AddMachineCard
            onPress={() => {
              hapticTick("light");
              router.push(connectMachineHref());
            }}
          />
        </View>
      ) : null}
    </>
  );
  const listEmpty = (
    <ProblemCard
      testID="homer-conversations-empty"
      title={
        searchQuery.trim()
          ? "No matching conversations"
          : "No conversations yet"
      }
      body={
        searchQuery.trim()
          ? "Try another title, Machine, agent, or status."
          : selectedProjectId
            ? "Conversations created in this project will show up here."
            : selectedMachineId
              ? "Conversations created on this Machine will show up here."
              : "Conversations started with a model or on a Machine will show up here."
      }
    />
  );
  // LegendList's web build renders raw DOM nodes instead of react-native-web
  // hosts, so React Native props reach the div verbatim. Give web the DOM
  // spelling of the selector and keep the native-only props off it.
  const listPlatformProps =
    Platform.OS === "web"
      ? { "data-testid": "homer-conversations-list" }
      : ({
          accessible: false,
          contentInsetAdjustmentBehavior: "automatic",
          testID: "homer-conversations-list",
        } as const);
  const list = visibleItems && (
    <LegendList
      {...listPlatformProps}
      data={visibleItems}
      keyExtractor={(item) => item.key}
      getItemType={(item) => item.kind}
      renderItem={renderListItem}
      estimatedItemSize={59}
      recycleItems
      alignItemsAtEnd={false}
      ListHeaderComponent={listHeader}
      ListEmptyComponent={listEmpty}
      contentContainerStyle={{
        paddingBottom:
          Platform.OS === "ios"
            ? 16
            : CONVERSATIONS_FALLBACK_DOCK_RESERVE + bottom,
      }}
      style={{
        alignSelf: "center",
        flex: 1,
        maxWidth: listMaxWidth,
        width: "100%",
      }}
    />
  );

  return (
    <ThreadListScaffold
      showSearchControl={selectedProjectId !== null}
      title={title}
      searchQuery={searchQuery}
      onChangeSearch={onChangeSearch}
      onNewConversation={onNewConversation}
      canStartConversation={canStartConversation}
    >
      {list}
      {threadActionsOverlay}
    </ThreadListScaffold>
  );
}

import { useCallback, useEffect, useRef, useState } from "react";
import {
  useMutation as useConvexMutation,
  useQuery as useConvexQuery,
} from "convex/react";
import { api as convexApi } from "../../convex/_generated/api";
import { MediaViewerHeader } from "./media-viewer-header";
import { GenerationRenameSheet } from "./media-viewer-rename";
import {
  generationNameFromQuery,
  mediaViewerShareTitle,
  mediaViewerTitle,
  saveGenerationNameWhenPresent,
} from "./media-viewer-state";

export function useMediaViewerGenerationName({
  conversationId,
  generationId,
}: {
  conversationId: string;
  generationId: string;
}) {
  const dispatchConversationChange = useConvexMutation(
    convexApi.conversations.dispatch
  );
  const row = useConvexQuery(convexApi.conversations.getGenerationName, {
    conversationId,
    generationId,
  });
  const rowRef = useRef(row);
  useEffect(() => {
    rowRef.current = row;
  }, [row]);
  const persisted = generationNameFromQuery(row);
  const persistedName = persisted.found ? persisted.name : null;
  const title = persisted.loaded ? mediaViewerTitle(persistedName) : "";
  const contentName = persistedName;
  const shareName = persistedName;
  const persistRename = useCallback(
    async (name: string) => {
      await saveGenerationNameWhenPresent({
        readRow: () => rowRef.current,
        rename: (nextName) =>
          dispatchConversationChange({
            conversationId,
            change: {
              type: "generation.rename",
              generationId,
              name: nextName,
            },
          }),
        name,
      });
    },
    [conversationId, dispatchConversationChange, generationId]
  );

  return { title, contentName, shareName, persistRename };
}

export function MediaViewerNamingOverlay({
  title,
  shareName,
  persistRename,
  showHeader,
  canShare,
  onClose,
  onShare,
}: {
  title: string;
  shareName?: string | null;
  persistRename: (name: string) => Promise<void>;
  showHeader: boolean;
  canShare: boolean;
  onClose: () => void;
  onShare: (title?: string) => void;
}) {
  const [renameOpen, setRenameOpen] = useState(false);

  return (
    <>
      {showHeader ? (
        <MediaViewerHeader
          title={title}
          canShare={canShare}
          onClose={onClose}
          onShare={() => onShare(mediaViewerShareTitle(shareName))}
          onRename={() => setRenameOpen(true)}
        />
      ) : null}
      <GenerationRenameSheet
        open={renameOpen}
        name={shareName}
        onClose={() => setRenameOpen(false)}
        onSubmit={persistRename}
      />
    </>
  );
}

import { describe, expect, it } from "vitest";
import { endpointHealthState } from "./settings-endpoint-state";

describe("endpointHealthState", () => {
  it("preserves unresolved and runtime readiness states", () => {
    expect(endpointHealthState(undefined)).toBe("checking");
    expect(endpointHealthState({ ready: true })).toBe("online");
    expect(
      endpointHealthState({
        ready: false,
        code: "model_loading",
        message: "Model is loading.",
      })
    ).toBe("loading");
    expect(
      endpointHealthState({
        ready: false,
        code: "backend_unreachable",
        message: "Backend is unreachable.",
      })
    ).toBe("unreachable");
    expect(
      endpointHealthState({
        ready: false,
        code: "backend_not_ready",
        message: "Backend is not ready.",
      })
    ).toBe("not ready");
  });
});

import React from "react";
import {
  StyleSheet,
  type ImageStyle as RNImageStyle,
  type StyleProp,
} from "react-native";
import {
  Image as RNImage,
  type ImageContentFit,
  type ImageContentPositionString,
} from "expo-image";
import { withUniwind } from "uniwind";

type CSSImageStyle = RNImageStyle & {
  objectPosition?: ImageContentPositionString;
};

type CSSImageProps = Omit<
  React.ComponentPropsWithRef<typeof RNImage>,
  "style"
> & {
  className?: string;
  style?: StyleProp<CSSImageStyle>;
};

function contentFit(value: unknown): ImageContentFit | undefined {
  switch (value) {
    case "cover":
    case "contain":
    case "fill":
    case "none":
    case "scale-down":
      return value;
    default:
      return undefined;
  }
}

function contentPosition(
  value: unknown
): ImageContentPositionString | undefined {
  switch (value) {
    case "center":
    case "top":
    case "right":
    case "bottom":
    case "left":
    case "top center":
    case "top right":
    case "top left":
    case "right center":
    case "right top":
    case "right bottom":
    case "bottom center":
    case "bottom right":
    case "bottom left":
    case "left center":
    case "left top":
    case "left bottom":
      return value;
    default:
      return undefined;
  }
}

function CSSImage(props: CSSImageProps) {
  const { className: _className, ...imageProps } = props;
  const flattened = StyleSheet.flatten(props.style) ?? {};
  const styleWithObjectLayout: typeof flattened & {
    objectFit?: unknown;
    objectPosition?: unknown;
  } = flattened;
  const objectFit = contentFit(styleWithObjectLayout.objectFit);
  const objectPosition = contentPosition(styleWithObjectLayout.objectPosition);
  const {
    objectFit: _objectFit,
    objectPosition: _objectPosition,
    ...style
  } = styleWithObjectLayout;
  return (
    <RNImage
      contentFit={objectFit}
      contentPosition={objectPosition}
      {...imageProps}
      source={
        typeof props.source === "string" ? { uri: props.source } : props.source
      }
      style={style}
    />
  );
}

export const Image = withUniwind(CSSImage);

Object.defineProperty(Image, "displayName", { value: "CSS(Image)" });

export type ImageProps = React.ComponentPropsWithRef<typeof Image>;

import {
  Gauge,
  HStack,
  Image,
  ProgressView,
  Spacer,
  Text,
  VStack,
} from "@expo/ui/swift-ui";
import {
  font,
  foregroundStyle,
  frame,
  padding,
} from "@expo/ui/swift-ui/modifiers";
import { createWidget, type WidgetEnvironment } from "expo-widgets";

type ActivityProps = {
  modelName: string | null;
  loadPhase: string | null;
  loadPercent: number | null;
  agentsInFlight: number;
  activeRuntime: string | null;
};

const ACCENT = "#38D0FF";
const WARM = "#E7BC3C";
const MUTED = "#68849E";
const SUCCESS = "#40B882";

function phaseLabel(phase: string | null): string {
  switch (phase) {
    case "service_activating":
      return "Starting";
    case "model_loading":
      return "Loading";
    case "port_binding":
      return "Binding";
    case "http_warming":
      return "Warming";
    case "service_failed":
      return "Failed";
    case "ready":
      return "Ready";
    default:
      return "Idle";
  }
}

function isLoading(phase: string | null): boolean {
  return phase !== null && phase !== "ready" && phase !== "unknown";
}

function isIdle(props: ActivityProps): boolean {
  return (
    !isLoading(props.loadPhase) &&
    props.agentsInFlight === 0 &&
    props.activeRuntime === null
  );
}

// -- Lock screen: circular (gauge or bird icon)
function CircularView(props: ActivityProps) {
  "widget";
  if (isLoading(props.loadPhase)) {
    const pct = props.loadPercent !== null ? props.loadPercent / 100 : 0;
    return (
      <Gauge value={pct} modifiers={[foregroundStyle(WARM)]}>
        <Image
          systemName="cpu"
          modifiers={[font({ size: 10 }), foregroundStyle(WARM)]}
        />
      </Gauge>
    );
  }
  if (props.agentsInFlight > 0) {
    return (
      <VStack modifiers={[frame({ width: 50, height: 50 })]}>
        <Image
          systemName="bird"
          modifiers={[font({ size: 12 }), foregroundStyle(ACCENT)]}
        />
        <Text
          modifiers={[
            font({ design: "rounded", size: 16, weight: "bold" }),
            foregroundStyle(ACCENT),
          ]}
        >
          {String(props.agentsInFlight)}
        </Text>
      </VStack>
    );
  }
  return (
    <VStack modifiers={[frame({ width: 50, height: 50 })]}>
      <Image
        systemName="bird.fill"
        modifiers={[font({ size: 20 }), foregroundStyle(MUTED)]}
      />
    </VStack>
  );
}

// -- Lock screen: rectangular
function RectangularView(props: ActivityProps) {
  "widget";
  return (
    <VStack modifiers={[padding({ all: 4 })]}>
      <HStack>
        <Image
          systemName="bird.fill"
          modifiers={[font({ size: 10 }), foregroundStyle(MUTED)]}
        />
        <Text
          modifiers={[
            font({ design: "monospaced", size: 10, weight: "semibold" }),
            foregroundStyle(MUTED),
          ]}
        >
          HOMER
        </Text>
        <Spacer />
      </HStack>
      {isLoading(props.loadPhase) ? (
        <VStack>
          <Text
            modifiers={[
              font({ design: "rounded", size: 12, weight: "medium" }),
            ]}
          >
            {phaseLabel(props.loadPhase)}
            {props.loadPercent !== null
              ? ` ${Math.round(props.loadPercent)}%`
              : ""}
          </Text>
