function registerCleanup(
  cleanup: () => void | Promise<void>,
  closeWhenCancelled = true
) {
  let cleanupPromise: Promise<void> | undefined;
  const runOnce = () => {
    cleanupPromise ??= Promise.resolve().then(cleanup);
    return cleanupPromise;
  };
  activeCleanups.add(runOnce);
  if (closeWhenCancelled && smokeAbortController.signal.aborted) {
    void runOnce().catch(() => undefined);
  }
  return async () => {
    try {
      await runOnce();
    } finally {
      activeCleanups.delete(runOnce);
    }
  };
}

async function runCleanups(): Promise<void> {
  const failures: unknown[] = [];
  for (const cleanup of [...activeCleanups].reverse()) {
    try {
      await cleanup();
    } catch (error) {
      failures.push(error);
    } finally {
      activeCleanups.delete(cleanup);
    }
  }
  if (failures.length > 0) {
    throw new AggregateError(
      failures,
      "Authenticated desktop smoke cleanup failed"
    );
  }
}

function requestCancellation(exitCode: number): void {
  signalExitCode ??= exitCode;
  smokeAbortController.abort();
}

function waitForCancellation(): Promise<void> {
  if (smokeAbortController.signal.aborted) return Promise.resolve();
  return new Promise((resolve) => {
    smokeAbortController.signal.addEventListener("abort", () => resolve(), {
      once: true,
    });
  });
}

async function finishCancelledSmoke(smokeRun: Promise<void>): Promise<void> {
  const failures: unknown[] = [];
  try {
    await runCleanups();
  } catch (error) {
    failures.push(error);
  }
  await smokeRun.catch(() => undefined);
  try {
    await runCleanups();
  } catch (error) {
    failures.push(error);
  }
  if (failures.length > 0) {
    throw new AggregateError(
      failures,
      "Authenticated desktop smoke cancellation failed"
    );
  }
}

async function waitForExit(child: ReturnType<typeof spawn>): Promise<number> {
  if (child.exitCode !== null) return child.exitCode;
  return new Promise((resolve, reject) => {
    child.once("error", reject);
    child.once("exit", (code, signal) => resolve(code ?? (signal ? 1 : 0)));
  });
}

async function runCommand(args: string[]): Promise<void> {
  smokeAbortController.signal.throwIfAborted();
  const child = spawn(pnpm, args, {
    cwd: desktopRoot,
    detached: process.platform !== "win32",
    env: childEnvironment,
    stdio: "inherit",
  });
  const cleanup = registerCleanup(() => stopDetachedProcessTree(child));
  try {
    const exitCode = await waitForExit(child);
    if (exitCode !== 0) {
      throw new Error(`Authenticated desktop smoke command exited ${exitCode}`);
    }
  } finally {
    await cleanup();
  }
}

function playwrightEvaluate(page: Page): Evaluate {
  return (expression) => page.evaluate(expression);
}
async function waitForExpression(
  evaluate: Evaluate,
  expression: string,
  description: string,
  timeoutMs = 60_000
): Promise<void> {
  const deadline = Date.now() + timeoutMs;
  let lastError: unknown;
  while (Date.now() < deadline) {
    try {
      if ((await evaluate(expression)) === true) return;
      lastError = undefined;
    } catch (error) {
      lastError = error;
    }
    await delay(200);
  }
  let rendererState: unknown;
  try {
    rendererState = await evaluate(rendererStateExpression);
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    const errorOptions =
      lastError === undefined ? undefined : { cause: lastError };
    throw new Error(
      `Timed out waiting for ${description}; renderer state unavailable: ${message}`,
      errorOptions
    );
  }
  const errorOptions =
    lastError === undefined ? undefined : { cause: lastError };
  throw new Error(
    `Timed out waiting for ${description}; renderer state: ${JSON.stringify(rendererState)}`,
    errorOptions
  );
}

