// The error-test-id checks above are absence-of-error, which a request still in
// flight satisfies trivially. This asserts the positive: an authenticated,
// credentialed request leaves the renderer's real origin, is admitted by the
// API's exact-origin CORS, and returns 200 with the origin reflected.
async function assertApiReachable(evaluate: Evaluate): Promise<void> {
  // A cross-origin request the API does not admit is rejected by the
  // renderer before any status is visible, so reaching status 200 at all is the
  // proof that exact-origin CORS admitted this renderer's real origin. The
  // Access-Control-Allow-Origin header itself is deliberately not asserted:
  // browsers never expose it to script, so reading it would always yield null.
  const probe = z
    .object({
      status: z.number().nullable(),
      failure: z.string().nullable(),
      origin: z.string(),
    })
    .strict()
    .parse(
      await evaluate(`(async () => {
        const origin = window.location.origin;
        try {
          const token = await window.Clerk.session.getToken();
          const response = await fetch(
            ${JSON.stringify(childEnvironment.EXPO_PUBLIC_HOMER_BASE_URL)} + "/api/models",
            { headers: { authorization: "Bearer " + token } }
          );
          return { status: response.status, failure: null, origin };
        } catch (error) {
          return { status: null, failure: String(error), origin };
        }
      })()`)
    );
  assert.equal(
    probe.failure,
    null,
    `API request from ${probe.origin} was blocked: ${probe.failure}`
  );
  assert.equal(
    probe.status,
    200,
    `API refused an authenticated request from ${probe.origin}`
  );
}

