  const baseUrl = childEnvironment.EXPO_PUBLIC_HOMER_BASE_URL;
  assert.ok(baseUrl, "Local API origin must be set");
  const continuity = tokenRefreshContinuitySchema.parse(
    await evaluate(`(async () => {
      const session = window.Clerk?.session;
      if (!session) throw new Error("Clerk session is unavailable.");
      const token = await session.getToken({ skipCache: true });
      if (typeof token !== "string" || token.length === 0) {
        return { status: 0, tokenPresent: false };
      }
      const response = await fetch(
        ${JSON.stringify(baseUrl)} + "/api/models",
        { headers: { authorization: "Bearer " + token } }
      );
      return { status: response.status, tokenPresent: true };
    })()`)
  );
  assert.equal(
    continuity.tokenPresent,
    true,
    "Clerk must return a refreshed token"
  );
  assert.equal(
    continuity.status,
    200,
    "A refreshed token must keep the API model catalog reachable"
  );
}

function clerkApiUrl(): string {
  // Clerk's Backend API is hosted at api.clerk.com for both production and
  // development instances. The per-instance frontend host does not change the
  // backend API origin.
  return "https://api.clerk.com";
}

async function fetchClerkBackendJson<T>(
  path: string,
  schema: z.ZodType<T>,
  options: RequestInit = {}
): Promise<T> {
  const secretKey = environment.CLERK_SECRET_KEY;
  const response = await fetch(`${clerkApiUrl()}${path}`, {
    ...options,
    headers: {
      Authorization: `Bearer ${secretKey}`,
      ...(options.headers ?? {}),
    },
  });
  if (!response.ok) {
    const body = await response.text();
    throw new Error(
      `Clerk Backend API ${options.method ?? "GET"} ${path} failed: ${response.status} ${body}`
    );
  }
  const json = await response.json();
  return schema.parse(json);
}

async function revokeOwnedSmokeSession(
  sessionId: string,
  userId: string
): Promise<void> {
  if (environment.authLane === "production-ticket") {
    assert.ok(productionClerkAuth, "Production Clerk auth must be configured");
    if (productionSmokeSession) {
      assert.equal(
        userId,
        productionSmokeSession.userId,
        "Production smoke must be signed in as the sole production user"
      );
    }
    await productionClerkAuth.revokeSession(sessionId, userId);
    productionSmokeSession = undefined;
    return;
  }

  const user = await fetchClerkBackendJson(
    `/v1/users/${userId}`,
    clerkBackendUserSchema
  );
  const primaryEmail = user.email_addresses.find(
    (entry) => entry.email_address === environment.HOMER_E2E_EMAIL
  );
  assert.ok(
    primaryEmail,
    "The E2E email must be present on the Backend API user record"
  );

  const revoked = await fetchClerkBackendJson(
    `/v1/sessions/${sessionId}/revoke`,
    clerkBackendSessionSchema,
    { method: "POST" }
  );
  assert.equal(
    revoked.user_id,
    userId,
    "Backend API must revoke a session belonging to the verified user"
  );
}

