async function signInThroughEvaluate(
  evaluate: Evaluate,
  sendCommand: (
    method: string,
    params?: Record<string, unknown>
  ) => Promise<unknown>
): Promise<void> {
  const clickTestId = async (testId: string) => {
    await waitForVisibleTestId(evaluate, testId);
    await clickVisibleTestIdWithCdp(evaluate, sendCommand, testId);
  };
  smokeAbortController.signal.throwIfAborted();
  await waitForVisibleTestId(evaluate, "homer-auth-screen");
  await clickTestId("homer-auth-get-started");
  try {
    await waitForVisibleTestId(evaluate, "homer-auth-sign-in");
  } catch (error) {
    throw new Error(
      `Sign-in route did not render; renderer state: ${await rendererDiagnostics(evaluate)}`,
      { cause: error }
    );
  }
  assert.equal(await testIdCount(evaluate, "homer-auth-google"), 1);
  await assertElectronOAuthAvailable(evaluate);
  if (environment.authLane === "production-ticket") {
    await signInWithProductionTicket(evaluate);
    return;
  }
  await fillTestId(evaluate, "homer-auth-email", environment.HOMER_E2E_EMAIL);
  await clickTestId("homer-auth-submit");
  await fillTestId(
    evaluate,
    "homer-auth-password",
    environment.HOMER_E2E_PASSWORD
  );
  await clickTestId("homer-auth-submit");
  await waitForExpression(
    evaluate,
    `Boolean(window.Clerk?.user) ||
      Array.from(document.querySelectorAll('[data-testid="homer-auth-code"]')).some(
        (candidate) => candidate.getClientRects().length > 0
      )`,
    "Clerk sign-in or verification step"
  );
  if ((await testIdCount(evaluate, "homer-auth-code")) > 0) {
    const code = environment.HOMER_E2E_CODE;
    if (!code) {
      throw new Error(
        "Clerk requested a verification code; HOMER_E2E_CODE is required."
      );
    }
    await fillTestId(evaluate, "homer-auth-code", code);
    await clickTestId("homer-auth-submit");
  }
}

async function signInThroughPage(page: Page): Promise<void> {
  const evaluate = playwrightEvaluate(page);
  if (environment.authLane === "test-credentials") {
    await assertElectronOAuthAvailable(evaluate);
    await signInBrowser(page, environment);
    return;
  }
  const visible = (testId: string) =>
    page.locator(`[data-testid="${testId}"]:visible`).first();
  await visible("homer-auth-screen").waitFor({ timeout: 60_000 });
  await visible("homer-auth-get-started").click();
  await visible("homer-auth-sign-in").waitFor({ timeout: 30_000 });
  assert.equal(await visible("homer-auth-google").count(), 1);
  await assertElectronOAuthAvailable(evaluate);
  await signInWithProductionTicket(evaluate);
}

async function signInWithProductionTicket(evaluate: Evaluate): Promise<void> {
  assert.ok(productionClerkAuth, "Production Clerk auth must be configured");
  const { ticket, userId } = await productionClerkAuth.createSignInTicket();
  const session = z
    .object({ sessionId: z.string().min(1), userId: z.string().min(1) })
    .strict()
    .parse(
      await evaluate(`(async () => {
        const result = await window.Clerk.client.signIn.create({
          strategy: "ticket",
          ticket: ${JSON.stringify(ticket)},
        });
        if (result.status !== "complete" || !result.createdSessionId) {
          throw new Error("Production Clerk ticket sign-in did not complete");
        }
        await window.Clerk.setActive({ session: result.createdSessionId });
        return {
          sessionId: window.Clerk.session?.id ?? null,
          userId: window.Clerk.user?.id ?? null,
        };
      })()`)
    );
  assert.equal(
    session.userId,
    userId,
    "Production ticket must sign in as the sole production user"
  );
  productionSmokeSession = session;
}

async function mintMachinePairingAction(): Promise<string> {
  const cli = process.env.HOMER_CLI ?? "homer";
  const result = await execFileAsync(cli, ["machine", "pair", "--json"], {
    cwd: smokeWorkspaceRoot,
    env: childEnvironment,
    maxBuffer: 64 * 1024,
  });
  const output = z
    .object({
      version: z.literal(1),
      command: z.literal("pair"),
      ok: z.literal(true),
      action: z.literal("paired"),
      littleBirdLink: z.url(),
    })
    .strict()
    .parse(JSON.parse(String(result.stdout)));
  const pairing = parseLittleBirdText(output.littleBirdLink);
  assert.equal(pairing.kind, "accepted", pairing.message);
  return pairing.locator.actionId;
}

