async function smokeDevelopment(): Promise<void> {
  smokeAbortController.signal.throwIfAborted();
  await assertDesktopRendererPortClosed();
  const server = startDesktopRendererServer(childEnvironment);
  const stopServer = registerCleanup(() => stopDesktopRendererServer(server));
  const profileRoot = mkdtempSync(
    path.join(tmpdir(), "homer-authenticated-development-")
