async function smokePackagedHardened(): Promise<void> {
  smokeAbortController.signal.throwIfAborted();
  const profileRoot = mkdtempSync(
    path.join(tmpdir(), "homer-authenticated-hardened-")
  );
  try {
    let active = await electronLaunchers.launchPackaged(profileRoot);
    let network = createPackagedNetwork(active.sendCommand);
    try {
      await runSmokeSections({
        current: () => ({
          evaluate: active.evaluate,
          target: createSectionTarget({
            evaluate: active.evaluate,
            sendCommand: active.sendCommand,
          }),
          userDataDir: active.userDataDir,
        }),
        signIn: () =>
          signInThroughEvaluate(active.evaluate, active.sendCommand),
        runChatShell: () =>
          runPackagedChatShellScenario(active.evaluate, active.sendCommand),
        runNetworkOutages: () =>
          runSmokeNetworkOutages(() => active.evaluate, network),
        afterSignIn: async () => {
          const firstUserId = z
            .string()
            .parse(await active.evaluate("window.Clerk?.user?.id ?? null"));
          await active.cleanup();
          active = await electronLaunchers.launchPackaged(profileRoot);
          network = createPackagedNetwork(active.sendCommand);
          const restored = await waitForSignedIn(active.evaluate);
          assert.equal(restored.userId, firstUserId);
          await assertProtectedTokenStorage(active.userDataDir);
          await assertConvexReady(active.evaluate);
        },
        afterSignOut: async () => {
          await active.cleanup();
          const signedOut = await electronLaunchers.launchPackaged(profileRoot);
          try {
            await waitForClerkReady(signedOut.evaluate);
            assert.equal(
              (await readClerkSession(signedOut.evaluate)).signedIn,
              false
            );
            await waitForVisibleTestId(signedOut.evaluate, "homer-auth-screen");
          } catch (error) {
            throw await shot("hardened-signed-out", () => signedOut)(error);
          } finally {
            await signedOut.cleanup();
          }
          const revocation =
            await electronLaunchers.launchPackaged(profileRoot);
          try {
            await signInThroughEvaluate(
              revocation.evaluate,
              revocation.sendCommand
            );
            const session = await waitForSignedIn(revocation.evaluate);
            assert.ok(session.sessionId);
            assert.ok(session.userId);
            await revokeOwnedSmokeSession(session.sessionId, session.userId);
            await waitForExpression(
              revocation.evaluate,
              "!window.Clerk?.user",
              "Clerk to report no signed-in user after server-side revocation"
            );
            await waitForVisibleTestId(
              revocation.evaluate,
              "homer-auth-screen"
            );
            assert.equal(
              await testIdCount(revocation.evaluate, "homer-auth-sync-problem"),
              0
            );
            rmSync(clerkTokenStoragePath(revocation.userDataDir), {
              force: true,
            });
          } catch (error) {
            throw await shot("hardened-revocation", () => revocation)(error);
          } finally {
            await revocation.cleanup();
          }
        },
      }).catch(shot("packaged-hardened", () => active));
      console.log("[leg] packaged hardened: PASS");
    } finally {
      await active.cleanup();
    }
  } finally {
    rmSync(profileRoot, { force: true, recursive: true });
  }
}

async function startLocalApi(): Promise<string> {
  smokeAbortController.signal.throwIfAborted();
  const port = process.env.HOMER_AUTHENTICATED_SMOKE_API_PORT
    ? z.coerce
        .number()
        .int()
        .min(1)
        .max(65_535)
        .parse(process.env.HOMER_AUTHENTICATED_SMOKE_API_PORT)
    : await availableLoopbackPort();
  const apiRoot = path.join(desktopRoot, "..", "api");
  const child = spawn(pnpm, ["exec", "next", "dev", "--port", String(port)], {
    cwd: apiRoot,
    detached: process.platform !== "win32",
    env: {
      ...childEnvironment,
      CLERK_SECRET_KEY: environment.CLERK_SECRET_KEY,
      CONVEX_URL: environment.EXPO_PUBLIC_CONVEX_URL,
      EXPO_PUBLIC_CONVEX_URL: environment.EXPO_PUBLIC_CONVEX_URL,
      HOMER_PROJECT_ROOTS: smokeWorkspaceRoot,
      HOMER_RUNTIME_DEPENDENCIES_CONFIG: smokeRuntimeDependenciesPath,
      HOMER_STATE_DIR: smokeStateHome,
      HOMER_WORKSPACE_ROOT: smokeWorkspaceClientRoot,
      NEXT_PUBLIC_CLERK_PUBLISHABLE_KEY:
        environment.EXPO_PUBLIC_CLERK_PUBLISHABLE_KEY,
    },
    stdio: "inherit",
  });
  registerCleanup(() => stopDetachedProcessTree(child));
  const origin = `http://127.0.0.1:${port}`;
  const deadline = Date.now() + 120_000;
  let lastError: unknown;
  while (Date.now() < deadline) {
    if (childHasExited(child)) {
      throw new Error("Local API exited before it started listening");
    }
    try {
      const response = await fetch(`${origin}/healthz`);
      if (response.status !== 200) {
        throw new Error(`Local API health check returned ${response.status}`);
      }
      apiHealthSchema.parse(await response.json());
      console.log(`[api] lifecycle-owned local API listening ${origin}`);
      return origin;
    } catch (error) {
      lastError = error;
    }
    await delay(250);
  }
  throw new Error(`Local API did not start at ${origin}`, {
    cause: lastError,
  });
}

