const signalHandlers = [
  ["SIGINT", () => requestCancellation(130)],
  ["SIGTERM", () => requestCancellation(143)],
] as const;
for (const [signal, handler] of signalHandlers) {
  process.on(signal, handler);
}

const smokeRun = runAuthenticatedSmoke();
try {
  await Promise.race([smokeRun, waitForCancellation()]);
  if (smokeAbortController.signal.aborted) {
