    await smokeRun;
    console.log("Authenticated desktop smoke passed");
  }
} finally {
  for (const [signal, handler] of signalHandlers) {
    process.off(signal, handler);
  }
  try {
    await runCleanups();
  } finally {
    rmSync(smokeXdgRoot, { force: true, recursive: true });
  }
}

process.exit(process.exitCode ?? 0);

