    );
    const unsubscribeAvailability = bridge.subscribeAppleLocalModelAvailabilityChanges(
      () => undefined
    );
    const availability = await Promise.all([
      bridge.appleLocalModelAvailability({ kind: "system" }),
      bridge.appleLocalModelAvailability({
        kind: "package",
        modelId: "qwen3-0.6b-local",
      }),
    ]);
    unsubscribeProgress(); unsubscribeText(); unsubscribeAvailability();
    return {
      availability,
      subscriptions: [
        typeof unsubscribeProgress,
        typeof unsubscribeText,
        typeof unsubscribeAvailability,
      ],
    };
  })()`)
    );
  assert.deepEqual(result.subscriptions, ["function", "function", "function"]);
  assert.equal(result.availability.length, 2);
}

export async function runElectronSmokeSections(
  options: ElectronSectionOptions
): Promise<void> {
  const client = new ConvexHttpClient(options.convexUrl),
    sessionIds = new Set<string>(),
    conversationIds = new Set<string>(),
    machineIds = new Set<MachineId>();
  let sessionUserId: string | undefined,
    convexToken: string | undefined,
    tokenStoragePath: string | undefined,
    machineId: MachineId | undefined;
  const authorize = () => {
    assert.ok(convexToken, "Convex token was not captured during sign-in");
    client.setAuth(convexToken);
  };
  const cleanupConversations = async () => {
    if (!conversationIds.size) return;
    authorize();
    for (const conversationId of conversationIds)
      await client.mutation(convexApi.conversations.remove, { conversationId });
    conversationIds.clear();
  };
  const cleanupMachine = async () => {
    if (!machineIds.size) return;
    authorize();
    for (const ownedMachineId of machineIds) {
      const result = machineRemovalResponseSchema.parse(
        await client.mutation(convexApi.machines.remove, {
          machineId: ownedMachineId,
        })
      );
      assert.equal(result.machineId, ownedMachineId);
      assert.equal(result.removed, true);
    }
    machineIds.clear();
  };
  const runConversation = async (ownedMachineId?: MachineId) => {
    const target = options.current().target;
    if (ownedMachineId) {
      await target.navigate(
        `/conversations/compose?machineId=${encodeURIComponent(ownedMachineId)}`
      );
      await target.waitForExpression(
        `Array.from(document.querySelectorAll('[data-testid^="homer-compose-agent-"]')).some(
          (node) =>
            node.getClientRects().length > 0 &&
            !node.hasAttribute("disabled") &&
            node.getAttribute("aria-disabled") !== "true"
        )`,
        "an available Machine Agent"
      );
      const agentTestId = String(
        await target.evaluate(
          `(() => {
            const node = Array.from(
              document.querySelectorAll('[data-testid^="homer-compose-agent-"]')
            ).find(
              (candidate) =>
                candidate.getClientRects().length > 0 &&
                !candidate.hasAttribute("disabled") &&
                candidate.getAttribute("aria-disabled") !== "true"
            );
            return node?.getAttribute("data-testid") ?? null;
          })()`
        )
      );
      assert.match(agentTestId, /^homer-compose-agent-.+$/);
      await target.clickTestId(agentTestId);
      await target.waitForVisible("homer-compose-machine-default");
      await target.clickTestId("homer-compose-machine-default");
    } else await target.navigate("/conversations/new?binding=model");
    await target.waitForVisible("homer-chat-input");
    const pathname = String(await target.evaluate("window.location.pathname")),
      routeId = pathname.match(/^\/conversations\/([^/]+)$/)?.[1];
    assert.ok(routeId, `Conversation route did not contain an ID: ${pathname}`);
    conversationIds.add(decodeURIComponent(routeId));
    if (!ownedMachineId) {
      await target.setViewport(1024, 844);
      await target.waitForVisible("homer-model-selector");
      await target.clickTestId("homer-model-selector");
      await target.waitForExpression(
        `Array.from(
          document.querySelectorAll('[data-testid^="homer-model-option-"]')
        ).some((node) => node.getClientRects().length > 0)`,
        "a hosted model option"
      );
      await target.clickTestId("homer-model-selector");
      await target.setViewport(390, 844);
    }
    const scenario = createConversationSmokeScenario(
        `${ownedMachineId ? "machine" : "hosted"}_${Date.now().toString(36)}`
      ),
      [remember, recall, resume, cancel, recover] = scenario.turns;
    const startTurn = async (prompt: string) => {
      await target.fillChatInput(prompt);
      await target.waitForVisible("homer-voice-send");
      await target.clickTestId("homer-voice-send");
      await target.waitForVisible("homer-send", 30_000);
    };
    const settleTurn = async (expected: string) => {
      await target.waitForText(
        "homer-chat-assistant-latest",
        expected,
        180_000
      );
      await target.waitForHidden("homer-send");
      await target.waitForVisible("homer-voice-send");
    };
    await startTurn(remember.prompt);
    const initialLength = Number(
      await target.evaluate(
        "document.querySelector('[data-testid=\"homer-chat-assistant-latest\"]')?.textContent?.length ?? 0"
      )
    );
    await target.waitForExpression(
      `(
        (document.querySelector('[data-testid="homer-chat-assistant-latest"]')?.textContent?.length ?? 0) >
        ${initialLength}
      )`,
      "assistant output to grow while streaming",
      30_000
    );
    await settleTurn(scenario.firstMarker);
    await startTurn(recall.prompt);
    await settleTurn(scenario.codeword);
    const conversationPath = String(
      await target.evaluate("window.location.pathname")
    );
    await target.reload();
    await target.waitForVisible("homer-chat-input");
    assert.equal(
      await target.evaluate("window.location.pathname"),
      conversationPath
    );
    await target.waitForText(
      "homer-chat-assistant-latest",
      scenario.codeword,
      60_000
    );
    await startTurn(resume.prompt);
    await settleTurn(scenario.resumedMarker);
    await target.waitForText("homer-chat-assistant-latest", scenario.codeword);
    await startTurn(cancel.prompt);
    await target.clickTestId("homer-send");
    await target.waitForHidden("homer-send", 30_000);
    await target.waitForVisible("homer-voice-send");
    await startTurn(recover.prompt);
    await settleTurn(scenario.recoveredMarker);
    await target.waitForText("homer-chat-assistant-latest", scenario.codeword);
  };
  const cleanupSession = async () => {
    try {
      if (sessionUserId) {
        for (const sessionId of sessionIds)
          await options.revokeSession(sessionId, sessionUserId);
        sessionIds.clear();
      }
    } finally {
      if (tokenStoragePath) rmSync(tokenStoragePath, { force: true });
    }
  };
  const none = async () => undefined;
  const rows = [
    {
      name: "sign-in",
      requires: [],
      run: async () => {
        const initial = options.current();
        tokenStoragePath = clerkTokenStoragePath(initial.userDataDir);
        await options.waitForClerkReady(initial.evaluate);
        assert.equal(
          (await options.readSession(initial.evaluate)).signedIn,
          false
        );
        await options.signIn();
        const session = await options.waitForSignedIn(
          options.current().evaluate
        );
        assert.ok(session.sessionId);
        assert.ok(session.userId);
        sessionIds.add(session.sessionId);
        sessionUserId = session.userId;
        convexToken = z
          .string()
          .min(1)
          .parse(
            await options
              .current()
              .evaluate(
                `window.Clerk?.session?.getToken({ template: "convex" }) ?? null`
              )
          );
        await options.assertProtectedTokenStorage(
          options.current().userDataDir
        );
        await options.afterSignIn?.();
      },
      cleanup: cleanupSession,
    },
    {
      name: "application-ready",
      requires: ["sign-in"],
      run: () => options.assertApplicationReady(options.current().evaluate),
      cleanup: none,
    },
    {
      name: "apple-local-models",
      requires: ["sign-in"],
      run: () => assertAppleLocalModelBridge(options.current().evaluate),
      cleanup: none,
    },
    {
      name: "machine-enrollment",
      requires: ["sign-in"],
      run: async () => {
        const actionId = await options.mintMachinePairingAction();
        authorize();
        const action = activeMachineActionSchema.parse(
          await client.query(convexApi.littleBird.inspectAction, {
            actionId: littleBirdActionIdSchema.parse(actionId),
          })
        );
        const enrolledMachineId = action.machine.id;
        const access = z
          .object({ access: machineAccessSchema })
          .passthrough()
          .nullable()
          .parse(
            await client.query(convexApi.machines.get, {
              machineId: enrolledMachineId,
            })
          );
        if (access && access.access.status !== "unpaired")
          throw new Error(
            `Machine ${enrolledMachineId} is already registered; enrollment smoke requires a new registration`
          );
        const target = options.current().target;
        await target.navigate(`/connect-machine/${actionId}`);
        await target.waitForVisible("machine-pairing-sheet");
        await target.waitForExpression(
          `Array.from(
            document.querySelectorAll(
              '[data-testid="machine-pairing-connect"], [data-testid="machine-pairing-save-pending"]'
            )
          ).some((node) => node.getClientRects().length > 0)`,
          "a Machine enrollment transition",
          120_000
        );
        const transition = z
          .enum(["machine-pairing-connect", "machine-pairing-save-pending"])
          .parse(
            await target.evaluate(
              `(() => {
                for (const testId of [
                  "machine-pairing-connect",
                  "machine-pairing-save-pending",
                ]) {
                  const node = document.querySelector(
                    '[data-testid="' + testId + '"]'
                  );
                  if (node?.getClientRects().length) return testId;
                }
                return null;
              })()`
            )
          );
        machineId = enrolledMachineId;
        machineIds.add(enrolledMachineId);
        await target.clickTestId(transition);
        await target.waitForHidden("machine-pairing-sheet");
        await target.waitForVisible("homer-conversations-list");
      },
      cleanup: cleanupMachine,
    },
    {
      name: "hosted-conversation",
      requires: ["sign-in"],
      run: () => runConversation(),
      cleanup: cleanupConversations,
    },
    {
      name: "machine-conversation",
      requires: ["sign-in", "machine-enrollment"],
      run: () => runConversation(machineId),
      cleanup: cleanupConversations,
    },
    {
      name: "chat-shell",
      requires: ["sign-in"],
      run: options.runChatShell,
      cleanup: none,
    },
    {
      name: "token-refresh",
      requires: ["sign-in"],
      run: () => options.assertTokenRefresh(options.current().evaluate),
      cleanup: none,
    },
    {
      name: "api-session",
      requires: ["sign-in"],
      run: () => options.assertApiSession(options.current().evaluate),
      cleanup: none,
    },
    {
      name: "network-outages",
      requires: ["sign-in", "application-ready"],
      run: options.runNetworkOutages,
      cleanup: none,
    },
    {
      name: "auth-lifecycle",
      requires: ["sign-in"],
      run: () => options.assertAuthLifecycle(options.current().evaluate),
      cleanup: none,
    },
    {
      name: "sign-out",
      requires: ["sign-in"],
      run: async () => {
        await options.signOut(options.current().evaluate);
        await options.afterSignOut?.();
      },
      cleanup: none,
    },
  ] satisfies readonly AuthenticatedSmokeSectionRow[];
  await runAuthenticatedSmokeSections(options.sections, rows);
}

