import { execFile } from "node:child_process";
import { createHash } from "node:crypto";
import { fileURLToPath } from "node:url";
import type { FunctionReturnType } from "convex/server";
import { z } from "zod";
import type { internal } from "../../client/convex/_generated/api.js";

type CapacityDocumentTarget = {
  conversationId: string;
  turnId: string;
};

type CapacityDocumentInspection = CapacityDocumentTarget & {
  deployment: string;
};

type CommandOptions = {
  cwd: string;
  encoding: "utf8";
  env: NodeJS.ProcessEnv;
  maxBuffer: number;
  timeout: number;
};

type CommandRunner = (
  command: string,
  args: string[],
  options: CommandOptions
) => Promise<{ stdout: string }>;

const repositoryRoot = fileURLToPath(new URL("../../..", import.meta.url));
const exactDeploymentName = /^[a-z][a-z0-9]*(?:-[a-z0-9]+)+$/;
const deploymentAliases = new Set(["dev", "local", "prod"]);
const sha256Digest = /^[a-f0-9]{64}$/;
type CapacityInspectionMetadata = FunctionReturnType<
  typeof internal.conversationCapacityInspection.inspectAgentTurn
>;
type CapacityCleanupMetadata = FunctionReturnType<
  typeof internal.conversationCapacityInspection.removeCapacityConversation
>;
const capacityInspectionSchema = z
  .object({
    hashAlgorithm: z.literal("sha256"),
    conversationIdSha256: z.string().regex(sha256Digest),
    turnIdSha256: z.string().regex(sha256Digest),
    documentIdSha256: z.string().regex(sha256Digest),
    table: z.literal("agentTurns"),
    canonicalDocumentBytes: z.number().int().positive(),
  })
  .strict() satisfies z.ZodType<CapacityInspectionMetadata>;
const capacityCleanupSchema = z
  .object({
    hashAlgorithm: z.literal("sha256"),
    conversationIdSha256: z.string().regex(sha256Digest),
    status: z.union([z.literal("removed"), z.literal("already_absent")]),
    deleted: z
      .object({
        conversations: z.number().int().nonnegative().max(1),
        conversationMessages: z.number().int().nonnegative(),
        generations: z.number().int().nonnegative(),
        agentTurns: z.number().int().nonnegative(),
      })
      .strict(),
  })
  .strict() satisfies z.ZodType<CapacityCleanupMetadata>;

export type ConversationCapacityCleanup = CapacityCleanupMetadata & {
  deployment: string;
};
export type ConversationCapacityDocument = CapacityInspectionMetadata & {
  deployment: string;
};

function validateExactDeploymentName(value: string) {
  if (
    deploymentAliases.has(value) ||
    !exactDeploymentName.test(value) ||
    value.includes(":") ||
    value.includes("/")
  ) {
    throw new Error(
      "Capacity measurement requires an exact Convex deployment name, not an alias or reference."
    );
  }
  return value;
}

function deploymentFromConvexURL(value: string) {
  let url: URL;
  try {
    url = new URL(value);
  } catch {
    return undefined;
  }
  if (
    url.protocol !== "https:" ||
    url.username ||
    url.password ||
    url.port ||
    url.pathname !== "/" ||
    url.search ||
    url.hash
  ) {
    return undefined;
  }
  const match = url.hostname.match(/^([a-z0-9-]+)\.convex\.cloud$/);
  const deployment = match?.[1];
  return deployment && exactDeploymentName.test(deployment)
    ? deployment
    : undefined;
}

export function sha256ResourceIdentifier(value: string) {
  return createHash("sha256").update(value).digest("hex");
}

export function resolveExactConvexDeployment(
  convexURL: string,
  explicitDeployment: string | undefined
) {
  const derived = deploymentFromConvexURL(convexURL);
  const explicit = explicitDeployment?.trim();
  if (explicit) {
    const validated = validateExactDeploymentName(explicit);
    if (derived && derived !== validated) {
      throw new Error(
        "Explicit Convex deployment does not match EXPO_PUBLIC_CONVEX_URL."
      );
    }
    return validated;
  }
  if (!derived) {
    throw new Error(
      "Capacity measurement requires an exact Convex deployment derived from EXPO_PUBLIC_CONVEX_URL or provided explicitly."
    );
  }
  return derived;
}

export function parseConversationCapacityInspection(stdout: string) {
  let raw: unknown;
  try {
    raw = JSON.parse(stdout);
  } catch {
    throw new Error(
      "Convex agentTurns inspection was not valid JSON metadata."
    );
  }
  const parsed = capacityInspectionSchema.safeParse(raw);
  if (!parsed.success) {
    throw new Error(
      "Convex agentTurns inspection did not return exact metadata."
    );
  }
  return parsed.data;
}

export function parseConversationCapacityCleanup(stdout: string) {
  let raw: unknown;
  try {
    raw = JSON.parse(stdout);
  } catch {
    throw new Error("Convex capacity cleanup was not valid JSON metadata.");
  }
  const parsed = capacityCleanupSchema.safeParse(raw);
  if (!parsed.success) {
    throw new Error("Convex capacity cleanup did not return exact metadata.");
  }
  return parsed.data;
}

const runCommand: CommandRunner = (command, args, options) =>
  new Promise((resolve, reject) => {
    execFile(command, args, options, (error, stdout) => {
      if (error) {
        reject(error);
        return;
      }
      resolve({ stdout });
    });
  });

export async function inspectConversationCapacityDocument(
  input: CapacityDocumentInspection,
  runner: CommandRunner = runCommand
) {
  const deployment = validateExactDeploymentName(input.deployment);
  let stdout: string;
  try {
    ({ stdout } = await runner(
      "pnpm",
      [
        "-F",
        "@homer/client",
        "exec",
        "convex",
        "run",
        "conversationCapacityInspection:inspectAgentTurn",
        JSON.stringify({
          conversationId: input.conversationId,
          agentTurnId: input.turnId,
        }),
        "--deployment",
        deployment,
        "--typecheck",
        "disable",
        "--codegen",
        "disable",
      ],
      {
        cwd: repositoryRoot,
        encoding: "utf8",
        env: { ...process.env, NO_COLOR: "1" },
        maxBuffer: 1024 * 1024,
        timeout: 30_000,
      }
    ));
  } catch {
    throw new Error("Convex agentTurns inspection query failed.");
  }
  const inspection = parseConversationCapacityInspection(stdout);
  if (
    inspection.conversationIdSha256 !==
      sha256ResourceIdentifier(input.conversationId) ||
    inspection.turnIdSha256 !== sha256ResourceIdentifier(input.turnId)
  ) {
    throw new Error("Convex agentTurns inspection belongs to another target.");
  }
  return {
    deployment,
    ...inspection,
  };
}

export async function cleanupConversationCapacityRun(
  input: Pick<CapacityDocumentInspection, "deployment" | "conversationId">,
  runner: CommandRunner = runCommand
) {
  const deployment = validateExactDeploymentName(input.deployment);
  let stdout: string;
  try {
    ({ stdout } = await runner(
      "pnpm",
      [
        "-F",
        "@homer/client",
        "exec",
        "convex",
        "run",
        "conversationCapacityInspection:removeCapacityConversation",
        JSON.stringify({ conversationId: input.conversationId }),
        "--deployment",
        deployment,
        "--typecheck",
        "disable",
        "--codegen",
        "disable",
      ],
      {
        cwd: repositoryRoot,
        encoding: "utf8",
        env: { ...process.env, NO_COLOR: "1" },
        maxBuffer: 1024 * 1024,
        timeout: 30_000,
      }
    ));
  } catch {
    throw new Error("Convex capacity cleanup mutation failed.");
  }
  const cleanup = parseConversationCapacityCleanup(stdout);
  if (
    cleanup.conversationIdSha256 !==
    sha256ResourceIdentifier(input.conversationId)
  ) {
    throw new Error("Convex capacity cleanup belongs to another target.");
  }
  return { deployment, ...cleanup };
}

import {
  cpSync,
  mkdirSync,
  mkdtempSync,
  readFileSync,
  rmSync,
  symlinkSync,
  writeFileSync,
} from "node:fs";
import { execFileSync } from "node:child_process";
import os from "node:os";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { findPackagedApplication } from "./package-artifact.js";
import {
  buildSquirrelMacManifest,
  buildSquirrelMacStaticFeed,
  describeReleaseArtifact,
  normalizeReleaseChannel,
  publicArtifactUrl,
  releaseFileNames,
  resolveNotarizationCredentials,
  serializeStaticFeed,
  type NotarizationCredentials,
  serializeManifest,
  writeSha256Checksums,
} from "./release-artifacts.js";
import { verifyReleaseArtifacts } from "./verify-release.js";

const desktopRoot = fileURLToPath(new URL("..", import.meta.url));
const outputRoot = path.join(desktopRoot, "out");
const releaseRoot = path.join(outputRoot, "releases");
const hdiutilPath = "/usr/bin/hdiutil";
const dittoPath = "/usr/bin/ditto";
const xcrunPath = "/usr/bin/xcrun";
const tsxLoaderPath = path.join(
  desktopRoot,
  "node_modules",
  "tsx",
  "dist",
  "loader.mjs"
);

async function main(): Promise<void> {
  const dryRun = process.argv.slice(2).includes("--dry-run");
  if (process.platform !== "darwin" || process.arch !== "arm64") {
    throw new Error("Homer releases currently require macOS arm64.");
  }

  const credentials = dryRun ? undefined : resolveNotarizationCredentials();
  const version = readDesktopVersion();
  const gitSha = gitOutput(["rev-parse", "HEAD"]);
  const gitShaForFilename = gitOutput(["rev-parse", "--short=12", "HEAD"]);
  const channel = normalizeReleaseChannel(
    process.env.HOMER_RELEASE_CHANNEL || "stable"
  );
  const baseUrl =
    process.env.HOMER_RELEASE_BASE_URL?.trim() ||
    (dryRun ? "https://downloads.invalid/desktop" : undefined);
  if (!baseUrl) {
    throw new Error(
      "HOMER_RELEASE_BASE_URL is required for a non-dry-run release."
    );
  }

  const childEnvironment = {
    ...process.env,
    HOMER_RELEASE_DRY_RUN: dryRun ? "1" : "0",
  };
  runTypeScript(
    path.join(desktopRoot, "../client/scripts/export-renderer.ts"),
    path.join(desktopRoot, "../client"),
    childEnvironment
  );
  runTypeScript(
    path.join(desktopRoot, "scripts/build.ts"),
    desktopRoot,
    childEnvironment
  );
  runTypeScript(
    path.join(desktopRoot, "scripts/package.ts"),
    desktopRoot,
    childEnvironment
  );
  runTypeScript(
    path.join(desktopRoot, "scripts/harden.ts"),
    desktopRoot,
    childEnvironment
  );

  const packageRoot = findPackagedApplication(outputRoot);
  const applicationPath = path.join(packageRoot, "Homer.app");
  const names = releaseFileNames(version, gitShaForFilename);
  const channelRoot = path.join(releaseRoot, channel, "darwin", "arm64");
  mkdirSync(channelRoot, { recursive: true });

  if (credentials) {
    notarizeApplication(applicationPath, credentials);
  } else {
    console.log("[release] dry run: skipping app notarization and stapling");
  }

  const zipPath = path.join(channelRoot, names.zip);
  createZip(applicationPath, zipPath);
  const dmgPath = path.join(channelRoot, names.dmg);
  createDmg(applicationPath, dmgPath, dryRun);

  if (credentials) {
    notarizeAndStaple(dmgPath, credentials);
  } else {
    console.log("[release] dry run: skipping DMG notarization and stapling");
  }

  const publishedZipUrl = publicArtifactUrl(baseUrl, channel, names.zip);
  const [dmgArtifact, zipArtifact] = await Promise.all([
    describeReleaseArtifact({
      filePath: dmgPath,
      kind: "dmg",
      name: names.dmg,
      url: publicArtifactUrl(baseUrl, channel, names.dmg),
    }),
    describeReleaseArtifact({
      filePath: zipPath,
      kind: "zip",
      name: names.zip,
      url: publishedZipUrl,
    }),
  ]);
  const artifactDescriptors = [dmgArtifact, zipArtifact];
  const releaseNotes =
    process.env.HOMER_RELEASE_NOTES?.trim() ||
    `Homer ${version} desktop release.`;
  const pubDate = new Date().toISOString();
  const manifest = buildSquirrelMacManifest({
    artifactDescriptors,
    channel,
    gitSha,
    notes: releaseNotes,
    pubDate,
    version,
    zipUrl: publishedZipUrl,
  });
  const manifestPath = path.join(channelRoot, names.manifest);
  writeFileSync(manifestPath, serializeManifest(manifest), "utf8");
  const staticFeed = buildSquirrelMacStaticFeed({
    notes: releaseNotes,
    pubDate,
    version,
    zipArtifact,
  });
  writeFileSync(
    path.join(channelRoot, "latest.json"),
    serializeStaticFeed(staticFeed),
    "utf8"
  );
  const checksumsPath = path.join(channelRoot, names.checksums);
  await writeSha256Checksums(checksumsPath, [
    { filePath: dmgPath, name: names.dmg },
    { filePath: zipPath, name: names.zip },
    { filePath: manifestPath, name: names.manifest },
  ]);

  const verificationReport = await verifyReleaseArtifacts({
    applicationPath,
    dmgPath,
    dryRun,
    notarized: credentials !== undefined,
  });
  console.log("[release] verification report");
  for (const line of verificationReport) console.log(`[release] ${line}`);
  console.log(`[release] artifacts: ${channelRoot}`);
  for (const artifact of [
    names.dmg,
    names.zip,
    names.checksums,
    names.manifest,
    "latest.json",
  ]) {
    console.log(`[release] ${path.join(channelRoot, artifact)}`);
  }
}

