}

function createDmg(
  applicationPath: string,
  outputPath: string,
  dryRun: boolean
): void {
  const dmgStage = mkdtempSync(path.join(os.tmpdir(), "homer-release-dmg-"));
  try {
    cpSync(applicationPath, path.join(dmgStage, "Homer.app"), {
      recursive: true,
    });
    symlinkSync("/Applications", path.join(dmgStage, "Applications"));
    try {
      execFileSync(
        hdiutilPath,
        [
          "create",
          "-volname",
          "Homer",
          "-srcfolder",
          dmgStage,
          "-ov",
          "-format",
          "UDZO",
          outputPath,
        ],
        { stdio: "inherit" }
      );
    } catch (error) {
      if (!dryRun) throw error;
      console.warn(
        `[release] hdiutil create unavailable in dry run (${errorMessage(error)}); using hdiutil makehybrid`
      );
      execFileSync(
        hdiutilPath,
        [
          "makehybrid",
          "-o",
          outputPath,
          "-hfs",
          "-default-volume-name",
          "Homer",
          dmgStage,
        ],
        { stdio: "inherit" }
      );
    }
  } finally {
    rmSync(dmgStage, { force: true, recursive: true });
  }
  console.log(`[release] created DMG ${outputPath}`);
}

function errorMessage(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

function notarizeApplication(
  applicationPath: string,
  credentials: NotarizationCredentials
): void {
  const notarizationRoot = mkdtempSync(
    path.join(os.tmpdir(), "homer-release-notarization-")
  );
  const notarizationZipPath = path.join(notarizationRoot, "Homer.app.zip");
  try {
    createZip(applicationPath, notarizationZipPath);
    submitForNotarization(notarizationZipPath, credentials);
    stapleAndValidate(applicationPath);
    console.log(
      `[release] notarized temporary ZIP and stapled app ${applicationPath}`
    );
  } finally {
    rmSync(notarizationRoot, { force: true, recursive: true });
  }
}

function notarizeAndStaple(
  artifactPath: string,
  credentials: NotarizationCredentials
): void {
  submitForNotarization(artifactPath, credentials);
  stapleAndValidate(artifactPath);
  console.log(`[release] notarized and stapled ${artifactPath}`);
}

function submitForNotarization(
  artifactPath: string,
  credentials: NotarizationCredentials
): void {
  const args = ["notarytool", "submit", artifactPath, "--wait"];
  if (credentials.kind === "keychain-profile") {
    args.push("--keychain-profile", credentials.keychainProfile ?? "");
  } else {
    args.push(
      "--apple-id",
      credentials.appleId ?? "",
      "--team-id",
      credentials.teamId ?? "",
      "--password",
      credentials.password ?? ""
    );
  }
  execFileSync(xcrunPath, args, { stdio: "inherit" });
}

function stapleAndValidate(artifactPath: string): void {
  execFileSync(xcrunPath, ["stapler", "staple", artifactPath], {
    stdio: "inherit",
  });
  execFileSync(xcrunPath, ["stapler", "validate", artifactPath], {
    stdio: "inherit",
  });
}

