const activeSmokeCleanups = new Set<() => Promise<void>>();
const smokeAbortController = new AbortController();
let signalExitCode: number | undefined;

function registerSmokeCleanup(cleanup: SmokeCleanup): () => Promise<void> {
  let cleanupPromise: Promise<void> | undefined;
  const runOnce = () => {
    cleanupPromise ??= Promise.resolve().then(cleanup);
    return cleanupPromise;
  };
  activeSmokeCleanups.add(runOnce);
  if (smokeAbortController.signal.aborted) {
    void runOnce().catch(() => undefined);
  }
  return async () => {
    try {
      await runOnce();
    } finally {
      activeSmokeCleanups.delete(runOnce);
    }
  };
}

async function closeSmokeCleanups(): Promise<void> {
  const failures: unknown[] = [];
  for (const cleanup of [...activeSmokeCleanups].reverse()) {
    try {
      await cleanup();
    } catch (error) {
      failures.push(error);
    } finally {
      activeSmokeCleanups.delete(cleanup);
    }
  }
  if (failures.length > 0) {
    throw new AggregateError(failures, "Desktop smoke cleanup failed");
  }
}

async function finishCancelledSmoke(smokeRun: Promise<void>): Promise<void> {
  const failures: unknown[] = [];
  try {
    await closeSmokeCleanups();
  } catch (error) {
    failures.push(error);
  }
  await smokeRun.catch(() => undefined);
  try {
    await closeSmokeCleanups();
  } catch (error) {
    failures.push(error);
  }
  if (failures.length > 0) {
    throw new AggregateError(failures, "Desktop smoke cancellation failed");
  }
}

