function waitForCancellation(): Promise<void> {
  if (smokeAbortController.signal.aborted) return Promise.resolve();
  return new Promise((resolve) => {
    smokeAbortController.signal.addEventListener("abort", () => resolve(), {
      once: true,
    });
  });
}

