function startCommand(
  command: string,
  args: string[],
  cwd: string,
  environment: NodeJS.ProcessEnv = process.env
) {
  return spawn(command, args, {
    cwd,
    detached: process.platform !== "win32",
    env: environment,
    stdio: "inherit",
  });
}

async function waitForExit(child: ReturnType<typeof spawn>): Promise<number> {
  if (childHasExited(child)) return child.exitCode ?? 1;
  return new Promise((resolve, reject) => {
    child.once("error", reject);
    child.once("exit", (code, signal) => resolve(code ?? (signal ? 1 : 0)));
  });
}

async function closeElectronWithDeadline(
  electronApp: ElectronApplication
): Promise<void> {
  let timeout: ReturnType<typeof setTimeout> | undefined;
  try {
    await Promise.race([
      electronApp.close(),
      new Promise<never>((_resolve, reject) => {
        timeout = setTimeout(
          () => reject(new Error("Desktop application did not exit cleanly")),
          5_000
        );
      }),
    ]);
  } catch (error) {
    await stopDetachedProcessTree(electronApp.process());
    throw error;
  } finally {
    if (timeout) clearTimeout(timeout);
  }
}

async function runCommand(
  command: string,
  args: string[],
  cwd: string,
  environment: NodeJS.ProcessEnv = process.env
): Promise<void> {
  smokeAbortController.signal.throwIfAborted();
  const child = startCommand(command, args, cwd, environment);
  const cleanup = registerSmokeCleanup(() => stopDetachedProcessTree(child));
  try {
    const exitCode = await waitForExit(child);
    if (exitCode !== 0) {
      throw new Error(`${command} ${args.join(" ")} exited with ${exitCode}`);
    }
  } finally {
    await cleanup();
  }
}

