async function collectRendererEvidence() {
  const bridge = (window as DesktopWindow).homerDesktop;
  if (!bridge) throw new Error("Desktop bridge is unavailable");
  const browserProcess = Reflect.get(window, "process");
  const versions =
    typeof browserProcess === "object" && browserProcess !== null
      ? Reflect.get(browserProcess, "versions")
      : undefined;
  const scripts = await Promise.all(
    Array.from(document.scripts)
      .map((script) => script.src)
      .filter(Boolean)
      .filter((source) => {
        const url = new URL(source, window.location.href);
        return (
          url.protocol === window.location.protocol &&
          url.host === window.location.host
        );
      })
      .map(async (source) => (await fetch(source)).text())
  );
  return {
    bridgeKeys: Object.keys(bridge).sort(),
    clerkBridgePresent:
      typeof Reflect.get(window, "__clerk_internal_electron") === "object",
    externalStylesheetHrefs: Array.from(
      document.querySelectorAll<HTMLLinkElement>('link[rel="stylesheet"][href]')
    )
      .map((link) => link.href)
      .filter((href) => {
        const url = new URL(href, window.location.href);
        return (
          url.protocol !== window.location.protocol ||
          url.host !== window.location.host
        );
      }),
    hasDesktopMarker: scripts.some((script) =>
      script.includes("homer-renderer:desktop")
    ),
    hasNativeMarker: scripts.some((script) =>
      script.includes("homer-renderer:native")
    ),
    hasWebMarker: scripts.some((script) =>
      script.includes("homer-renderer:web")
    ),
    hasKatexStylesheet: Array.from(document.styleSheets).some((sheet) =>
      sheet.href?.endsWith("/vendor/katex/katex.min.css")
    ),
    nodeElectronVersionType:
      typeof versions === "object" && versions !== null
        ? typeof Reflect.get(versions, "electron")
        : "undefined",
    nodeRequireType: typeof Reflect.get(window, "require"),
    rootChildCount: document.getElementById("root")?.childElementCount ?? 0,
    runtimeInfo: await bridge.getRuntimeInfo(),
  };
}

async function rendererEvidence(page: Page) {
  await page.waitForLoadState("domcontentloaded");
  await page.waitForFunction(
    () => document.getElementById("root")?.childElementCount
  );
  await page.waitForFunction(
    () => (window as DesktopWindow).homerDesktop !== undefined
  );
  await page.waitForFunction(() =>
    Array.from(document.styleSheets).some((sheet) =>
      sheet.href?.endsWith("/vendor/katex/katex.min.css")
    )
  );
  await page.waitForFunction(
    () => typeof Reflect.get(window, "__clerk_internal_electron") === "object"
  );
  return rendererEvidenceSchema.parse(
    await page.evaluate(collectRendererEvidence)
  );
}

async function assertWindowSecurity(
  electronApp: ElectronApplication
): Promise<void> {
  const preferences = await electronApp.evaluate(
    ({ BrowserWindow, session }, partition) => {
      const window = BrowserWindow.getAllWindows()[0];
      if (!window) throw new Error("Homer window is unavailable");
      const current = (
        window.webContents as typeof window.webContents & {
          getLastWebPreferences: () => DesktopWebPreferences;
        }
      ).getLastWebPreferences();
      return {
        allowRunningInsecureContent: current.allowRunningInsecureContent,
        contextIsolation: current.contextIsolation,
        nodeIntegration: current.nodeIntegration,
        nodeIntegrationInSubFrames: current.nodeIntegrationInSubFrames,
        safeDialogs: current.safeDialogs,
        sandbox: current.sandbox,
        usesDesktopSession:
          window.webContents.session === session.fromPartition(partition),
        webSecurity: current.webSecurity,
        webviewTag: current.webviewTag,
      };
    },
    DESKTOP_SESSION_PARTITION
  );
  assert.deepEqual(preferences, {
    allowRunningInsecureContent: false,
    contextIsolation: true,
    nodeIntegration: false,
    nodeIntegrationInSubFrames: false,
    safeDialogs: true,
    sandbox: true,
    usesDesktopSession: true,
    webSecurity: true,
    webviewTag: false,
  });
}

