async function assertRendererRuntime(
  electronApp: ElectronApplication,
  expectedUrl: string,
  expectedBuildId: string,
  isPackaged: boolean
): Promise<Page> {
  const pageErrors = recordPageErrors(electronApp);
  const page = await electronApp.firstWindow();
  try {
    await page.waitForURL(
      (url) => isTrustedRendererUrl(url.href, expectedUrl),
      { timeout: 120_000 }
    );
  } catch (error) {
    throw new Error(
      `Desktop renderer did not navigate to ${expectedUrl}; current URL: ${page.url()}`,
      { cause: error }
    );
  }
  let evidence: Awaited<ReturnType<typeof rendererEvidence>>;
  try {
    evidence = await rendererEvidence(page);
  } catch (error) {
    const diagnostics = await page.evaluate(() => ({
      bodyText: document.body?.innerText.slice(0, 1_000),
      readyState: document.readyState,
      rootChildCount: document.getElementById("root")?.childElementCount,
      rootExists: document.getElementById("root") !== null,
    }));
    throw new Error(
      `Desktop renderer did not become ready: ${JSON.stringify({
        ...diagnostics,
        pageErrors,
        url: page.url(),
      })}`,
      { cause: error }
    );
  }
  assert.equal(isTrustedRendererUrl(page.url(), expectedUrl), true);
  assertRendererEvidence(evidence, expectedBuildId, isPackaged);
  await assertWindowSecurity(electronApp);
  await assertPopupBlocked(electronApp, page);
  assert.equal(isTrustedRendererUrl(page.url(), expectedUrl), true);
  assert.deepEqual(pageErrors, []);
  return page;
}

