async function assertLinuxProtocolRegistration(
  electronApp: ElectronApplication,
  executablePath: string
): Promise<void> {
  if (process.platform !== "linux") return;
  const desktopFile = path.join(
    smokeDataHome,
    "applications",
    LINUX_DESKTOP_FILENAME
  );
  for (let attempt = 0; attempt < 40; attempt += 1) {
    if (existsSync(desktopFile)) {
      assert.equal(
        readFileSync(desktopFile, "utf8"),
        linuxApplicationDesktopEntry(executablePath, PACKAGED_RENDERER_SCHEME)
      );
      if (
        await electronApp.evaluate(
          ({ app }, scheme) => app.isDefaultProtocolClient(scheme),
          PACKAGED_RENDERER_SCHEME
        )
      ) {
        return;
      }
    }
    await delay(50);
  }
  throw new Error(
    existsSync(desktopFile)
      ? "Packaged Linux protocol association was not activated"
      : "Packaged Linux protocol registration was not written"
  );
}

