async function smokePackagedBeforeHardening(
  packageRoot: string,
  expectedBuildId: string
): Promise<void> {
  const executable = packagedExecutablePath(packageRoot);
  assert.equal(existsSync(executable), true);
  await withTemporaryProfile(async (profileRoot) => {
    const profileArgument = `--user-data-dir=${profileRoot}`;
    const coldConversationId = "6b62f469-7d55-4b9e-a540-e5876ff9f011";
    const coldLink = `homer://app/conversations/${coldConversationId}`;
    const electronApp = await _electron.launch({
      args: [profileArgument, coldLink],
      chromiumSandbox: true,
      env: smokeEnvironment,
      executablePath: executable,
    });
    const closeElectron = registerSmokeCleanup(() =>
      closeElectronWithDeadline(electronApp)
    );
    try {
      smokeAbortController.signal.throwIfAborted();
      const page = await assertRendererRuntime(
        electronApp,
        PACKAGED_RENDERER_URL,
        expectedBuildId,
        true
      );
      await assertLinuxProtocolRegistration(electronApp, executable);
      const rendererTimeOrigin = await page.evaluate(
        () => performance.timeOrigin
      );
      assert.deepEqual(await readPendingApplicationDestination(page), {
        revision: 1,
        destination: {
          kind: "conversation",
          conversationId: coldConversationId,
        },
      });

      const warmLink = `homer://app/conversations/${coldConversationId}/model`;
      await runSecondaryApplication(executable, [profileArgument, warmLink]);
      await page.waitForFunction(async () => {
        const bridge = (window as DesktopWindow).homerDesktop;
        const pending = await bridge?.readPendingApplicationDestination();
        return pending?.revision === 2;
      });
      assert.deepEqual(await readPendingApplicationDestination(page), {
        revision: 2,
        destination: {
          kind: "conversationSurface",
          conversationId: coldConversationId,
          surface: "model",
        },
      });
      assert.equal(electronApp.windows().length, 1);
      assert.equal(page.url(), PACKAGED_RENDERER_URL);
      assert.equal(
        await page.evaluate(() => performance.timeOrigin),
        rendererTimeOrigin
      );

      await runSecondaryApplication(executable, [
        profileArgument,
        "homer://app/_debug",
      ]);
      assert.equal(
        (await readPendingApplicationDestination(page))?.revision,
        2
      );
      assert.equal(page.url(), PACKAGED_RENDERER_URL);
      assert.equal(
        await page.evaluate(() => performance.timeOrigin),
        rendererTimeOrigin
      );

      const acknowledgement = await page.evaluate(async () => {
        const bridge = (window as DesktopWindow).homerDesktop;
        if (!bridge) throw new Error("Desktop bridge is unavailable");
        return {
          stale: await bridge.acknowledgeApplicationDestination(1),
          current: await bridge.acknowledgeApplicationDestination(2),
          pending: await bridge.readPendingApplicationDestination(),
        };
      });
      assert.deepEqual(acknowledgement, {
        stale: false,
        current: true,
        pending: null,
      });
      const csp = await page.evaluate(async () => {
        const response = await fetch(window.location.href);
        return response.headers.get("content-security-policy");
      });
      assertRendererContentSecurityPolicy(csp);

      for (const routePath of [
        "machines",
        `conversations/${coldConversationId}/model`,
      ]) {
        const routeUrl = `${PACKAGED_RENDERER_URL}${routePath}`;
        const directResponse = await page.goto(routeUrl);
        assert.equal(directResponse?.ok(), true);
        assert.match(
          directResponse?.headers()["content-type"] ?? "",
          /text\/html/
        );
        assert.equal(page.url(), routeUrl);
        const reloadResponse = await page.reload();
        assert.equal(reloadResponse?.ok(), true);
        assert.equal(page.url(), routeUrl);
        await page.waitForFunction(
          () => (window as DesktopWindow).homerDesktop !== undefined
        );
        await page.waitForFunction(
          () => (document.getElementById("root")?.childElementCount ?? 0) > 0
        );
      }
    } finally {
      await closeElectron();
    }
  });
}

function verifyPackagedRenderer(
  packageRoot: string,
  expectedBuildId: string
): void {
  const asarPath = packagedAsarPath(packageRoot);
  const entries = listPackage(asarPath, { isPack: false });
  assert.equal(entries.includes("/package.json"), true);
  assert.equal(entries.includes("/dist/main.cjs"), true);
  assert.equal(entries.includes("/dist/preload.cjs"), true);
  assert.equal(
    entries.some((entry) =>
      entry.startsWith("/dist/desktop-public-environment")
    ),
    false
  );
  assert.equal(
    entries.includes("/dist/renderer/homer-renderer-manifest.json"),
    true
  );
  assert.equal(
    entries.some((entry) => entry.startsWith("/src/")),
    false
  );
  assert.equal(
    entries.some((entry) => entry.startsWith("/scripts/")),
    false
  );
  assert.equal(
    entries.some((entry) => entry.startsWith("/node_modules/")),
    false
  );
  assert.equal(
    entries.some((entry) => entry.endsWith(".map")),
    false
  );

  if (process.platform === "darwin") {
    const infoPlistPath = path.join(
      packageRoot,
      "Homer.app",
      "Contents",
      "Info.plist"
    );
    let extractedUrlTypes: unknown;
    try {
      extractedUrlTypes = JSON.parse(
        execFileSync(
          "/usr/bin/plutil",
          ["-extract", "CFBundleURLTypes", "json", "-o", "-", infoPlistPath],
          { encoding: "utf8" }
        )
      );
    } catch (error) {
      throw new Error(
        `Failed to read CFBundleURLTypes from ${infoPlistPath}.`,
        {
          cause: error,
        }
      );
    }
    const registrations =
      macProtocolRegistrationSchema.parse(extractedUrlTypes);
    assert.equal(
      registrations.some((entry) =>
        entry.CFBundleURLSchemes.includes(PACKAGED_RENDERER_SCHEME)
      ),
      true
    );
  }

  const extractionRoot = mkdtempSync(
    path.join(tmpdir(), "homer-desktop-asar-")
  );
  try {
    extractAll(asarPath, extractionRoot);
    const manifest = verifyRendererManifest(
      path.join(extractionRoot, "dist/renderer")
    );
    assert.equal(manifest.kind, "expo-web");
    assert.equal(manifest.buildId, expectedBuildId);
  } finally {
    rmSync(extractionRoot, { force: true, recursive: true });
  }
}

