async function availableLoopbackPort(): Promise<number> {
  const server = createServer();
  await new Promise<void>((resolve, reject) => {
    server.once("error", reject);
    server.listen(0, "127.0.0.1", resolve);
  });
  const address = server.address();
  await new Promise<void>((resolve, reject) => {
    server.close((error) => (error ? reject(error) : resolve()));
  });
  if (typeof address !== "object" || address === null) {
    throw new Error("Unable to allocate a desktop smoke CDP port");
  }
  return address.port;
}

async function waitForHardenedRendererTarget(
  child: ReturnType<typeof spawn>,
  port: number
): Promise<z.infer<typeof cdpTargetSchema>> {
  const endpoint = `http://127.0.0.1:${port}/json/list`;
  const deadline = Date.now() + 30_000;
  let lastError: unknown;
  while (Date.now() < deadline) {
    if (childHasExited(child)) {
      throw new Error(
        `Hardened desktop package exited before CDP connected: ${child.exitCode ?? child.signalCode}`
      );
    }
    try {
      const response = await fetch(endpoint);
      if (!response.ok) throw new Error(`CDP returned ${response.status}`);
      const targets = z.array(z.unknown()).parse(await response.json());
      for (const candidate of targets) {
        const target = cdpTargetSchema.safeParse(candidate);
        if (
          target.success &&
          isTrustedRendererUrl(target.data.url, PACKAGED_RENDERER_URL)
        ) {
          return target.data;
        }
      }
    } catch (error) {
      lastError = error;
    }
    await delay(100);
  }
  throw new Error(`Hardened desktop CDP did not start at ${endpoint}`, {
    cause: lastError,
  });
}

async function evaluateCdp(
  target: z.infer<typeof cdpTargetSchema>,
  expression: string,
  userGesture = false
): Promise<unknown> {
  const socket = new WebSocket(target.webSocketDebuggerUrl);
  const commandId = 1;
  return new Promise((resolve, reject) => {
    let settled = false;
    const timeout = setTimeout(() => {
      finish(new Error("Hardened desktop CDP evaluation timed out"));
    }, 30_000);
    const finish = (error?: unknown, value?: unknown) => {
      if (settled) return;
      settled = true;
      clearTimeout(timeout);
      socket.close();
      if (error) reject(error);
      else resolve(value);
    };
    socket.addEventListener(
      "open",
      () => {
        socket.send(
          JSON.stringify({
            id: commandId,
            method: "Runtime.evaluate",
            params: {
              awaitPromise: true,
              expression,
              returnByValue: true,
              userGesture,
            },
          })
        );
      },
      { once: true }
    );
    socket.addEventListener("message", (event) => {
      try {
        if (typeof event.data !== "string") return;
        const raw: unknown = JSON.parse(event.data);
        const response = cdpCommandResponseSchema.parse(raw);
        if (response.id !== commandId) return;
        if (response.error) {
          finish(new Error(response.error.message));
          return;
        }
        const evaluation = cdpEvaluationResultSchema.parse(response.result);
        if (evaluation.exceptionDetails !== undefined) {
          finish(
            new Error(
              `Hardened desktop renderer evaluation failed: ${JSON.stringify(evaluation.exceptionDetails)}`
            )
          );
          return;
        }
        finish(undefined, evaluation.result.value);
      } catch (error) {
        finish(error);
      }
    });
    socket.addEventListener("error", () => {
      finish(new Error("Hardened desktop CDP socket failed"));
    });
    socket.addEventListener("close", () => {
      finish(new Error("Hardened desktop CDP socket closed early"));
    });
  });
}

async function assertHardenedRendererRuntime(
  target: z.infer<typeof cdpTargetSchema>,
  expectedBuildId: string
): Promise<void> {
  assert.equal(isTrustedRendererUrl(target.url, PACKAGED_RENDERER_URL), true);
  const deadline = Date.now() + 30_000;
  let evidence: z.infer<typeof rendererEvidenceSchema> | undefined;
  let lastError: unknown;
  while (Date.now() < deadline && evidence === undefined) {
    try {
      const candidate = rendererEvidenceSchema.parse(
        await evaluateCdp(target, `(${collectRendererEvidence.toString()})()`)
      );
      if (candidate.rootChildCount === 0) {
        throw new Error("Hardened desktop renderer root is empty");
      }
      if (!candidate.hasKatexStylesheet) {
        throw new Error("Hardened desktop renderer is missing KaTeX styles");
      }
      if (!candidate.clerkBridgePresent) {
        throw new Error("Hardened desktop Clerk bridge is unavailable");
      }
      evidence = candidate;
    } catch (error) {
      lastError = error;
      await delay(100);
    }
  }
  if (!evidence) {
    throw new Error("Hardened desktop renderer did not become ready", {
      cause: lastError,
    });
  }
  assertRendererEvidence(evidence, expectedBuildId, true);
  const csp = z
    .string()
    .nullable()
    .parse(
      await evaluateCdp(
        target,
        "fetch(window.location.href).then((response) => response.headers.get('content-security-policy'))"
      )
    );
  assertRendererContentSecurityPolicy(csp);
  assert.equal(
    await evaluateCdp(
      target,
      "window.open('https://example.com') === null",
      true
    ),
    true
  );
}

