): Promise<void> {
  await withTemporaryProfile(async (profileRoot) => {
    const cdpPort = await availableLoopbackPort();
    smokeAbortController.signal.throwIfAborted();
    const child = spawn(
      packagedExecutablePath(packageRoot),
