const terminate = () => requestCancellation(143);
process.on("SIGINT", interrupt);
process.on("SIGTERM", terminate);
const smokeRun = runSmoke();
try {
  await Promise.race([smokeRun, waitForCancellation()]);
  if (smokeAbortController.signal.aborted) {
    await finishCancelledSmoke(smokeRun);
    process.exitCode = signalExitCode ?? 1;
  } else {
    await smokeRun;
  }
} finally {
  process.off("SIGINT", interrupt);
  process.off("SIGTERM", terminate);
  rmSync(smokeXdgRoot, { force: true, recursive: true });
}

import { randomUUID } from "node:crypto";
import { mkdir, open, readFile, rename, rm } from "node:fs/promises";
import path from "node:path";
import type { TokenStorage } from "@clerk/electron";
import type { SafeStorage } from "electron";
import { z } from "zod";

export type DesktopSafeStorage = Pick<
  SafeStorage,
  | "decryptStringAsync"
  | "encryptStringAsync"
  | "getSelectedStorageBackend"
  | "isAsyncEncryptionAvailable"
  | "isEncryptionAvailable"
>;

const storedClerkTokensSchema = z.record(z.string(), z.string());

type StoredClerkTokens = z.infer<typeof storedClerkTokensSchema>;

type StoredClerkTokenState =
  | { kind: "absent" }
  | { kind: "present"; tokens: StoredClerkTokens };

type ClerkTokenStorageDependencies = {
  platform: NodeJS.Platform;
  safeStorage: DesktopSafeStorage;
  userDataDir: string;
};

export class ClerkTokenStorageUnavailableError extends Error {
  constructor(message: string, options?: ErrorOptions) {
    super(message, options);
    this.name = "ClerkTokenStorageUnavailableError";
  }
}

const CLERK_TOKEN_STORAGE_FILENAME = "clerk-token-storage.bin";

export function clerkTokenStoragePath(userDataDir: string): string {
  return path.join(userDataDir, CLERK_TOKEN_STORAGE_FILENAME);
}

// macOS binds the safeStorage key to the code signature that created it. When a
// differently signed build meets that entry the platform blocks on an
// authorization prompt, and isAsyncEncryptionAvailable never settles, so the app
// hangs with no diagnostic and cannot even quit. Fail loudly instead: a signing
// identity change is a credential migration, not a transparent update.
const ENCRYPTION_AVAILABILITY_TIMEOUT_MS = 10_000;

async function encryptionAvailability(
  dependencies: ClerkTokenStorageDependencies
): Promise<boolean> {
  let timer: ReturnType<typeof setTimeout> | undefined;
  try {
    return await Promise.race([
      dependencies.safeStorage.isAsyncEncryptionAvailable(),
      new Promise<never>((_resolve, reject) => {
        timer = setTimeout(
          () =>
            reject(
              new ClerkTokenStorageUnavailableError(
                "Desktop credential encryption did not respond. The operating system is most likely waiting on an authorization prompt because this build is signed differently from the one that created the stored key."
              )
            ),
          ENCRYPTION_AVAILABILITY_TIMEOUT_MS
        );
      }),
    ]);
  } finally {
    if (timer) clearTimeout(timer);
  }
}

async function assertProtectedStorage(
  dependencies: ClerkTokenStorageDependencies
): Promise<void> {
  if (
    !(await encryptionAvailability(dependencies)) ||
    !dependencies.safeStorage.isEncryptionAvailable()
  ) {
    throw new ClerkTokenStorageUnavailableError(
      "Desktop credential encryption is unavailable."
    );
  }
  if (
    dependencies.platform === "linux" &&
    dependencies.safeStorage.getSelectedStorageBackend() === "basic_text"
  ) {
    throw new ClerkTokenStorageUnavailableError(
      "Desktop credential storage is unavailable: Linux selected the unencrypted basic_text password store."
    );
  }
}

export function createClerkTokenStorage(
  dependencies: ClerkTokenStorageDependencies
) {
  const storePath = clerkTokenStoragePath(dependencies.userDataDir);

  const readTokens = async (): Promise<StoredClerkTokenState> => {
    let encrypted: Buffer;
    try {
      encrypted = await readFile(storePath);
    } catch (error) {
      if (
        error instanceof Error &&
        "code" in error &&
        error.code === "ENOENT"
      ) {
        return { kind: "absent" };
      }
      throw new ClerkTokenStorageUnavailableError(
        "Desktop credential storage could not read Clerk tokens."
      );
    }
    await assertProtectedStorage(dependencies);
    let decrypted: Awaited<
      ReturnType<DesktopSafeStorage["decryptStringAsync"]>
    >;
    try {
      decrypted = await dependencies.safeStorage.decryptStringAsync(encrypted);
    } catch {
      throw new ClerkTokenStorageUnavailableError(
        "Desktop credential storage could not decrypt Clerk tokens."
      );
    }
    try {
      return {
        kind: "present",
        tokens: storedClerkTokensSchema.parse(JSON.parse(decrypted.result)),
      };
    } catch (cause) {
      throw new ClerkTokenStorageUnavailableError(
        "Stored Clerk credentials could not be decoded.",
        { cause }
      );
    }
  };

  const persistTokens = async (tokens: StoredClerkTokens): Promise<void> => {
    await assertProtectedStorage(dependencies);
    let encrypted: Buffer;
    try {
      encrypted = await dependencies.safeStorage.encryptStringAsync(
        JSON.stringify(tokens)
      );
      await mkdir(dependencies.userDataDir, { recursive: true });
    } catch {
      throw new ClerkTokenStorageUnavailableError(
        "Desktop credential storage could not encrypt Clerk tokens."
      );
    }
    const temporaryPath = `${storePath}.${process.pid}.${randomUUID()}.tmp`;
    try {
      const handle = await open(temporaryPath, "wx", 0o600);
      try {
        await handle.writeFile(encrypted);
        await handle.sync();
      } finally {
        await handle.close();
      }
      await rename(temporaryPath, storePath);
    } catch {
      throw new ClerkTokenStorageUnavailableError(
        "Desktop credential storage could not persist Clerk tokens."
      );
    } finally {
      await rm(temporaryPath, { force: true }).catch(() => undefined);
    }
  };

  return {
    async getItem(key: string): Promise<string | null> {
      const state = await readTokens();
      return state.kind === "absent" ? null : (state.tokens[key] ?? null);
    },

    async removeItem(key: string): Promise<void> {
      const state = await readTokens();
      if (state.kind === "absent") return;
      const tokens = state.tokens;
      if (!(key in tokens)) return;
      delete tokens[key];
      await persistTokens(tokens);
    },

    async setItem(key: string, value: string): Promise<void> {
      const state = await readTokens();
      const tokens = state.kind === "absent" ? {} : state.tokens;
      tokens[key] = value;
      await persistTokens(tokens);
    },
  } satisfies TokenStorage;
}

import { spawn } from "node:child_process";
import type { Agent, AgentAvailability, AgentId } from "@homer/shared/machine";
import { turnMachineError } from "./machine-errors.js";
import type {
  ExecutorAdapter,
  ExecutorCommandProbe,
  ExecutorCommandProbeResult,
  ExecutorProbeResult,
} from "./turn-execution.js";
import { errorFromUnknown } from "./errors.js";

export const EXECUTOR_PROBE_TIMEOUT_MS = 5_000;

export function spawnExecutorCommandProbe(
  argv: string[],
  timeoutMs: number
): Promise<ExecutorCommandProbeResult> {
  const [executable, ...commandArguments] = argv;
  const startedAt = Date.now();
  if (!executable) {
    return Promise.resolve({
      ok: false,
      latencyMs: 0,
      reason: "The agent command is empty on this Machine.",
    });
  }
  const printable = argv.join(" ");

  return new Promise<ExecutorCommandProbeResult>((resolve) => {
    const child = spawn(executable, commandArguments, {
      stdio: ["ignore", "ignore", "pipe"],
    });
    let stderr = "";
    let settled = false;
    const settle = (result: ExecutorCommandProbeResult) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      resolve(result);
    };
    const timer = setTimeout(() => {
      child.kill("SIGKILL");
      settle({
        ok: false,
        latencyMs: Date.now() - startedAt,
        reason: `${printable} did not answer within ${timeoutMs}ms.`,
      });
    }, timeoutMs);

    child.stderr?.on("data", (chunk: Buffer) => {
      stderr = `${stderr}${chunk.toString("utf8")}`.slice(-500);
    });
    child.once("error", (error) => {
      settle({
        ok: false,
        latencyMs: Date.now() - startedAt,
        reason: `${executable} could not be started: ${error.message}`,
      });
    });
    child.once("close", (code, signal) => {
      const latencyMs = Date.now() - startedAt;
      if (code === 0) {
        settle({ ok: true, latencyMs });
        return;
      }
      const detail = stderr.trim();
      settle({
        ok: false,
        latencyMs,
        reason: `${printable} exited with ${signal ?? code}${
          detail ? `: ${detail}` : "."
        }`,
      });
    });
  });
}

function unknownAvailability(checkedAt: string): AgentAvailability {
  return { status: "unknown", checkedAt };
}

type AgentProbeSnapshot = {
  checkedAt: string;
  agents: readonly Agent[];
};

export type AgentRoster = {
  snapshot: () => readonly Agent[];
  probeSnapshot: () => Promise<AgentProbeSnapshot>;
  refresh: () => Promise<readonly Agent[]>;
  refreshAgent: (agentId: AgentId) => Promise<readonly Agent[]>;
  start: () => Promise<void>;
  subscribe(listener: () => void): () => void;
};

export function createAgentRoster({
  executors,
  probe,
  now,
  timeoutMs = EXECUTOR_PROBE_TIMEOUT_MS,
}: {
  executors: ReadonlyMap<AgentId, ExecutorAdapter>;
  probe: ExecutorCommandProbe;
  now: () => Date;
  timeoutMs?: number;
}): AgentRoster {
  const checkedAt = now().toISOString();
  const initialAgents: Agent[] = [];
  for (const executor of executors.values()) {
    initialAgents.push({
      id: executor.id,
      label: executor.label,
      availability: unknownAvailability(checkedAt),
    });
  }
  let agents: readonly Agent[] = initialAgents;
  const listeners = new Set<() => void>();

  const availabilityFromProbe = (
    agent: Agent,
    result: ExecutorProbeResult,
    checkedAt: string
  ): AgentAvailability => {
    if (result.status === "available") {
      return { status: "available", checkedAt, latencyMs: result.latencyMs };
    }
    const probeFailed = result.status === "unknown";
    return {
      status: result.status,
      checkedAt,
      latencyMs: result.latencyMs,
      error: turnMachineError(
        probeFailed ? "harness_error" : "unavailable",
        probeFailed
          ? `Agent availability probe failed: ${result.reason}`
          : result.reason,
        probeFailed ? 502 : 503,
        { agentId: agent.id }
      ),
    };
  };

  const probeAgent = async (
    agent: Agent,
    checkedAt: string
  ): Promise<Agent> => {
    const executor = executors.get(agent.id);
    if (!executor) {
      throw new Error(`Agent ${agent.id} is missing its executor.`);
    }
    const result = await executor.probe(probe, timeoutMs).catch(
      (cause: unknown): ExecutorProbeResult => ({
        status: "unknown",
        latencyMs: 0,
        reason: errorFromUnknown(cause).message,
      })
    );
    return {
      ...agent,
      availability: availabilityFromProbe(agent, result, checkedAt),
    };
  };

  const publish = (next: readonly Agent[]): readonly Agent[] => {
    agents = Object.freeze(next);
    for (const listener of listeners) listener();
    return agents;
  };

  const probeSnapshot = async (): Promise<AgentProbeSnapshot> => {
    const snapshotCheckedAt = now().toISOString();
    return {
      checkedAt: snapshotCheckedAt,
      agents: Object.freeze(
        await Promise.all(
          agents.map(
            async (agent) => await probeAgent(agent, snapshotCheckedAt)
          )
        )
      ),
    };
  };

  const refresh = async (): Promise<readonly Agent[]> => {
    const probed = await probeSnapshot();
    return publish(probed.agents);
  };

  const refreshAgent = async (agentId: AgentId): Promise<readonly Agent[]> => {
    const snapshotCheckedAt = now().toISOString();
    const probed = await Promise.all(
      agents.map(async (agent) =>
        agent.id === agentId
          ? await probeAgent(agent, snapshotCheckedAt)
          : agent
      )
    );
    return publish(probed);
  };

  return {
    snapshot: () => agents,
    probeSnapshot,
    refresh,
    refreshAgent,
    start: async () => {
      await refresh();
    },
    subscribe: (listener) => {
      listeners.add(listener);
      return () => listeners.delete(listener);
    },
  };
}

import { execFileSync } from "node:child_process";
import { createHash, randomUUID } from "node:crypto";
import {
  closeSync,
  constants,
  fchmodSync,
  fstatSync,
  fsyncSync,
  linkSync,
  lstatSync,
  mkdirSync,
  openSync,
  readFileSync,
  readlinkSync,
  readdirSync,
  renameSync,
  symlinkSync,
  unlinkSync,
  writeFileSync,
  type BigIntStats,
  type Mode,
} from "node:fs";
import { dirname, isAbsolute } from "node:path";
import { z } from "zod";
import { tryAcquireAdvisoryFileLockSync } from "./advisory-file-lock.js";
import { errorFromUnknown } from "./errors.js";

export class AtomicFileWriteError extends Error {
  readonly committed: boolean;

  constructor(committed: boolean, options: ErrorOptions) {
    super(
      committed
        ? "Atomic file was installed, but durability confirmation or cleanup failed."
        : "Atomic file could not be installed.",
      options
    );
    this.name = "AtomicFileWriteError";
    this.committed = committed;
  }
}

type AtomicFileWriteOptions = {
  directoryMode?: Mode;
  fileMode?: Mode;
  expectedDestination?: AtomicFileDestinationExpectation;
  beforeCommit?: () => void;
  afterDestinationLink?: () => void;
};

type AtomicFileDestinationExpectation =
  | { state: "absent" }
  | {
      state: "present";
      device: bigint;
      inode: bigint;
      mode: bigint;
      userId: bigint;
      linkCount: bigint;
      size: bigint;
      modifiedNanoseconds: bigint;
      changedNanoseconds: bigint;
      contentDigest: string;
    };

type AtomicFileRecoveryOptions = {
  fileMode: Mode;
  userId: number;
};

const digestSchema = z.string().regex(/^[0-9a-f]{64}$/u);
const serializedDestinationSchema = z.discriminatedUnion("state", [
  z.object({ state: z.literal("absent") }).strict(),
  z
    .object({
      state: z.literal("present"),
      device: z.string().regex(/^\d+$/u),
      inode: z.string().regex(/^\d+$/u),
      mode: z.string().regex(/^\d+$/u),
      userId: z.string().regex(/^\d+$/u),
      linkCount: z.string().regex(/^\d+$/u),
      size: z.string().regex(/^\d+$/u),
      modifiedNanoseconds: z.string().regex(/^\d+$/u),
      changedNanoseconds: z.string().regex(/^\d+$/u),
      contentDigest: digestSchema,
    })
    .strict(),
]);
const transactionRecordSchema = z
  .object({
    version: z.literal(2),
    destination: z.string().min(1),
    fileMode: z.number().int().nonnegative(),
    expected: serializedDestinationSchema,
    candidateDigest: digestSchema,
  })
  .strict();

type SerializedDestination = z.infer<typeof serializedDestinationSchema>;
type TransactionRecord = z.infer<typeof transactionRecordSchema>;

function isMissing(cause: unknown): boolean {
  return cause instanceof Error && "code" in cause && cause.code === "ENOENT";
}

function statusIfPresent(path: string): BigIntStats | undefined {
  try {
    return lstatSync(path, { bigint: true });
  } catch (cause) {
    if (isMissing(cause)) return undefined;
    throw cause;
  }
}

function sameIdentity(left: BigIntStats, right: BigIntStats): boolean {
  return left.dev === right.dev && left.ino === right.ino;
}

function sameSnapshot(left: BigIntStats, right: BigIntStats): boolean {
  return (
    sameIdentity(left, right) &&
    left.mode === right.mode &&
    left.uid === right.uid &&
    left.nlink === right.nlink &&
    left.size === right.size &&
    left.mtimeNs === right.mtimeNs &&
    left.ctimeNs === right.ctimeNs
  );
}

function contentDigest(content: Buffer): string {
  return createHash("sha256").update(content).digest("hex");
}

function captureAtomicFileDestination(
  path: string
): AtomicFileDestinationExpectation {
  const initial = statusIfPresent(path);
  if (initial === undefined) return { state: "absent" };
  if (!initial.isFile() || initial.isSymbolicLink()) {
    throw new Error(`Atomic destination is not a regular file: ${path}.`);
  }
  const descriptor = openSync(path, constants.O_RDONLY | constants.O_NOFOLLOW);
  let opened: BigIntStats;
  let content: Buffer;
  try {
    opened = fstatSync(descriptor, { bigint: true });
    if (!sameIdentity(initial, opened)) {
      throw new Error(`Atomic destination changed during open: ${path}.`);
    }
    content = readFileSync(descriptor);
  } finally {
    closeSync(descriptor);
  }
  const final = lstatSync(path, { bigint: true });
  if (!sameIdentity(opened, final)) {
    throw new Error(`Atomic destination changed during read: ${path}.`);
  }
  return {
    state: "present",
    device: final.dev,
    inode: final.ino,
    mode: final.mode,
    userId: final.uid,
    linkCount: final.nlink,
    size: final.size,
    modifiedNanoseconds: final.mtimeNs,
    changedNanoseconds: final.ctimeNs,
    contentDigest: contentDigest(content),
  };
}

function atomicFileDestinationsMatch(
  left: AtomicFileDestinationExpectation,
  right: AtomicFileDestinationExpectation
): boolean {
  if (left.state !== right.state) return false;
  if (left.state === "absent" || right.state === "absent") return true;
  return (
    left.device === right.device &&
    left.inode === right.inode &&
    left.mode === right.mode &&
    left.userId === right.userId &&
    left.linkCount === right.linkCount &&
    left.size === right.size &&
    left.modifiedNanoseconds === right.modifiedNanoseconds &&
    left.changedNanoseconds === right.changedNanoseconds &&
    left.contentDigest === right.contentDigest
  );
}

function sameDirectory(left: BigIntStats, right: BigIntStats): boolean {
  return (
    left.isDirectory() &&
    right.isDirectory() &&
    !right.isSymbolicLink() &&
    sameIdentity(left, right)
  );
}

function verifyTransactionDirectoryPath(
  path: string,
  expected: BigIntStats
): void {
  const actual = lstatSync(path, { bigint: true });
  if (!sameDirectory(expected, actual)) {
    throw new Error(`Atomic recovery directory was replaced: ${path}.`);
  }
}

function preservedDestinationMatches(
  expected: Extract<AtomicFileDestinationExpectation, { state: "present" }>,
  actual: AtomicFileDestinationExpectation,
  linkCount: bigint
): boolean {
  return (
    actual.state === "present" &&
    expected.device === actual.device &&
    expected.inode === actual.inode &&
    expected.mode === actual.mode &&
    expected.userId === actual.userId &&
    actual.linkCount === linkCount &&
    expected.size === actual.size &&
    expected.modifiedNanoseconds === actual.modifiedNanoseconds &&
    expected.contentDigest === actual.contentDigest
  );
}

function preservedDestinationPathMatches(
  expected: Extract<AtomicFileDestinationExpectation, { state: "present" }>,
  path: string,
  linkCount: bigint
): boolean {
  const status = statusIfPresent(path);
  return (
    status !== undefined &&
    status.isFile() &&
    !status.isSymbolicLink() &&
    preservedDestinationMatches(
      expected,
      captureAtomicFileDestination(path),
      linkCount
    )
  );
}

function preservedDestinationPathHasExpectedLinks(
  expected: Extract<AtomicFileDestinationExpectation, { state: "present" }>,
  path: string,
  actualLinkCount: bigint
): boolean {
  return (
    (actualLinkCount === expected.linkCount ||
      actualLinkCount === expected.linkCount + 1n) &&
    preservedDestinationPathMatches(expected, path, actualLinkCount)
  );
}

function captureFailure(failures: Error[], action: () => void): void {
  try {
    action();
  } catch (cause) {
    failures.push(errorFromUnknown(cause));
  }
}

function transactionDirectory(path: string): string {
  return `${path}.homer-atomic-replacement`;
}

function transactionOwnerPath(path: string): string {
  return `${transactionDirectory(path)}.owner`;
}

function transactionLockPath(path: string): string {
  return `${transactionDirectory(path)}.lock`;
}

type TransactionOwner = {
  processId: number;
  birthDigest: string;
  target: string;
};

let cachedCurrentProcessBirthDigest: string | undefined;

function processExists(processId: number): boolean {
  try {
    process.kill(processId, 0);
    return true;
  } catch (cause) {
    if (cause instanceof Error && "code" in cause && cause.code === "ESRCH") {
      return false;
    }
    return true;
  }
}

function processBirthIdentity(processId: number): string | undefined {
  if (!processExists(processId)) return undefined;
  try {
    if (process.platform === "linux") {
      const stat = readFileSync(`/proc/${processId}/stat`, "utf8");
      const closingParenthesis = stat.lastIndexOf(")");
      const fields = stat
        .slice(closingParenthesis + 2)
        .trim()
        .split(/\s+/u);
      const startTime = fields[19];
      const bootId = readFileSync(
        "/proc/sys/kernel/random/boot_id",
        "utf8"
      ).trim();
      if (
        closingParenthesis < 1 ||
        startTime === undefined ||
        !/^\d+$/u.test(startTime) ||
        !/^[0-9a-f-]{36}$/u.test(bootId)
      ) {
        throw new Error(
          `Linux process birth identity is invalid: ${processId}.`
        );
      }
      return `linux:${bootId}:${startTime}`;
    }
    if (process.platform === "darwin") {
      const started = execFileSync(
        "/bin/ps",
        ["-p", String(processId), "-o", "lstart="],
        { encoding: "utf8", stdio: ["ignore", "pipe", "ignore"] }
      )
        .trim()
        .replaceAll(/\s+/gu, " ");
      if (started.length === 0) return undefined;
      return `darwin:${started}`;
    }
    throw new Error(
      `Atomic replacement does not support process identity on ${process.platform}.`
    );
  } catch (cause) {
    if (!processExists(processId)) return undefined;
    throw new Error(`Unable to read process birth identity: ${processId}.`, {
      cause,
    });
  }
}

function processBirthDigest(processId: number): string | undefined {
  const identity = processBirthIdentity(processId);
  return identity === undefined
    ? undefined
    : createHash("sha256").update(identity).digest("hex");
}

function currentProcessBirthDigest(): string {
  cachedCurrentProcessBirthDigest ??= processBirthDigest(process.pid);
  if (cachedCurrentProcessBirthDigest === undefined) {
    throw new Error("Unable to identify the current process birth.");
  }
  return cachedCurrentProcessBirthDigest;
}

function currentTransactionOwnerTarget(): string {
  return `v1:${process.pid}:${currentProcessBirthDigest()}`;
}

function readTransactionOwner(path: string, userId: bigint): TransactionOwner {
  const initial = lstatSync(path, { bigint: true });
  if (!initial.isSymbolicLink() || initial.uid !== userId) {
    throw new Error(`Atomic transaction owner is unsafe: ${path}.`);
  }
  const target = readlinkSync(path);
  const final = lstatSync(path, { bigint: true });
  if (!sameSnapshot(initial, final)) {
    throw new Error(`Atomic transaction owner changed during read: ${path}.`);
  }
  const match = /^v1:(0|[1-9]\d*):([0-9a-f]{64})$/u.exec(target);
  const processId = Number(match?.[1]);
  const birthDigest = match?.[2];
  if (
    !Number.isSafeInteger(processId) ||
    processId <= 0 ||
    birthDigest === undefined ||
    `v1:${processId}:${birthDigest}` !== target
  ) {
    throw new Error(`Atomic transaction owner is invalid: ${path}.`);
  }
  return { processId, birthDigest, target };
}

function transactionOwnerIsCurrent(owner: TransactionOwner): boolean {
  return (
    owner.processId === process.pid &&
    owner.birthDigest === currentProcessBirthDigest()
  );
}

function transactionOwnerIsLive(owner: TransactionOwner): boolean {
  return processBirthDigest(owner.processId) === owner.birthDigest;
}

function removeTransactionOwner(
  path: string,
  expected: TransactionOwner,
  userId: bigint
): void {
  const current = readTransactionOwner(path, userId);
  if (current.target !== expected.target) {
    throw new Error(
      `Atomic transaction owner changed before cleanup: ${path}.`
    );
  }
  unlinkSync(path);
}

function normalizedFileMode(mode: Mode): number {
  const value =
    typeof mode === "number"
      ? mode
      : /^0o[0-7]+$/u.test(mode)
        ? Number(mode)
        : /^[0-7]+$/u.test(mode)
          ? Number.parseInt(mode, 8)
          : Number.NaN;
  if (!Number.isInteger(value) || value < 0 || value > 0o777) {
    throw new Error(`Atomic file mode is invalid: ${String(mode)}.`);
  }
  return value;
}

function openVerifiedTransactionDirectory(
  path: string,
  userId: bigint
): number {
  const initial = lstatSync(path, { bigint: true });
  if (
    !initial.isDirectory() ||
    initial.isSymbolicLink() ||
    initial.uid !== userId ||
    (initial.mode & 0o777n) !== 0o700n
  ) {
    throw new Error(`Atomic recovery directory is unsafe: ${path}.`);
  }
  const descriptor = openSync(
    path,
    constants.O_RDONLY | constants.O_DIRECTORY | constants.O_NOFOLLOW
  );
  const opened = fstatSync(descriptor, { bigint: true });
  if (!sameDirectory(initial, opened)) {
    closeSync(descriptor);
    throw new Error(`Atomic recovery directory changed during open: ${path}.`);
  }
  return descriptor;
}

function verifyCandidate(
  path: string,
  userId: bigint,
  fileMode: Mode,
  allowedLinkCounts: readonly bigint[]
): BigIntStats {
  const status = lstatSync(path, { bigint: true });
  if (
    !status.isFile() ||
    status.isSymbolicLink() ||
    status.uid !== userId ||
    !allowedLinkCounts.includes(status.nlink) ||
    (status.mode & 0o777n) !== BigInt(fileMode)
  ) {
    throw new Error(`Atomic recovery candidate is unsafe: ${path}.`);
  }
  return status;
}

function serializeDestination(
  destination: AtomicFileDestinationExpectation
): SerializedDestination {
  if (destination.state === "absent") return destination;
  return {
    state: "present",
    device: destination.device.toString(),
    inode: destination.inode.toString(),
    mode: destination.mode.toString(),
    userId: destination.userId.toString(),
    linkCount: destination.linkCount.toString(),
    size: destination.size.toString(),
    modifiedNanoseconds: destination.modifiedNanoseconds.toString(),
    changedNanoseconds: destination.changedNanoseconds.toString(),
    contentDigest: destination.contentDigest,
  };
}

function deserializeDestination(
  destination: SerializedDestination
): AtomicFileDestinationExpectation {
  if (destination.state === "absent") return destination;
  return {
    state: "present",
    device: BigInt(destination.device),
    inode: BigInt(destination.inode),
    mode: BigInt(destination.mode),
    userId: BigInt(destination.userId),
    linkCount: BigInt(destination.linkCount),
    size: BigInt(destination.size),
    modifiedNanoseconds: BigInt(destination.modifiedNanoseconds),
    changedNanoseconds: BigInt(destination.changedNanoseconds),
    contentDigest: destination.contentDigest,
  };
}

function serializeTransactionRecord(record: TransactionRecord): string {
  return `${JSON.stringify(record)}\n`;
}

function readTransactionRecord(
  path: string,
  userId: bigint
): TransactionRecord {
  const initial = lstatSync(path, { bigint: true });
  if (
    !initial.isFile() ||
    initial.isSymbolicLink() ||
    initial.uid !== userId ||
    initial.nlink !== 1n ||
    (initial.mode & 0o777n) !== 0o600n ||
    initial.size > 16_384n
  ) {
    throw new Error(`Atomic recovery record is unsafe: ${path}.`);
  }
  const descriptor = openSync(path, constants.O_RDONLY | constants.O_NOFOLLOW);
  let content: string;
  try {
    const opened = fstatSync(descriptor, { bigint: true });
    if (!sameSnapshot(initial, opened)) {
      throw new Error(`Atomic recovery record changed during open: ${path}.`);
    }
    content = readFileSync(descriptor, "utf8");
    const read = fstatSync(descriptor, { bigint: true });
    const final = lstatSync(path, { bigint: true });
    if (!sameSnapshot(opened, read) || !sameSnapshot(read, final)) {
      throw new Error(`Atomic recovery record changed during read: ${path}.`);
    }
  } finally {
    closeSync(descriptor);
  }
  let parsed: unknown;
  try {
    parsed = JSON.parse(content);
  } catch (cause) {
    throw new Error(`Atomic recovery record is invalid: ${path}.`, { cause });
  }
  const record = transactionRecordSchema.parse(parsed);
  if (serializeTransactionRecord(record) !== content) {
    throw new Error(`Atomic recovery record is not canonical: ${path}.`);
  }
  return record;
}

function verifyPreparingRecord(path: string, userId: bigint): void {
  const status = lstatSync(path, { bigint: true });
  if (
    !status.isFile() ||
    status.isSymbolicLink() ||
    status.uid !== userId ||
    status.nlink !== 1n ||
    (status.mode & 0o777n) !== 0o600n
  ) {
    throw new Error(`Atomic preparing record is unsafe: ${path}.`);
  }
}

function verifyTransactionRecord(
  record: TransactionRecord,
  path: string,
  fileMode: number,
  userId: bigint
): AtomicFileDestinationExpectation {
  if (record.destination !== path || record.fileMode !== fileMode) {
    throw new Error(`Atomic recovery record does not own ${path}.`);
  }
  const expected = deserializeDestination(record.expected);
  if (
    expected.state === "present" &&
    (expected.userId !== userId ||
      expected.linkCount !== 1n ||
      (expected.mode & 0o777n) !== BigInt(fileMode))
  ) {
    throw new Error(
      `Atomic recovery record has an unsafe destination: ${path}.`
    );
  }
  return expected;
}

function candidateMatchesRecord(
  path: string,
  userId: bigint,
  fileMode: number,
  allowedLinkCounts: readonly bigint[],
  digest: string
): BigIntStats {
  const status = verifyCandidate(path, userId, fileMode, allowedLinkCounts);
  const captured = captureAtomicFileDestination(path);
  if (
    captured.state !== "present" ||
    captured.device !== status.dev ||
    captured.inode !== status.ino ||
    captured.contentDigest !== digest
  ) {
    throw new Error(
      `Atomic recovery candidate changed or is corrupt: ${path}.`
    );
  }
  return status;
}

function destinationMatchesCandidateRecord(
  path: string,
  userId: bigint,
  fileMode: number,
  allowedLinkCounts: readonly bigint[],
  digest: string
): boolean {
  const status = statusIfPresent(path);
  if (
    status === undefined ||
    !status.isFile() ||
    status.isSymbolicLink() ||
    status.uid !== userId ||
    !allowedLinkCounts.includes(status.nlink) ||
    (status.mode & 0o777n) !== BigInt(fileMode)
  ) {
    return false;
  }
  const captured = captureAtomicFileDestination(path);
  return (
    captured.state === "present" &&
    captured.device === status.dev &&
    captured.inode === status.ino &&
    captured.contentDigest === digest
  );
}

function verifyCommittedDestination(
  candidatePath: string,
  destination: string,
  userId: bigint,
  fileMode: number,
  digest: string
): void {
  const candidate = candidateMatchesRecord(
    candidatePath,
    userId,
    fileMode,
    [2n],
    digest
  );
  const installed = lstatSync(destination, { bigint: true });
  if (
    !sameIdentity(candidate, installed) ||
    !destinationMatchesCandidateRecord(
      destination,
      userId,
      fileMode,
      [2n],
      digest
    )
  ) {
    throw new Error(
      `Atomic destination changed after installation: ${destination}.`
    );
  }
}

function restoreDisplacedDestination(
  displacedPath: string,
  destination: string,
  userId: bigint
): void {
  const status = lstatSync(displacedPath, { bigint: true });
  if (status.uid !== userId) {
    throw new Error(
      `Displaced atomic destination is not user-owned: ${displacedPath}.`
    );
  }
  if (status.isSymbolicLink()) {
    symlinkSync(readlinkSync(displacedPath), destination);
  } else if (status.isFile()) {
    linkSync(displacedPath, destination);
  } else {
    throw new Error(
      `Displaced destination preserved at ${displacedPath}; it cannot be restored without overwrite.`
    );
  }
}

function openTransactionLock(
  path: string,
  userId: bigint,
  parentDescriptor: number
): number {
  let descriptor: number;
  let created = false;
  try {
    descriptor = openSync(path, "wx+", 0o600);
    created = true;
  } catch (cause) {
    if (
      !(cause instanceof Error && "code" in cause && cause.code === "EEXIST")
    ) {
      throw new Error(`Unable to create atomic transaction lock: ${path}.`, {
        cause,
      });
    }
    descriptor = openSync(path, constants.O_RDWR | constants.O_NOFOLLOW);
  }
  try {
    if (created) {
      fchmodSync(descriptor, 0o600);
      fsyncSync(descriptor);
    }
    const opened = fstatSync(descriptor, { bigint: true });
    const current = lstatSync(path, { bigint: true });
    if (
      !opened.isFile() ||
      opened.isSymbolicLink() ||
      opened.uid !== userId ||
      opened.nlink !== 1n ||
      (opened.mode & 0o777n) !== 0o600n ||
      !sameIdentity(opened, current)
    ) {
      throw new Error(`Atomic transaction lock is unsafe: ${path}.`);
    }
    if (created) fsyncSync(parentDescriptor);
    if (!tryAcquireAdvisoryFileLockSync(descriptor)) {
      throw new Error(
        "Atomic transaction recovery is active in another process."
      );
    }
    const locked = fstatSync(descriptor, { bigint: true });
    const claimed = lstatSync(path, { bigint: true });
    if (
      !locked.isFile() ||
      locked.isSymbolicLink() ||
      locked.uid !== userId ||
      locked.nlink !== 1n ||
      (locked.mode & 0o777n) !== 0o600n ||
      !sameIdentity(opened, locked) ||
      !sameIdentity(locked, claimed)
    ) {
      throw new Error(`Atomic transaction lock changed during claim: ${path}.`);
    }
    return descriptor;
  } catch (cause) {
    closeSync(descriptor);
    throw cause;
  }
}

function recoverClaimedAtomicFileReplacement(
  path: string,
  options: AtomicFileRecoveryOptions,
  parentDescriptor: number,
  transactionDescriptor: number,
  transactionStatus: BigIntStats
): void {
  const directory = transactionDirectory(path);
  const userId = BigInt(options.userId);
  const fileMode = normalizedFileMode(options.fileMode);
  const originalWorkingDirectory = process.cwd();
  let anchored = false;
  try {
    verifyTransactionDirectoryPath(directory, transactionStatus);
    process.chdir(directory);
    anchored = true;
    if (!sameDirectory(transactionStatus, lstatSync(".", { bigint: true }))) {
      throw new Error(`Atomic recovery directory changed: ${directory}.`);
    }
    verifyTransactionDirectoryPath(directory, transactionStatus);
    const entries = readdirSync(".").sort();
    if (
      entries.some(
        (entry) =>
          entry !== "candidate" &&
          entry !== "displaced" &&
          entry !== "record" &&
          entry !== "record-preparing"
      )
    ) {
      throw new Error(
        `Atomic recovery directory has unexpected entries: ${directory}.`
      );
    }
    const candidatePath = "candidate";
    const displacedPath = "displaced";
    const recordPath = "record";
    const preparingRecordPath = "record-preparing";
    const preparingRecord = statusIfPresent(preparingRecordPath);
    let mutated = false;
    if (preparingRecord !== undefined) {
      if (entries.length !== 1) {
        throw new Error(
          `Atomic preparing record has competing transaction state: ${preparingRecordPath}.`
        );
      }
      verifyPreparingRecord(preparingRecordPath, userId);
      unlinkSync(preparingRecordPath);
      fsyncSync(transactionDescriptor);
      mutated = true;
    }
    let candidate = statusIfPresent(candidatePath);
    let displaced = statusIfPresent(displacedPath);
    const recordStatus = statusIfPresent(recordPath);
    if (recordStatus === undefined) {
      if (displaced !== undefined) {
        throw new Error(`Atomic recovery record is missing: ${recordPath}.`);
      }
      if (candidate !== undefined) {
        verifyCandidate(candidatePath, userId, fileMode, [1n]);
        fsyncSync(parentDescriptor);
        fsyncSync(transactionDescriptor);
        unlinkSync(candidatePath);
        mutated = true;
      }
    }
    const record =
      recordStatus === undefined
        ? undefined
        : readTransactionRecord(recordPath, userId);
    const expected =
      record === undefined
        ? undefined
        : verifyTransactionRecord(record, path, fileMode, userId);
    let preservesCompetingDestination = false;
    if (record !== undefined) {
      if (displaced !== undefined && expected?.state !== "present") {
        throw new Error(`Atomic recovery cannot validate ${displacedPath}.`);
      }
      let destination = statusIfPresent(path);
      if (destination === undefined) {
        if (candidate !== undefined) {
          candidateMatchesRecord(
            candidatePath,
            userId,
            fileMode,
            [1n, 2n],
            record.candidateDigest
          );
          linkSync(candidatePath, path);
        } else if (displaced !== undefined && expected?.state === "present") {
          const displacedLinkCount = lstatSync(displacedPath, {
            bigint: true,
          }).nlink;
          if (
            !preservedDestinationPathHasExpectedLinks(
              expected,
              displacedPath,
              displacedLinkCount
            )
          ) {
            throw new Error(
              `Atomic recovery cannot validate ${displacedPath}.`
            );
          }
          restoreDisplacedDestination(displacedPath, path, userId);
        } else if (displaced !== undefined) {
          throw new Error(`Atomic recovery cannot validate ${displacedPath}.`);
        }
        if (candidate !== undefined || displaced !== undefined) {
          fsyncSync(parentDescriptor);
          fsyncSync(transactionDescriptor);
          destination = lstatSync(path, { bigint: true });
        }
      }
      candidate = statusIfPresent(candidatePath);
      displaced = statusIfPresent(displacedPath);
      if (candidate !== undefined) {
        candidateMatchesRecord(
          candidatePath,
          userId,
          fileMode,
          [1n, 2n],
          record.candidateDigest
        );
        if (
          destination !== undefined &&
          !sameIdentity(candidate, destination)
        ) {
          const destinationIsExpected =
            expected?.state === "present" &&
            preservedDestinationPathHasExpectedLinks(
              expected,
              path,
              destination.nlink
            );
          preservesCompetingDestination = !destinationIsExpected;
        }
      }
      if (displaced !== undefined) {
        const displacedLinkCount = lstatSync(displacedPath, {
          bigint: true,
        }).nlink;
        const displacedIsExpected =
          expected?.state === "present" &&
          preservedDestinationPathHasExpectedLinks(
            expected,
            displacedPath,
            displacedLinkCount
          );
        const displacedIsChangedCanonical =
          candidate !== undefined &&
          destination !== undefined &&
          expected?.state === "present" &&
          sameIdentity(displaced, destination) &&
          displaced.dev === expected.device &&
          displaced.ino === expected.inode &&
          displaced.uid === expected.userId &&
          (displaced.mode & 0o777n) === (expected.mode & 0o777n);
        if (!displacedIsExpected && !displacedIsChangedCanonical) {
          throw new Error(`Atomic recovery cannot validate ${displacedPath}.`);
        }
        if (displacedIsChangedCanonical) {
          preservesCompetingDestination = true;
        }
      }
      destination = statusIfPresent(path);
      const destinationIsCandidate = destinationMatchesCandidateRecord(
        path,
        userId,
        fileMode,
        [1n, 2n],
        record.candidateDigest
      );
      const destinationIsExpected =
        destination !== undefined &&
        expected?.state === "present" &&
        preservedDestinationPathHasExpectedLinks(
          expected,
          path,
          destination.nlink
        );
      if (
        destination !== undefined &&
        !destinationIsCandidate &&
        !destinationIsExpected
      ) {
        preservesCompetingDestination = true;
      }
      if (
        preservesCompetingDestination &&
        (candidate === undefined || candidate.nlink > 1n)
      ) {
        throw new Error(
          `Atomic recovery preserved a competing destination at ${path}.`
        );
      }
      fsyncSync(parentDescriptor);
      fsyncSync(transactionDescriptor);
      displaced = statusIfPresent(displacedPath);
      if (displaced !== undefined) {
        unlinkSync(displacedPath);
        mutated = true;
      }
      candidate = statusIfPresent(candidatePath);
      if (candidate !== undefined) {
        const currentDestination = statusIfPresent(path);
        const allowedLinkCounts =
          currentDestination !== undefined &&
          sameIdentity(candidate, currentDestination)
            ? [2n]
            : [1n];
        candidateMatchesRecord(
          candidatePath,
          userId,
          fileMode,
          allowedLinkCounts,
          record.candidateDigest
        );
        unlinkSync(candidatePath);
        mutated = true;
      }
      if (!preservesCompetingDestination) {
        if (destination === undefined) {
          if (expected?.state !== "absent") {
            throw new Error(
              `Atomic recovery cannot validate completion: ${path}.`
            );
          }
        } else {
          const finalDestination = lstatSync(path, { bigint: true });
          const isOriginal =
            expected?.state === "present" &&
            preservedDestinationPathMatches(
              expected,
              path,
              finalDestination.nlink
            );
          const isInstalled = destinationMatchesCandidateRecord(
            path,
            userId,
            fileMode,
            [1n],
            record.candidateDigest
          );
          if (!isOriginal && !isInstalled) {
            throw new Error(
              `Atomic recovery cannot validate completion: ${path}.`
            );
          }
        }
      }
      unlinkSync(recordPath);
      mutated = true;
    }
    if (mutated) fsyncSync(transactionDescriptor);
    if (readdirSync(".").length !== 0) {
      throw new Error(`Atomic recovery remains incomplete: ${directory}.`);
    }
    verifyTransactionDirectoryPath(directory, transactionStatus);
  } finally {
    if (anchored) process.chdir(originalWorkingDirectory);
  }
  verifyTransactionDirectoryPath(directory, transactionStatus);
}

function recoverAtomicFileReplacementLocked(
  path: string,
  options: AtomicFileRecoveryOptions,
  parentDescriptor: number
): void {
  const directory = transactionDirectory(path);
  const ownerPath = transactionOwnerPath(path);
  const userId = BigInt(options.userId);
  const ownerStatus = statusIfPresent(ownerPath);
  const directoryStatus = statusIfPresent(directory);
  if (ownerStatus === undefined) {
    if (directoryStatus === undefined) return;
    const descriptor = openVerifiedTransactionDirectory(directory, userId);
    const transactionStatus = fstatSync(descriptor, { bigint: true });
    const originalWorkingDirectory = process.cwd();
    let anchored = false;
    try {
      verifyTransactionDirectoryPath(directory, transactionStatus);
      process.chdir(directory);
      anchored = true;
      if (!sameDirectory(transactionStatus, lstatSync(".", { bigint: true }))) {
        throw new Error(`Atomic recovery directory changed: ${directory}.`);
      }
      verifyTransactionDirectoryPath(directory, transactionStatus);
      if (readdirSync(".").length === 0) return;
    } finally {
      if (anchored) process.chdir(originalWorkingDirectory);
      closeSync(descriptor);
    }
    throw new Error(`Atomic transaction owner is missing: ${ownerPath}.`);
  }
  const owner = readTransactionOwner(ownerPath, userId);
  if (!transactionOwnerIsCurrent(owner) && transactionOwnerIsLive(owner)) {
    throw new Error(
      `Atomic replacement is active in another process: ${path}.`
    );
  }
  if (directoryStatus === undefined) {
    removeTransactionOwner(ownerPath, owner, userId);
    fsyncSync(parentDescriptor);
    return;
  }
  const transactionDescriptor = openVerifiedTransactionDirectory(
    directory,
    userId
  );
  const transactionStatus = fstatSync(transactionDescriptor, { bigint: true });
  try {
    recoverClaimedAtomicFileReplacement(
      path,
      options,
      parentDescriptor,
      transactionDescriptor,
      transactionStatus
    );
  } finally {
    closeSync(transactionDescriptor);
  }
  removeTransactionOwner(ownerPath, owner, userId);
  fsyncSync(parentDescriptor);
}

export function writeFileAtomicallySync(
  path: string,
  data: Parameters<typeof writeFileSync>[1],
  options: AtomicFileWriteOptions = {}
): void {
  const directory = dirname(path);
  const failures: Error[] = [];
  const fileMode = normalizedFileMode(options.fileMode ?? 0o600);
  const userId = process.getuid?.();
  let committed = false;
  let parent: number | undefined;
  let replacementLock: number | undefined;
  let transaction: number | undefined;
  let temporary: number | undefined;
  let temporaryPath: string | undefined;
  let transactionStarted = false;
  let transactionOwnerAcquired = false;

  try {
    mkdirSync(directory, { recursive: true, mode: options.directoryMode });
    parent = openSync(directory, "r");
    const parentStatus = fstatSync(parent, { bigint: true });
    if (options.expectedDestination !== undefined) {
      if (!isAbsolute(path)) {
        throw new Error(
          `Atomic replacement requires an absolute path: ${path}.`
        );
      }
      if (userId === undefined) {
        throw new Error(
          "Atomic destination replacement requires a Unix user ID."
        );
      }
      replacementLock = openTransactionLock(
        transactionLockPath(path),
        BigInt(userId),
        parent
      );
      recoverAtomicFileReplacementLocked(path, { fileMode, userId }, parent);
      if (
        !atomicFileDestinationsMatch(
          options.expectedDestination,
          captureAtomicFileDestination(path)
        )
      ) {
        throw new Error(`Atomic destination changed before commit: ${path}.`);
      }
      if (
        !sameDirectory(parentStatus, lstatSync(directory, { bigint: true }))
      ) {
        throw new Error(`Atomic destination directory changed: ${directory}.`);
      }
      const transactionPath = transactionDirectory(path);
      const ownerPath = transactionOwnerPath(path);
      symlinkSync(currentTransactionOwnerTarget(), ownerPath);
      transactionOwnerAcquired = true;
      fsyncSync(parent);
      try {
        mkdirSync(transactionPath, { mode: 0o700 });
        fsyncSync(parent);
      } catch (cause) {
        if (
          !(
            cause instanceof Error &&
            "code" in cause &&
            cause.code === "EEXIST"
          )
        ) {
          throw cause;
        }
      }
      transactionStarted = true;
      transaction = openVerifiedTransactionDirectory(
        transactionPath,
        BigInt(userId)
      );
      if (readdirSync(transactionPath).length !== 0) {
        throw new Error(
          `Atomic transaction directory is not empty: ${transactionPath}.`
        );
      }
      const candidatePath = `${transactionPath}/candidate`;
      const recordPath = `${transactionPath}/record`;
      const preparingRecordPath = `${transactionPath}/record-preparing`;
      const candidateDigest = (() => {
        const digest = createHash("sha256");
        if (typeof data === "string") {
          digest.update(data);
        } else {
          digest.update(
            new Uint8Array(data.buffer, data.byteOffset, data.byteLength)
          );
        }
        return digest.digest("hex");
      })();
      const record: TransactionRecord = {
        version: 2,
        destination: path,
        fileMode,
        expected: serializeDestination(options.expectedDestination),
        candidateDigest,
      };
      const recordDescriptor = openSync(preparingRecordPath, "wx", 0o600);
      try {
        fchmodSync(recordDescriptor, 0o600);
        writeFileSync(recordDescriptor, serializeTransactionRecord(record));
        fsyncSync(recordDescriptor);
      } finally {
        closeSync(recordDescriptor);
      }
      renameSync(preparingRecordPath, recordPath);
      fsyncSync(transaction);
      temporary = openSync(candidatePath, "wx", fileMode);
      fchmodSync(temporary, fileMode);
      writeFileSync(temporary, data);
      fsyncSync(temporary);
      closeSync(temporary);
      temporary = undefined;
      candidateMatchesRecord(
        candidatePath,
        BigInt(userId),
        fileMode,
        [1n],
        candidateDigest
      );
      fsyncSync(transaction);
      fsyncSync(parent);
      if (options.expectedDestination.state === "absent") {
        options.beforeCommit?.();
        linkSync(candidatePath, path);
      } else {
        const displacedPath = `${transactionPath}/displaced`;
        linkSync(path, displacedPath);
        fsyncSync(transaction);
        if (
          !preservedDestinationPathMatches(
            options.expectedDestination,
            path,
            options.expectedDestination.linkCount + 1n
          ) ||
          !preservedDestinationPathMatches(
            options.expectedDestination,
            displacedPath,
            options.expectedDestination.linkCount + 1n
          )
        ) {
          throw new Error(`Atomic destination changed before commit: ${path}.`);
        }
        options.beforeCommit?.();
        if (
          !preservedDestinationPathMatches(
            options.expectedDestination,
            path,
            options.expectedDestination.linkCount + 1n
          ) ||
          !preservedDestinationPathMatches(
            options.expectedDestination,
            displacedPath,
            options.expectedDestination.linkCount + 1n
          )
        ) {
          throw new Error(`Atomic destination changed at commit: ${path}.`);
        }
        renameSync(candidatePath, path);
      }
      fsyncSync(parent);
      fsyncSync(transaction);
      committed = true;
      options.afterDestinationLink?.();
      const displacedPath = `${transactionPath}/displaced`;
      if (
        !destinationMatchesCandidateRecord(
          path,
          BigInt(userId),
          fileMode,
          [options.expectedDestination.state === "absent" ? 2n : 1n],
          candidateDigest
        )
      ) {
        throw new Error(
          `Atomic destination changed after installation: ${path}.`
        );
      }
      if (statusIfPresent(displacedPath) !== undefined) {
        if (
          options.expectedDestination.state !== "present" ||
          !preservedDestinationPathMatches(
            options.expectedDestination,
            displacedPath,
            options.expectedDestination.linkCount
          )
        ) {
          throw new Error(`Displaced destination changed: ${displacedPath}.`);
        }
        fsyncSync(parent);
        fsyncSync(transaction);
        unlinkSync(displacedPath);
        fsyncSync(transaction);
      }
      if (statusIfPresent(candidatePath) !== undefined) {
        verifyCommittedDestination(
          candidatePath,
          path,
          BigInt(userId),
          fileMode,
          candidateDigest
        );
        fsyncSync(parent);
        fsyncSync(transaction);
        unlinkSync(candidatePath);
        fsyncSync(transaction);
      }
      unlinkSync(recordPath);
      fsyncSync(transaction);
      closeSync(transaction);
      transaction = undefined;
      transactionStarted = false;
      unlinkSync(ownerPath);
      transactionOwnerAcquired = false;
      fsyncSync(parent);
      closeSync(replacementLock);
      replacementLock = undefined;
    } else {
      temporaryPath = `${path}.${process.pid}.${randomUUID()}.tmp`;
      temporary = openSync(temporaryPath, "wx", fileMode);
      fchmodSync(temporary, fileMode);
      writeFileSync(temporary, data);
      fsyncSync(temporary);
      closeSync(temporary);
      temporary = undefined;
      options.beforeCommit?.();
      renameSync(temporaryPath, path);
      temporaryPath = undefined;
      committed = true;
      fsyncSync(parent);
    }
  } catch (cause) {
    failures.push(errorFromUnknown(cause));
  }

  if (temporary !== undefined) {
    captureFailure(failures, () => closeSync(temporary));
  }
  if (transaction !== undefined) {
    captureFailure(failures, () => closeSync(transaction));
  }
  if (temporaryPath !== undefined) {
    captureFailure(failures, () => unlinkSync(temporaryPath));
  }
  if (
    (transactionStarted || transactionOwnerAcquired) &&
    userId !== undefined &&
    parent !== undefined &&
    replacementLock !== undefined
  ) {
    captureFailure(failures, () =>
      recoverAtomicFileReplacementLocked(path, { fileMode, userId }, parent)
    );
  }
  if (replacementLock !== undefined) {
    captureFailure(failures, () => closeSync(replacementLock));
  }
  if (parent !== undefined) {
    captureFailure(failures, () => closeSync(parent));
  }

  if (failures.length > 0) {
    const cause =
      failures.length === 1
        ? failures[0]
        : new AggregateError(failures, "Atomic file cleanup also failed.");
    throw new AtomicFileWriteError(committed, { cause });
  }
}

