function cliFailureMessage(error: unknown, depth = 0): string {
  if (error instanceof AggregateError) {
    const failures = error.errors.map((cause) =>
      cliFailureMessage(cause, depth + 1)
    );
    if (failures.length > 0) return failures.join("; ");
  }
  const resolved = errorFromUnknown(error);
  const cause = (error as { cause?: unknown } | null)?.cause;
  if (cause === undefined || depth >= 5) return resolved.message;
  return `${resolved.message.replace(/\.$/u, "")}: ${cliFailureMessage(cause, depth + 1)}`;
}

function pathPresent(path: string): boolean {
  try {
    lstatSync(path);
    return true;
  } catch (cause) {
    if (cause instanceof Error && "code" in cause && cause.code === "ENOENT") {
      return false;
    }
    throw cause;
  }
}

async function findPriorAgentBridgeArtifact(): Promise<string | undefined> {
  const home = homedir();
  const priorEnvironmentFile = join(
    home,
    ".config",
    "murderbox",
    "agent-bridge.env"
  );
  const priorConfigurationDirectory = join(home, ".config", "murderbox");
  const priorRepository = join(home, "code", "murderbox-production");
  const priorSystemdUnit = join(
    home,
    ".config",
    "systemd",
    "user",
    "murderbox-agent-bridge.service"
  );
  const priorLaunchdPlist = join(
    home,
    "Library",
    "LaunchAgents",
    "com.joedeleeuw.murderbox-agent-bridge.plist"
  );
  for (const path of [
    priorEnvironmentFile,
    priorConfigurationDirectory,
    priorRepository,
    priorSystemdUnit,
    priorLaunchdPlist,
  ]) {
    if (pathPresent(path)) return path;
  }
  if (process.platform === "linux") {
    const { stdout } = await execFileAsync("systemctl", [
      "--user",
      "show",
      "murderbox-agent-bridge.service",
      "--property=LoadState",
      "--value",
    ]);
    if (stdout.trim() !== "not-found") {
      return "murderbox-agent-bridge.service";
    }
  }
  if (process.platform === "darwin") {
    const userId = process.getuid?.();
    if (userId === undefined) {
      throw new Error("launchd requires a Unix user ID.");
    }
    try {
      await execFileAsync("launchctl", [
        "print",
        `gui/${userId}/com.joedeleeuw.murderbox-agent-bridge`,
      ]);
      return "com.joedeleeuw.murderbox-agent-bridge";
    } catch (cause) {
      const message = cause instanceof Error ? cause.message.toLowerCase() : "";
      if (
        !message.includes("could not find service") &&
        !message.includes("not loaded")
      ) {
        throw cause;
      }
    }
  }
  return undefined;
}

