  issueLittleBirdAction: async (env, ownerIdentityToken, machineId) => {
    const { issueLittleBirdAction } = await import("./little-bird-action");
    return issueLittleBirdAction(env, ownerIdentityToken, machineId);
  },
  persistOwnerAuth: (env, machineId, credential) =>
    saveClerkAuthFile(env.HOMER_MACHINE_AUTH_FILE, {
      version: 1,
      machineId,
      refreshToken: credential.refreshToken,
      cachedIdToken: {
        idToken: credential.idToken,
        expiresAt: credential.idTokenExpiresAt,
      },
    }),
  initializeState: (stateFilePath) =>
    initializePersistedBridgeState(
      stateFilePath,
      randomUUID(),
      new Date().toISOString()
    ),
  acquireRuntimeLock,
  displayPairingCode,
  stdout: process.stdout,
  stderr: process.stderr,
  terminal: { input: process.stdin, output: process.stdout },
  isInteractiveTerminal: () =>
    process.stdin.isTTY === true && process.stdout.isTTY === true,
  runLifecycleCommand: (command) =>
    runDefaultLifecycleCommand(command, defaultDependencies),
  signals: process,
  exit: async (code) => process.exit(code),
  version: process.env.npm_package_version,
};

async function runDefaultLifecycleCommand(
  command: CliCommand,
  cliDependencies: CliDependencies
): Promise<CliResult> {
  if (
    command.kind !== "status" &&
    command.kind !== "check" &&
    command.kind !== "service" &&
    command.kind !== "init"
  ) {
    throw new Error(`${command.kind} is not implemented.`);
  }
  if (command.kind === "check") {
    return await checkMachine(defaultMachineCheckDependencies());
  }
  const hostAdapter = selectMachineHostAdapter(process.platform);
  const serviceManager =
    cliDependencies.serviceManager ?? hostAdapter.serviceManager();
  const environmentFilePath =
    cliDependencies.environmentFilePath ?? hostAdapter.environmentFilePath();
  const inspect = async () => {
    const service = await serviceManager.inspect();
    return inspectLocalMachine({
      environmentFilePath,
      service: service.status,
    });
  };
  if (command.kind === "init") {
    await serviceManager.requireAbsent();
    return withServiceLifecycleLock(environmentFilePath, async () => {
      await serviceManager.requireAbsent();
      return initializeMachine(command, {
        inspect,
        resolveConfiguration: async () => {
          const readline = command.json
            ? undefined
            : createInterface({
                input: cliDependencies.terminal?.input ?? process.stdin,
                output: cliDependencies.terminal?.output ?? process.stdout,
              });
          try {
            return await resolveInitConfiguration({
              path: environmentFilePath,
              userId: hostAdapter.currentUserId(),
              interactive: !command.json,
              prompt: readline
                ? async (key) => {
                    try {
                      return await readline.question(`${key}: `);
                    } catch (cause) {
                      throw new InitPromptCancelledError(
                        "Initialization cancelled.",
                        { cause }
                      );
                    }
                  }
                : undefined,
            });
          } finally {
            readline?.close();
          }
        },
        pair: async (configuration, presentation) => {
          return pairMachine(
            {
              ...cliDependencies,
              readPairingEnv: () => configuration.pairing,
              readServeEnv: () =>
                configuration.serve(hostAdapter.terminalSocketPath()),
            },
            presentation
          );
        },
        serviceManager,
      });
    });
  }
  if (command.kind === "service") {
    try {
      const service = await runServiceOperation(
        serviceManager,
        command.operation
      );
      const inspected = await inspectLocalMachine({
        environmentFilePath,
        service: service.status,
      });
      return {
        version: 1,
        command: "service",
        ok: true,
        ...localMachineResultFields(inspected),
        action: command.operation,
      };
    } catch (cause) {
      const broken = cause instanceof InvalidMachineStateError;
      const unsupported = cause instanceof UnsupportedServicePlatformError;
      const detail = cliFailureMessage(cause);
      return {
        version: 1,
        command: "service",
        ok: false,
        error: {
          code: broken
            ? "broken-state"
            : unsupported
              ? "unsupported-platform"
              : "operation-failed",
          message: broken
            ? cause.message
            : unsupported
              ? "Service management is unsupported on this platform."
              : "Service operation failed.",
          ...(broken || unsupported ? {} : { diagnostic: detail }),
        },
      };
    }
  }
  if (command.kind === "status") {
    const local = await inspect();
    return {
      version: 1,
      command: "status",
      ok: true,
      ...localMachineResultFields(local),
      action: "inspected",
    };
  }
  throw new Error("Unsupported lifecycle command.");
}

function writeHumanLifecycleResult(
  result: CliResult,
  dependencies: CliDependencies
): void {
  const stdout = dependencies.stdout ?? process.stdout;
  if (!result.ok) {
    const label =
      result.command === "init"
        ? "Machine init"
        : result.command === "status"
          ? "Machine status"
          : result.command === "check"
            ? "Machine check"
            : result.command === "service"
              ? "Machine service"
              : "Machine lifecycle";
    dependencies.stderr.write(
      `${label} failed: ${result.error.diagnostic === undefined ? result.error.message : `${result.error.message.replace(/\.$/u, "")}: ${result.error.diagnostic}`}\n`
    );
    dependencies.stderr.write(
      `Repair: ${"repair" in result ? (result.repair ?? "explicit owner action required; no automatic repair") : result.error.code === "broken-state" ? "repair the reported local artifacts before retrying" : "resolve the reported failure before retrying"}.\n`
    );
    dependencies.stderr.write(
      `Next: ${"next" in result && result.next ? result.next : "none"}\n`
    );
    return;
  }
  if (result.command === "init") {
    stdout.write(
      `${result.local.host}: ${result.action} (${result.local.level}, ${result.local.runtime}, ${result.local.service})\nNext: ${result.next ?? "none"}\n`
    );
    return;
  }
  if (result.command === "status") {
    stdout.write(
      `${result.local.host}: ${result.local.level} (${result.local.runtime}, ${result.local.service})\n${result.local.level === "broken" && result.local.configurationError ? `Error: ${result.local.configurationError}\n` : ""}Next: ${result.next ?? "none"}\n`
    );
    return;
  }
  if (result.command === "check") {
    stdout.write(
      `${result.local.host}: checked (${result.health.availableAgents} available agents)\nProjection: ${result.projection.machineId} (connected)\nEndpoint: ${result.endpoint}\nOrigin: ${result.origin}\nNext: none\n`
    );
    return;
  }
  if (result.command === "service") {
    stdout.write(
      `service: ${result.local.service} (${result.action})\nNext: ${result.next ?? "none"}\n`
    );
  }
}

function bridgeLaunchArguments(
  env: MachineEnv,
  version: string | undefined,
  logger: LoggerFactory
) {
  const auth = loadClerkAuthFile(env.HOMER_MACHINE_AUTH_FILE);
  const authService = createClerkAuthService({
    authFilePath: env.HOMER_MACHINE_AUTH_FILE,
    issuer: env.HOMER_CLERK_OAUTH_ISSUER,
    clientId: env.HOMER_CLI_OAUTH_CLIENT_ID,
  });
  const trustVerifier = createConvexMachineTrustVerifier({
    convexUrl: env.HOMER_CONVEX_URL,
    identity: authService,
  });
  return {
    options: {
      host: env.HOMER_MACHINE_HOST,
      port: env.HOMER_MACHINE_PORT,
      machineId: auth.machineId,
      executors: [
        new CodexCliExecutorAdapter([env.HOMER_MACHINE_CODEX_COMMAND]),
        new ClaudeCliExecutorAdapter([env.HOMER_MACHINE_CLAUDE_COMMAND]),
        new CursorCliExecutorAdapter([env.HOMER_MACHINE_CURSOR_COMMAND]),
      ],
      version,
      corsOrigins: env.HOMER_MACHINE_CORS_ORIGINS,
      publicEndpoint: env.HOMER_MACHINE_PUBLIC_ENDPOINT,
      stateFilePath: env.HOMER_MACHINE_STATE_FILE,
      terminalSocketPath: env.HOMER_MACHINE_TERMINAL_SOCKET,
    },
    dependencies: {
      verifyRequestToken: authService.verifyRequestToken,
      verifyMachineTrust: trustVerifier.verify,
      syncSender: createConvexMachineSyncSender({
        convexUrl: env.HOMER_CONVEX_URL,
        identity: authService,
      }),
      logger,
    },
  };
}

const failStoppedRuntimeLocks = new Set<RuntimeLock>();

function failStop(
  dependencies: CliDependencies,
  runtimeLock: RuntimeLock,
  cause: unknown
): Promise<never> {
  failStoppedRuntimeLocks.add(runtimeLock);
  try {
    dependencies.stderr.write(
      `Unable to stop Homer Machine: ${cliFailureMessage(cause)}\n`
    );
  } catch (writeCause) {
    void writeCause;
  }
  return dependencies.exit(1);
}

async function requireSupervisedMachine(): Promise<void> {
  const platforms = {
    linux: async () => {
      const invocation = process.env.INVOCATION_ID;
      if (!invocation || !/^[0-9a-f]{32}$/u.test(invocation)) return false;
      const { stdout } = await execFileAsync("systemctl", [
        "--user",
        "show",
        "homer-machine.service",
        "--property=InvocationID",
        "--value",
      ]);
      return stdout.trim() === invocation;
    },
    darwin: async () => process.env.XPC_SERVICE_NAME === macosServiceLabel,
  } satisfies Record<"linux" | "darwin", () => Promise<boolean>>;
  const platform = process.platform;
  if (
    (platform !== "linux" && platform !== "darwin") ||
    !(await platforms[platform]())
  ) {
    throw new Error(
      "Machine serve requires the supervised service; run `homer machine service start`."
    );
  }
}

async function serve(dependencies: CliDependencies): Promise<void> {
  const env = dependencies.readServeEnv();
  const runtimeLock = await dependencies.acquireRuntimeLock(
    env.HOMER_MACHINE_AUTH_FILE
  );
  let server: RunningMachineServer | undefined;
  try {
    const logger = createMachineLoggerFactory(dependencies);
    const launch = bridgeLaunchArguments(env, dependencies.version, logger);
    const startedServer = await dependencies.listenServer(
      launch.options,
      launch.dependencies
    );
    logger("machine:daemon").info("Machine listening", {
      url: startedServer.url,
    });
    server = startedServer;

    let closePromise: Promise<void> | undefined;
    const close = () => {
      closePromise ??= (async () => {
        try {
          await startedServer.close();
          await runtimeLock.release();
        } catch (cause) {
          return failStop(dependencies, runtimeLock, cause);
        }
        return dependencies.exit(0);
      })();
      return closePromise;
    };
    dependencies.signals.once("SIGINT", () => {
      void close();
    });
    dependencies.signals.once("SIGTERM", () => {
      void close();
    });
  } catch (cause) {
    const failures = [errorFromUnknown(cause)];
    let quiescent = server === undefined;
    if (server) {
      try {
        await server.close();
        quiescent = true;
      } catch (cause) {
        await failStop(dependencies, runtimeLock, cause);
      }
    }
    if (quiescent) {
      try {
        await runtimeLock.release();
      } catch (cleanupCause) {
        failures.push(errorFromUnknown(cleanupCause));
      }
    }
    if (failures.length === 1) throw failures[0];
    throw new AggregateError(failures, "Unable to start Homer Machine.", {
      cause,
    });
  }
}

export type PairMachineResult = {
  machineId: MachineId;
  littleBirdLink: string;
};

async function pairMachine(
  dependencies: CliDependencies,
  presentation: "human" | "json"
): Promise<PairMachineResult> {
  const env = dependencies.readPairingEnv();
  const runtimeLock = await dependencies.acquireRuntimeLock(
    env.HOMER_MACHINE_AUTH_FILE
  );
  let primaryCause: unknown;
  let hasPrimaryCause = false;
  let result: PairMachineResult | undefined;
  try {
    const serveEnv = dependencies.readServeEnv();
    if (serveEnv.HOMER_MACHINE_AUTH_FILE !== env.HOMER_MACHINE_AUTH_FILE) {
      throw new Error("Pairing and serving must use the same auth file.");
    }
    const hasExistingAuth = existsSync(env.HOMER_MACHINE_AUTH_FILE);
    const hasExistingState = existsSync(serveEnv.HOMER_MACHINE_STATE_FILE);
    if (hasExistingAuth !== hasExistingState) {
      throw new Error(
        "Machine auth and persisted state must either both exist or both be absent."
      );
    }
    const machineId = hasExistingAuth
      ? (() => {
          const auth = loadClerkAuthFile(env.HOMER_MACHINE_AUTH_FILE);
          loadPersistedBridgeState(serveEnv.HOMER_MACHINE_STATE_FILE);
          return auth.machineId;
        })()
      : randomUUID();
    const credential =
      presentation === "json"
        ? await dependencies.authenticateOwner(env, {
            openBrowser: false,
            authorizationReady: (authorizationUrl, callbackUrl) => {
              dependencies.stderr.write(
                `Open this authorization URL:\n${authorizationUrl}\nComplete the callback at ${callbackUrl}\n`
              );
            },
          })
        : await dependencies.authenticateOwner(env);
    if (hasExistingAuth) {
      dependencies.persistOwnerAuth(env, machineId, credential);
    } else {
      persistFreshPairing(
        env.HOMER_MACHINE_AUTH_FILE,
        serveEnv.HOMER_MACHINE_STATE_FILE,
        {
          persistOwnerAuth: () =>
            dependencies.persistOwnerAuth(env, machineId, credential),
          initializeState: () =>
            dependencies.initializeState(serveEnv.HOMER_MACHINE_STATE_FILE),
        }
      );
    }
    const actionId = await dependencies.issueLittleBirdAction(
      env,
      credential.idToken,
      machineId
    );
    const pairingLink = littleBirdLink(actionId, env.HOMER_CLIENT_ORIGIN);
    if (presentation === "human") {
      await dependencies.displayPairingCode(pairingLink);
    }
    result = { machineId, littleBirdLink: pairingLink };
  } catch (cause) {
    hasPrimaryCause = true;
    primaryCause = cause;
  }
  let cleanupCause: unknown;
  try {
    await runtimeLock.release();
  } catch (cause) {
    cleanupCause = cause;
  }
  if (hasPrimaryCause) {
    if (cleanupCause !== undefined) {
      throw new AggregateError(
        [primaryCause, cleanupCause],
        "Machine pairing and runtime lock cleanup both failed.",
        { cause: cleanupCause }
      );
    }
    throw primaryCause;
  }
  if (cleanupCause !== undefined) throw cleanupCause;
  if (result === undefined) {
    throw new Error("Machine pairing completed without a result.");
  }
  return result;
}

type JsonCliCommand = Exclude<CliCommand, { kind: "serve" }>;

function writeJsonLifecycleFailure(
  command: JsonCliCommand,
  detail: string,
  dependencies: CliDependencies,
  message = command.kind === "service"
    ? "Service operation failed."
    : "Lifecycle command failed."
): void {
  (dependencies.stdout ?? process.stdout).write(
    serializeCliResult(jsonLifecycleFailureResult(command, detail, message))
  );
}

function jsonLifecycleFailureResult(
  command: JsonCliCommand,
  detail: string,
  message = command.kind === "service"
    ? "Service operation failed."
    : "Lifecycle command failed."
): unknown {
  return command.kind === "check"
    ? {
        version: 1,
        command: "check" as const,
        ok: false as const,
        stage: "internal" as const,
        error: {
          code: "operation-failed" as const,
          message: "Machine check failed.",
          diagnostic: detail,
        },
      }
    : command.kind === "pair"
      ? {
          version: 1,
          command: "pair" as const,
          ok: false as const,
          error: {
            code: "operation-failed" as const,
            message: "Unable to create Little Bird pairing code.",
            diagnostic: detail,
          },
        }
      : {
          version: 1,
          command: command.kind,
          ok: false as const,
          error: {
            code: "operation-failed" as const,
            message,
            diagnostic: detail,
          },
        };
}

function requiresPriorArtifactRefusal(command: CliCommand): boolean {
  return (
    command.kind === "init" ||
    command.kind === "serve" ||
    (command.kind === "service" && command.operation === "install")
  );
}

type LifecycleExecution = {
  result: unknown;
  exitCode: number;
};

async function runLifecycleCommand(
  command: Exclude<CliCommand, { kind: "serve" } | { kind: "pair" }>,
  dependencies: CliDependencies
): Promise<LifecycleExecution> {
  try {
    if (!dependencies.runLifecycleCommand) {
      throw new Error("Lifecycle command is unavailable.");
    }
    const result = await dependencies.runLifecycleCommand(command);
    const projectionExitCode =
      !result.ok && result.command === "check" && result.stage === "projection"
        ? Object.values(machineProjectionFailures).find(
            (row) => row.code === result.error.code
          )?.exitCode
        : undefined;
    const exitCode = result.ok
      ? 0
      : projectionExitCode !== undefined
        ? projectionExitCode
        : result.error.code === "broken-state"
          ? 3
          : result.error.code === "cancelled"
            ? 130
            : result.error.code === "usage"
              ? 2
              : 1;
    if (command.json) {
      serializeCliResult(result);
      return { result, exitCode };
    }
    serializeCliResult(result);
    writeHumanLifecycleResult(result, dependencies);
    return { result: undefined, exitCode };
  } catch (cause) {
    const detail = cliFailureMessage(cause);
    if (cause instanceof InvalidMachineStateError && command.kind === "init") {
      const result = {
        version: 1,
        command: "init",
        ok: false,
        error: { code: "broken-state", message: detail },
      } satisfies CliResult;
      if (!command.json) writeHumanLifecycleResult(result, dependencies);
      return { result: command.json ? result : undefined, exitCode: 3 };
    }
    if (command.json) {
      return {
        result: jsonLifecycleFailureResult(command, detail),
        exitCode: 1,
      };
    }
    const label =
      command.kind === "init"
        ? "Machine init"
        : command.kind === "status"
          ? "Machine status"
          : command.kind === "check"
            ? "Machine check"
            : "Machine service";
    dependencies.stderr.write(
      `${label} failed: Lifecycle command failed: ${detail}\n`
    );
    dependencies.stderr.write(
      "Repair: resolve the reported failure before retrying.\n"
    );
    dependencies.stderr.write("Next: none\n");
    return { result: undefined, exitCode: 1 };
  }
}

async function runCli(
  args: string[],
  dependencies: CliDependencies = defaultDependencies
): Promise<number> {
  let command: CliCommand;
  try {
    if (args[0] !== "machine") throw new Error(cliUsage);
    command = parseCliCommand(
      args.slice(1),
      dependencies.isInteractiveTerminal?.() ??
        (process.stdin.isTTY === true && process.stdout.isTTY === true)
    );
  } catch (cause) {
    const usageMessage = errorFromUnknown(cause).message;
    if (args.includes("--json")) {
      (dependencies.stdout ?? process.stdout).write(
        serializeCliResult({
          version: 1,
          command: "usage",
          ok: false,
          error: { code: "usage", message: usageMessage },
        })
      );
    } else {
      dependencies.stderr.write(`${usageMessage}\n`);
    }
    return 2;
  }

  if (
    requiresPriorArtifactRefusal(command) &&
    dependencies.findPriorAgentBridgeArtifact
  ) {
    try {
      const artifact = await dependencies.findPriorAgentBridgeArtifact();
      if (artifact !== undefined) {
        const detail = `Prior agent-bridge artifact ${artifact} is present; retire it manually before running Homer Machine.`;
        if (command.kind !== "serve" && command.json) {
          writeJsonLifecycleFailure(command, detail, dependencies);
        } else {
          dependencies.stderr.write(`${detail}\n`);
        }
        return 3;
      }
    } catch (cause) {
      const detail = cliFailureMessage(cause);
      if (command.kind !== "serve" && command.json) {
        writeJsonLifecycleFailure(command, detail, dependencies);
      } else {
        const label =
          command.kind === "init" ? "Machine init" : "Machine service";
        const message =
          command.kind === "init"
            ? "Lifecycle command failed:"
            : "Service operation failed:";
        dependencies.stderr.write(`${label} failed: ${message} ${detail}\n`);
        dependencies.stderr.write(
          "Repair: resolve the reported failure before retrying.\n"
        );
        dependencies.stderr.write("Next: none\n");
      }
      return 1;
    }
  }

  if (command.kind !== "serve" && command.kind !== "pair") {
    const lifecycleExecution = await runLifecycleCommand(command, dependencies);
    if (lifecycleExecution === undefined) return 3;
    if (command.json) {
      (dependencies.stdout ?? process.stdout).write(
        serializeCliResult(lifecycleExecution.result)
      );
    }
    return lifecycleExecution.exitCode;
  }

  try {
    if (command.kind === "serve") {
      await requireSupervisedMachine();
      await serve(dependencies);
    } else {
      const result = await pairMachine(
        dependencies,
        command.json ? "json" : "human"
      );
      if (command.json) {
        (dependencies.stdout ?? process.stdout).write(
          serializeCliResult({
            version: 1,
            command: "pair",
            ok: true,
            action: "paired",
            littleBirdLink: result.littleBirdLink,
          })
        );
      }
    }
    return 0;
  } catch (error) {
    if (
      error instanceof RuntimeLockHeldError &&
      (command.kind === "serve" || !command.json)
    ) {
      dependencies.stderr.write(`${error.message}\n`);
      return 1;
    }
    if (command.kind === "pair" && command.json) {
      const cancelled = error instanceof OwnerAuthCancelledError;
      (dependencies.stdout ?? process.stdout).write(
        serializeCliResult({
          version: 1,
          command: "pair",
          ok: false,
          error: cancelled
            ? {
                code: "cancelled",
                message: "Little Bird pairing was cancelled.",
              }
            : {
                code: "operation-failed",
                message: "Unable to create Little Bird pairing code.",
                diagnostic: cliFailureMessage(error),
              },
        })
      );
    } else {
      const failureMessage = cliFailureMessage(error);
      dependencies.stderr.write(
        command.kind === "pair"
          ? `${
              error instanceof OwnerAuthCancelledError
                ? "Little Bird pairing was cancelled"
                : "Unable to create Little Bird pairing code"
            }: ${failureMessage}\n`
          : `Unable to start Homer Machine: ${failureMessage}\n`
      );
    }
    return error instanceof OwnerAuthCancelledError ? 130 : 1;
  }
}

async function main() {
  const exitCode = await runCli(process.argv.slice(2));
  if (exitCode !== 0) process.exitCode = exitCode;
}

const entryPath = process.argv[1];
if (entryPath && import.meta.url === pathToFileURL(entryPath).href) {
  void main();
}

import { join } from "node:path";
import {
  launcherToken,
  releaseRootToken,
  systemdPathValue,
  terminalHardenToken,
  terminalStartToken,
} from "./linux-systemd-projection.js";
import type { MachineCliLauncherProjection } from "./machine-cli-launcher.js";

const environmentFilePathToken = "@@HOMER_MACHINE_ENVIRONMENT_FILE@@";
const terminalExecutableToken = "@@HOMER_TERMINAL_TTYD@@";

/**
 * Fails the install rather than projecting a terminal unit whose
 * `ConditionPathExists` systemd would quietly skip at start time.
 *
 * The path arrives already resolved (`linux-ttyd.ts`, honouring
 * `HOMER_MACHINE_TTYD_EXECUTABLE` exactly as macOS does). It is load-bearing in
 * three places that must agree, and this projection is what welds them: the
 * `ConditionPathExists=` and `Environment=HOMER_MACHINE_TTYD_EXECUTABLE=` lines
 * in the unit below, `start-terminal.sh` which execs the value the unit gave
 * it, and the `/proc/<pid>/exe` identity check in `linux-terminal-process.ts`.
 * Because the installed unit must byte-equal this render, the identity check's
 * expectation cannot diverge from what actually launched ttyd.
 */
export function requireLinuxTerminalExecutable(
  terminalExecutable: string,
  exists: (path: string) => boolean
): void {
  if (exists(terminalExecutable)) return;
  throw new Error(
    `The Machine terminal service requires ttyd at ${terminalExecutable}; install the distribution ttyd package or set HOMER_MACHINE_TTYD_EXECUTABLE to an executable ttyd.`
  );
}

