RuntimeDirectoryMode=0700
UMask=0077
Environment=HOME=%h
Environment=HOMER_TERMINAL_FONT_SIZE=15
Environment=HOMER_TERMINAL_SOCKET=%t/homer-terminal/ttyd.sock
