export function renderLinuxBridgeServiceUnit(
  launcher: MachineCliLauncherProjection,
  environmentFile = "%h/.config/homer/machine.env"
): string {
  return linuxBridgeServiceTemplate
    .replaceAll(releaseRootToken, systemdPathValue(launcher.repositoryRoot))
    .replaceAll(launcherToken, systemdPathValue(launcher.launcherPath))
    .replaceAll(
      environmentFilePathToken,
      environmentFile.startsWith("%h/")
        ? environmentFile
        : systemdPathValue(environmentFile)
    );
}

export function renderLinuxTerminalServiceUnit(
  launcher: MachineCliLauncherProjection,
  terminalExecutable: string
): string {
  return linuxTerminalServiceTemplate
    .replaceAll(terminalExecutableToken, systemdPathValue(terminalExecutable))
    .replaceAll(releaseRootToken, systemdPathValue(launcher.repositoryRoot))
    .replaceAll(
      terminalStartToken,
      systemdPathValue(
        join(
          launcher.repositoryRoot,
          "apps",
          "api",
          "scripts",
          "start-terminal.sh"
        )
      )
    )
    .replaceAll(
      terminalHardenToken,
      systemdPathValue(
        join(
          launcher.repositoryRoot,
          "apps",
          "api",
          "scripts",
          "harden-terminal-socket.sh"
        )
      )
    );
}

import { ConvexHttpClient } from "convex/browser";
import { makeFunctionReference } from "convex/server";
import type { FunctionArgs, FunctionReturnType } from "convex/server";
import type { MachineId } from "@homer/shared/machine-id";
import type { MachineSyncIdentity } from "./sync.js";
import type { api } from "../../client/convex/_generated/api";

export type MachineTrustVerifier = {
  verify(machineId: MachineId): Promise<void>;
};

export class MachineTrustRemovedError extends Error {
  constructor() {
    super("Authenticated owner is not paired with this Machine.");
    this.name = "MachineTrustRemovedError";
  }
}

type GetMachine = typeof api.machines.get;
type GetMachineArgs = FunctionArgs<GetMachine>;
type GetMachineResult = FunctionReturnType<GetMachine>;

export const getMachine = makeFunctionReference<
  "query",
  GetMachineArgs,
  GetMachineResult
>("machines:get");

export function createConvexMachineTrustVerifier(options: {
  convexUrl: string;
  identity: MachineSyncIdentity;
  fetch?: typeof fetch;
  requestTimeoutMs?: number;
  query?: (idToken: string, machineId: MachineId) => Promise<GetMachineResult>;
}): MachineTrustVerifier {
  const request = options.fetch ?? fetch;
  const query =
    options.query ??
    (async (idToken: string, machineId: MachineId) => {
      const client = new ConvexHttpClient(options.convexUrl, {
        auth: idToken,
        fetch: (input, init) =>
          request(input, {
            ...init,
            signal: AbortSignal.timeout(options.requestTimeoutMs ?? 10_000),
          }),
      });
      return await client.query(getMachine, { machineId });
    });

  return {
    verify: async (machineId) => {
      const idToken = await options.identity.getIdentityToken();
      const machine = await query(idToken, machineId);
      if (
        machine === null ||
        machine.id !== machineId ||
        machine.access.status !== "ready"
      ) {
        throw new MachineTrustRemovedError();
      }
    },
  };
}

import { constants } from "node:fs";
import { lstat, mkdir, open, type FileHandle } from "node:fs/promises";
import { dirname, resolve, sep } from "node:path";
import { setTimeout as delay } from "node:timers/promises";
import {
  tryAcquireAdvisoryFileLock,
  type AdvisoryFileLockDependencies,
} from "./advisory-file-lock";
import { errorFromUnknown } from "./errors";

export type RuntimeLock = {
  descriptor: number;
  path: string;
  release(): Promise<void>;
};

export class RuntimeLockHeldError extends Error {}

type FileIdentity = {
  dev: bigint;
  ino: bigint;
};

type RuntimeLockDependencies = AdvisoryFileLockDependencies & {
  beforeReleaseClose?: (path: string) => Promise<void>;
};

type ServiceLifecycleLockDependencies = RuntimeLockDependencies & {
  timeoutMilliseconds?: number;
  retryDelay?: (milliseconds: number) => Promise<void>;
  now?: () => number;
};

const noFollow = constants.O_NOFOLLOW ?? 0;

function hasFileSystemErrorCode(error: unknown, code: string): boolean {
  return error instanceof Error && "code" in error && error.code === code;
}

function currentUserId(): number {
  const userId = process.getuid?.();
  if (userId === undefined) {
    throw new Error("Runtime locks require a Unix user ID.");
  }
  return userId;
}

function sameFile(
  stats: { dev: number | bigint; ino: number | bigint },
  identity: FileIdentity
): boolean {
  return (
    BigInt(stats.dev) === identity.dev && BigInt(stats.ino) === identity.ino
  );
}

function verifyPrivateFile(
  path: string,
  stats: {
    isFile(): boolean;
    isSymbolicLink(): boolean;
    uid: number | bigint;
    mode: number | bigint;
    nlink: number | bigint;
  }
): void {
  if (!stats.isFile() || stats.isSymbolicLink()) {
    throw new Error(`Runtime lock is not a regular file: ${path}`);
  }
  if (Number(stats.uid) !== currentUserId()) {
    throw new Error(`Runtime lock is not owned by the current user: ${path}`);
  }
  if ((Number(stats.mode) & 0o777) !== 0o600) {
    throw new Error(`Runtime lock must have mode 0600: ${path}`);
  }
  if (Number(stats.nlink) !== 1) {
    throw new Error(`Runtime lock must have exactly one link: ${path}`);
  }
}

async function verifyPrivateParent(path: string): Promise<FileIdentity> {
  const parent = dirname(path);
  const stats = await lstat(parent, { bigint: true });
  if (
    !stats.isDirectory() ||
    stats.isSymbolicLink() ||
    Number(stats.uid) !== currentUserId() ||
    (Number(stats.mode) & 0o777) !== 0o700
  ) {
    throw new Error(`Runtime lock parent is not owned mode 0700: ${parent}`);
  }
  return { dev: stats.dev, ino: stats.ino };
}

async function verifyStableParent(
  path: string,
  expected: FileIdentity
): Promise<void> {
  const actual = await verifyPrivateParent(path);
  if (actual.dev !== expected.dev || actual.ino !== expected.ino) {
    throw new Error(
      `Runtime lock parent changed during access: ${dirname(path)}`
    );
  }
}

async function verifyCanonicalLock(
  path: string,
  identity: FileIdentity,
  parentIdentity: FileIdentity
): Promise<void> {
  const stats = await lstat(path, { bigint: true });
  verifyPrivateFile(path, stats);
  if (!sameFile(stats, identity)) {
    throw new Error(`Runtime lock ownership changed: ${path}`);
  }
  await verifyStableParent(path, parentIdentity);
}

type DirectoryStatus = {
  isDirectory(): boolean;
  isSymbolicLink(): boolean;
  uid: number | bigint;
};

function requireRealDirectory(path: string, status: DirectoryStatus): void {
  if (status.isSymbolicLink() || !status.isDirectory()) {
    throw new Error(
      `Runtime lock parent path is not a real directory: ${path}`
    );
  }
}

function requireTraversableComponent(
  path: string,
  status: DirectoryStatus
): void {
  if (status.isSymbolicLink() && Number(status.uid) === 0) return;
  requireRealDirectory(path, status);
}

async function directoryStatusIfPresent(path: string) {
  try {
    return await lstat(path, { bigint: true });
  } catch (error) {
    if (hasFileSystemErrorCode(error, "ENOENT")) return undefined;
    throw error;
  }
}

async function createOwnedDirectory(path: string): Promise<void> {
  try {
    await mkdir(path, { mode: 0o700 });
  } catch (cause) {
    if (!hasFileSystemErrorCode(cause, "EEXIST")) throw cause;
  }
  const status = await lstat(path, { bigint: true });
  requireRealDirectory(path, status);
  if (Number(status.uid) !== currentUserId()) {
    throw new Error(
      `Runtime lock parent path is not owned by the current user: ${path}`
    );
  }
}

async function createLockParent(directory: string): Promise<void> {
  const segments = resolve(directory)
    .split(sep)
    .filter((segment) => segment.length > 0);
  let current = "";
  let creating = false;
  for (const segment of segments) {
    current = `${current}${sep}${segment}`;
    if (creating) {
      await createOwnedDirectory(current);
      continue;
    }
    const status = await directoryStatusIfPresent(current);
    if (status !== undefined) {
      requireTraversableComponent(current, status);
      continue;
    }
    creating = true;
    await createOwnedDirectory(current);
  }
}

async function openLockFile(
  path: string,
  create: boolean
): Promise<{
  handle: FileHandle;
  identity: FileIdentity;
  parentIdentity: FileIdentity;
}> {
  if (create) await createLockParent(dirname(path));
  const parentIdentity = await verifyPrivateParent(path);
  let handle: FileHandle;
  try {
    handle = await open(
      path,
      constants.O_RDWR | noFollow | (create ? constants.O_CREAT : 0),
      0o600
    );
  } catch (cause) {
    if (hasFileSystemErrorCode(cause, "ELOOP")) {
      throw new Error(`Runtime lock is not a regular file: ${path}`, { cause });
    }
    throw cause;
  }
  try {
    const stats = await handle.stat({ bigint: true });
    verifyPrivateFile(path, stats);
    const identity = { dev: stats.dev, ino: stats.ino };
    await verifyCanonicalLock(path, identity, parentIdentity);
    return { handle, identity, parentIdentity };
  } catch (cause) {
    try {
      await handle.close();
    } catch (closeCause) {
      throw new AggregateError(
        [errorFromUnknown(cause), errorFromUnknown(closeCause)],
        `Runtime lock validation and close both failed: ${path}`,
        { cause: closeCause }
      );
    }
    throw cause;
  }
}

async function closeAfterFailure(
  handle: FileHandle,
  path: string,
  cause: unknown
): Promise<never> {
  const failures = [errorFromUnknown(cause)];
  try {
    await handle.close();
  } catch (closeCause) {
    failures.push(errorFromUnknown(closeCause));
  }
  if (failures.length > 1) {
    throw new AggregateError(
      failures,
      `Runtime lock operation and cleanup both failed: ${path}`,
      { cause: failures.at(-1) }
    );
  }
  throw cause;
}

async function acquireOwnedPathLock(
  path: string,
  dependencies: RuntimeLockDependencies = {}
): Promise<RuntimeLock> {
  const opened = await openLockFile(path, true);
  let acquired: boolean;
  try {
    acquired = await tryAcquireAdvisoryFileLock(opened.handle.fd, dependencies);
  } catch (cause) {
    return closeAfterFailure(opened.handle, path, cause);
  }
  if (!acquired) {
    await opened.handle.close();
    throw new RuntimeLockHeldError(
      "Homer Machine runtime is already active; run `homer machine service stop` first."
    );
  }
  try {
    await verifyCanonicalLock(path, opened.identity, opened.parentIdentity);
  } catch (cause) {
    return closeAfterFailure(opened.handle, path, cause);
  }
  let released = false;
  return {
    descriptor: opened.handle.fd,
    path,
    release: async () => {
      if (released) return;
      await dependencies.beforeReleaseClose?.(path);
      await opened.handle.close();
      released = true;
    },
  };
}

function runtimeLockPath(authFilePath: string): string {
  return `${authFilePath}.runtime.lock`;
}

function serviceLifecycleLockPath(environmentFile: string): string {
  return `${environmentFile}.service-lifecycle.lock`;
}

export async function inspectRuntimeLock(
  authFilePath: string
): Promise<{ status: "absent" | "live" }> {
  const path = runtimeLockPath(authFilePath);
  let opened;
  try {
    opened = await openLockFile(path, false);
  } catch (cause) {
    if (hasFileSystemErrorCode(cause, "ENOENT")) return { status: "absent" };
    throw cause;
  }
  try {
    const acquired = await tryAcquireAdvisoryFileLock(opened.handle.fd);
    await verifyCanonicalLock(path, opened.identity, opened.parentIdentity);
    return { status: acquired ? "absent" : "live" };
  } finally {
    await opened.handle.close();
  }
}

export async function waitForRuntimeLock(authFilePath: string): Promise<void> {
  for (let attempt = 0; attempt < 100; attempt += 1) {
    if ((await inspectRuntimeLock(authFilePath)).status === "live") return;
    await delay(50);
  }
  throw new Error("The supervised Machine did not acquire its runtime lock.");
}

export async function acquireRuntimeLock(
  authFilePath: string,
  dependencies: RuntimeLockDependencies = {}
): Promise<RuntimeLock> {
  return acquireOwnedPathLock(runtimeLockPath(authFilePath), dependencies);
}

async function acquireContendedPathLock(
  path: string,
  timeoutMessage: string,
  dependencies: ServiceLifecycleLockDependencies
): Promise<RuntimeLock> {
  const timeoutMilliseconds = dependencies.timeoutMilliseconds ?? 30_000;
  const retryDelay = dependencies.retryDelay ?? delay;
  const now = dependencies.now ?? Date.now;
  const startedAt = now();
  let lastContention: Error | undefined;
  do {
    try {
      return await acquireOwnedPathLock(path, dependencies);
    } catch (error) {
      if (!(error instanceof RuntimeLockHeldError)) {
        throw error;
      }
      lastContention = error;
    }
    await retryDelay(25);
  } while (now() - startedAt < timeoutMilliseconds);
  throw new Error(timeoutMessage, { cause: lastContention });
}

export async function acquireServiceLifecycleLock(
  environmentFile: string,
  dependencies: ServiceLifecycleLockDependencies = {}
): Promise<RuntimeLock> {
  return acquireContendedPathLock(
    serviceLifecycleLockPath(environmentFile),
    `Timed out waiting for the Machine service lifecycle lock: ${environmentFile}`,
    dependencies
  );
}

import {
  createServer,
  type IncomingMessage,
  type ServerResponse,
} from "node:http";
import type { AddressInfo } from "node:net";
import { conversationIdSchema } from "@homer/shared/conversation-id";
import {
  machineTerminalGrantRequestSchema,
  turnIdSchema,
  type MachineAuthErrorResponse,
  type MachineErrorResponse,
} from "@homer/shared/machine";
import { ClerkAuthUnavailableError } from "./clerk-auth.js";
import { errorFromUnknown } from "./errors.js";
import { classifyRoute } from "./http-routes.js";
import { writeJSON } from "./http-response.js";
import { machineError } from "./machine-errors.js";
import { handleHealth } from "./route-handlers.js";
import {
  applyCorsHeaders,
  enqueueRosterSnapshot,
  normalizeOptions,
  type MachineServerDependencies,
  type MachineServerOptions,
  type RequestAuthPurpose,
  type ServerState,
} from "./server-options.js";
import {
  cancelActiveExecutions,
  cancelTurn,
  startTurn,
} from "./turn-lifecycle.js";

export type RunningMachineServer = {
  url: string;
  close(): Promise<void>;
};

export type {
  MachineServerDependencies,
  MachineServerOptions,
} from "./server-options.js";

async function captureFailure(
  failures: Error[],
  operation: () => void | Promise<void>
): Promise<void> {
  try {
    await operation();
  } catch (cause) {
    failures.push(errorFromUnknown(cause));
  }
}

function authError(
  reason: MachineAuthErrorResponse["reason"]
): MachineAuthErrorResponse {
  const messages = {
    missing_bearer: "Clerk session authorization is required.",
    malformed_bearer: "Authorization header must use Bearer authentication.",
    invalid_session: "Clerk session authorization was rejected.",
  };
  return {
    code: "auth_failed",
    message: messages[reason],
    retryable: false,
    recoverable: true,
    httpStatus: 401,
    reason,
  };
}

async function authorize(
  request: IncomingMessage,
  state: ServerState,
  purpose: RequestAuthPurpose
): Promise<MachineErrorResponse | null> {
  const header = request.headers.authorization;
  if (!header) return authError("missing_bearer");
  const match = /^Bearer\s+(.+)$/.exec(header);
  if (!match?.[1]?.trim()) return authError("malformed_bearer");
  try {
    await state.verifyRequestToken(match[1].trim(), purpose);
    return null;
  } catch (cause) {
    if (cause instanceof ClerkAuthUnavailableError) {
      return machineError(
        "unavailable",
        "Clerk session verification is unavailable.",
        503
      );
    }
    return authError("invalid_session");
  }
}

function writeMachineError(
  response: ServerResponse,
  error: MachineErrorResponse
): void {
  writeJSON(response, error.httpStatus, error);
}

function isTerminalGrantRequest(
  request: IncomingMessage,
  state: Pick<ServerState, "host" | "port">
): boolean {
  if (!request.url) return false;
  try {
    return (
      new URL(request.url, `http://${state.host}:${state.port}`).pathname ===
      "/v2/terminal/grants"
    );
  } catch {
    return false;
  }
}

async function routeRequest(
  request: IncomingMessage,
  response: ServerResponse,
  state: ServerState
): Promise<void> {
  if (isTerminalGrantRequest(request, state)) {
    response.setHeader("cache-control", "no-store");
    response.setHeader("referrer-policy", "no-referrer");
  }
  const corsAllowed = applyCorsHeaders(request, response, state);
  if (request.method === "OPTIONS") {
    response.writeHead(corsAllowed ? 204 : 403);
    response.end();
    return;
  }
  if (request.headers.origin && !corsAllowed) {
    writeMachineError(
      response,
      machineError("forbidden", "Origin is not allowed.", 403)
    );
    return;
  }
  if (!request.url) {
    writeMachineError(
      response,
      machineError("invalid_request", "Missing request URL.", 400)
    );
    return;
  }
  const url = new URL(request.url, `http://${state.host}:${state.port}`);
  if (await state.terminalProxy.handleHttp(request, response, url)) return;
  const route = classifyRoute(url.pathname, request.method);
  const purpose: RequestAuthPurpose =
    route.kind === "health"
      ? "health"
      : route.kind === "turnCancel"
        ? "cancel"
        : route.kind === "terminalGrants"
          ? "terminal"
          : "normal";
  const authFailure = await authorize(request, state, purpose);
  if (authFailure) {
    writeJSON(response, authFailure.httpStatus, authFailure);
    return;
  }
  if (route.kind === "reject") {
    writeMachineError(response, route.error);
    return;
  }
  if (route.kind === "health") {
    writeJSON(response, 200, await handleHealth(state));
    return;
  }
  if (!state.acceptingCommands) {
    writeMachineError(
      response,
      machineError("unavailable", "Daemon is stopping.", 503)
    );
    return;
  }
  if (route.kind === "terminalGrants") {
    const chunks: Buffer[] = [];
    let received = 0;
    for await (const chunk of request) {
      const buffer = Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk);
      received += buffer.byteLength;
      if (received > 1_024) {
        writeMachineError(
          response,
          machineError(
            "invalid_request",
            "Terminal grant request is too large.",
            413
          )
        );
        return;
      }
      chunks.push(buffer);
    }
    try {
      const text = Buffer.concat(chunks).toString("utf8");
      const parsedBody = machineTerminalGrantRequestSchema.safeParse(
        text.trim() ? JSON.parse(text) : {}
      );
      if (!parsedBody.success) {
        writeMachineError(
          response,
          machineError(
            "invalid_request",
            "Invalid terminal grant request.",
            400
          )
        );
        return;
      }
    } catch {
      writeMachineError(
        response,
        machineError(
          "invalid_request",
          "Terminal grant request must be JSON.",
          400
        )
      );
      return;
    }
    try {
      writeJSON(response, 201, await state.terminalProxy.mint());
    } catch {
      writeMachineError(
        response,
        machineError("unavailable", "Terminal runtime is unavailable.", 503)
      );
    }
    return;
  }
  if (state.persistenceFailure) {
    writeMachineError(
      response,
      machineError(
        "harness_error",
        "Daemon persistence failed; restart is required.",
        503
      )
    );
    return;
  }
  if (route.kind === "conversationTurnStart") {
    const conversationId = conversationIdSchema.safeParse(route.conversationId);
    if (!conversationId.success) {
      writeMachineError(
        response,
        machineError("invalid_request", "Invalid conversation id.", 400)
      );
      return;
    }
    await startTurn(conversationId.data, request, response, state);
    return;
  }
  const turnId = turnIdSchema.safeParse(route.turnId);
  if (!turnId.success) {
    writeMachineError(
      response,
      machineError("invalid_request", "Invalid turn id.", 400)
    );
    return;
  }
  await cancelTurn(turnId.data, request, response, state);
}

export async function listenMachineServer(
  options: MachineServerOptions,
  dependencies: MachineServerDependencies
): Promise<RunningMachineServer> {
  const state = normalizeOptions(options, dependencies);
  const server = createServer((request, response) => {
    void routeRequest(request, response, state).catch((cause: unknown) => {
      const failure = errorFromUnknown(cause);
      state.logger.error("Machine request failed", {
        error: failure.message,
        method: request.method ?? null,
        path: request.url ?? null,
      });
      if (response.headersSent) {
        response.destroy(failure);
        return;
      }
      writeJSON(
        response,
        500,
        machineError("harness_error", failure.message, 500)
      );
    });
  });
  server.on("upgrade", (request, socket, head) => {
    if (!request.url) {
      socket.destroy();
      return;
    }
    let url: URL;
    try {
      url = new URL(request.url, `http://${state.host}:${state.port}`);
    } catch {
      socket.destroy();
      return;
    }
    void state.terminalProxy
      .handleUpgrade(request, socket, head, url)
      .then((handled) => {
        if (!handled) socket.destroy();
      })
      .catch((cause: unknown) => {
        state.logger.warn("Terminal upgrade failed", {
          error: errorFromUnknown(cause).message,
        });
        socket.destroy();
      });
  });
  const unsubscribeRoster = state.roster.subscribe(() => {
    enqueueRosterSnapshot(state);
  });
  await state.roster.start();
  state.syncWorker.start();
  return await new Promise((resolve, reject) => {
    server.once("error", (error) => {
      void (async () => {
        const listenFailure = errorFromUnknown(error);
        state.logger.error("Machine listener failed", {
          error: listenFailure.message,
          host: state.host,
          port: state.port,
        });
        const cleanupFailures: Error[] = [];
        await captureFailure(cleanupFailures, unsubscribeRoster);
        await captureFailure(cleanupFailures, () => state.syncWorker.stop());
        reject(
          cleanupFailures.length === 0
            ? listenFailure
            : new AggregateError(
                [listenFailure, ...cleanupFailures],
                "Unable to listen for Homer Machine requests."
              )
        );
      })();
    });
    server.listen(state.port, state.host, () => {
      server.removeAllListeners("error");
      const address = server.address() as AddressInfo;
      state.port = address.port;
      state.logger.info("Machine listener ready", {
        host: state.host,
        port: state.port,
      });
      let closePromise: Promise<void> | undefined;
      const close = () => {
        closePromise ??= (async () => {
          state.logger.info("Machine shutdown started");
          state.acceptingCommands = false;
          const failures: Error[] = [];
          await captureFailure(failures, () => state.terminalProxy.close());
          await captureFailure(failures, unsubscribeRoster);
          const serverClose = new Promise<void>((closeResolve, closeReject) => {
            server.close((error) => {
              if (error) closeReject(error);
              else closeResolve();
            });
          });
          await captureFailure(failures, () =>
            cancelActiveExecutions(state, "Daemon stopping.")
          );
          await captureFailure(failures, () => state.syncWorker.stop());
          await captureFailure(failures, () => serverClose);
          if (failures.length > 1) {
            throw new AggregateError(failures, "Unable to stop Homer Machine.");
          }
          const [failure] = failures;
          if (failure) throw failure;
          state.logger.info("Machine shutdown completed");
        })();
        return closePromise;
      };
      resolve({
        url: `http://${state.host}:${state.port}`,
        close,
      });
    });
  });
}

import { accessSync, constants, statSync } from "node:fs";
import { delimiter, isAbsolute, join, resolve } from "node:path";

/**
 * Both hosts read the same override key so an operator does not have to learn a
 * per-OS variable name. The host-specific modules (`macos-ttyd.ts`,
 * `linux-ttyd.ts`) supply only their candidate directories.
 */
const ttydExecutableEnvironmentKey = "HOMER_MACHINE_TTYD_EXECUTABLE";

export type TtydResolutionOptions = {
  environment?: NodeJS.ProcessEnv;
  candidatePaths?: readonly string[];
  isExecutableFile?(path: string): boolean;
};

function executableRegularFile(path: string): boolean {
  try {
    accessSync(path, constants.X_OK);
    return statSync(path).isFile();
  } catch {
    return false;
  }
}

export function resolveTtydExecutable(
  hostLabel: string,
  defaultCandidatePaths: readonly string[],
  options: TtydResolutionOptions = {}
): string {
  const environment = options.environment ?? process.env;
  const isExecutableFile = options.isExecutableFile ?? executableRegularFile;
  const configuredValue = environment[ttydExecutableEnvironmentKey];
  if (configuredValue !== undefined) {
    const configured = configuredValue.trim();
    if (configured.length === 0) {
      throw new Error(`${ttydExecutableEnvironmentKey} must not be blank.`);
    }
    if (!isAbsolute(configured) || resolve(configured) !== configured) {
      throw new Error(
        `${ttydExecutableEnvironmentKey} must be an absolute normalized path.`
      );
    }
    if (!isExecutableFile(configured)) {
      throw new Error(
        `${ttydExecutableEnvironmentKey} does not name an executable regular file: ${configured}.`
      );
    }
    return configured;
  }

  const candidates = [
    ...(options.candidatePaths ?? defaultCandidatePaths),
    ...(environment.PATH ?? "")
      .split(delimiter)
      .filter((directory) => isAbsolute(directory))
      .map((directory) => join(directory, "ttyd")),
  ];
  const uniqueCandidates = [...new Set(candidates)];
  for (const candidate of uniqueCandidates) {
    if (isExecutableFile(candidate)) return candidate;
  }
  throw new Error(
    `Unable to resolve ttyd for the ${hostLabel} Machine service. Install ttyd or set ${ttydExecutableEnvironmentKey} to its executable path. Searched: ${uniqueCandidates.join(", ") || "no executable candidates"}.`
  );
}

