export type ResolvedAnswer = { address: string; family: 4 | 6 };

class ProbeDeadlineError extends Error {}

class ProbeDeadline {
  readonly signal: AbortSignal;
  private readonly controller = new AbortController();
  private readonly timeout: ReturnType<typeof setTimeout>;
  private readonly externalSignal: AbortSignal | undefined;
  private readonly abortFromExternal = () => this.controller.abort();

  constructor(externalSignal?: AbortSignal) {
    this.signal = this.controller.signal;
    this.timeout = setTimeout(() => this.controller.abort(), PROBE_TIMEOUT_MS);
    this.externalSignal = externalSignal;
    if (externalSignal?.aborted) {
      this.controller.abort();
    } else {
      externalSignal?.addEventListener("abort", this.abortFromExternal, {
        once: true,
      });
    }
  }

  async run<T>(operation: () => Promise<T>): Promise<T> {
    if (this.signal.aborted) throw new ProbeDeadlineError();
    const pending = operation();
    return new Promise<T>((resolve, reject) => {
      const onAbort = () => reject(new ProbeDeadlineError());
      this.signal.addEventListener("abort", onAbort, { once: true });
      pending.then(resolve, reject).finally(() => {
        this.signal.removeEventListener("abort", onAbort);
      });
    });
  }

  dispose() {
    clearTimeout(this.timeout);
    this.externalSignal?.removeEventListener("abort", this.abortFromExternal);
  }
}

export type MachineEnrollmentDependencies<
  MachineView extends MachineWorkflowRecord = MachineWorkflowRecord,
> = {
  repository: MachineWorkflowRepository<MachineView>;
  now?(): Date;
} & MachineProbeDependencies;

export type MachineProbeDependencies = {
  resolveHost?(host: string): Promise<ResolvedAnswer[]>;
  connectAddress?(answer: ResolvedAnswer): ResolvedAnswer;
  signal?: AbortSignal;
};

type ResolvedMachineProbeDependencies = Required<
  Pick<MachineProbeDependencies, "connectAddress" | "resolveHost">
> &
  Pick<MachineProbeDependencies, "signal">;

type ResolvedMachineEnrollmentDependencies<
  MachineView extends MachineWorkflowRecord,
> = ResolvedMachineProbeDependencies & {
  repository: MachineWorkflowRepository<MachineView>;
  now(): Date;
};

type ValidatedEndpoint = {
  endpoint: MachineEndpoint;
  url: URL;
  answer: ResolvedAnswer;
};

type PerformedMachineProbeResult =
  | {
      kind: "ready";
      agents: MachinePairingAgentSummary[];
      attempt: MachineProbeAttempt;
    }
  | { kind: "authenticationRejected"; attempt: MachineProbeAttempt }
  | { kind: "invalidPayload"; attempt: MachineProbeAttempt }
  | { kind: "unavailable"; attempt: MachineProbeAttempt };

export type MachineProbeResult =
  | PerformedMachineProbeResult
  | { kind: "invalidIdentity" };

function resolveProbeDependencies(
  dependencies: MachineProbeDependencies
): ResolvedMachineProbeDependencies {
  return {
    resolveHost:
      dependencies.resolveHost ??
      (async (host) => {
        const answers = await dnsLookup(host, { all: true, verbatim: true });
        return answers.flatMap((answer) =>
          answer.family === 4 || answer.family === 6
            ? [{ address: answer.address, family: answer.family }]
            : []
        );
      }),
    connectAddress: dependencies.connectAddress ?? ((answer) => answer),
    ...(dependencies.signal ? { signal: dependencies.signal } : {}),
  };
}

function resolveDependencies<MachineView extends MachineWorkflowRecord>(
  dependencies: MachineEnrollmentDependencies<MachineView>
): ResolvedMachineEnrollmentDependencies<MachineView> {
  return {
    ...resolveProbeDependencies(dependencies),
    repository: dependencies.repository,
    now: dependencies.now ?? (() => new Date()),
  };
}

function ipv4Number(address: string): number | undefined {
  const parts = address.split(".");
  if (parts.length !== 4) return undefined;
  const octets = parts.map(Number);
  if (
    octets.some((octet) => !Number.isInteger(octet) || octet < 0 || octet > 255)
  ) {
    return undefined;
  }
  return octets.reduce((value, octet) => value * 256 + octet, 0) >>> 0;
}

function inIpv4Range(address: string, base: string, prefix: number) {
  const value = ipv4Number(address);
  const start = ipv4Number(base);
  if (value === undefined || start === undefined) return false;
  const mask = prefix === 0 ? 0 : (0xffffffff << (32 - prefix)) >>> 0;
  return (value & mask) === (start & mask);
}

type Ipv6Words = readonly [
  number,
  number,
  number,
  number,
  number,
  number,
  number,
  number,
];

type Ipv6WordStrings = readonly [
  string,
  string,
  string,
  string,
  string,
  string,
  string,
  string,
];

function hasEightWords(words: readonly string[]): words is Ipv6WordStrings {
  return words.length === 8;
}

function ipv6Words(address: string): Ipv6Words | undefined {
  if (isIP(address) !== 6) return undefined;
  const dottedMatch = /^(?<head>.*:)(?<dotted>\d+\.\d+\.\d+\.\d+)$/i.exec(
    address
  );
  let hexadecimal = address;
  const dottedHead = dottedMatch?.groups?.head;
  const dottedTail = dottedMatch?.groups?.dotted;
  if (dottedHead !== undefined && dottedTail !== undefined) {
    const value = ipv4Number(dottedTail);
    if (value === undefined) return undefined;
    hexadecimal = `${dottedHead}${(value >>> 16).toString(16)}:${(
      value & 0xffff
    ).toString(16)}`;
  }
  const halves = hexadecimal.toLowerCase().split("::");
  if (halves.length > 2) return undefined;
  const left = halves[0] ? halves[0].split(":") : [];
  const right = halves[1] ? halves[1].split(":") : [];
  const omitted = halves.length === 2 ? 8 - left.length - right.length : 0;
  const words = [
    ...left,
    ...Array.from({ length: omitted }, () => "0"),
    ...right,
  ];
  if (
    omitted < 0 ||
    !hasEightWords(words) ||
    words.some((word) => !/^[0-9a-f]{1,4}$/.test(word))
  ) {
    return undefined;
  }
  const [first, second, third, fourth, fifth, sixth, seventh, eighth] = words;
  return [
    Number.parseInt(first, 16),
    Number.parseInt(second, 16),
    Number.parseInt(third, 16),
    Number.parseInt(fourth, 16),
    Number.parseInt(fifth, 16),
    Number.parseInt(sixth, 16),
    Number.parseInt(seventh, 16),
    Number.parseInt(eighth, 16),
  ];
}

function mappedIpv4(address: string): string | undefined {
  const values = ipv6Words(address);
  if (
    !values ||
    values.slice(0, 5).some((word) => word !== 0) ||
    values[5] !== 0xffff
  ) {
    return undefined;
  }
  return [
    values[6] >>> 8,
    values[6] & 0xff,
    values[7] >>> 8,
    values[7] & 0xff,
  ].join(".");
}

function inIpv6Range(address: string, base: string, prefix: number) {
  const values = ipv6Words(address);
  const start = ipv6Words(base);
  if (!values || !start) return false;
  const completeWords = Math.floor(prefix / 16);
  if (
    values.slice(0, completeWords).some((word, index) => word !== start[index])
  ) {
    return false;
  }
  const remainingBits = prefix % 16;
  if (remainingBits === 0) return true;
  const mask = (0xffff << (16 - remainingBits)) & 0xffff;
  const word = values.at(completeWords);
  const startWord = start.at(completeWords);
  if (word === undefined || startWord === undefined) return false;
  return (word & mask) === (startWord & mask);
}

function isGloballyRoutable(address: string) {
  const mapped = mappedIpv4(address);
  if (mapped) return isGloballyRoutable(mapped);
  if (isIP(address) === 4) {
    return !IANA_IPV4_SPECIAL_PURPOSE_PREFIXES.some(([base, prefix]) =>
      inIpv4Range(address, base, prefix)
    );
  }
  if (isIP(address) !== 6 || !inIpv6Range(address, "2000::", 3)) return false;
  return !IANA_IPV6_SPECIAL_PURPOSE_PREFIXES.some(([base, prefix]) =>
    inIpv6Range(address, base, prefix)
  );
}

async function validateEndpoint(
  identity: MachinePairingIdentity,
  dependencies: ResolvedMachineProbeDependencies,
  deadline: ProbeDeadline
): Promise<ValidatedEndpoint | undefined> {
  let url: URL;
  try {
    url = new URL(identity.endpoint);
  } catch {
    return undefined;
  }
  if (
    url.protocol !== "https:" ||
    url.username ||
    url.password ||
    url.search ||
    url.hash ||
    url.pathname !== "/" ||
    isIP(url.hostname) !== 0
  ) {
    return undefined;
  }

  const answers = await deadline.run(() =>
    dependencies.resolveHost(url.hostname.toLowerCase())
  );
  if (
    answers.length === 0 ||
    answers.some(
      (answer) =>
        isIP(answer.address) !== answer.family ||
        !isGloballyRoutable(answer.address)
    )
  ) {
    return undefined;
  }
  const answer = [
    ...new Map(
      answers.map((candidate) => [
        `${candidate.family}:${candidate.address}`,
        candidate,
      ])
    ).values(),
  ].sort(
    (left, right) =>
      left.family - right.family || left.address.localeCompare(right.address)
  )[0];
  return answer ? { endpoint: identity.endpoint, url, answer } : undefined;
}

function readResponse(
  endpoint: ValidatedEndpoint,
  token: string,
  dependencies: ResolvedMachineProbeDependencies,
  signal: AbortSignal
): Promise<{ status: number; body: unknown }> {
  return new Promise((resolveResponse, rejectResponse) => {
    const connected = dependencies.connectAddress(endpoint.answer);
    const originalHostname = endpoint.url.hostname;
    let request: ReturnType<typeof httpsRequest> | undefined;
    try {
      request = httpsRequest(
        {
          protocol: "https:",
          hostname: originalHostname,
          port: endpoint.url.port || undefined,
          path: "/health",
          method: "GET",
          headers: {
            accept: "application/json",
            authorization: `Bearer ${token}`,
            connection: "close",
            host: endpoint.url.host,
          },
          lookup: (_hostname, options, callback) => {
            if (options.all) {
              callback(null, [connected]);
              return;
            }
            callback(null, connected.address, connected.family);
          },
          servername: originalHostname,
          signal,
        },
        (response) => {
          let bytes = 0;
          const chunks: Buffer[] = [];
          response.on("data", (chunk: Buffer) => {
            bytes += chunk.byteLength;
            if (bytes > MAX_RESPONSE_BYTES) {
              request?.destroy(new Error("response too large"));
              return;
            }
            chunks.push(chunk);
          });
          response.on("end", () => {
            try {
              resolveResponse({
                status: response.statusCode ?? 0,
                body: JSON.parse(Buffer.concat(chunks).toString("utf8")),
              });
            } catch (error) {
              rejectResponse(error);
            }
          });
        }
      );
    } catch (error) {
      rejectResponse(error);
      return;
    }
    request.on("error", rejectResponse);
    request.end();
  });
}

function probeAttempt(
  outcome: MachineProbeOutcome,
  detail?: string
): MachineProbeAttempt {
  const attempt: MachineProbeAttempt = { outcome };
  return detail ? { ...attempt, detail } : attempt;
}

function errorDetail(error: unknown): string {
  const message = error instanceof Error ? error.message : String(error);
  return message.trim() || "could not be reached";
}

async function probeValidatedEndpoint(
  endpoint: ValidatedEndpoint,
  expectedMachineId: MachineId,
  token: string,
  dependencies: ResolvedMachineProbeDependencies,
  deadline: ProbeDeadline
): Promise<PerformedMachineProbeResult> {
  try {
    const response = await deadline.run(() =>
      readResponse(endpoint, token, dependencies, deadline.signal)
    );
    if (response.status === 401) {
      const attempt = probeAttempt("http_error", "returned 401");
      return machineAuthErrorResponseSchema.safeParse(response.body).success
        ? { kind: "authenticationRejected", attempt }
        : { kind: "unavailable", attempt };
    }
    if (response.status < 200 || response.status >= 300) {
      const attempt = probeAttempt("http_error", `returned ${response.status}`);
      return { kind: "unavailable", attempt };
    }
    const health = machineHealthSchema.safeParse(response.body);
    if (!health.success) {
      const attempt = probeAttempt(
        "invalid_payload",
        `returned an unreadable health payload (HTTP ${response.status})`
      );
      return { kind: "unavailable", attempt };
    }
    if (health.data.machineId !== expectedMachineId) {
      const attempt = probeAttempt(
        "invalid_payload",
        "returned health for a different Machine"
      );
      return { kind: "unavailable", attempt };
    }
    if (health.data.status === "unavailable") {
      const attempt = probeAttempt(
        "self_reported_unavailable",
        "the daemon reported unavailable health"
      );
      return { kind: "unavailable", attempt };
    }
    const attempt = probeAttempt("ok", `returned ${response.status}`);
    return {
      kind: "ready",
      agents: health.data.agents.map(({ id, label }) => ({
        id,
        label,
      })),
      attempt,
    };
  } catch (error) {
    const attempt = probeAttempt("unreachable", errorDetail(error));
    return { kind: "unavailable", attempt };
  }
}

async function probeWithDependencies(
  identity: MachinePairingIdentity,
  token: string,
  dependencies: ResolvedMachineProbeDependencies
): Promise<PerformedMachineProbeResult> {
  const deadline = new ProbeDeadline(dependencies.signal);
  try {
    let endpoint: ValidatedEndpoint | undefined;
    try {
      endpoint = await validateEndpoint(identity, dependencies, deadline);
    } catch (error) {
      const attempt = probeAttempt("unreachable", errorDetail(error));
      return { kind: "unavailable", attempt };
    }
    if (!endpoint) {
      const attempt = probeAttempt(
        "invalid_payload",
        "failed endpoint validation"
      );
      return { kind: "invalidPayload", attempt };
    }
    return await probeValidatedEndpoint(
      endpoint,
      identity.id,
      token,
      dependencies,
      deadline
    );
  } finally {
    deadline.dispose();
  }
}

export function probeMachine(
  identity: unknown,
  token: string,
  dependencies: MachineProbeDependencies = {}
): Promise<MachineProbeResult> {
  const parsed = machinePairingIdentitySchema.safeParse(identity);
  if (!parsed.success) return Promise.resolve({ kind: "invalidIdentity" });
  return probeWithDependencies(
    parsed.data,
    token,
    resolveProbeDependencies(dependencies)
  );
}

export async function enrollMachine<MachineView extends MachineWorkflowRecord>(
  input: unknown,
  clerkJwt: string,
  suppliedDependencies: MachineEnrollmentDependencies<MachineView>
): Promise<MachineEnrollmentResult> {
  const parsed = littleBirdRequestSchema.safeParse(input);
  if (!parsed.success) {
    return { kind: "invalidPayload", message: INVALID_REQUEST_MESSAGE };
  }

  const dependencies = resolveDependencies(suppliedDependencies);
  const action = await dependencies.repository.inspectAction(
    parsed.data.actionId
  );
  if (action.kind === "invalidAction") {
    return { kind: "invalidPayload", message: INVALID_REQUEST_MESSAGE };
  }
  if (action.kind === "consumed") {
    return { kind: "alreadyConnected", machineId: action.machineId };
  }

  const identity = action.machine;
  const canonical =
    parsed.data.operation === "inspect"
      ? await dependencies.repository.get(identity.id)
      : null;
  if (parsed.data.operation === "inspect") {
    if (
      parsed.data.intent.kind === "new" &&
      canonical?.access.status === "ready"
    ) {
      return { kind: "alreadyConnected", machineId: identity.id };
    }
    if (
      parsed.data.intent.kind === "repair" &&
      (parsed.data.intent.machineId !== identity.id || !canonical)
    ) {
      return { kind: "invalidPayload", message: INVALID_REQUEST_MESSAGE };
    }
  }

  const probeResult = await probeWithDependencies(
    identity,
    clerkJwt,
    dependencies
  );
  if (probeResult.kind === "invalidPayload") {
    return { kind: "invalidPayload", message: INVALID_REQUEST_MESSAGE };
  }
  if (dependencies.signal?.aborted) {
    return {
      kind: "probeUnavailable",
      machine: identity,
      message: UNAVAILABLE_MESSAGE,
      attempt: probeResult.attempt,
      nextAction: "retryOnly",
    };
  }
  if (probeResult.kind === "authenticationRejected") {
    return {
      kind: "authenticationRejected",
      machine: identity,
      message: AUTHENTICATION_REJECTED_MESSAGE,
    };
  }
  if (parsed.data.operation === "inspect") {
    if (probeResult.kind === "unavailable") {
      return {
        kind: "probeUnavailable",
        machine: identity,
        message: UNAVAILABLE_MESSAGE,
        attempt: probeResult.attempt,
        nextAction: canonical ? "retryOnly" : "savePending",
      };
    }
    return {
      kind: "registrationReady",
      machine: identity,
      agents: probeResult.agents,
    };
  }
  if (
    parsed.data.transition === "savePending" &&
    probeResult.kind === "ready"
  ) {
    return {
      kind: "registrationReady",
      machine: identity,
      agents: probeResult.agents,
    };
  }

  return await dependencies.repository.applyTransition({
    actionId: parsed.data.actionId,
    transition: parsed.data.transition,
    probe:
      probeResult.kind === "ready"
        ? {
            kind: "available",
            probedAt: dependencies.now().toISOString(),
          }
        : {
            kind: "unavailable",
            reason: UNAVAILABLE_MESSAGE,
            attempt: probeResult.attempt,
            probedAt: dependencies.now().toISOString(),
          },
  });
}

import { z } from "zod";
import { loadProgressKindSchema } from "./load-telemetry-types";

export const RUNTIME_PROGRESS_PHASE_IDS = [
  "queued",
  "service_inactive",
  "service_stopping",
  "service_starting",
  "model_loading",
  "runtime_warming",
  "runtime_ready",
  "request_submitted",
  "request_accepted",
  "preprocessing",
  "generating",
  "postprocessing",
  "artifact_ready",
  "completed",
  "failed",
  "canceled",
  "disabled",
] as const;

export const runtimeProgressPhaseSchema = z.enum(RUNTIME_PROGRESS_PHASE_IDS);
export type RuntimeProgressPhase = z.infer<typeof runtimeProgressPhaseSchema>;

export const runtimeProgressScopeSchema = z.enum([
  "switch",
  "service",
  "image_task",
  "video_task",
]);
export type RuntimeProgressScope = z.infer<typeof runtimeProgressScopeSchema>;

export const runtimeProgressEvidenceSchema = z.object({
  label: z.string().min(1),
  source: z.string().min(1),
  observedAt: z.number().int().min(0).optional(),
  current: z.number().finite().optional(),
  total: z.number().finite().positive().optional(),
  unit: z.string().min(1).optional(),
});

export type RuntimeProgressEvidence = z.infer<
  typeof runtimeProgressEvidenceSchema
>;

export const runtimeProgressSchema = z.object({
  scope: runtimeProgressScopeSchema,
  phase: runtimeProgressPhaseSchema,
  phaseIndex: z.number().int().min(1),
  phaseTotal: z.number().int().min(1),
  canonicalIndex: z.number().int().min(1),
  canonicalTotal: z.number().int().min(1),
  progressKind: loadProgressKindSchema,
  percent: z.number().finite().min(0).max(100).nullable(),
  label: z.string().min(1),
  detail: z.string().nullable().optional(),
  observedAt: z.number().int().min(0).optional(),
  terminal: z.boolean(),
  evidence: z.array(runtimeProgressEvidenceSchema).optional(),
});

export type RuntimeProgress = z.infer<typeof runtimeProgressSchema>;

type RuntimeProgressObservationInput = {
  progressKind?: RuntimeProgress["progressKind"];
  percent?: number | null;
  label?: string | null;
  detail?: string | null;
  observedAt?: number;
  evidence?: RuntimeProgressEvidence[];
};

const PHASE_LABELS = {
  queued: "Queued",
  service_inactive: "Service inactive",
  service_stopping: "Stopping runtime",
  service_starting: "Starting runtime",
  model_loading: "Loading model",
  runtime_warming: "Warming runtime",
  runtime_ready: "Runtime ready",
  request_submitted: "Submitting request",
  request_accepted: "Request accepted",
  preprocessing: "Preprocessing",
  generating: "Generating",
  postprocessing: "Postprocessing",
  artifact_ready: "Artifact ready",
  completed: "Completed",
  failed: "Failed",
  canceled: "Canceled",
  disabled: "Disabled",
} satisfies Record<RuntimeProgressPhase, string>;

const TERMINAL_PHASES = new Set<RuntimeProgressPhase>([
  "runtime_ready",
  "completed",
  "failed",
  "canceled",
  "disabled",
]);

export const RUNTIME_PROGRESS_PHASE_SEQUENCES = {
  switch: [
    "service_stopping",
    "service_starting",
    "model_loading",
    "runtime_ready",
  ],
  service: [
    "service_inactive",
    "service_starting",
    "model_loading",
    "runtime_warming",
    "runtime_ready",
  ],
  image_task: [
    "queued",
    "request_submitted",
    "request_accepted",
    "preprocessing",
    "generating",
    "postprocessing",
    "artifact_ready",
    "completed",
  ],
  video_task: [
    "queued",
    "request_submitted",
    "request_accepted",
    "preprocessing",
    "generating",
    "postprocessing",
    "artifact_ready",
    "completed",
  ],
} satisfies Readonly<
  Record<RuntimeProgressScope, readonly RuntimeProgressPhase[]>
>;

type RuntimeProgressInput = RuntimeProgressObservationInput & {
  scope: RuntimeProgressScope;
  phase: RuntimeProgressPhase;
  terminal?: boolean;
  sequence?: readonly RuntimeProgressPhase[];
};

function clampPercent(value: number | null | undefined): number | null {
  if (typeof value !== "number" || !Number.isFinite(value)) return null;
  return Math.max(0, Math.min(100, value));
}

export function runtimeProgressPhaseLabel(phase: RuntimeProgressPhase): string {
  return PHASE_LABELS[phase];
}

export function createRuntimeProgress(
  input: RuntimeProgressInput
): RuntimeProgress {
  const canonicalIndex = RUNTIME_PROGRESS_PHASE_IDS.indexOf(input.phase) + 1;
  const sequence =
    input.sequence ?? RUNTIME_PROGRESS_PHASE_SEQUENCES[input.scope];
  const localIndex = sequence.indexOf(input.phase);
  const terminal = input.terminal ?? TERMINAL_PHASES.has(input.phase);
  const phaseTotal = sequence.length;
  const phaseIndex =
    localIndex >= 0 ? localIndex + 1 : terminal ? phaseTotal : canonicalIndex;
  const progressKind =
    input.progressKind ?? (terminal ? "terminal" : "indeterminate");
  const percent =
    input.percent !== undefined
      ? clampPercent(input.percent)
      : input.phase === "runtime_ready" || input.phase === "completed"
        ? 100
        : input.phase === "disabled"
          ? 0
          : null;

  return {
    scope: input.scope,
    phase: input.phase,
    phaseIndex,
    phaseTotal:
      localIndex >= 0 || terminal
        ? phaseTotal
        : RUNTIME_PROGRESS_PHASE_IDS.length,
    canonicalIndex,
    canonicalTotal: RUNTIME_PROGRESS_PHASE_IDS.length,
    progressKind,
    percent,
    label: input.label?.trim() || runtimeProgressPhaseLabel(input.phase),
    detail: input.detail ?? null,
    observedAt: input.observedAt,
    terminal,
    evidence: input.evidence,
  } satisfies RuntimeProgress;
}

export function runtimeProgressCount(progress: RuntimeProgress): string {
  return `${progress.phaseIndex}/${progress.phaseTotal}`;
}

export function runtimeProgressDisplayLabel(progress: RuntimeProgress): string {
  return `${progress.label} (${runtimeProgressCount(progress)})`;
}

import { describe, expect, it } from "vitest";

import {
