  });

  it("keeps official WTI2V primary/default and LightX2V AITER explicit-only", () => {
    expect(PRIMARY_VIDEO_RUNTIME_TARGET).toEqual({
      modelId: "wan2.2-ti2v-5b",
      configId: "WTI2V-720",
      runtime: "diffusers-video",
      runtimeStatus: "enabled",
      role: "primary",
      defaultEligible: true,
      unavailableLabel:
        "video runtime requires worker GPUs that are not visible",
      preflightTimeoutMs: 20_000,
    });
    expect(videoRuntimeTargetForConfig("LX22-AITER-I2V-FP8-720")).toEqual({
      modelId: "wan2.2-i2v-a14b-aiter",
      configId: "LX22-AITER-I2V-FP8-720",
      runtime: "lightx2v-aiter-video",
      runtimeStatus: "enabled",
      role: "alternate",
      defaultEligible: false,
      unavailableLabel: "LightX2V AITER runtime is unavailable",
      preflightTimeoutMs: 930_000,
    });
    expect(DEFAULT_VIDEO_CONFIG_ID_BY_MODEL["wan2.2-ti2v-5b"]).toBe(
      "WTI2V-720"
    );
    expect(DEFAULT_VIDEO_CONFIG_ID_BY_MODEL["wan2.2-i2v-a14b"]).toBe("WGP-480");
    expect(DEFAULT_VIDEO_CONFIG_ID_BY_MODEL["wan2.2-i2v-a14b-aiter"]).toBe(
      "LX22-AITER-I2V-FP8-720"
    );
    expect(videoRuntimeTargetForConfig("LX22-I2V-FP8-720")).toBeNull();
    expect(VIDEO_PROSPECTIVE_CONFIGS["LX22-I2V-FP8-720"]).toMatchObject({
      runtimeStatus: "metadata-only",
      role: "fallback",
      execution: {
        runtime: "lightx2v-video",
        launcher: "lightx2v",
        attention: "native",
        offloadPolicy: "fallback-only",
      },
    });
    expect(VIDEO_RUNTIME_TARGETS).toEqual([
      PRIMARY_VIDEO_RUNTIME_TARGET,
      LIGHTX2V_AITER_VIDEO_RUNTIME_TARGET,
    ]);
    expect(LIGHTX2V_AITER_VIDEO_RUNTIME_TARGET.defaultEligible).toBe(false);
  });

  it("correlates runnable catalog benchmark labels to exact configs", () => {
    for (const model of Object.values(VIDEO_MODELS)) {
      for (const benchmark of Object.values(model.benchmarkConfigs)) {
        if (benchmark === undefined) continue;
        const configId = videoProspectiveConfigIdSchema.safeParse(
          benchmark.label
