        if (!configId.success) continue;
        const config = VIDEO_PROSPECTIVE_CONFIGS[configId.data];
        if (config?.runtimeStatus !== "enabled") continue;
        expect({
          modelId: config.modelId,
          resolution: `${config.resolution.width}x${config.resolution.height}`,
        }).toEqual({
          modelId: model.id,
          resolution: benchmark.resolution,
        });
