    }
    expect(
      VIDEO_MODELS[LIGHTX2V_AITER_VIDEO_RUNTIME_TARGET.modelId].benchmarkConfigs
    ).toEqual({
      "720p": expect.objectContaining({
        label: LIGHTX2V_AITER_VIDEO_RUNTIME_TARGET.configId,
        resolution: "1280x720",
      }),
    });
  });
});

#!/usr/bin/env node

import {
  cpSync,
  createWriteStream,
  existsSync,
  mkdirSync,
  mkdtempSync,
  rmSync,
  writeFileSync,
} from "node:fs";
import { join, resolve } from "node:path";
import { pathToFileURL } from "node:url";
import { spawn, spawnSync } from "node:child_process";
import { tmpdir } from "node:os";
import {
  BACKEND_CTL,
  ROOT_DIR,
  buildControlPlan,
  buildJournalSpecs,
  parseBackendUnits,
} from "./agent-runtime-commands.ts";

export { buildControlPlan, buildJournalSpecs, parseBackendUnits };

const DEFAULT_URL = process.env.HOMER_AGENT_URL ?? "http://127.0.0.1:3000";
const DEFAULT_BROWSER =
  process.env.HOMER_AGENT_CHROME ?? "/usr/bin/google-chrome";
const DEFAULT_ARTIFACT_DIR = join(ROOT_DIR, "artifacts", "agent-runtime");
const DEFAULT_CDP_PORT = Number(process.env.HOMER_AGENT_CDP_PORT ?? 9333);
const NEEDLE_INSPECTOR_EXTENSION_NAME = "Needle Inspector";

const DEFAULT_OBSERVE_SERVICES = ["web", "model", "backend-detected"];
const DEFAULT_CONTROL_SERVICES = ["all"];
const CONTROL_COMMANDS = new Set(["start", "stop", "restart", "status"]);
const OBSERVE_COMMANDS = new Set(["observe"]);

const HELP = `Usage: pnpm agent:runtime [observe|start|stop|restart|status] [options]

Agent runtime CLI for chromeless browser capture and namespaced service logs.

Commands:
  observe             Capture browser FPS, network, console events, and service logs
  start              Start selected services
  stop               Stop selected services
  restart            Restart selected services
  status             Report selected service active states

Options:
  --url <url>                Browser target URL (default: ${DEFAULT_URL})
  --browser <path>           Chrome binary for direct CDP (default: ${DEFAULT_BROWSER})
  --extension <path>         Unpacked Chrome extension path to load
  --activate-needle-inspector Enable Needle Inspector extension before navigation
  --cdp-port <port>          Remote debugging port (default: ${DEFAULT_CDP_PORT})
  --duration-ms <ms>         Observe duration; 0 streams until SIGINT/SIGTERM (default: 30000)
  --artifact-dir <dir>       Artifact root (default: artifacts/agent-runtime)
  --service <list>           Comma-separated services: all, web, model, backend:<profile>, backend-active
  --since <time>             journalctl --since value for logs (default: now)
  --fps-interval-ms <ms>     FPS sample interval (default: 1000)
  --width <px>               Browser viewport width (default: 1280)
  --height <px>              Browser viewport height (default: 800)
  --no-browser               Observe logs only
  --no-logs                  Observe browser only
  --no-screenshot            Skip final screenshot capture
  --observe                  Continue into observe after start/restart/status
  --dry-run                  Print service command plan without executing it
  --help                     Show this help
`;

function timestampForPath(date = new Date()) {
  return date.toISOString().replace(/[:.]/g, "-");
}

function delay(ms) {
  return new Promise((resolveDelay) => setTimeout(resolveDelay, ms));
}

function requireValue(argv, index, option) {
  const value = argv[index + 1];
  if (!value || value.startsWith("--")) {
    throw new Error(`missing_value:${option}`);
  }
  return value;
}

function parsePositiveInteger(value, option, { allowZero = false } = {}) {
  const parsed = Number(value);
  if (!Number.isInteger(parsed) || parsed < 0 || (!allowZero && parsed === 0)) {
    throw new Error(`invalid_integer:${option}`);
  }
  return parsed;
}

export function parseServiceList(values, defaultServices) {
  const services = values
    .flatMap((value) => value.split(","))
    .map((value) => value.trim())
    .filter(Boolean);
  return services.length > 0 ? services : [...defaultServices];
}

export function parseArgs(argv) {
  const options = {
    command: "observe",
    url: DEFAULT_URL,
    browser: DEFAULT_BROWSER,
    extensions: [],
    activateNeedleInspector: false,
    cdpPort: DEFAULT_CDP_PORT,
    durationMs: 30000,
    artifactDir: DEFAULT_ARTIFACT_DIR,
    services: [],
    since: "now",
    fpsIntervalMs: 1000,
    width: 1280,
    height: 800,
    browserEnabled: true,
    logsEnabled: true,
    screenshot: true,
    observeAfterControl: false,
    dryRun: false,
    help: false,
  };

  const positional = [];
  for (let index = 0; index < argv.length; index += 1) {
    const arg = argv[index];
    switch (arg) {
      case "--help":
      case "-h":
        options.help = true;
        break;
      case "--url":
        options.url = requireValue(argv, index, arg);
        index += 1;
        break;
      case "--browser":
        options.browser = requireValue(argv, index, arg);
        index += 1;
        break;
      case "--extension":
        options.extensions.push(resolve(requireValue(argv, index, arg)));
        index += 1;
        break;
      case "--activate-needle-inspector":
        options.activateNeedleInspector = true;
        break;
      case "--cdp-port":
        options.cdpPort = parsePositiveInteger(
          requireValue(argv, index, arg),
          arg
        );
        index += 1;
        break;
      case "--duration-ms":
        options.durationMs = parsePositiveInteger(
          requireValue(argv, index, arg),
          arg,
          {
            allowZero: true,
          }
        );
        index += 1;
        break;
      case "--artifact-dir":
        options.artifactDir = resolve(requireValue(argv, index, arg));
        index += 1;
        break;
      case "--service":
        options.services.push(requireValue(argv, index, arg));
        index += 1;
        break;
      case "--since":
        options.since = requireValue(argv, index, arg);
        index += 1;
        break;
      case "--fps-interval-ms":
        options.fpsIntervalMs = parsePositiveInteger(
          requireValue(argv, index, arg),
          arg
        );
        index += 1;
        break;
      case "--width":
        options.width = parsePositiveInteger(
          requireValue(argv, index, arg),
          arg
        );
        index += 1;
        break;
      case "--height":
        options.height = parsePositiveInteger(
          requireValue(argv, index, arg),
          arg
        );
        index += 1;
        break;
      case "--no-browser":
        options.browserEnabled = false;
        break;
      case "--no-logs":
        options.logsEnabled = false;
        break;
      case "--no-screenshot":
        options.screenshot = false;
        break;
      case "--observe":
        options.observeAfterControl = true;
        break;
      case "--dry-run":
        options.dryRun = true;
        break;
      default:
        if (arg.startsWith("--")) {
          throw new Error(`unknown_option:${arg}`);
        }
        positional.push(arg);
        break;
    }
  }

  if (positional.length > 1) {
    throw new Error(`unexpected_args:${positional.slice(1).join(",")}`);
  }
  if (positional.length === 1) {
    options.command = positional[0];
  }
  if (
    !CONTROL_COMMANDS.has(options.command) &&
    !OBSERVE_COMMANDS.has(options.command)
  ) {
    throw new Error(`unknown_command:${options.command}`);
  }
  if (
    !options.browserEnabled &&
    !options.logsEnabled &&
    options.command === "observe"
  ) {
    throw new Error("observe_requires_browser_or_logs");
  }
  return options;
}

function renderData(data) {
  if (!data || Object.keys(data).length === 0) return "";
  return ` ${JSON.stringify(data)}`;
}

export function formatEventLine(event) {
  return `[${event.ts}] ${event.namespace} ${event.level} ${event.message}${renderData(
    event.data
  )}`;
}

class RuntimeStream {
  constructor({ artifactDir, stdout = process.stdout }) {
    this.startedAt = new Date().toISOString();
    this.runId = timestampForPath(new Date());
    this.runDir = join(artifactDir, this.runId);
    this.stdout = stdout;
    this.counts = new Map();
    mkdirSync(this.runDir, { recursive: true });
    this.jsonlPath = join(this.runDir, "stream.jsonl");
    this.logPath = join(this.runDir, "stream.log");
    this.reportPath = join(this.runDir, "report.json");
    this.jsonl = createWriteStream(this.jsonlPath, { flags: "a" });
    this.log = createWriteStream(this.logPath, { flags: "a" });
  }

  emit(namespace, level, message, data = {}) {
    const event = {
      ts: new Date().toISOString(),
      namespace,
      level,
      message,
      data,
    };
    this.counts.set(namespace, (this.counts.get(namespace) ?? 0) + 1);
    const json = `${JSON.stringify(event)}\n`;
    const line = `${formatEventLine(event)}\n`;
    this.jsonl.write(json);
    this.log.write(line);
    this.stdout.write(line);
    return event;
  }

  writeReport(extra = {}) {
    const report = {
      runId: this.runId,
      startedAt: this.startedAt,
      finishedAt: new Date().toISOString(),
      artifacts: {
        runDir: this.runDir,
        jsonl: this.jsonlPath,
        log: this.logPath,
        report: this.reportPath,
        ...extra.artifacts,
      },
      counts: Object.fromEntries(this.counts),
      ...extra,
    };
    writeFileSync(this.reportPath, `${JSON.stringify(report, null, 2)}\n`);
    return report;
  }

  close() {
    this.jsonl.end();
    this.log.end();
  }
}

function expandAllControlServices(services) {
  return services.flatMap((service) => {
    if (service === "all") return ["web", "model", "backend-active"];
    return [service];
  });
}

function listBackendUnits() {
  const result = spawnSync(
    "systemctl",
    [
      "list-units",
      "homer-backend@*.service",
      "--all",
      "--no-legend",
      "--plain",
    ],
    { encoding: "utf8" }
  );
  if (result.status !== 0) {
    throw new Error(
      `backend_unit_discovery_failed:${result.stderr.trim() || result.status}`
    );
  }
  return parseBackendUnits(result.stdout);
}

function readActiveBackendProfile() {
  const result = spawnSync(
    "/usr/bin/sudo",
    ["-n", BACKEND_CTL, "active-profile"],
    {
      encoding: "utf8",
    }
  );
  if (result.status !== 0) {
    throw new Error(
      `backend_active_profile_failed:${result.stderr.trim() || result.status}`
    );
  }
  const profile = result.stdout.trim();
  if (!profile) throw new Error("backend_active_profile_empty");
  return profile;
}

export function createFpsProbeExpression() {
  return `(() => {
  const key = "__homerAgentRuntimeFps";
  if (!globalThis[key]) {
    const state = { frames: 0, fps: 0, last: performance.now(), updatedAt: Date.now() };
    globalThis[key] = state;
    const tick = (now) => {
      state.frames += 1;
      const elapsed = now - state.last;
      if (elapsed >= 1000) {
        state.fps = Math.round((state.frames * 1000 / elapsed) * 10) / 10;
        state.frames = 0;
        state.last = now;
        state.updatedAt = Date.now();
      }
      requestAnimationFrame(tick);
    };
    requestAnimationFrame(tick);
  }
  return { fps: globalThis[key].fps, updatedAt: globalThis[key].updatedAt };
})()`;
}

function pipeLines(readable, onLine) {
  let buffer = "";
  readable.setEncoding("utf8");
  readable.on("data", (chunk) => {
    buffer += chunk;
    let newline = buffer.indexOf("\n");
    while (newline >= 0) {
      const line = buffer.slice(0, newline).replace(/\r$/, "");
      buffer = buffer.slice(newline + 1);
      if (line) onLine(line);
      newline = buffer.indexOf("\n");
    }
  });
  readable.on("end", () => {
    const line = buffer.trim();
    if (line) onLine(line);
  });
}

function spawnLoggedProcess(spec, stream, children) {
  const child = spawn(spec.command, spec.args, {
    env: spec.env ? { ...process.env, ...spec.env } : process.env,
    stdio: ["ignore", "pipe", "pipe"],
  });
  children.add(child);
  stream.emit(spec.namespace, "info", "process_started", {
    command: spec.command,
    args: spec.args,
  });
  pipeLines(child.stdout, (line) => stream.emit(spec.namespace, "info", line));
  pipeLines(child.stderr, (line) => stream.emit(spec.namespace, "error", line));
  child.on("exit", (code, signal) => {
    children.delete(child);
    stream.emit(
      spec.namespace,
      code === 0 ? "info" : "error",
      "process_exited",
      { code, signal }
    );
  });
  return child;
}

function runCommand(spec, stream, { dryRun = false } = {}) {
  if (dryRun) {
    stream.emit(spec.namespace, "info", "dry_run", {
      command: spec.command,
      args: spec.args,
    });
    return Promise.resolve(0);
  }
  return new Promise((resolveCommand, rejectCommand) => {
    const child = spawn(spec.command, spec.args, {
      env: spec.env ? { ...process.env, ...spec.env } : process.env,
      stdio: ["ignore", "pipe", "pipe"],
    });
    pipeLines(child.stdout, (line) =>
      stream.emit(spec.namespace, "info", line)
    );
    pipeLines(child.stderr, (line) =>
      stream.emit(spec.namespace, "error", line)
    );
    child.on("error", rejectCommand);
    child.on("exit", (code, signal) => {
      stream.emit(
        spec.namespace,
        code === 0 ? "info" : "error",
        "command_exited",
        { code, signal }
      );
      resolveCommand(code ?? 1);
    });
  });
}

class CdpConnection {
  constructor(socket) {
    this.socket = socket;
    this.nextId = 1;
    this.pending = new Map();
    this.listeners = new Map();
    socket.addEventListener("message", (event) =>
      this.handleMessage(event.data)
    );
    socket.addEventListener("close", () => {
      for (const { reject } of this.pending.values())
        reject(new Error("cdp_socket_closed"));
      this.pending.clear();
    });
  }

  static async connect(url) {
    if (typeof WebSocket !== "function") {
      throw new Error("node_websocket_required_for_direct_cdp");
    }
    const socket = new WebSocket(url);
    await new Promise((resolveOpen, rejectOpen) => {
      socket.addEventListener("open", resolveOpen, { once: true });
      socket.addEventListener(
        "error",
        () => rejectOpen(new Error("cdp_socket_error")),
        { once: true }
      );
    });
    return new CdpConnection(socket);
  }

  on(method, listener) {
    const existing = this.listeners.get(method) ?? [];
    existing.push(listener);
    this.listeners.set(method, existing);
  }

  send(method, params = {}, sessionId) {
    const id = this.nextId;
    this.nextId += 1;
    const message = { id, method, params };
    if (sessionId) message.sessionId = sessionId;
    return new Promise((resolveSend, rejectSend) => {
      this.pending.set(id, { resolve: resolveSend, reject: rejectSend });
      this.socket.send(JSON.stringify(message));
    });
  }

  handleMessage(raw) {
    const message = JSON.parse(String(raw));
    if (message.id) {
      const pending = this.pending.get(message.id);
      if (!pending) return;
      this.pending.delete(message.id);
      if (message.error) {
        pending.reject(
          new Error(`${message.error.code}:${message.error.message}`)
        );
      } else {
        pending.resolve(message.result ?? {});
      }
      return;
    }
    if (message.method) {
      for (const listener of this.listeners.get(message.method) ?? []) {
        listener(message.params ?? {}, message);
      }
    }
  }

  close() {
    this.socket.close();
  }
}

async function waitForJson(url, timeoutMs) {
  const deadline = Date.now() + timeoutMs;
  let lastError = null;
  while (Date.now() < deadline) {
    try {
      const response = await fetch(url);
      if (response.ok) return await response.json();
      lastError = new Error(`http_${response.status}`);
    } catch (error) {
      lastError = error;
    }
    await delay(100);
  }
  throw new Error(
    `cdp_endpoint_unavailable:${lastError?.message ?? "timeout"}`
  );
}

async function findNeedleInspectorServiceWorker(cdp, timeoutMs) {
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    const targets = await cdp.send("Target.getTargets");
    const serviceWorkers =
      targets.targetInfos?.filter(
        (target) =>
          target.type === "service_worker" &&
          target.url?.startsWith("chrome-extension://")
      ) ?? [];
    for (const target of serviceWorkers) {
      const attached = await cdp.send("Target.attachToTarget", {
        targetId: target.targetId,
        flatten: true,
      });
      await cdp.send("Runtime.enable", {}, attached.sessionId);
      const manifest = await cdp.send(
        "Runtime.evaluate",
        {
          expression: "chrome.runtime.getManifest()",
          returnByValue: true,
        },
        attached.sessionId
      );
      const name = manifest.result?.value?.name ?? "";
      if (name.includes(NEEDLE_INSPECTOR_EXTENSION_NAME)) {
        const extensionId = new URL(target.url).host;
        return { extensionId, sessionId: attached.sessionId, target };
      }
      await cdp.send("Target.detachFromTarget", {
        sessionId: attached.sessionId,
      });
    }
    await delay(100);
  }
  throw new Error("needle_inspector_service_worker_unavailable");
}

async function activateNeedleInspectorExtension(cdp, stream) {
  const { extensionId, sessionId, target } =
    await findNeedleInspectorServiceWorker(cdp, 5000);
  await cdp.send(
    "Runtime.evaluate",
    {
      expression: `new Promise((resolve, reject) => {
        chrome.storage.local.set({
          inspectorActive: true,
          inspectorVisible: true,
          loadEditor: true
        }, () => {
          const lastError = chrome.runtime.lastError;
          if (lastError) reject(lastError.message);
          else resolve(true);
        });
      })`,
      awaitPromise: true,
      returnByValue: true,
    },
    sessionId
  );
  stream.emit("browser", "info", "needle_inspector_extension_activated", {
    extensionId,
    targetId: target.targetId,
  });
}

function stageExtensions(extensions, userDataDir, stream) {
  if (extensions.length === 0) return [];
  const stagedRoot = join(userDataDir, "extensions");
  mkdirSync(stagedRoot, { recursive: true });
  return extensions.map((extension, index) => {
    const staged = join(stagedRoot, `extension-${index}`);
    cpSync(extension, staged, { recursive: true });
    rmSync(join(staged, "_metadata"), { recursive: true, force: true });
    stream.emit("browser", "info", "extension_staged", {
      source: extension,
      staged,
    });
    return staged;
  });
}

function consoleText(args = []) {
  return args
    .map((arg) => {
      if (Object.hasOwn(arg, "value")) return String(arg.value);
      return arg.description ?? arg.type ?? "";
    })
    .filter(Boolean)
    .join(" ");
}

function installBrowserEventHandlers(cdp, sessionId, stream) {
  cdp.on("Network.requestWillBeSent", (params, message) => {
    if (message.sessionId !== sessionId) return;
    stream.emit("network", "info", "request", {
      requestId: params.requestId,
      method: params.request?.method,
      url: params.request?.url,
      type: params.type,
    });
  });
  cdp.on("Network.responseReceived", (params, message) => {
    if (message.sessionId !== sessionId) return;
    stream.emit("network", "info", "response", {
      requestId: params.requestId,
      status: params.response?.status,
      mimeType: params.response?.mimeType,
      url: params.response?.url,
    });
  });
  cdp.on("Network.loadingFailed", (params, message) => {
    if (message.sessionId !== sessionId) return;
    stream.emit("network", "error", "loading_failed", {
      requestId: params.requestId,
      errorText: params.errorText,
      blockedReason: params.blockedReason,
      type: params.type,
    });
  });
  cdp.on("Runtime.consoleAPICalled", (params, message) => {
    if (message.sessionId !== sessionId) return;
    const level = params.type === "error" ? "error" : "info";
    stream.emit("client.console", level, consoleText(params.args), {
      type: params.type,
    });
  });
  cdp.on("Runtime.exceptionThrown", (params, message) => {
    if (message.sessionId !== sessionId) return;
    stream.emit(
      "client.error",
      "error",
      params.exceptionDetails?.text ?? "exception",
      {
        url: params.exceptionDetails?.url,
        lineNumber: params.exceptionDetails?.lineNumber,
        columnNumber: params.exceptionDetails?.columnNumber,
      }
    );
  });
}

async function waitForLoad(cdp, sessionId, timeoutMs) {
  await new Promise((resolveLoad) => {
    const timeout = setTimeout(resolveLoad, timeoutMs);
    cdp.on("Page.loadEventFired", (_params, message) => {
      if (message.sessionId !== sessionId) return;
      clearTimeout(timeout);
      resolveLoad();
    });
  });
}

async function startBrowserCapture(options, stream, children) {
  if (!existsSync(options.browser)) {
    throw new Error(`browser_not_found:${options.browser}`);
  }
  const userDataDir = mkdtempSync(join(tmpdir(), "homer-agent-runtime-"));
  const chromeArgs = [
    "--headless=new",
    "--ignore-gpu-blocklist",
    "--enable-unsafe-swiftshader",
    "--use-gl=angle",
    "--use-angle=swiftshader",
    "--no-first-run",
    "--no-default-browser-check",
    "--disable-dev-shm-usage",
    "--remote-debugging-address=127.0.0.1",
    `--remote-debugging-port=${options.cdpPort}`,
    `--user-data-dir=${userDataDir}`,
    `--window-size=${options.width},${options.height}`,
    "about:blank",
  ];
  for (const extension of options.extensions) {
    if (!existsSync(extension)) {
      throw new Error(`extension_not_found:${extension}`);
    }
  }
  const stagedExtensions = stageExtensions(
    options.extensions,
    userDataDir,
    stream
  );
  if (stagedExtensions.length > 0) {
    const extensionList = stagedExtensions.join(",");
    chromeArgs.push(`--disable-extensions-except=${extensionList}`);
    chromeArgs.push(`--load-extension=${extensionList}`);
  }
  const chrome = spawn(options.browser, chromeArgs, {
    stdio: ["ignore", "pipe", "pipe"],
  });
  children.add(chrome);
  pipeLines(chrome.stdout, (line) => stream.emit("browser", "info", line));
  pipeLines(chrome.stderr, (line) => {
    const level = line.startsWith("DevTools listening on") ? "info" : "error";
    stream.emit("browser", level, line);
  });
  chrome.on("exit", (code, signal) => {
    children.delete(chrome);
    stream.emit("browser", code === 0 ? "info" : "error", "chrome_exited", {
      code,
      signal,
    });
  });
  stream.emit("browser", "info", "chrome_started", {
    browser: options.browser,
    cdpPort: options.cdpPort,
    extensions: options.extensions,
    stagedExtensions,
    userDataDir,
  });

  const version = await waitForJson(
    `http://127.0.0.1:${options.cdpPort}/json/version`,
    10000
  );
  const cdp = await CdpConnection.connect(version.webSocketDebuggerUrl);
  if (options.activateNeedleInspector) {
    await activateNeedleInspectorExtension(cdp, stream);
  }
  const targets = await cdp.send("Target.getTargets");
  let page = targets.targetInfos?.find((target) => target.type === "page");
  if (!page) {
    const created = await cdp.send("Target.createTarget", {
      url: "about:blank",
    });
    page = { targetId: created.targetId };
  }
  const attached = await cdp.send("Target.attachToTarget", {
    targetId: page.targetId,
    flatten: true,
  });
  const sessionId = attached.sessionId;
  await cdp.send("Page.enable", {}, sessionId);
  await cdp.send("Runtime.enable", {}, sessionId);
  await cdp.send("Network.enable", {}, sessionId);
  installBrowserEventHandlers(cdp, sessionId, stream);
  await cdp.send("Page.navigate", { url: options.url }, sessionId);
  await waitForLoad(cdp, sessionId, 10000);
  await cdp.send(
    "Runtime.evaluate",
    { expression: createFpsProbeExpression(), returnByValue: true },
    sessionId
  );
  stream.emit("browser", "info", "page_ready", { url: options.url });

  const fpsTimer = setInterval(async () => {
    try {
      const sample = await cdp.send(
        "Runtime.evaluate",
        { expression: createFpsProbeExpression(), returnByValue: true },
        sessionId
      );
      stream.emit("fps", "info", "sample", sample.result?.value ?? {});
    } catch (error) {
      stream.emit("fps", "error", "sample_failed", { error: error.message });
    }
  }, options.fpsIntervalMs);

  return {
    async screenshot(path) {
      const result = await cdp.send(
        "Page.captureScreenshot",
        { format: "png", fromSurface: true },
        sessionId
      );
      writeFileSync(path, Buffer.from(result.data, "base64"));
    },
    close() {
      clearInterval(fpsTimer);
      cdp.close();
      chrome.kill("SIGTERM");
    },
  };
}

function waitForStop(durationMs) {
  if (durationMs > 0) return delay(durationMs).then(() => "duration");
  return new Promise((resolveStop) => {
    const stop = (signal) => resolveStop(signal);
    process.once("SIGINT", () => stop("SIGINT"));
    process.once("SIGTERM", () => stop("SIGTERM"));
  });
}

async function runControl(options, stream) {
  const services = parseServiceList(options.services, DEFAULT_CONTROL_SERVICES);
  const needsActiveBackend =
    expandAllControlServices(services).includes("backend-active");
  const activeBackendProfile =
    needsActiveBackend && !options.dryRun
      ? readActiveBackendProfile()
      : "active-profile";
  const plan = buildControlPlan(options.command, services, {
    activeBackendProfile,
  });
  stream.emit("runtime", "info", "control_plan", {
    action: options.command,
    services,
    count: plan.length,
  });
  let failed = false;
  for (const spec of plan) {
    const code = await runCommand(spec, stream, { dryRun: options.dryRun });
    if (code !== 0) failed = true;
  }
  return failed ? 1 : 0;
}

async function runObserve(options, stream) {
  const children = new Set();
  const browserSessions = [];
  let screenshotPath = null;
  try {
    if (options.logsEnabled) {
      const services = parseServiceList(
        options.services,
        DEFAULT_OBSERVE_SERVICES
      );
      let backendUnits = [];
      if (services.includes("backend-detected") || services.includes("all")) {
        try {
          backendUnits = listBackendUnits();
          stream.emit("runtime", "info", "backend_units_detected", {
            units: backendUnits,
          });
        } catch (error) {
          stream.emit("runtime", "error", "backend_unit_discovery_failed", {
            error: error.message,
          });
          throw error;
        }
      }
      const needsActiveBackend = services.includes("backend-active");
      const activeBackendProfile = needsActiveBackend
        ? readActiveBackendProfile()
        : undefined;
      const specs = buildJournalSpecs(services, {
        since: options.since,
        backendUnits,
        activeBackendProfile,
      });
      for (const spec of specs) spawnLoggedProcess(spec, stream, children);
    }
    if (options.browserEnabled) {
      browserSessions.push(
        await startBrowserCapture(options, stream, children)
      );
    }
    const stopReason = await waitForStop(options.durationMs);
    stream.emit("runtime", "info", "observe_stopping", { reason: stopReason });
    if (options.screenshot && browserSessions.length > 0) {
      screenshotPath = join(stream.runDir, "screenshot.png");
      await browserSessions[0].screenshot(screenshotPath);
      stream.emit("browser", "info", "screenshot_written", {
        path: screenshotPath,
      });
    }
    return { screenshotPath };
  } finally {
    for (const session of browserSessions) session.close();
    for (const child of children) child.kill("SIGTERM");
  }
}

async function main(argv) {
  let options;
  try {
    options = parseArgs(argv);
  } catch (error) {
    process.stderr.write(`${error.message}\n\n${HELP}`);
    return 2;
  }
  if (options.help) {
    process.stdout.write(HELP);
    return 0;
  }

  const stream = new RuntimeStream({ artifactDir: options.artifactDir });
  stream.emit("runtime", "info", "run_started", {
    command: options.command,
    url: options.url,
    artifactDir: stream.runDir,
  });

  let exitCode = 0;
  let observeResult = {};
  try {
    if (CONTROL_COMMANDS.has(options.command)) {
      exitCode = await runControl(options, stream);
      if (options.observeAfterControl && exitCode === 0) {
        observeResult = await runObserve(
          { ...options, command: "observe" },
          stream
        );
      }
    } else {
      observeResult = await runObserve(options, stream);
    }
  } catch (error) {
    exitCode = 1;
    stream.emit("runtime", "error", "run_failed", { error: error.message });
  } finally {
    stream.writeReport({
      command: options.command,
      url: options.url,
      exitCode,
      artifacts: observeResult.screenshotPath
        ? { screenshot: observeResult.screenshotPath }
        : {},
    });
    stream.emit("runtime", exitCode === 0 ? "info" : "error", "run_finished", {
      exitCode,
      report: stream.reportPath,
    });
    stream.close();
  }

  return exitCode;
}

const invokedPath = process.argv[1]
  ? pathToFileURL(resolve(process.argv[1])).href
  : "";
if (import.meta.url === invokedPath) {
  main(process.argv.slice(2)).then((code) => {
    process.exitCode = code;
  });
}

#!/usr/bin/env node
// Hermetic openai-compatible chat-completions stub for the PR-gating
// conversation smoke. Scripted conversationalist: answers recall prompts from
// the forwarded request history (so correct answers are only possible when
// prior turns arrive on the wire), streams replies in multiple chunks, and
// classifies finish_reason per the lane-10 truncation rule: an explicit
// scripted EOS is authoritative ("stop"); "length" is reported only when the
// requested max_tokens cap is reached without an explicit stop.
// Every request body is captured to STUB_CAPTURE_FILE as JSONL so the smoke
// driver can assert wire-level history forwarding and exact turn counts.

import { createServer } from "node:http";
import { appendFileSync, mkdirSync } from "node:fs";
import { dirname } from "node:path";

const port = Number(process.env.STUB_PORT ?? "11515");
const modelName = process.env.STUB_MODEL_NAME ?? "ci-conversation-stub";
const captureFile = process.env.STUB_CAPTURE_FILE?.trim();
if (!captureFile) {
  console.error("STUB_CAPTURE_FILE is required");
  process.exit(64);
}
mkdirSync(dirname(captureFile), { recursive: true });

const ENUMERATION_LIMIT = 10_000;

function textOf(content) {
  if (typeof content === "string") return content;
  if (Array.isArray(content)) {
    return content
      .map((part) => (part && part.type === "text" ? part.text : ""))
      .join("\n");
  }
  return "";
}

function lastUserText(messages) {
  for (let i = messages.length - 1; i >= 0; i -= 1) {
    if (messages[i]?.role === "user") return textOf(messages[i].content);
  }
  return "";
}

// One streamed chunk counts as one token; deterministic and cap-enforceable.
// cap is Infinity when the request set no max_tokens.
function planTurn(messages, maxTokens) {
  const cap =
    Number.isInteger(maxTokens) && maxTokens > 0 ? maxTokens : Infinity;
  const last = lastUserText(messages);
  const history = messages.map((message) => textOf(message.content)).join("\n");
  const codeword = history.match(/MBX_CONTEXT_[A-Za-z0-9_]+/)?.[0] ?? null;
  if (/ten thousand/.test(last)) {
    return { kind: "enumerate", cap };
  }
  if (/Count from 1 through 80/.test(last)) {
    const marker = last.match(/write (MBX_STREAMED_[A-Za-z0-9_]+)/)?.[1];
    const lines = Array.from({ length: 80 }, (_, i) => String(i + 1));
    if (marker) lines.push(marker);
    return { kind: "reply", lines, cap };
  }
  if (/What exact codeword/.test(last)) {
    return { kind: "reply", lines: [codeword ?? "CODEWORD_MISSING"], cap };
  }
  const replyWith = last.match(
    /Reply with (MBX_[A-Za-z0-9_]+), one space, and the (?:exact codeword|codeword remembered)/
  );
  if (replyWith) {
    return {
      kind: "reply",
      lines: [`${replyWith[1]} ${codeword ?? "CODEWORD_MISSING"}`],
      cap,
    };
  }
  return { kind: "reply", lines: ["."], cap };
}

function chunkLines(lines, perChunk) {
  const chunks = [];
  for (let i = 0; i < lines.length; i += perChunk) {
    chunks.push(`${lines.slice(i, i + perChunk).join("\n")}\n`);
  }
  return chunks;
}

const server = createServer((req, res) => {
  const url = new URL(req.url ?? "/", "http://127.0.0.1");
  if (req.method === "GET" && url.pathname === "/v1/models") {
    res.writeHead(200, { "content-type": "application/json" });
    res.end(
      JSON.stringify({
        object: "list",
        data: [
          { id: modelName, object: "model", created: 0, owned_by: "homer-ci" },
        ],
      })
    );
    return;
  }
  if (req.method !== "POST" || url.pathname !== "/v1/chat/completions") {
    res.writeHead(404, { "content-type": "application/json" });
    res.end(JSON.stringify({ error: { message: "not found" } }));
    return;
  }
  const buffers = [];
  req.on("data", (chunk) => buffers.push(chunk));
  req.on("end", () => {
    void respond(req, res, Buffer.concat(buffers));
  });
});

async function respond(req, res, bodyBuffer) {
  let body;
  try {
    body = JSON.parse(bodyBuffer.toString("utf8"));
  } catch {
    res.writeHead(400, { "content-type": "application/json" });
    res.end(JSON.stringify({ error: { message: "invalid JSON body" } }));
    return;
  }
  const messages = Array.isArray(body?.messages) ? body.messages : [];
  appendFileSync(
    captureFile,
    `${JSON.stringify({
      received_at: new Date().toISOString(),
      model: body?.model ?? null,
      stream: body?.stream === true,
      max_tokens: body?.max_tokens ?? null,
      message_count: messages.length,
      tool_count: Array.isArray(body?.tools) ? body.tools.length : 0,
      body_bytes: bodyBuffer.byteLength,
      messages,
    })}\n`,
    "utf8"
  );
  if (body?.stream !== true) {
    res.writeHead(400, { "content-type": "application/json" });
    res.end(
      JSON.stringify({ error: { message: "stub requires stream: true" } })
    );
    return;
  }
  const plan = planTurn(messages, body?.max_tokens);
  const promptTokens = Math.ceil(
    messages.reduce((sum, message) => sum + textOf(message.content).length, 0) /
      4
  );
  let closed = false;
  // res "close" fires on client disconnect (and after res.end); req "close"
  // fires as soon as the request body is consumed, which is not an abort.
  res.on("close", () => {
    closed = true;
  });
  res.writeHead(200, {
    "content-type": "text/event-stream; charset=utf-8",
    "cache-control": "no-cache",
    connection: "keep-alive",
  });
  const base = {
    id: "chatcmpl-ci-stub",
    object: "chat.completion.chunk",
    created: 1700000000,
    model: modelName,
  };
  const send = (chunk) => {
    if (closed) return false;
    try {
      res.write(`data: ${JSON.stringify(chunk)}\n\n`);
      return true;
    } catch {
      return false;
    }
  };
  send({
    ...base,
    choices: [
      {
        index: 0,
        delta: { role: "assistant", content: "" },
        finish_reason: null,
      },
    ],
  });
  // emitText returns false when the token cap forbids another chunk; a false
  // return therefore means the turn was cut by the cap, never by an EOS.
  let emitted = 0;
  const emitText = (text) => {
    if (emitted >= plan.cap || closed) return false;
    emitted += 1;
    return send({
      ...base,
      choices: [{ index: 0, delta: { content: text }, finish_reason: null }],
    });
  };
  let completedScript = false;
  if (plan.kind === "enumerate") {
    let n = 1;
    while (n <= ENUMERATION_LIMIT && emitText(`${n}\n`)) {
      if (n % 64 === 0) await new Promise((resolve) => setImmediate(resolve));
      n += 1;
    }
    if (closed) return;
    if (n > ENUMERATION_LIMIT && emitText("done\n")) completedScript = true;
  } else {
    const chunks = chunkLines(plan.lines, 8);
    let index = 0;
    while (index < chunks.length && emitText(chunks[index])) index += 1;
    completedScript = index === chunks.length;
  }
  if (closed) return;
  // Lane-10 classification: "length" only when the requested cap was reached
  // without the scripted EOS; an explicit stop is authoritative.
  const finishReason = completedScript ? "stop" : "length";
  send({
    ...base,
    choices: [{ index: 0, delta: {}, finish_reason: finishReason }],
  });
  send({
    ...base,
    choices: [],
    usage: {
      prompt_tokens: promptTokens,
      completion_tokens: emitted,
      total_tokens: promptTokens + emitted,
    },
  });
  res.end("data: [DONE]\n\n");
}

server.listen(port, "127.0.0.1", () => {
  console.log(
    JSON.stringify({
      type: "ci_stub_model_server_ready",
      port,
      model: modelName,
      captureFile,
    })
  );
});

#!/usr/bin/env node

import {
  createWriteStream,
  existsSync,
  mkdirSync,
  writeFileSync,
} from "node:fs";
import { dirname, join, relative, resolve } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import { spawn } from "node:child_process";

const ROOT_DIR = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const DEFAULT_ENDPOINT =
  process.env.NEEDLE_MCP_URL ?? "http://127.0.0.1:8424/mcp";
const DEFAULT_ARTIFACT_DIR = join(ROOT_DIR, "artifacts", "needle-mcp-smoke");
const DEFAULT_GLB = join(
  ROOT_DIR,
  "experiments",
  "3d-assets",
  "references",
  "accepted",
  "stone-floor-tile-chunk",
  "canonical.glb"
);

const HELP = `Usage: pnpm needle:mcp:smoke [options]

Verifies Needle MCP server availability and records whether live Inspector scene tools are connected.

Options:
  --endpoint <url>            MCP HTTP endpoint (default: ${DEFAULT_ENDPOINT})
  --artifact-dir <dir>        Artifact root (default: artifacts/needle-mcp-smoke)
  --gltf <path>               GLB/glTF path to summarize with local_read_gltf when available
  --no-gltf                   Skip local_read_gltf probe
  --start-server              Start npx -y needle-cloud start when endpoint is unavailable
  --keep-server               Keep a server started by this script running after the smoke
  --require-inspector         Exit nonzero when live Inspector scene tools are absent
  --timeout-ms <ms>           Endpoint startup/query timeout (default: 15000)
  --help                      Show this help
`;

const BASE_TOOL_NAMES = new Set([
  "needle_cloud_me",
  "needle_search",
  "get_editor_logpath",
  "get_editor_project_path",
  "get_editor_scene_path",
  "get_web_project_path",
  "local_read_file",
  "local_grep",
  "local_list_files",
  "local_read_editor_log",
  "local_read_gltf",
  "load_needle_engine_skill",
]);

const REQUIRED_BASE_TOOLS = [
  "needle_search",
  "local_read_gltf",
  "load_needle_engine_skill",
];

function timestampForPath(date = new Date()) {
  return date.toISOString().replace(/[:.]/g, "-");
}

function requireValue(argv, index, option) {
  const value = argv[index + 1];
  if (!value || value.startsWith("--"))
    throw new Error(`missing_value:${option}`);
  return value;
}

function parsePositiveInteger(value, option) {
  const parsed = Number(value);
  if (!Number.isInteger(parsed) || parsed <= 0)
    throw new Error(`invalid_integer:${option}`);
  return parsed;
}

export function parseArgs(argv) {
  const options = {
    endpoint: DEFAULT_ENDPOINT,
    artifactDir: DEFAULT_ARTIFACT_DIR,
    gltf: existsSync(DEFAULT_GLB) ? DEFAULT_GLB : null,
    startServer: false,
    keepServer: false,
    requireInspector: false,
    timeoutMs: 15000,
    help: false,
  };

  for (let index = 0; index < argv.length; index += 1) {
    const arg = argv[index];
    switch (arg) {
      case "--help":
      case "-h":
        options.help = true;
        break;
      case "--endpoint":
        options.endpoint = requireValue(argv, index, arg);
        index += 1;
        break;
      case "--artifact-dir":
        options.artifactDir = resolve(requireValue(argv, index, arg));
        index += 1;
        break;
      case "--gltf":
        options.gltf = resolve(requireValue(argv, index, arg));
        index += 1;
        break;
      case "--no-gltf":
        options.gltf = null;
        break;
      case "--start-server":
        options.startServer = true;
        break;
      case "--keep-server":
        options.keepServer = true;
        break;
      case "--require-inspector":
        options.requireInspector = true;
        break;
      case "--timeout-ms":
        options.timeoutMs = parsePositiveInteger(
          requireValue(argv, index, arg),
          arg
        );
        index += 1;
        break;
      default:
        throw new Error(
          arg.startsWith("--")
            ? `unknown_option:${arg}`
            : `unexpected_arg:${arg}`
        );
    }
  }

  return options;
}

function delay(ms) {
  return new Promise((resolveDelay) => setTimeout(resolveDelay, ms));
}

function renderData(data) {
  if (!data || Object.keys(data).length === 0) return "";
  return ` ${JSON.stringify(data)}`;
}

function formatLine(event) {
  return `[${event.ts}] ${event.namespace} ${event.level} ${event.message}${renderData(event.data)}`;
}

class SmokeStream {
  constructor({ artifactDir, stdout = process.stdout }) {
    this.runId = timestampForPath(new Date());
    this.runDir = join(artifactDir, this.runId);
    this.reportPath = join(this.runDir, "report.json");
    this.logPath = join(this.runDir, "stream.log");
    this.eventsPath = join(this.runDir, "stream.jsonl");
    this.startedAt = new Date().toISOString();
    this.stdout = stdout;
    this.counts = new Map();
    mkdirSync(this.runDir, { recursive: true });
    this.log = createWriteStream(this.logPath, { flags: "a" });
    this.events = createWriteStream(this.eventsPath, { flags: "a" });
  }

  emit(namespace, level, message, data = {}) {
    const event = {
      ts: new Date().toISOString(),
      namespace,
      level,
      message,
      data,
    };
    this.counts.set(namespace, (this.counts.get(namespace) ?? 0) + 1);
    this.events.write(`${JSON.stringify(event)}\n`);
    this.log.write(`${formatLine(event)}\n`);
    this.stdout.write(`${formatLine(event)}\n`);
    return event;
  }

  writeReport(report) {
    const body = {
      schemaVersion: 1,
      runId: this.runId,
      startedAt: this.startedAt,
      finishedAt: new Date().toISOString(),
      artifacts: {
        runDir: this.runDir,
        report: this.reportPath,
        log: this.logPath,
        events: this.eventsPath,
      },
      eventCounts: Object.fromEntries(this.counts),
      ...report,
    };
    writeFileSync(this.reportPath, `${JSON.stringify(body, null, 2)}\n`);
    return body;
  }

  close() {
    this.events.end();
    this.log.end();
  }
}

async function readResponseBody(response) {
  const text = await response.text();
  try {
    return JSON.parse(text);
  } catch {
    return { raw: text };
  }
}

async function tryInitialize(endpoint) {
  const response = await fetch(endpoint, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Accept: "application/json",
    },
    body: JSON.stringify({
      jsonrpc: "2.0",
      id: 1,
      method: "initialize",
      params: {
        protocolVersion: "2025-06-18",
        capabilities: {},
        clientInfo: { name: "homer-needle-mcp-smoke", version: "0.1.0" },
      },
    }),
  });
  if (!response.ok) throw new Error(`initialize_http_${response.status}`);
  const body = await readResponseBody(response);
  if (body.error)
    throw new Error(`initialize_rpc_${body.error.message ?? body.error.code}`);
  return {
    body,
    sessionId:
      response.headers.get("mcp-session-id") ??
      response.headers.get("Mcp-Session-Id"),
  };
}

async function waitForEndpoint(endpoint, timeoutMs) {
  const deadline = Date.now() + timeoutMs;
  let lastError = null;
  while (Date.now() < deadline) {
    try {
      return await tryInitialize(endpoint);
    } catch (error) {
      lastError = error;
      await delay(250);
    }
  }
  throw new Error(`needle_mcp_unavailable:${lastError?.message ?? "timeout"}`);
}

function pipeLines(readable, onLine) {
  let buffer = "";
  readable.setEncoding("utf8");
  readable.on("data", (chunk) => {
    buffer += chunk;
    let newline = buffer.indexOf("\n");
    while (newline >= 0) {
      const line = buffer.slice(0, newline).replace(/\r$/, "");
      buffer = buffer.slice(newline + 1);
      if (line) onLine(line);
      newline = buffer.indexOf("\n");
    }
  });
}

function startNeedleServer(stream) {
  const child = spawn("npx", ["-y", "needle-cloud", "start"], {
    cwd: ROOT_DIR,
    stdio: ["ignore", "pipe", "pipe"],
  });
  pipeLines(child.stdout, (line) => stream.emit("needle-cloud", "info", line));
  pipeLines(child.stderr, (line) => stream.emit("needle-cloud", "error", line));
  child.on("exit", (code, signal) => {
    stream.emit(
      "needle-cloud",
      code === 0 ? "info" : "error",
      "server_exited",
      { code, signal }
    );
  });
  stream.emit("needle-cloud", "info", "server_starting", {
    command: "npx -y needle-cloud start",
  });
  return child;
}

async function rpc(endpoint, sessionId, id, method, params = {}) {
  const headers = {
    "Content-Type": "application/json",
    Accept: "application/json",
  };
  if (sessionId) headers["Mcp-Session-Id"] = sessionId;
  const response = await fetch(endpoint, {
    method: "POST",
    headers,
    body: JSON.stringify({ jsonrpc: "2.0", id, method, params }),
  });
  if (!response.ok) throw new Error(`${method}_http_${response.status}`);
  const body = await readResponseBody(response);
  if (body.error)
    throw new Error(`${method}_rpc_${body.error.message ?? body.error.code}`);
  return body.result;
}

export function classifyTools(tools) {
  const names = tools.map((tool) => tool.name).sort();
  const missingBaseTools = REQUIRED_BASE_TOOLS.filter(
    (name) => !names.includes(name)
  );
  const additionalTools = names.filter((name) => !BASE_TOOL_NAMES.has(name));
  const liveInspectorTools = additionalTools.filter((name) =>
    /inspector|hierarchy|object|material|transform|selection|scene|three/i.test(
      name
    )
  );

  return {
    names,
    count: names.length,
    missingBaseTools,
    additionalTools,
    liveInspectorTools,
    inspectorConnected: liveInspectorTools.length > 0,
  };
}

function pathForNeedleTool(path) {
  const rel = relative(ROOT_DIR, path);
  return rel && !rel.startsWith("..") ? rel : path;
}

function compactToolResult(result) {
  const content = Array.isArray(result?.content) ? result.content : [];
  const text = content
    .map((part) => (typeof part?.text === "string" ? part.text : ""))
    .filter(Boolean)
    .join("\n")
    .slice(0, 4000);
  return {
    isError: result?.isError === true,
    contentTypes: content.map((part) => part?.type ?? "unknown"),
    textPreview: text,
  };
}

async function callNeedleTool(endpoint, sessionId, id, name, args = {}) {
  const result = await rpc(endpoint, sessionId, id, "tools/call", {
    name,
    arguments: args,
  });
  return compactToolResult(result);
}

async function runSmoke(options, stream) {
  let serverProcess = null;
  let initialized;
  try {
    initialized = await waitForEndpoint(options.endpoint, 1500);
    stream.emit("needle-mcp", "info", "endpoint_ready", {
      endpoint: options.endpoint,
      startedBySmoke: false,
    });
  } catch (error) {
    if (!options.startServer) throw error;
    stream.emit("needle-mcp", "info", "endpoint_unavailable_starting_server", {
      error: error.message,
    });
    serverProcess = startNeedleServer(stream);
    initialized = await waitForEndpoint(options.endpoint, options.timeoutMs);
    stream.emit("needle-mcp", "info", "endpoint_ready", {
      endpoint: options.endpoint,
      startedBySmoke: true,
    });
  }

  const sessionId = initialized.sessionId;
  const serverInfo = initialized.body?.result?.serverInfo ?? null;
  const capabilities = initialized.body?.result?.capabilities ?? null;
  const toolsResult = await rpc(options.endpoint, sessionId, 2, "tools/list");
  const tools = Array.isArray(toolsResult?.tools) ? toolsResult.tools : [];
  const classification = classifyTools(tools);
  stream.emit("needle-mcp", "info", "tools_listed", {
    count: classification.count,
    inspectorConnected: classification.inspectorConnected,
  });

  const projectPathProbes = {};
  const pathTools = [
    "get_web_project_path",
    "get_editor_project_path",
    "get_editor_scene_path",
  ];
  for (const [index, tool] of pathTools.entries()) {
    if (!classification.names.includes(tool)) continue;
    try {
      projectPathProbes[tool] = await callNeedleTool(
        options.endpoint,
        sessionId,
        10 + index,
        tool
      );
      stream.emit("needle-mcp", "info", "project_path_probe_finished", {
        tool,
      });
    } catch (error) {
      projectPathProbes[tool] = { isError: true, textPreview: error.message };
      stream.emit("needle-mcp", "error", "project_path_probe_failed", {
        tool,
        error: error.message,
      });
    }
  }

  let gltfProbe = null;
  if (options.gltf) {
    if (!existsSync(options.gltf)) {
      gltfProbe = {
        status: "blocked",
        reason: `gltf_not_found:${options.gltf}`,
      };
      stream.emit("needle-mcp", "error", "gltf_probe_blocked", gltfProbe);
    } else if (!classification.names.includes("local_read_gltf")) {
      gltfProbe = { status: "blocked", reason: "local_read_gltf_tool_missing" };
      stream.emit("needle-mcp", "error", "gltf_probe_blocked", gltfProbe);
    } else {
      const toolPath = pathForNeedleTool(options.gltf);
      const compact = await callNeedleTool(
        options.endpoint,
        sessionId,
        3,
        "local_read_gltf",
        { path: toolPath }
      );
      const blocked =
        compact.isError || /^Error:/i.test(compact.textPreview.trim());
      gltfProbe = {
        status: blocked ? "blocked" : "passed",
        path: options.gltf,
        toolPath,
        result: compact,
      };
      stream.emit(
        "needle-mcp",
        gltfProbe.status === "passed" ? "info" : "error",
        "gltf_probe_finished",
        {
          status: gltfProbe.status,
          path: options.gltf,
        }
      );
    }
  }

  const missing = classification.missingBaseTools.length;
  const inspectorBlocked = !classification.inspectorConnected;
  const status =
    missing > 0 || inspectorBlocked || gltfProbe?.status === "blocked"
      ? "blocked"
      : "passed";
  const report = stream.writeReport({
    status,
    endpoint: options.endpoint,
    serverInfo,
    capabilities,
    tools: classification,
    projectPathProbes,
    gltfProbe,
    blockers: [
      ...classification.missingBaseTools.map(
        (tool) => `missing_base_tool:${tool}`
      ),
      ...(inspectorBlocked ? ["needle_inspector_live_scene_tools_absent"] : []),
      ...(gltfProbe?.status === "blocked"
        ? [gltfProbe.reason ?? "gltf_probe_blocked"]
        : []),
    ],
  });

  if (serverProcess && !options.keepServer) {
    serverProcess.kill("SIGTERM");
  }

  return {
    exitCode:
      options.requireInspector && inspectorBlocked ? 1 : missing > 0 ? 1 : 0,
    report,
  };
}

async function main(argv) {
  let options;
  try {
    options = parseArgs(argv);
  } catch (error) {
    process.stderr.write(`${error.message}\n\n${HELP}`);
    return 2;
  }
  if (options.help) {
    process.stdout.write(HELP);
    return 0;
  }

  const stream = new SmokeStream({ artifactDir: options.artifactDir });
  stream.emit("needle-mcp", "info", "smoke_started", {
    endpoint: options.endpoint,
    requireInspector: options.requireInspector,
    artifactDir: stream.runDir,
  });

  try {
    const { exitCode, report } = await runSmoke(options, stream);
    stream.emit(
      "needle-mcp",
      exitCode === 0 ? "info" : "error",
      "smoke_finished",
      {
        exitCode,
        status: report.status,
        report: stream.reportPath,
      }
    );
    return exitCode;
  } catch (error) {
    const report = stream.writeReport({
      status: "blocked",
      endpoint: options.endpoint,
      blockers: [error.message],
    });
    stream.emit("needle-mcp", "error", "smoke_failed", {
      error: error.message,
      report: report.artifacts.report,
    });
    return 1;
  } finally {
    stream.close();
  }
}

const invokedPath = process.argv[1]
  ? pathToFileURL(resolve(process.argv[1])).href
  : "";
if (import.meta.url === invokedPath) {
  main(process.argv.slice(2)).then((code) => {
    process.exitCode = code;
  });
}

#!/usr/bin/env node
import { existsSync, readFileSync, renameSync, writeFileSync } from "node:fs";
import { homedir } from "node:os";
import { join, resolve } from "node:path";
import { spawnSync } from "node:child_process";

const repoRoot = resolve(process.env.HOMER_WORKSPACE_ROOT ?? process.cwd());
const stateDir = resolve(process.env.HOMER_STATE_DIR ?? repoRoot);
const agentConfigPath = resolve(stateDir, ".homer-agent-config.json");
const opencodeConfigPath = resolve(
  homedir(),
  ".config/opencode/opencode.jsonc"
);

const defaultProtectedRoots = ["/", "~", "~/code", "~/code/homer", "~/notes"];
const defaultAgentConfig = {
  toolMode: "workspace",
  basePrompt: "You are a local Homer coding agent.",
  includeSkillPrompts: true,
  includeRepoInstructions: false,
  toolPathRules: {
    bash: {
      readRoots: ["~/code"],
      protectedRoots: defaultProtectedRoots,
      allowShellDestructive: false,
    },
    delete_file: {
      writeRoots: ["~/notes"],
      protectedRoots: defaultProtectedRoots,
      allowRecursiveDelete: false,
    },
  },
};

function stripJsonc(input) {
  let out = "";
  let inString = false;
  let quote = "";
  let escape = false;
  for (let i = 0; i < input.length; i++) {
    const c = input[i];
    const n = input[i + 1];
    if (inString) {
      out += c;
      if (escape) escape = false;
      else if (c === "\\") escape = true;
      else if (c === quote) inString = false;
      continue;
    }
    if (c === '"' || c === "'") {
      inString = true;
      quote = c;
      out += c;
      continue;
    }
    if (c === "/" && n === "/") {
      while (i < input.length && input[i] !== "\n") i++;
      out += "\n";
      continue;
    }
    if (c === "/" && n === "*") {
      i += 2;
      while (i < input.length && !(input[i] === "*" && input[i + 1] === "/"))
        i++;
      i++;
      continue;
    }
    out += c;
  }
  return out.replace(/,\s*([}\]])/g, "$1");
}

function readJsonc(path, fallback) {
  if (!existsSync(path)) return fallback;
  return JSON.parse(stripJsonc(readFileSync(path, "utf8")));
}

function expandHome(path) {
  if (path === "~") return homedir();
  if (path.startsWith("~/")) return join(homedir(), path.slice(2));
  return path;
}

function opencodePathPattern(root) {
  expandHome(root);
  if (root === "/") return "/**";
  if (root === "~") return "~/**";
  return root.endsWith("/**") ? root : `${root.replace(/\/$/, "")}/**`;
}

function dangerousBashRules(agentConfig) {
  const bashRule = agentConfig.toolPathRules?.bash ?? {};
  const protectedRoots = bashRule.protectedRoots ?? defaultProtectedRoots;
  const deny = {
    "find * -delete": "deny",
    "rm *": "deny",
    "rm -r*": "deny",
    "rm -R*": "deny",
    "rm -f*": "deny",
    "rm -rf*": "deny",
    "rm -fr*": "deny",
    "rmdir *": "deny",
    "shred *": "deny",
    "truncate *": "deny",
    "sudo *": "deny",
    "dd *": "deny",
    "mkfs*": "deny",
    "chmod *777*": "deny",
    "git clean*": "deny",
    "git reset --hard*": "deny",
  };
  for (const root of protectedRoots) {
    if (root === "/") {
      deny["rm /"] = "deny";
      deny["rm -r /"] = "deny";
      deny["rm -rf /"] = "deny";
      continue;
    }
    deny[`rm ${root}`] = "deny";
    deny[`rm ${root}/`] = "deny";
    deny[`rm -r ${root}*`] = "deny";
    deny[`rm -rf ${root}*`] = "deny";
    deny[`rmdir ${root}`] = "deny";
  }
  return deny;
}

function buildPermission(agentConfig) {
  const toolMode = agentConfig.toolMode ?? "workspace";
  if (toolMode === "off") return { "*": "deny", question: "allow" };

  const readonly = toolMode === "readonly";
  const externalDirectory = { "*": "ask", "/**": "deny" };
  for (const root of ["~/code", "~/notes"]) {
    externalDirectory[opencodePathPattern(root)] = "ask";
  }

  const permission = {
    "*": "ask",
    read: {
      "*": "allow",
      "*.env": "deny",
      "*.env.*": "deny",
      "*.env.example": "allow",
    },
    glob: "allow",
    grep: "allow",
    edit: readonly
      ? "deny"
      : {
          "*": "ask",
          "/**": "deny",
          "~/code/homer/**": "ask",
          "~/notes/**": "ask",
        },
    bash: {
      "*": "ask",
      pwd: "allow",
      "ls *": "allow",
      "cat *": readonly ? "allow" : "ask",
      "rg *": "allow",
      "grep *": "allow",
      "find *": readonly ? "allow" : "ask",
      "git status*": "allow",
      "git diff*": "allow",
      "git log*": "allow",
      ...dangerousBashRules(agentConfig),
    },
    external_directory: externalDirectory,
    webfetch: "ask",
    websearch: "ask",
    task: "ask",
    skill: "ask",
    doom_loop: "ask",
  };

  if (readonly) {
    permission.bash = {
      "*": "deny",
      pwd: "allow",
      "ls *": "allow",
      "cat *": "allow",
      "rg *": "allow",
      "grep *": "allow",
      "find *": "allow",
      "git status*": "allow",
      "git diff*": "allow",
      "git log*": "allow",
      ...dangerousBashRules(agentConfig),
    };
  }

  return permission;
}

function buildAgent(agentConfig) {
  return {
    "homer-build": {
      description: "Homer default coding agent with shared safe tool policy",
      mode: "primary",
      prompt: agentConfig.basePrompt ?? defaultAgentConfig.basePrompt,
      permission: buildPermission(agentConfig),
    },
    "homer-review": {
      description: "Homer read-only review agent",
      mode: "primary",
      prompt: `${agentConfig.basePrompt ?? defaultAgentConfig.basePrompt}\n\nReview and analyze only. Do not edit files.`,
      permission: buildPermission({ ...agentConfig, toolMode: "readonly" }),
    },
  };
}

function readAgentConfig() {
  const raw = readJsonc(agentConfigPath, {});
  return {
    ...defaultAgentConfig,
    ...raw,
    toolPathRules: {
      ...defaultAgentConfig.toolPathRules,
      ...(raw.toolPathRules ?? {}),
      bash: {
        ...defaultAgentConfig.toolPathRules.bash,
        ...(raw.toolPathRules?.bash ?? {}),
      },
      delete_file: {
        ...defaultAgentConfig.toolPathRules.delete_file,
        ...(raw.toolPathRules?.delete_file ?? {}),
      },
    },
  };
}

function buildOverlay(agentConfig = readAgentConfig()) {
  return {
    permission: buildPermission(agentConfig),
    default_agent: "homer-build",
    agent: buildAgent(agentConfig),
  };
}

function mergeConfig(base, overlay) {
  return {
    ...base,
    permission: overlay.permission,
    default_agent: overlay.default_agent,
    agent: {
      ...(base.agent ?? {}),
      ...overlay.agent,
    },
  };
}

function writeAtomic(path, content) {
  const tmp = `${path}.${process.pid}.tmp`;
  writeFileSync(tmp, content, "utf8");
  renameSync(tmp, path);
}

function apply() {
  const base = readJsonc(opencodeConfigPath, {
    $schema: "https://opencode.ai/config.json",
  });
  const merged = mergeConfig(base, buildOverlay());
  const backup = `${opencodeConfigPath}.bak-${new Date().toISOString().replace(/[:.]/g, "-")}`;
  if (existsSync(opencodeConfigPath))
    writeFileSync(backup, readFileSync(opencodeConfigPath));
  writeAtomic(opencodeConfigPath, `${JSON.stringify(merged, null, 2)}\n`);
  return { path: opencodeConfigPath, backup };
}

const command = process.argv[2] ?? "print-overlay";
if (command === "print-overlay") {
  console.log(JSON.stringify(buildOverlay(), null, 2));
} else if (command === "apply") {
  console.log(JSON.stringify(apply(), null, 2));
} else if (command === "launch") {
  const model = process.argv[3] ?? "qwen36";
  const project = process.argv[4] ?? repoRoot;
  const overlay = JSON.stringify(buildOverlay());
  const result = spawnSync(
    "opencode",
    ["--model", `homer/${model}`, "--agent", "homer-build", project],
    {
      stdio: "inherit",
      env: { ...process.env, OPENCODE_CONFIG_CONTENT: overlay },
    }
  );
  process.exit(result.status ?? 1);
} else {
  console.error(`unknown command: ${command}`);
  process.exit(2);
}
